#!/usr/bin/env python3
"""patch_s194_cut_fx.py - Ayat Studio S194 (run from repo root, after S193)

Cut: the scissors split a PIP clip under the playhead (or the selected one).
Everyday video looks (B&W, negative, dramatic, warm, cool, cinematic bars,
fade in / out / both, flash, shake, pulse) in the Effects tab, previewed live
and exported. Effects tab added to the main-clip and PIP tool strips.
Idempotent; every anchor is verified before anything is written.
"""
import os, sys
MARK = "PATCH_S194_CUT_FX"
if not os.path.exists("lib/widgets/pro_pip.dart"):
    sys.exit("Run from the repo root.")
SPEC = {'lib/models/studio_state.dart': ('full', ('af6f2e5d74385aa9a091e6dcfdf81e0374cbff12421aa96d06ff3ffea48a6b93', 'import \'package:flutter/material.dart\';\nimport \'../data/studio_presets.dart\';\nimport \'../services/ayah_matcher.dart\';\nimport \'../services/ai_art_service.dart\'; // PATCH_S32_AI_ART_NANO_BANANA\nimport \'../services/stage_effects.dart\'; // PATCH_S34_STAGE_EFFECTS\nimport \'../services/whisper_service.dart\'; // PATCH_S43_MODEL_SIZE_PICKER\nimport \'../services/subtitle_service.dart\'; // PATCH_S125_SUBTITLES\nimport \'../data/text_transitions.dart\'; // PATCH_S126_TEXT_TRANSITIONS\nimport \'video_transform.dart\'; // PATCH_S180_TRANSFORM\nimport \'pip_clip.dart\'; // PATCH_S188_PIP\nimport \'../services/video_fx.dart\'; // PATCH_S194_CUT_FX\n\n/// One detected span of the auto-sync timeline: [ayah] was heard between\n/// [start] and [end] (seconds into the uploaded clip).\nclass TimelineSegment {\n  double start;\n  double end;\n  final Ayah ayah;\n  double confidence;\n  // PATCH_S55_WORD_TIMESTAMPS: absolute onsets (seconds into the clip) of\n  // the words Whisper heard inside this segment — the karaoke lighting\n  // paces itself along these instead of assuming an even reciting speed.\n  final List<double> wordStarts;\n  // PATCH_S82_AUTOSYNC_MAX: true when this segment was never acoustically\n  // matched — it was inserted because its neighbours are the same surah with\n  // exactly this ayah missing between them and there was recitation time in\n  // the gap. The UI flags these so the user knows to double-check them.\n  final bool inferred;\n  // PATCH_S118_PARTIAL_AYAH_TIMELINE_MERGE: when this segment is a sliced\n  // word range from "استخدام جزء من الآية فقط" rather than the whole\n  // ayah, the sliced text lives here -- null means "use ayah.ar as-is".\n  // PATCH_S133_STAGE_TEXT_SELECT_EDIT: no longer final -- the stage-text\n  // edit dialog corrects it in place instead of rebuilding the segment.\n  String? textOverride;\n\n  // PATCH_S157_TYPED_TEXT_DISPLAY: the ONE text this segment shows\n  // in preview, export and subtitles alike. Typed text, partial-ayah\n  // slices and custom captions carry their exact words in\n  // textOverride; ayah.ar is the full canonical ayah and must never\n  // replace them. Renderers read this getter — never ayah.ar.\n  String get displayText => textOverride ?? ayah.ar;\n\n  TimelineSegment({\n    required this.start,\n    required this.end,\n    required this.ayah,\n    required this.confidence,\n    List<double>? wordStarts,\n    this.inferred = false,\n    this.textOverride,\n  }) : wordStarts = wordStarts ?? [];\n}\n\n/// Central mutable app state — the Flutter counterpart of the HTML\n/// prototype\'s single `state` object. Everything the stage preview and the\n/// exporter read lives here so they can never disagree.\n// PATCH_S76_QURAN_MODEL_DEFAULT\n// PATCH_S128: label shapes for the text background chip\nenum S128LabelShape { rounded, circle, pill, scallop, hexagon }\n\n// PATCH_S143_TEXT_LAYERS: a single independent "fixed text" box, stacked\n// freely on top of the ayah and the caption. Unlike ayahText/captionText\n// (one slot each, silently overwritten), these live in a real list -- add\n// as many as you like, remove any one without touching the others.\nclass TextLayer {\n  String text;\n  AyahTextPosition position;\n  double fontSize; // preview-scale px, same convention as ayahFontSize\n  Color color;\n  TextLayer({\n    required this.text,\n    this.position = AyahTextPosition.top,\n    this.fontSize = 20,\n    this.color = const Color(0xFFECC875),\n  });\n}\n\n// PATCH_S160_MULTI_TEXT_TIME_CUES: one independently-timed piece of ayah text. The old\n// PATCH_S109 textTimeStartOverride/textTimeEndOverride pair could only\n// ever describe ONE text\'s window -- a second typed text just overwrote\n// it. StudioState.textTimeCues below is a real list of these instead.\nclass TextTimeCue {\n  String text;\n  String translation;\n  double start;\n  double end;\n  TextTimeCue({\n    required this.text,\n    this.translation = \'\',\n    required this.start,\n    required this.end,\n  });\n}\n\nclass StudioState extends ChangeNotifier {\n  // ---- corpus ----\n  List<Ayah> ayaat = [];\n  AyahMatcher? matcher;\n  String corpusStatus = \'جارٍ تحميل القرآن الكريم كاملاً…\';\n\n  // ---- currently displayed ayah ----\n  String ayahText = \'\';\n  String translationText = \'\';\n  String detectedLabel = \'\';\n  String matchConfidenceText = \'\';\n  bool get hasAyah => ayahText.isNotEmpty;\n\n  // ---- PATCH_S143_TEXT_LAYERS: stackable fixed-text boxes ----------------\n  List<TextLayer> textLayers = [];\n\n  void addTextLayer(TextLayer layer) {\n    // PATCH_S162_CUE_GATE_AND_UNDO_FIX: called directly (never wrapped in\n    // state.update()) everywhere in the UI, and this method never pushed\n    // its own history entry -- adding a text layer was invisible to\n    // undo/redo, not merely unrestorable. Paired with the textLayers\n    // entry added to _capture()/_apply() above.\n    pushHistory();\n    textLayers = [...textLayers, layer];\n    notifyListeners();\n  }\n\n  void updateTextLayerAt(int index, TextLayer layer) {\n    if (index < 0 || index >= textLayers.length) return;\n    // PATCH_S162_CUE_GATE_AND_UNDO_FIX: see addTextLayer() above.\n    pushHistory();\n    final next = [...textLayers];\n    next[index] = layer;\n    textLayers = next;\n    notifyListeners();\n  }\n\n  void removeTextLayerAt(int index) {\n    if (index < 0 || index >= textLayers.length) return;\n    // PATCH_S162_CUE_GATE_AND_UNDO_FIX: see addTextLayer() above.\n    pushHistory();\n    final next = [...textLayers]..removeAt(index);\n    textLayers = next;\n    notifyListeners();\n  }\n\n  // PATCH_S129_QURAN_CAPTION_PARITY: project identity (dashboard + chapters header)\n  String projectName = \'\';\n  String reciterName = \'\';\n\n  // PATCH_S129_QURAN_CAPTION_PARITY: independent translation-layer styling.\n  // Defaults preserve the previous look; the live preview and the exporter\n  // both read these so they can never disagree.\n  double translationFontSize = 22;\n  Color translationColor = const Color(0xFFE8E0D0);\n  double translationOpacity = 0.92;\n  double translationOffsetY = 12; // positive = below the ayah block\n\n  // ---- uploaded media ----\n  String? videoPath;\n  bool get hasVideo => videoPath != null;\n  // PATCH_S34_PLAYER_CONTROLS_TRIM: known once the preview player initializes;\n  // drives the seek bar and the manual-cut range slider.\n  double videoDurationSec = 0;\n\n  // ---- PATCH_S34_STAGE_EFFECTS: decorative particle overlay ----\n  StageEffect effect = StageEffect.none;\n  double effectIntensity = 0.7; // 0.2..1.0\n  VideoFx videoFx = VideoFx.none; // PATCH_S194_CUT_FX: everyday video looks\n\n  // ---- PATCH_S38_VIDEO_EFFECTS: export-time video effects (never audio) ----\n  ColorGrade colorGrade = ColorGrade.none;\n  bool vignetteEnabled = false;\n  int vignetteIntensity = 50; // 0..100\n  // PATCH_S100_FONTS_SPINSTAR_TINT: a color tint independent of the\n  // colorGrade presets above -- null means off. Any color is valid\n  // (picked via showAyatColorPicker); blue/gold are just quick presets\n  // in the UI, not the only options.\n  Color? tintColor;\n  int tintIntensity = 45; // 0..100\n  bool grainEnabled = false;\n  int grainIntensity = 30; // 0..100\n  bool kenBurnsEnabled = false; // slow zoom on background images only, never on uploaded video\n  bool softTransitions = true; // fade in/out around bismillah/outro cards instead of a hard cut\n\n  // ---- PATCH_S85_VIDEO_ADJUST: manual picture controls on top of the ----\n  // preset grades — live in the preview, burned in at export (ffmpeg eq).\n  double adjustBrightness = 0.0; // -0.25..0.25, 0 = neutral\n  double adjustContrast = 1.0; // 0.7..1.4, 1 = neutral\n  double adjustSaturation = 1.0; // 0.0..2.0, 1 = neutral\n  // Blur of the video/background layer only (text and particles stay\n  // sharp), in 270-reference-width units like the text sizes.\n  double videoBlur = 0.0; // 0..6\n  bool get hasManualAdjust =>\n      adjustBrightness.abs() > 0.005 ||\n      (adjustContrast - 1).abs() > 0.005 ||\n      (adjustSaturation - 1).abs() > 0.005;\n  void resetManualAdjust() {\n    adjustBrightness = 0.0;\n    adjustContrast = 1.0;\n    adjustSaturation = 1.0;\n    videoBlur = 0.0;\n    notifyListeners();\n  }\n\n  // ---- PATCH_S123_WATERMARK: entirely opt-in --------------------------\n  // Off by default and never turned on for the user. An export carries no\n  // watermark unless this switch was flipped deliberately, and there is no\n  // "remove watermark" upsell anywhere -- the app does not brand the user\'s\n  // work for them.\n  bool watermarkEnabled = false;\n  String watermarkText = \'\';\n  /// A logo/PNG to stamp instead of text. Text is used when this is null.\n  String? watermarkImagePath;\n  WatermarkCorner watermarkCorner = WatermarkCorner.bottomRight;\n  double watermarkOpacity = 0.65; // 0.15..1.0\n  /// Width of the mark as a fraction of the frame width.\n  double watermarkScale = 0.22; // 0.08..0.45\n  bool get hasWatermark =>\n      watermarkEnabled &&\n      (watermarkImagePath != null || watermarkText.trim().isNotEmpty);\n\n  // ---- PATCH_S123_AUDIO_MIX -------------------------------------------\n  /// How loud the clip\'s OWN audio sits under an attached reciter track,\n  /// 0..1. 0 replaces it entirely, which is what the app always did; raising\n  /// it keeps rain/wind/room tone audible beneath the recitation instead of\n  /// forcing a choice between the two.\n  double originalAudioMix = 0.0;\n\n  /// Export with no audio track at all.\n  bool muteAudio = false;\n\n  // ---- PATCH_S127_MUSIC_BED ------------------------------------------\n  /// An optional background audio / ambience track, mixed UNDER whatever\n  /// audio the export already has (the recitation, the clip\'s own sound, or\n  /// both). Separate from [originalAudioMix], which only rebalances the two\n  /// tracks that were already there.\n  ///\n  /// A bed shorter than the clip is looped rather than leaving silence, and\n  /// a longer one is cut to length, so its duration never has to match.\n  String? ambienceBedPath;\n\n  /// 0..1, how loud the bed sits under everything else. The default is\n  /// deliberately quiet: this is meant to sit behind a recitation.\n  double ambienceBedVolume = 0.18;\n\n  /// Ease the bed in and out rather than starting and stopping it dead.\n  bool ambienceBedFade = true;\n\n  bool get hasAmbienceBed =>\n      !muteAudio && ambienceBedPath != null && ambienceBedVolume > 0.005;\n\n  // ---- PATCH_S54_PRO_EXPORT_CONTROLS ----\n  VideoFitMode videoFit = VideoFitMode.source;\n  int videoRotationQuarterTurns = 0; // 0..3, clockwise\n  bool videoMirror = false;\n  ExportQuality exportQuality = ExportQuality.high;\n  ExportResolutionCap exportResolution = ExportResolutionCap.source;\n  double audioVolume = 1.0; // 0.0..2.0, applied to whichever track is exported\n  bool audioFadeIn = false;\n  bool audioFadeOut = false;\n  // PATCH_S175_CAPCUT: CapCut-style export + clean-up controls\n  int exportFps = 30; // 24 | 25 | 30 | 50 | 60\n  int enhanceSharpen = 0; // 0..100, picture sharpen (export)\n  int enhanceDenoise = 0; // 0..100, picture denoise (export)\n  bool audioDenoise = false; // voice noise reduction (export)\n  bool audioNormalize = false; // loudness normalize (export)\n  // ---- PATCH_S180_TRANSFORM: free transform + keyframes of the video layer ----\n  double videoScale = 1.0; // 0.3..2.0 (used when there are no keyframes)\n  double videoPosX = 0.0; // -0.9..0.9 of the frame width\n  double videoPosY = 0.0; // -0.9..0.9 of the frame height\n  double videoRot = 0.0; // degrees, -180..180\n  double videoOpacity = 1.0; // 0..1, one value for the whole clip\n  List<VideoKey> videoKeys = []; // sorted by time; 2+ = animated\n  bool videoKeyEase = true; // smoothstep between keys (false = linear)\n\n  // ---- PATCH_S188_PIP: picture-in-picture clips -------------------------\n  List<PipClip> pipClips = []; // layer order: last = on top\n  int pipSel = -1; // selection only, not part of undo\n\n  bool get hasPipSel => pipSel >= 0 && pipSel < pipClips.length;\n  PipClip? get selectedPip => hasPipSel ? pipClips[pipSel] : null;\n\n  void selectPip(int i) {\n    final v = (i >= 0 && i < pipClips.length) ? i : -1;\n    if (v == pipSel) return;\n    pipSel = v;\n    if (v >= 0) stageTextSelected = false;\n    notifyListeners();\n  }\n\n  void addPip(PipClip c) {\n    pushHistory();\n    pipClips = [...pipClips, c];\n    pipSel = pipClips.length - 1;\n    stageTextSelected = false;\n    notifyListeners();\n  }\n\n  void removePipAt(int i) {\n    if (i < 0 || i >= pipClips.length) return;\n    pushHistory();\n    pipClips = [...pipClips]..removeAt(i);\n    pipSel = -1;\n    notifyListeners();\n  }\n\n  void duplicatePipAt(int i) {\n    if (i < 0 || i >= pipClips.length) return;\n    pushHistory();\n    final d = pipClips[i].duplicate();\n    d.cx = (d.cx + 0.06).clamp(0.0, 1.0).toDouble();\n    d.cy = (d.cy + 0.06).clamp(0.0, 1.0).toDouble();\n    pipClips = [...pipClips]..insert(i + 1, d);\n    pipSel = i + 1;\n    notifyListeners();\n  }\n\n  /// Moves one or both edges (seconds). Trimming the start keeps the picture\n  /// in step (the part of the media that plays moves with it).\n  void setPipWindow(int i, {double? start, double? end}) {\n    if (i < 0 || i >= pipClips.length) return;\n    final c = pipClips[i];\n    var s = start ?? c.start;\n    var e = end ?? c.end;\n    if (s < 0) s = 0;\n    if (e - s < kPipMinLen) {\n      if (start != null) {\n        s = e - kPipMinLen;\n      } else {\n        e = s + kPipMinLen;\n      }\n    }\n    if (s < 0) {\n      s = 0;\n      e = kPipMinLen;\n    }\n    if (start != null && !c.isImage) {\n      final ni = c.srcIn + (s - c.start);\n      c.srcIn = ni < 0 ? 0.0 : ni;\n    }\n    c.start = s;\n    c.end = e;\n    notifyListeners();\n  }\n\n  /// Slides the whole clip so it starts at [s] (length unchanged).\n  void movePipTo(int i, double s) {\n    if (i < 0 || i >= pipClips.length) return;\n    final c = pipClips[i];\n    final len = c.end - c.start;\n    c.start = s < 0 ? 0.0 : s;\n    c.end = c.start + len;\n    notifyListeners();\n  }\n\n  /// Cuts a clip in two at [t]. False when [t] is too close to an edge.\n  bool splitPipAt(int i, double t) {\n    if (i < 0 || i >= pipClips.length) return false;\n    final c = pipClips[i];\n    if (t <= c.start + kPipMinLen || t >= c.end - kPipMinLen) return false;\n    pushHistory();\n    // PATCH_S194_CUT_FX: a cut is seamless - the tail keeps the look and\n    // timing, neither half fades at the cut (the junction button adds one).\n    final second = c.splitTail(t);\n    c.end = t;\n    c.outAnim = PipAnim.none;\n    pipClips = [...pipClips]..insert(i + 1, second);\n    pipSel = i + 1;\n    notifyListeners();\n    return true;\n  }\n\n  /// [dir] +1 = one layer closer to the front, -1 = one layer back.\n  void movePipLayer(int i, int dir) {\n    final j = i + dir;\n    if (i < 0 || i >= pipClips.length || j < 0 || j >= pipClips.length) return;\n    pushHistory();\n    final next = [...pipClips];\n    final tmp = next[i];\n    next[i] = next[j];\n    next[j] = tmp;\n    pipClips = next;\n    pipSel = j;\n    notifyListeners();\n  }\n\n  bool get hasVideoTransform =>\n      hasVideo &&\n      (videoKeys.isNotEmpty ||\n          (videoScale - 1).abs() > 0.001 ||\n          videoPosX.abs() > 0.001 ||\n          videoPosY.abs() > 0.001 ||\n          videoRot.abs() > 0.05 ||\n          videoOpacity < 0.999);\n\n  VideoXform videoTransformAt(double t) => evalVideoXform(\n        keys: videoKeys,\n        ease: videoKeyEase,\n        scale: videoScale,\n        x: videoPosX,\n        y: videoPosY,\n        rot: videoRot,\n        opacity: videoOpacity,\n        t: t,\n      );\n\n  /// The part of the source video that gets exported (same rules as the exporter).\n  (double, double) videoClipRange() {\n    final ts = trimStart;\n    final te = trimEnd;\n    if (ts != null && te != null) return (ts, te);\n    if (manualTrimSet) {\n      final end = trimManualEnd < 0\n          ? videoDurationSec\n          : (trimManualEnd < videoDurationSec ? trimManualEnd : videoDurationSec);\n      return (trimManualStart, end);\n    }\n    return (0.0, videoDurationSec);\n  }\n\n  /// Write a keyframe at [t]; anything not given keeps its current value.\n  void setKeyAt(double t, {double? scale, double? x, double? y, double? rot}) {\n    pushHistory();\n    final tt = (t * 1000).round() / 1000.0;\n    final cur = videoTransformAt(tt);\n    final k = VideoKey(tt,\n        scale: scale ?? cur.scale, x: x ?? cur.x, y: y ?? cur.y, rot: rot ?? cur.rot);\n    videoKeys.removeWhere((e) => (e.t - tt).abs() < 0.05);\n    videoKeys.add(k);\n    videoKeys.sort((a, b) => a.t.compareTo(b.t));\n    notifyListeners();\n  }\n\n  /// True when a keyframe sits within [tol] seconds of [t].\n  bool hasKeyNear(double t, [double tol = 0.12]) =>\n      videoKeys.any((e) => (e.t - t).abs() <= tol);\n\n  void removeKeyNear(double t, [double tol = 0.12]) {\n    if (!hasKeyNear(t, tol)) return;\n    pushHistory();\n    videoKeys.removeWhere((e) => (e.t - t).abs() <= tol);\n    notifyListeners();\n  }\n\n  void clearVideoKeys() {\n    if (videoKeys.isEmpty) return;\n    pushHistory();\n    videoKeys = [];\n    notifyListeners();\n  }\n\n  void applyCameraMove(CameraMove m) {\n    final (a, b) = videoClipRange();\n    if (b - a < 0.2) return;\n    pushHistory();\n    final (k0, k1) = cameraMoveKeys(m, a, b);\n    videoKeys = [k0, k1];\n    notifyListeners();\n  }\n\n  void resetVideoTransform() {\n    pushHistory();\n    videoScale = 1.0;\n    videoPosX = 0.0;\n    videoPosY = 0.0;\n    videoRot = 0.0;\n    videoOpacity = 1.0;\n    videoKeys = [];\n    notifyListeners();\n  }\n\n\n  // ---- PATCH_S40_MULTI_BG_CYCLE: cycling 2+ preset backgrounds, export-time only ----\n  bool multiBgEnabled = false;\n  List<int> multiBgIndexes = []; // indexes into kBackgrounds, cycle order = selection order\n  BgSwitchTrigger bgSwitchTrigger = BgSwitchTrigger.seconds;\n  int bgSwitchAyahs = 3; // 1..10, needs an active auto-sync timeline\n  int bgSwitchSeconds = 8; // 3..30\n  BgTransitionStyle bgTransitionStyle = BgTransitionStyle.hardCut;\n  double bgCrossfadeDuration = 0.6; // 0.2..3.0s, only used when transition is crossfade\n\n  // ---- PATCH_S34_PLAYER_CONTROLS_TRIM: manual cut (seconds, free-range) ----\n  // Unlike the ayah-boundary trim below, this cuts anywhere. -1 end = unset.\n  double trimManualStart = 0;\n  double trimManualEnd = -1;\n  bool get manualTrimSet =>\n      hasVideo &&\n      trimManualEnd > 0 &&\n      (trimManualStart > 0.05 ||\n          (videoDurationSec > 0 && trimManualEnd < videoDurationSec - 0.05));\n\n  // ---- PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION ----\n  // Manual override for when the ayah text overlay appears/disappears in\n  // the exported clip (seconds, relative to the exported clip\'s own start).\n  // Both null (the default) means "shown for the whole clip", same as before.\n  double? textTimeStartOverride;\n  double? textTimeEndOverride;\n  // ---- PATCH_S160_MULTI_TEXT_TIME_CUES ----\n  // Committed timed texts -- each keeps its own independent [start, end)\n  // window. textTimeStartOverride/textTimeEndOverride above are now just\n  // "the entry currently being typed/edited"; commitTextTimeCue() below\n  // is what actually locks it in as its own cue instead of silently\n  // replacing whatever text+window was set before it.\n  List<TextTimeCue> textTimeCues = [];\n\n  void commitTextTimeCue() {\n    if (textTimeStartOverride == null || textTimeEndOverride == null) return;\n    if (textTimeEndOverride! <= textTimeStartOverride!) return;\n    if (ayahText.trim().isEmpty) return;\n    textTimeCues = [\n      ...textTimeCues,\n      TextTimeCue(\n        text: ayahText,\n        translation: translationText,\n        start: textTimeStartOverride!,\n        end: textTimeEndOverride!,\n      ),\n    ];\n    textTimeStartOverride = null;\n    textTimeEndOverride = null;\n    notifyListeners();\n  }\n\n  void removeTextTimeCueAt(int index) {\n    if (index < 0 || index >= textTimeCues.length) return;\n    final next = [...textTimeCues]..removeAt(index);\n    textTimeCues = next;\n    notifyListeners();\n  }\n\n  // PATCH_S181_CLIPTOUCH: shaping text blocks on the timeline.\n  /// Moves one or both edges of a text block (seconds). The block never gets\n  /// shorter than 0.3 s and never starts before 0.\n  void setTextCueWindow(int index, {double? start, double? end}) {\n    if (index < 0 || index >= textTimeCues.length) return;\n    final c = textTimeCues[index];\n    var s = start ?? c.start;\n    var e = end ?? c.end;\n    if (s < 0) s = 0;\n    if (e - s < 0.3) {\n      if (start != null) {\n        s = e - 0.3;\n      } else {\n        e = s + 0.3;\n      }\n    }\n    if (s < 0) {\n      s = 0;\n      e = 0.3;\n    }\n    c.start = s;\n    c.end = e;\n    notifyListeners();\n  }\n\n  /// Splits a text block in two at [atSec]. False when the point is too close\n  /// to an edge (or outside the block).\n  bool splitTextCueAt(int index, double atSec) {\n    if (index < 0 || index >= textTimeCues.length) return false;\n    final c = textTimeCues[index];\n    if (atSec < c.start + 0.3 || atSec > c.end - 0.3) return false;\n    final second = TextTimeCue(\n        text: c.text, translation: c.translation, start: atSec, end: c.end);\n    c.end = atSec;\n    final next = [...textTimeCues]..insert(index + 1, second);\n    textTimeCues = next;\n    notifyListeners();\n    return true;\n  }\n\n  /// A copy of the block right after it (same length), nudged to start where\n  /// the original ends.\n  void duplicateTextCue(int index) {\n    if (index < 0 || index >= textTimeCues.length) return;\n    final c = textTimeCues[index];\n    final len = c.end - c.start;\n    final copy = TextTimeCue(\n        text: c.text,\n        translation: c.translation,\n        start: c.end,\n        end: c.end + len);\n    final next = [...textTimeCues]..insert(index + 1, copy);\n    textTimeCues = next;\n    notifyListeners();\n  }\n\n  // PATCH_S183_TEXT_BAR: the window (begin / stop) of the typed text. Both ends\n  // are always set together, because the exporter only honours the window when\n  // it has both. [dur] is the clip length in seconds.\n  void setTextWindow(double dur, {double? start, double? end}) {\n    if (dur <= 0.3) return;\n    var s = start ?? textTimeStartOverride ?? 0.0;\n    var e = end ?? textTimeEndOverride ?? dur;\n    s = s < 0.0 ? 0.0 : (s > dur ? dur : s);\n    e = e < 0.0 ? 0.0 : (e > dur ? dur : e);\n    if (e - s < 0.3) {\n      if (start != null) {\n        s = e - 0.3 < 0.0 ? 0.0 : e - 0.3;\n        if (e - s < 0.3) e = s + 0.3;\n      } else {\n        e = s + 0.3 > dur ? dur : s + 0.3;\n        if (e - s < 0.3) s = e - 0.3;\n      }\n    }\n    textTimeStartOverride = s;\n    textTimeEndOverride = e;\n    notifyListeners();\n  }\n\n  void clearTextWindow() {\n    textTimeStartOverride = null;\n    textTimeEndOverride = null;\n    notifyListeners();\n  }\n  // PATCH_S145_SCROLL_WORDCOLOR_FONTS_GLOW: word index (into\n  // state.ayahText.split(RegExp(r\'\\s+\'))) -> the color that word is\n  // drawn in instead of the normal text color. Was a Set<int> that only\n  // ever meant "red"; now any color, chosen from the same picker every\n  // other color field in this app already uses (showAyatColorPicker) or\n  // one of the quick swatches next to the word chips. Cleared whenever\n  // setAyah()/applyStageTextEdit() changes the underlying words, same\n  // as redWordIndices always was.\n  Map<int, Color> wordColors = {};\n  // The color the next tapped word gets. Defaults to the old hardcoded\n  // red so existing habits (tap a word, it turns red) keep working\n  // exactly as before unless a different color is deliberately picked.\n  Color activeWordColor = const Color(0xFFE53935);\n  // Optional extra line (reciter/sheikh name, ayah-range label, ...) drawn\n  // near the top or bottom of the frame, independent of the ayah text.\n  String captionText = \'\';\n  CaptionPosition captionPosition = CaptionPosition.bottom;\n\n  // ---- background ----\n  int bgIndex = 0;\n  bool useCustomBg = false;\n  String? customBgPath;\n  // PATCH_S82_CUSTOM_BG_LIBRARY: every uploaded background is kept here,\n  // uncapped -- no limit on how many. customBgPath just points at whichever\n  // one is currently active.\n  List<String> customBgLibrary = [];\n  bool bgAnimated = true; // PATCH_S29_BG_ANIMATION_TOGGLE: animated sheen on/off (preset backgrounds only)\n\n  // ---- PATCH_S32_AI_ART_NANO_BANANA: AI art background ----\n  bool aiArtEnabled = false;\n  bool aiArtBusy = false;\n  // PATCH_S87_AI_ART_ONE_TAP_FLOW: batch generation for the whole\n  // auto-sync segment, tracked separately from the single-ayah\n  // aiArtBusy above so the two flows never fight over one spinner.\n  bool aiArtBatchBusy = false;\n  String? aiArtBatchProgress;\n  int? _aiArtSurah;\n  int? _aiArtAyahNum;\n  String? _aiArtAyahText;\n  int _aiArtSeedOffset = 0;\n  bool get hasAiArt => useCustomBg && aiArtEnabled && _aiArtSurah != null;\n  // PATCH_S69_AI_ART_FIX: surfaced to the UI instead of failing silently.\n  String? aiArtError;\n  // Tracked on EVERY match regardless of aiArtEnabled, so a manual\n  // generate works even if the toggle was flipped on after the match\n  // already happened (previously: no context, silent no-op).\n  int? _lastMatchedSurah;\n  int? _lastMatchedAyahNum;\n  String? _lastMatchedAyahText;\n  // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART: the ayah\'s English meaning,\n  // kept alongside the Arabic so AI art can describe the actual scene.\n  String? _lastMatchedAyahEn;\n  // PATCH_S80_POLLINATIONS_KEYLESS_FLUX: the S69b hardcoded key is removed.\n  // It was a *secret* sk_ key baked into a public APK and committed to git\n  // history, which was never a safe place for it, and it\'s no longer\n  // needed since Flux generation works fully keyless. Default is empty;\n  // Settings can still set a personal key later for higher limits.\n  // IMPORTANT: treat the old key as burned regardless of this patch --\n  // rotate/revoke it at enter.pollinations.ai since it was already exposed.\n  String pollinationsApiKey = \'\';\n\n  // ---- chroma key ----\n  bool chromaEnabled = false;\n  Color chromaColor = const Color(0xFF00FF00);\n  int chromaThreshold = 90; // same 40..140 scale as the HTML sliders\n  int chromaSoftness = 45; // 10..90\n\n  // ---- reciters ----\n  int reciterIndex = 0;\n  final List<String?> reciterAudioPaths = List.filled(kReciters.length, null);\n  String? get selectedReciterAudio => reciterAudioPaths[reciterIndex];\n\n  // ---- text formatting ----\n  int templateIndex = 0;\n  // PATCH_S100_FONTS_SPINSTAR_TINT: DigitalMadina is now the bundled default font\n  // (Elgharib was the default from S46 through S99).\n  String fontKey = \'digitalmadina\';\n  final List<AyahFontChoice> customFonts = [];\n  double ayahFontSize = 20; // 14..30, preview-relative like the HTML slider\n  double transFontSize = 12; // 9..18\n  Color textColor = const Color(0xFFECE2CB);\n  AyahTextPosition textPosition = AyahTextPosition.bottom;\n  FrameExtra extra = FrameExtra.none;\n  bool showTranslation = true;\n  // PATCH_S46_DEFAULT_FONT_AND_GLOW: glow on/off + intensity, applies to karaoke lit words\n  // and, when on, to static (non-karaoke) ayah text too.\n  bool glowEnabled = true;\n  double glowIntensity = 1.0; // 0..1.5\n  // PATCH_S48_TEXT_SPACING_TOGGLES\n  double letterSpacing = 0; // -1..3\n  double lineHeightMultiplier = 1.5; // 1.2..2.2, previous hardcoded value\n  // PATCH_S128: pro editor + selection fields\n  bool textBorderEnabled = false;\n  double textBorderWidth = 6;\n  bool shadowEnabled = true;\n  double shadowDistance = 10;\n  double shadowBlur = 20;\n  bool labelEnabled = false;\n  S128LabelShape labelShape = S128LabelShape.rounded;\n  Color labelColor = const Color(0xFF000000);\n  double labelOpacity = 0.65;\n  double overallOpacity = 1.0;\n  bool unifiedOneLine = false;\n  List<Color> favoriteColors = [\n    const Color(0xFFFFFFFF), const Color(0xFFF3E5C0), const Color(0xFFD4A94E),\n    const Color(0xFF8A6B3F), const Color(0xFF5C4033), const Color(0xFF000000)];\n  List<String> unifiedTexts = const [];\n  bool stageTextSelected = false;\n  // PATCH_S181_CLIPTOUCH: touching the text on the stage dresses the stage in\n  // its روح (Ayah Mood) by itself. Switch lives in the روح card.\n  bool autoRuhOnTouch = true;\n  // PATCH_S133_STAGE_TEXT_SELECT_EDIT: which TimelineSegment the selection\n  // box on the stage is currently around -- null while stageTextSelected\n  // is showing the statically-picked ayah (no auto-sync timeline playing,\n  // or playback is between segments) rather than a live timeline part.\n  TimelineSegment? selectedSegment;\n\n  void selectStageText([TimelineSegment? segment]) {\n    stageTextSelected = true;\n    selectedSegment = segment;\n    notifyListeners();\n  }\n\n  void clearStageSelection() {\n    if (!stageTextSelected && selectedSegment == null) return;\n    stageTextSelected = false;\n    selectedSegment = null;\n    notifyListeners();\n  }\n\n  /// Writes a correction back to whichever text is currently selected on\n  /// the stage: the segment\'s textOverride during auto-sync playback --\n  /// buildKaraokeChunks() already reads textOverride ahead of ayah.ar, so\n  /// the live karaoke preview and the exporter both pick this up with no\n  /// further wiring -- or ayahText when nothing from the timeline is\n  /// selected (the statically-picked ayah).\n  void applyStageTextEdit(String newText) {\n    final trimmed = newText.trim();\n    if (trimmed.isEmpty) return;\n    pushHistory();\n    if (selectedSegment != null) {\n      selectedSegment!.textOverride = trimmed;\n    } else {\n      ayahText = trimmed;\n      // PATCH_S133_STAGE_TEXT_SELECT_EDIT: a hand correction can change the\n      // word count/order -- a previous word-color selection almost never\n      // still lines up (same reasoning as setAyah()).\n      wordColors = {};\n    }\n    notifyListeners();\n  }\n  // PATCH_S128_FIX1_BUILD_ERRORS: fields the S128 glow tab/settings persistence needed\n  double glowSize = 20;      // 0..60, see text_editor_pro.dart GLOW tab\n  double glowSharpness = 50; // 0..100\n  void saveStyleAsDefault() { notifyListeners(); }\n\n  // PATCH_S50_DRAGGABLE_TEXT: user drag/pinch on the stage preview, on top of the\n  // textPosition preset + ayahFontSize/transFontSize sliders above.\n  // textOffset is stored in 270-wide reference units (same convention\n  // as ayahFontSize etc.) so preview and export can both multiply it\n  // by their own `scale = width / 270.0` and land on the same spot.\n  Offset textOffset = Offset.zero;\n  double textUserScale = 1.0; // 0.6..1.8, pinch-to-resize multiplier\n\n  // ---- intro / outro cards ----\n  bool showIntro = false;\n  bool showOutro = false;\n  String outroText = kDefaultOutro;\n\n  // ---- PATCH_S43_MODEL_SIZE_PICKER: which Whisper tier drives detection/auto-sync ----\n  // PATCH_S76_QURAN_MODEL_DEFAULT: default is now the Quran-tuned tier (S66),\n  // not generic-speech `small` -- see whisper_service.dart for why this is\n  // safe even if that tier\'s asset isn\'t published yet (S75 fallback).\n  WhisperModelSize whisperModelSize = WhisperModelSize.quranTuned;\n\n  // ---- auto-sync timeline ----\n  List<TimelineSegment> timeline = [];\n  bool timelineActive = false;\n  // PATCH_S51_KARAOKE_TOGGLE: word-by-word highlight while الشيخ recites,\n  // on by default (matches previous always-on behavior). Off falls back\n  // to showing each ayah part as plain static text.\n  bool karaokeEnabled = true;\n  // PATCH_S156_LONG_AYAH_SPLIT_CONTROL: whether long ayat get split into\n  // sequential on-screen parts at all. On by default (matches previous\n  // always-split behavior). This is independent of karaokeEnabled above,\n  // which only ever controlled the per-word lighting, not the splitting.\n  bool splitLongAyahsEnabled = true;\n  // PATCH_S156_LONG_AYAH_SPLIT_CONTROL: word-count threshold above which\n  // an ayah is split, when splitLongAyahsEnabled is on. 12 matches\n  // karaoke.dart\'s kKaraokeMaxWordsPerChunk, the previous fixed value.\n  int maxWordsPerChunk = 12;\n\n  // PATCH_S82_AUTOSYNC_MAX: the segment playing at clip-time [t], if any —\n  // shared by the karaoke ticker, the loop-one-ayah control and the ribbon.\n  TimelineSegment? segmentAt(double t) {\n    for (final s in timeline) {\n      if (t >= s.start && t < s.end) return s;\n    }\n    return null;\n  }\n\n  // PATCH_S82_AUTOSYNC_MAX: how much of the clip the detected timeline\n  // covers (for the post-scan summary).\n  // PATCH_S90_HONEST_COVERAGE: the real decoded audio duration from the\n  // last scan -- set by TimelineBuilder.build(), which measures it from\n  // actual decoded PCM rather than a container header or the video\n  // player\'s own (frequently absent, for audio-only files) duration.\n  double detectedAudioDurationSec = 0;\n\n  double timelineCoverageFraction() {\n    if (timeline.isEmpty) return 0;\n    // PATCH_S90_HONEST_COVERAGE: prefer the real decoded duration. Falling\n    // back to timeline.last.end (the old behavior when videoDurationSec\n    // was 0, which is the common case for audio-only files) made coverage\n    // self-referential -- it could never report under-coverage because the\n    // denominator moved with whatever got detected.\n    final total = detectedAudioDurationSec > 0\n        ? detectedAudioDurationSec\n        : (videoDurationSec > 0 ? videoDurationSec : timeline.last.end);\n    if (total <= 0) return 0;\n    var covered = 0.0;\n    for (final s in timeline) {\n      covered += s.end - s.start;\n    }\n    return (covered / total).clamp(0.0, 1.0);\n  }\n\n  // PATCH_S88_AUTOSYNC_HONEST_FIX: mean confidence across the detected\n  // timeline -- surfaced in the post-scan summary so a shaky scan reads\n  // as shaky instead of a plain, encouraging-looking list of ayat.\n  double timelineAverageConfidence() {\n    if (timeline.isEmpty) return 0;\n    final total = timeline.fold<double>(0, (sum, s) => sum + s.confidence);\n    return total / timeline.length;\n  }\n\n  // ---- trim (ayah-boundary indexes into [timeline], -1 = whole clip) ----\n  int trimFromIndex = -1;\n  int trimToIndex = -1;\n  double? get trimStart =>\n      (trimFromIndex >= 0 && trimToIndex >= 0) ? timeline[trimFromIndex].start : null;\n  double? get trimEnd =>\n      (trimFromIndex >= 0 && trimToIndex >= 0) ? timeline[trimToIndex].end : null;\n\n  // ---- output ----\n  // PATCH_S53_LANDSCAPE_EXPORT: was `bool squareRatio` (9:16 vs. 1:1 only); story916 is the\n  // same default the old `false` gave.\n  AyatAspectRatio aspectRatio = AyatAspectRatio.story916;\n\n  // ---- PATCH_S125_CUSTOM_ASPECT ----\n  /// Frame size used when [aspectRatio] is [AyatAspectRatio.custom]. Kept as\n  /// real pixel dimensions rather than a ratio so what the user types is\n  /// exactly what the encoder gets.\n  int customAspectW = 1080;\n  int customAspectH = 1920;\n\n  /// The exported frame size, whichever ratio is selected. Both are forced\n  /// even: H.264 4:2:0 chroma subsampling cannot represent an odd dimension,\n  /// and libx264 fails outright on one.\n  (int, int) get frameSize {\n    if (aspectRatio == AyatAspectRatio.custom) {\n      final w = customAspectW.clamp(240, 3840);\n      final h = customAspectH.clamp(240, 3840);\n      return (w - (w % 2), h - (h % 2));\n    }\n    final preset = kAspectRatios.firstWhere((r) => r.$1 == aspectRatio);\n    return (preset.$3, preset.$4);\n  }\n\n  // ---- PATCH_S126_TEXT_TRANSITIONS ----\n  /// How the ayah text arrives and leaves. Separate in/out so an ayah can\n  /// rise in and simply fade out, which is the combination most people\n  /// actually want.\n  TextTransition textInTransition = TextTransition.riseFade;\n  TextTransition textOutTransition = TextTransition.fade;\n\n  /// Length of each transition in milliseconds. Longer reads as calmer;\n  /// this is the single biggest lever on whether text feels smooth.\n  int textTransitionMs = 550;\n\n  bool get hasTextTransition =>\n      textInTransition != TextTransition.none ||\n      textOutTransition != TextTransition.none;\n\n  // ---- PATCH_S125_SPEED ----\n  /// Export speed multiplier. 1.0 is untouched; below 1 is slow motion,\n  /// above 1 speeds the clip up. Applied to picture, the clip\'s own audio and\n  /// the synced ayah overlay together, so nothing drifts out of step.\n  ///\n  /// An attached reciter track is deliberately NOT retimed -- pitching up a\n  /// recitation is not something this app will do to someone\'s tilawa.\n  double playbackSpeed = 1.0; // 0.25 .. 4.0\n  bool get hasSpeedChange => (playbackSpeed - 1.0).abs() > 0.005;\n\n  // ---- PATCH_S125_SUBTITLES ----\n  /// Write an .srt/.vtt next to the exported MP4. Off by default: most\n  /// exports are for platforms that burn in their own captions.\n  bool exportSubtitles = false;\n  SubtitleFormat subtitleFormat = SubtitleFormat.srt;\n  SubtitleContent subtitleContent = SubtitleContent.arabic;\n  int staticDurationSec = 6; // export length when no video is loaded (2..60)\n\n  List<AyahFontChoice> get allFonts => [...kBuiltInFonts, ...customFonts];\n\n  void setAyah(String ar, String en, String label,\n      {String confidenceText = \'\', int? surahNum, int? ayahNum}) {\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    ayahText = ar;\n    translationText = en;\n    // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION: a previous ayah\'s\n    // word-color selection almost never lines up with the new ayah\'s word\n    // count/order.\n    wordColors = {};\n    detectedLabel = label;\n    matchConfidenceText = confidenceText;\n    notifyListeners();\n    // PATCH_S32_AI_ART_NANO_BANANA: only ayat resolved against the real corpus carry a\n    // surah/ayah number -- free-typed unmatched text is skipped since\n    // there is nothing reliable to cache the art against.\n    // PATCH_S69_AI_ART_FIX: track the match UNCONDITIONALLY (not just when\n    // aiArtEnabled happened to already be on) so a later manual\n    // generateAiArtNow() always has something to work from.\n    if (surahNum != null && ayahNum != null) {\n      _lastMatchedSurah = surahNum;\n      _lastMatchedAyahNum = ayahNum;\n      _lastMatchedAyahText = ar;\n      _lastMatchedAyahEn = en; // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n    }\n    if (aiArtEnabled && surahNum != null && ayahNum != null) {\n      _aiArtSeedOffset = 0;\n      _generateAiArt(surahNum, ayahNum, ar, en);\n    }\n  }\n\n  // PATCH_S32_AI_ART_NANO_BANANA\n  Future<void> _generateAiArt(\n      int surahNum, int ayahNum, String arText, String enText) async {\n    _aiArtSurah = surahNum;\n    _aiArtAyahNum = ayahNum;\n    _aiArtAyahText = arText;\n    aiArtBusy = true;\n    aiArtError = null; // PATCH_S69_AI_ART_FIX\n    notifyListeners();\n    try {\n      final path = await AiArtService.artFor(\n        surahNum: surahNum,\n        ayahNum: ayahNum,\n        ayahArabic: arText,\n        ayahEnglish: enText, // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n        seedOffset: _aiArtSeedOffset,\n      );\n      if (path != null) {\n        useCustomBg = true;\n        customBgPath = path;\n      }\n    } on AiArtException catch (e) {\n      aiArtError = e.message;\n    } catch (e) {\n      aiArtError = \'تعذر توليد الفن: $e\';\n    } finally {\n      aiArtBusy = false;\n      notifyListeners();\n    }\n  }\n\n  // PATCH_S32_AI_ART_NANO_BANANA: manual regenerate -- bumps the seed instead of touching\n  // anything paid; no-ops quietly if there is no current ayah to redo.\n  Future<void> regenerateAiArt() async {\n    if (_aiArtSurah == null || _aiArtAyahNum == null || _aiArtAyahText == null) {\n      return;\n    }\n    _aiArtSeedOffset += 1;\n    await _generateAiArt(_aiArtSurah!, _aiArtAyahNum!, _aiArtAyahText!,\n        _lastMatchedAyahEn ?? \'\'); // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n  }\n\n  // PATCH_S84_AI_ART_FOLLOWS_PLAYBACK: called every karaoke tick with the\n  // ayah currently being recited. "فن لكل آية" used to only fire on the\n  // one-shot detection paths (setAyah) -- during auto-sync playback the\n  // background never changed. Now each ayah\'s art generates as the reciter\n  // reaches it and swaps in via the existing S51 background crossfade.\n  // Cheap to call at 10Hz: the attempt-dedupe below means one real\n  // generation per ayah (success OR failure -- no retry spam), and cached\n  // art returns without touching the network.\n  int? _artAttemptSurah;\n  int? _artAttemptAyah;\n  void ensureArtForPlayback(Ayah ayah) {\n    if (!aiArtEnabled || aiArtBusy) return;\n    if (_artAttemptSurah == ayah.surahNum && _artAttemptAyah == ayah.num) {\n      return;\n    }\n    _artAttemptSurah = ayah.surahNum;\n    _artAttemptAyah = ayah.num;\n    _lastMatchedSurah = ayah.surahNum;\n    _lastMatchedAyahNum = ayah.num;\n    _lastMatchedAyahText = ayah.ar;\n    _lastMatchedAyahEn = ayah.en; // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n    _aiArtSeedOffset = 0;\n    _generateAiArt(ayah.surahNum, ayah.num, ayah.ar, ayah.en);\n    _prefetchNextArt(ayah); // PATCH_S163_AI_ART_SPEED\n  }\n\n  // PATCH_S163_AI_ART_SPEED: warm the NEXT distinct ayah\'s art while this one\n  // plays, so the crossfade finds it already on disk. Fire-and-forget.\n  void _prefetchNextArt(Ayah current) {\n    var seenCurrent = false;\n    for (final seg in timeline) {\n      final a = seg.ayah;\n      if (a.surahNum == current.surahNum && a.num == current.num) {\n        seenCurrent = true;\n        continue;\n      }\n      if (seenCurrent) {\n        AiArtService.artFor(\n          surahNum: a.surahNum,\n          ayahNum: a.num,\n          ayahArabic: a.ar,\n          ayahEnglish: a.en,\n        ).then((_) {}, onError: (_) {});\n        return;\n      }\n    }\n  }\n\n  // PATCH_S69_AI_ART_FIX: standalone manual entry point -- works from whatever ayah\n  // was last matched, with a real, visible error instead of the old\n  // silent no-op when there\'s no context yet.\n  Future<void> generateAiArtNow() async {\n    if (_lastMatchedSurah == null ||\n        _lastMatchedAyahNum == null ||\n        _lastMatchedAyahText == null) {\n      aiArtError = \'اختر آية أولًا (بالتعرف التلقائي أو من المصحف) قبل توليد الفن\';\n      notifyListeners();\n      return;\n    }\n    _aiArtSeedOffset = 0;\n    await _generateAiArt(_lastMatchedSurah!, _lastMatchedAyahNum!,\n        _lastMatchedAyahText!,\n        _lastMatchedAyahEn ?? \'\'); // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n  }\n\n  // PATCH_S87_AI_ART_ONE_TAP_FLOW: one tap generates + caches art for the\n  // first [_aiArtBatchMax] unique ayat of the active auto-sync timeline\n  // (in timeline order), switches the background to the first one, and\n  // leaves aiArtEnabled on so the existing playback path (S84) swaps each\n  // ayah\'s art in from the now-warm cache as the reciter reaches it --\n  // no separate "follow-along" flag needed, ensureArtForPlayback already\n  // does that whenever aiArtEnabled is true. artFor() is itself\n  // cache-checked, so re-running this after a partial success only retries\n  // whatever didn\'t finish, and never re-hits the network for ayat that\n  // already have art.\n  static const int _aiArtBatchMax = 10; // PATCH_S163: was 6 (parallel now)\n  Future<void> generateArtForTimelineBatch() async {\n    if (aiArtBatchBusy || aiArtBusy) return;\n    if (timeline.isEmpty) {\n      aiArtError = \'شغّل المزامنة التلقائية أولًا لرصد آيات المقطع\';\n      notifyListeners();\n      return;\n    }\n    final seen = <String>{};\n    final targets = <Ayah>[];\n    for (final seg in timeline) {\n      final key = \'${seg.ayah.surahNum}:${seg.ayah.num}\';\n      if (seen.add(key)) {\n        targets.add(seg.ayah);\n        if (targets.length >= _aiArtBatchMax) break;\n      }\n    }\n\n    aiArtBatchBusy = true;\n    aiArtBatchProgress = null;\n    aiArtError = null;\n    notifyListeners();\n    var ok = 0;\n    try {\n      // PATCH_S163_AI_ART_SPEED: every target starts at once; AiArtService\n      // gates real network concurrency itself (2, or 1 after a 429). The first\n      // ayah\'s art still takes over the background the moment it lands.\n      var done = 0;\n      await Future.wait([\n        for (var i = 0; i < targets.length; i++)\n          () async {\n            final ayah = targets[i];\n            try {\n              final path = await AiArtService.artFor(\n                surahNum: ayah.surahNum,\n                ayahNum: ayah.num,\n                ayahArabic: ayah.ar,\n                ayahEnglish: ayah.en, // PATCH_S89_EXPORT_DURATION_AND_SCENE_ART\n              );\n              if (path != null) {\n                ok++;\n                if (i == 0) {\n                  useCustomBg = true;\n                  customBgPath = path;\n                  _aiArtSurah = ayah.surahNum;\n                  _aiArtAyahNum = ayah.num;\n                  _aiArtAyahText = ayah.ar;\n                  _aiArtSeedOffset = 0;\n                  _lastMatchedSurah = ayah.surahNum;\n                  _lastMatchedAyahNum = ayah.num;\n                  _lastMatchedAyahText = ayah.ar;\n                  _lastMatchedAyahEn = ayah.en;\n                }\n              }\n            } on AiArtException catch (e) {\n              aiArtError = e.message; // last error stays visible if all fail\n            } catch (e) {\n              aiArtError = \'تعذر توليد الفن: $e\';\n            }\n            done++;\n            aiArtBatchProgress = \'تم $done من ${targets.length}…\';\n            notifyListeners();\n          }(),\n      ]);\n      if (ok == 0) {\n        aiArtError ??= \'تعذر توليد الفن لأي من آيات المقطع\';\n        aiArtBatchProgress = null;\n      } else if (ok < targets.length) {\n        aiArtError = null;\n        aiArtBatchProgress =\n            \'تم توليد فن $ok من ${targets.length} آيات — البقية ستُحاول تلقائيًا أثناء التشغيل\';\n      } else {\n        aiArtError = null;\n        aiArtBatchProgress = null;\n      }\n    } finally {\n      aiArtBatchBusy = false;\n      notifyListeners();\n    }\n  }\n\n  // PATCH_S51_AI_ART_DELETE: wipes every cached file for this ayah from\n  // disk (so a later visit regenerates fresh instead of silently reusing\n  // the deleted one) and drops the current custom background back to the\n  // preset gradients. Leaves aiArtEnabled untouched -- this deletes what\n  // was made, it doesn\'t turn the feature off (use the switch for that).\n  Future<void> deleteAiArt() async {\n    if (_aiArtSurah == null || _aiArtAyahNum == null) return;\n    await AiArtService.deleteCached(_aiArtSurah!, _aiArtAyahNum!);\n    useCustomBg = false;\n    customBgPath = null;\n    _aiArtSeedOffset = 0;\n    // PATCH_S84_AI_ART_FOLLOWS_PLAYBACK: let the playback path regenerate\n    // this ayah\'s art instead of the dedupe treating it as already tried.\n    _artAttemptSurah = null;\n    _artAttemptAyah = null;\n    notifyListeners();\n  }\n\n  void setVideo(String path) {\n    videoPath = path;\n    // A new video invalidates any previously detected timeline/trim range.\n    timeline = [];\n    timelineActive = false;\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    // PATCH_S34_PLAYER_CONTROLS_TRIM: and any manual cut from the old clip.\n    videoDurationSec = 0;\n    // PATCH_S90_HONEST_COVERAGE: the old scan\'s real decoded duration is\n    // meaningless for a new file too.\n    detectedAudioDurationSec = 0;\n    trimManualStart = 0;\n    trimManualEnd = -1;\n    // PATCH_S54_PRO_EXPORT_CONTROLS: rotation/mirror are per-clip fixes.\n    videoRotationQuarterTurns = 0;\n    videoMirror = false;\n    // PATCH_S180_TRANSFORM: the transform is per clip too.\n    videoScale = 1.0;\n    videoPosX = 0.0;\n    videoPosY = 0.0;\n    videoRot = 0.0;\n    videoOpacity = 1.0;\n    videoKeys = [];\n    notifyListeners();\n  }\n\n  void setTimeline(List<TimelineSegment> segments) {\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    timeline = segments;\n    timelineActive = segments.isNotEmpty;\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n  }\n\n  // PATCH_S36_TIMELINE_EDITOR: remove one wrongly detected segment. The trim\n  // range indexes into [timeline], so it resets rather than dangle.\n  // PATCH_S83_SYNC_QOL: returns the removed segment so the UI can offer undo.\n  TimelineSegment? removeTimelineSegment(int index) {\n    if (index < 0 || index >= timeline.length) return null;\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    final removed = timeline.removeAt(index);\n    timelineActive = timeline.isNotEmpty;\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n    return removed;\n  }\n\n  // PATCH_S83_SYNC_QOL: undo of removeTimelineSegment — puts the segment\n  // back where it was. Trim indexes reset for the same dangling reason.\n  void insertTimelineSegment(int index, TimelineSegment segment) {\n    timeline.insert(index.clamp(0, timeline.length), segment);\n    timelineActive = true;\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n  }\n\n  // PATCH_S36_TIMELINE_EDITOR: nudge a segment\'s start/end by [startDelta]/\n  // [endDelta] seconds. A segment keeps at least 0.3s of length, and moving\n  // an edge past a neighbour pulls the neighbour\'s shared boundary along\n  // (detected boundaries are shared after normalization, so this behaves\n  // like dragging the cut point between two ayat).\n  void nudgeTimelineSegment(int index,\n      {double startDelta = 0, double endDelta = 0}) {\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    if (index < 0 || index >= timeline.length) return;\n    final seg = timeline[index];\n    if (startDelta != 0) {\n      final floor = index > 0 ? timeline[index - 1].start + 0.3 : 0.0;\n      seg.start = (seg.start + startDelta).clamp(floor, seg.end - 0.3);\n      if (index > 0 && timeline[index - 1].end > seg.start) {\n        timeline[index - 1].end = seg.start;\n      }\n    }\n    if (endDelta != 0) {\n      final ceil = index + 1 < timeline.length\n          ? timeline[index + 1].end - 0.3\n          : (videoDurationSec > 0 ? videoDurationSec : double.infinity);\n      seg.end = (seg.end + endDelta).clamp(seg.start + 0.3, ceil);\n      if (index + 1 < timeline.length &&\n          timeline[index + 1].start < seg.end) {\n        timeline[index + 1].start = seg.end;\n      }\n    }\n    notifyListeners();\n  }\n\n  // PATCH_S49_MANUAL_SEGMENTS_MERGE: append a segment the user placed by hand -- keeps\n  // [timeline] sorted by start time since playback/tick logic assumes\n  // ascending order.\n  void addManualSegment(Ayah ayah, double start, double end,\n      {String? textOverride}) {\n    final seg = TimelineSegment(\n        start: start,\n        end: end,\n        ayah: ayah,\n        confidence: 1.0,\n        // PATCH_S118_PARTIAL_AYAH_TIMELINE_MERGE\n        textOverride: textOverride);\n    final idx = timeline.indexWhere((s) => s.start > start);\n    if (idx == -1) {\n      timeline.add(seg);\n    } else {\n      timeline.insert(idx, seg);\n    }\n    timelineActive = true;\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n  }\n\n  // PATCH_S86_TIMELINE_EDITING: split segment [index] at [atSec] (clip\n  // seconds) — the inverse of mergeTimelineSegments, for when one detected\n  // span actually covers two ayat. Both halves keep the ayah and\n  // confidence; relabel the wrong half with [changeSegmentAyah]. Word\n  // onsets are divided by time so karaoke pacing survives on both sides.\n  // Returns false when [atSec] isn\'t usable (outside, or too close to an\n  // edge to leave two real segments).\n  bool splitTimelineSegment(int index, double atSec) {\n    if (index < 0 || index >= timeline.length) return false;\n    final seg = timeline[index];\n    if (atSec < seg.start + 0.3 || atSec > seg.end - 0.3) return false;\n    final first = TimelineSegment(\n      start: seg.start,\n      end: atSec,\n      ayah: seg.ayah,\n      confidence: seg.confidence,\n      wordStarts: [for (final s in seg.wordStarts) if (s < atSec) s],\n      inferred: seg.inferred,\n    );\n    final second = TimelineSegment(\n      start: atSec,\n      end: seg.end,\n      ayah: seg.ayah,\n      confidence: seg.confidence,\n      wordStarts: [for (final s in seg.wordStarts) if (s >= atSec) s],\n      inferred: seg.inferred,\n    );\n    timeline\n      ..removeAt(index)\n      ..insert(index, first)\n      ..insert(index + 1, second);\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n    return true;\n  }\n\n  // PATCH_S86_TIMELINE_EDITING: relabel a detection with the RIGHT ayah\n  // while keeping its (already reviewed) timing — beats delete + manual\n  // re-add, which loses the tuned boundaries. Confidence becomes 1.0: the\n  // user just told us what this span is. Word onsets stay — they describe\n  // the audio, not the label. The inferred flag clears for the same reason.\n  void changeSegmentAyah(int index, Ayah ayah) {\n    if (index < 0 || index >= timeline.length) return;\n    final seg = timeline[index];\n    timeline[index] = TimelineSegment(\n      start: seg.start,\n      end: seg.end,\n      ayah: ayah,\n      confidence: 1.0,\n      // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE: seg.wordStarts are\n      // Whisper onsets measured against the OLD (wrong) ayah\'s words --\n      // carrying them into a different ayah desyncs karaoke lighting\n      // (wrong word count, wrong text). Drop them; karaoke.dart\'s\n      // letter-weighted fallback paces the new ayah honestly instead.\n      wordStarts: const [],\n    );\n    notifyListeners();\n  }\n\n  // PATCH_S49_MANUAL_SEGMENTS_MERGE: merge segment [index] with the next one -- for when\n  // auto-sync splits one continuous recited ayah (elongated/مجود\n  // recitation) across two detected windows. Keeps whichever ayah had\n  // the higher confidence; caller decides when offering this makes sense.\n  void mergeTimelineSegments(int index) {\n    if (index < 0 || index + 1 >= timeline.length) return;\n    final a = timeline[index];\n    final b = timeline[index + 1];\n    final merged = TimelineSegment(\n      start: a.start,\n      end: b.end,\n      ayah: a.confidence >= b.confidence ? a.ayah : b.ayah,\n      confidence: (a.confidence + b.confidence) / 2,\n    );\n    timeline[index] = merged;\n    timeline.removeAt(index + 1);\n    trimFromIndex = -1;\n    trimToIndex = -1;\n    notifyListeners();\n  }\n\n  void applyTemplate(int index) {\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    templateIndex = index;\n    final t = kTemplates[index];\n    fontKey = t.fontKey;\n    textColor = t.color;\n    textPosition = t.pos;\n    extra = t.extra;\n    notifyListeners();\n  }\n\n  void update(void Function() mutate) {\n    pushHistory(); // PATCH_S56_UNDO_REDO\n    mutate();\n    notifyListeners();\n  }\n\n  // ---- PATCH_S56_UNDO_REDO: tester-requested undo/redo -------------------\n  // Snapshot-based: before every edit a snapshot of the editable state is\n  // pushed (coalesced to one step per 800ms so a slider drag is a single\n  // undo step, not fifty). Media files themselves (video/model downloads)\n  // are not part of history — only the edit decisions about them.\n  static const int _maxHistory = 40;\n  final List<Map<String, Object?>> _undoStack = [];\n  final List<Map<String, Object?>> _redoStack = [];\n  DateTime _lastPush = DateTime.fromMillisecondsSinceEpoch(0);\n  bool _restoring = false;\n  bool get canUndo => _undoStack.isNotEmpty;\n  bool get canRedo => _redoStack.isNotEmpty;\n\n  Map<String, Object?> _capture() => {\n        \'timeline\': [\n          for (final s in timeline)\n            TimelineSegment(\n                start: s.start,\n                end: s.end,\n                ayah: s.ayah,\n                confidence: s.confidence,\n                wordStarts: List.of(s.wordStarts),\n                // PATCH_S133_STAGE_TEXT_SELECT_EDIT: undo/redo rebuilds the\n                // timeline from this snapshot -- without carrying these\n                // over, a stage-text correction (or an inferred-gap flag)\n                // would silently vanish on the next unrelated undo/redo.\n                inferred: s.inferred,\n                textOverride: s.textOverride),\n        ],\n        \'timelineActive\': timelineActive,\n        \'trimFromIndex\': trimFromIndex,\n        \'trimToIndex\': trimToIndex,\n        \'trimManualStart\': trimManualStart,\n        \'trimManualEnd\': trimManualEnd,\n        \'ayahText\': ayahText,\n        \'translationText\': translationText,\n        \'detectedLabel\': detectedLabel,\n        \'matchConfidenceText\': matchConfidenceText,\n        \'fontKey\': fontKey,\n        \'ayahFontSize\': ayahFontSize,\n        \'transFontSize\': transFontSize,\n        \'textColor\': textColor,\n        \'textPosition\': textPosition,\n        \'extra\': extra,\n        \'showTranslation\': showTranslation,\n        \'templateIndex\': templateIndex,\n        \'bgIndex\': bgIndex,\n        \'useCustomBg\': useCustomBg,\n        \'customBgPath\': customBgPath,\n        \'bgAnimated\': bgAnimated,\n        \'effect\': effect,\n        \'videoFx\': videoFx, // PATCH_S194_CUT_FX\n        \'effectIntensity\': effectIntensity,\n        \'glowEnabled\': glowEnabled,\n        \'glowIntensity\': glowIntensity,\n        \'letterSpacing\': letterSpacing,\n        \'lineHeightMultiplier\': lineHeightMultiplier,\n        \'textOffset\': textOffset,\n        \'textUserScale\': textUserScale,\n        \'karaokeEnabled\': karaokeEnabled,\n        \'splitLongAyahsEnabled\': splitLongAyahsEnabled,\n        \'maxWordsPerChunk\': maxWordsPerChunk,\n        \'aspectRatio\': aspectRatio,\n        \'colorGrade\': colorGrade,\n        \'vignetteEnabled\': vignetteEnabled,\n        \'vignetteIntensity\': vignetteIntensity,\n        \'grainEnabled\': grainEnabled,\n        \'grainIntensity\': grainIntensity,\n        \'kenBurnsEnabled\': kenBurnsEnabled,\n        \'softTransitions\': softTransitions,\n        \'videoFit\': videoFit,\n        \'videoRotationQuarterTurns\': videoRotationQuarterTurns,\n        \'videoMirror\': videoMirror,\n        // PATCH_S180_TRANSFORM\n        \'videoXform\': <double>[videoScale, videoPosX, videoPosY, videoRot, videoOpacity],\n        \'videoKeys\': [for (final k in videoKeys) k.copy()],\n        \'videoKeyEase\': videoKeyEase,\n        \'pipClips\': [for (final c in pipClips) c.copy()], // PATCH_S188_PIP\n        \'pipSel\': pipSel,\n        \'showIntro\': showIntro,\n        \'showOutro\': showOutro,\n        \'outroText\': outroText,\n        // PATCH_S123_WATERMARK + PATCH_S123_AUDIO_MIX: undoable like every\n        // other export decision.\n        \'watermarkEnabled\': watermarkEnabled,\n        \'watermarkText\': watermarkText,\n        \'watermarkImagePath\': watermarkImagePath,\n        \'watermarkCorner\': watermarkCorner,\n        \'watermarkOpacity\': watermarkOpacity,\n        \'watermarkScale\': watermarkScale,\n        \'originalAudioMix\': originalAudioMix,\n        \'muteAudio\': muteAudio,\n        // PATCH_S127_MUSIC_BED\n        \'ambienceBedPath\': ambienceBedPath,\n        \'ambienceBedVolume\': ambienceBedVolume,\n        \'ambienceBedFade\': ambienceBedFade,\n        // PATCH_S162_CUE_GATE_AND_UNDO_FIX: these were never added when\n        // each feature landed (S129/S143/S145/S160), unlike same-vintage\n        // watermark/ambience-bed fields just above -- removing a committed\n        // text-time-cue and hitting Undo did not bring it back, and\n        // editing a caption/word-color/transition choice was not\n        // undoable at all. Lists/maps are copied by value here, same\n        // reasoning as the `timeline` entry above: capturing the live\n        // List/Map reference would let later mutations bleed into this\n        // "old" snapshot and undo would silently do nothing.\n        \'textTimeCues\': [\n          for (final c in textTimeCues)\n            TextTimeCue(\n                text: c.text,\n                translation: c.translation,\n                start: c.start,\n                end: c.end),\n        ],\n        \'textTimeStartOverride\': textTimeStartOverride,\n        \'textTimeEndOverride\': textTimeEndOverride,\n        \'textLayers\': [\n          for (final l in textLayers)\n            TextLayer(\n                text: l.text,\n                position: l.position,\n                fontSize: l.fontSize,\n                color: l.color),\n        ],\n        \'wordColors\': Map<int, Color>.from(wordColors),\n        \'activeWordColor\': activeWordColor,\n        \'captionText\': captionText,\n        \'captionPosition\': captionPosition,\n        \'textInTransition\': textInTransition,\n        \'textOutTransition\': textOutTransition,\n      };\n\n  void _apply(Map<String, Object?> s) {\n    timeline = (s[\'timeline\'] as List).cast<TimelineSegment>();\n    timelineActive = s[\'timelineActive\'] as bool;\n    trimFromIndex = s[\'trimFromIndex\'] as int;\n    trimToIndex = s[\'trimToIndex\'] as int;\n    trimManualStart = s[\'trimManualStart\'] as double;\n    trimManualEnd = s[\'trimManualEnd\'] as double;\n    ayahText = s[\'ayahText\'] as String;\n    translationText = s[\'translationText\'] as String;\n    detectedLabel = s[\'detectedLabel\'] as String;\n    matchConfidenceText = s[\'matchConfidenceText\'] as String;\n    fontKey = s[\'fontKey\'] as String;\n    ayahFontSize = s[\'ayahFontSize\'] as double;\n    transFontSize = s[\'transFontSize\'] as double;\n    textColor = s[\'textColor\'] as Color;\n    textPosition = s[\'textPosition\'] as AyahTextPosition;\n    extra = s[\'extra\'] as FrameExtra;\n    showTranslation = s[\'showTranslation\'] as bool;\n    templateIndex = s[\'templateIndex\'] as int;\n    bgIndex = s[\'bgIndex\'] as int;\n    useCustomBg = s[\'useCustomBg\'] as bool;\n    customBgPath = s[\'customBgPath\'] as String?;\n    bgAnimated = s[\'bgAnimated\'] as bool;\n    effect = s[\'effect\'] as StageEffect;\n    videoFx = (s[\'videoFx\'] as VideoFx?) ?? VideoFx.none; // PATCH_S194_CUT_FX\n    effectIntensity = s[\'effectIntensity\'] as double;\n    glowEnabled = s[\'glowEnabled\'] as bool;\n    glowIntensity = s[\'glowIntensity\'] as double;\n    letterSpacing = s[\'letterSpacing\'] as double;\n    lineHeightMultiplier = s[\'lineHeightMultiplier\'] as double;\n    textOffset = s[\'textOffset\'] as Offset;\n    textUserScale = s[\'textUserScale\'] as double;\n    karaokeEnabled = s[\'karaokeEnabled\'] as bool;\n    splitLongAyahsEnabled = s[\'splitLongAyahsEnabled\'] as bool;\n    maxWordsPerChunk = s[\'maxWordsPerChunk\'] as int;\n    aspectRatio = s[\'aspectRatio\'] as AyatAspectRatio;\n    colorGrade = s[\'colorGrade\'] as ColorGrade;\n    vignetteEnabled = s[\'vignetteEnabled\'] as bool;\n    vignetteIntensity = s[\'vignetteIntensity\'] as int;\n    grainEnabled = s[\'grainEnabled\'] as bool;\n    grainIntensity = s[\'grainIntensity\'] as int;\n    kenBurnsEnabled = s[\'kenBurnsEnabled\'] as bool;\n    softTransitions = s[\'softTransitions\'] as bool;\n    videoFit = s[\'videoFit\'] as VideoFitMode;\n    videoRotationQuarterTurns = s[\'videoRotationQuarterTurns\'] as int;\n    videoMirror = s[\'videoMirror\'] as bool;\n    // PATCH_S180_TRANSFORM\n    final vx = s[\'videoXform\'] as List<double>;\n    videoScale = vx[0];\n    videoPosX = vx[1];\n    videoPosY = vx[2];\n    videoRot = vx[3];\n    videoOpacity = vx[4];\n    videoKeys = [for (final k in (s[\'videoKeys\'] as List).cast<VideoKey>()) k.copy()];\n    videoKeyEase = s[\'videoKeyEase\'] as bool;\n    // PATCH_S188_PIP\n    pipClips = [for (final c in (s[\'pipClips\'] as List).cast<PipClip>()) c.copy()];\n    pipSel = s[\'pipSel\'] as int;\n    if (pipSel >= pipClips.length) pipSel = -1;\n    showIntro = s[\'showIntro\'] as bool;\n    showOutro = s[\'showOutro\'] as bool;\n    outroText = s[\'outroText\'] as String;\n    watermarkEnabled = s[\'watermarkEnabled\'] as bool;\n    watermarkText = s[\'watermarkText\'] as String;\n    watermarkImagePath = s[\'watermarkImagePath\'] as String?;\n    watermarkCorner = s[\'watermarkCorner\'] as WatermarkCorner;\n    watermarkOpacity = s[\'watermarkOpacity\'] as double;\n    watermarkScale = s[\'watermarkScale\'] as double;\n    originalAudioMix = s[\'originalAudioMix\'] as double;\n    muteAudio = s[\'muteAudio\'] as bool;\n    ambienceBedPath = s[\'ambienceBedPath\'] as String?;\n    ambienceBedVolume = s[\'ambienceBedVolume\'] as double;\n    ambienceBedFade = s[\'ambienceBedFade\'] as bool;\n    // PATCH_S162_CUE_GATE_AND_UNDO_FIX: restore the fields captured above.\n    textTimeCues = (s[\'textTimeCues\'] as List).cast<TextTimeCue>();\n    textTimeStartOverride = s[\'textTimeStartOverride\'] as double?;\n    textTimeEndOverride = s[\'textTimeEndOverride\'] as double?;\n    textLayers = (s[\'textLayers\'] as List).cast<TextLayer>();\n    wordColors = (s[\'wordColors\'] as Map).cast<int, Color>();\n    activeWordColor = s[\'activeWordColor\'] as Color;\n    captionText = s[\'captionText\'] as String;\n    captionPosition = s[\'captionPosition\'] as CaptionPosition;\n    textInTransition = s[\'textInTransition\'] as TextTransition;\n    textOutTransition = s[\'textOutTransition\'] as TextTransition;\n  }\n\n  /// Pushes a pre-edit snapshot. Called automatically by [update] and the\n  /// timeline mutators; call manually before any direct field mutation that\n  /// should be undoable.\n  void pushHistory() {\n    if (_restoring) return;\n    final now = DateTime.now();\n    if (_undoStack.isNotEmpty &&\n        now.difference(_lastPush).inMilliseconds < 800) {\n      return; // coalesce rapid slider ticks into one step\n    }\n    _lastPush = now;\n    _undoStack.add(_capture());\n    if (_undoStack.length > _maxHistory) _undoStack.removeAt(0);\n    _redoStack.clear();\n  }\n\n  void undoStep() {\n    if (_undoStack.isEmpty) return;\n    _redoStack.add(_capture());\n    _restoring = true;\n    _apply(_undoStack.removeLast());\n    // PATCH_S133_STAGE_TEXT_SELECT_EDIT: _apply() rebuilds `timeline` with\n    // fresh TimelineSegment objects, so any selection pointing at the old\n    // ones is now dangling -- drop it rather than risk editing a segment\n    // that is no longer part of the timeline.\n    selectedSegment = null;\n    stageTextSelected = false;\n    _restoring = false;\n    _lastPush = DateTime.fromMillisecondsSinceEpoch(0);\n    notifyListeners();\n  }\n\n  void redoStep() {\n    if (_redoStack.isEmpty) return;\n    _undoStack.add(_capture());\n    _restoring = true;\n    _apply(_redoStack.removeLast());\n    // PATCH_S133_STAGE_TEXT_SELECT_EDIT: same as undoStep() above.\n    selectedSegment = null;\n    stageTextSelected = false;\n    _restoring = false;\n    _lastPush = DateTime.fromMillisecondsSinceEpoch(0);\n    notifyListeners();\n  }\n}\n')), 'lib/screens/home_screen.dart': ('full', ('cb63081b2533d6c255b4d5a4955db101fc9983a909cdb6e266c830719096440a', '// PATCH_S31_UNLIMITED_EXPORT_NATURE_BGS\n// استوديو الآيات — the full native studio screen, feature-matched to the\n// HTML prototype: ayah selection (manual / typed / mic / from-video-audio /\n// auto-sync timeline), backgrounds, chroma settings, reciters, templates,\n// text formatting, ayah-boundary trim and real MP4 export.\nimport \'dart:async\';\nimport \'dart:io\';\nimport \'dart:math\';\n\nimport \'package:file_picker/file_picker.dart\';\nimport \'package:flutter/material.dart\';\nimport \'package:flutter/services.dart\'\n    show HapticFeedback, SystemChrome, SystemNavigator, SystemUiMode, rootBundle; // PATCH_S178_FIX + PATCH_S83_SYNC_QOL tactile feedback + PATCH_S107 curated bg assets\nimport \'package:path_provider/path_provider.dart\'; // PATCH_S64_BG_UPLOAD_PERSIST\nimport \'package:share_plus/share_plus.dart\';\nimport \'package:video_player/video_player.dart\';\n\nimport \'../data/quran_repository.dart\';\nimport \'../data/studio_presets.dart\';\nimport \'../models/studio_state.dart\';\nimport \'../services/ayah_matcher.dart\';\nimport \'../widgets/quran_text_sheet.dart\'; // PATCH_S189_QURAN_TYPE\nimport \'../widgets/nudge_sheet.dart\'; // PATCH_S190_COMFORT\nimport \'../services/ai_art_service.dart\'; // PATCH_S73C_FIX_MISSING_IMPORT: restores the import\n// dropped somewhere in S73/S73b\'s edits -- AiArtService.apiKey is used\n// below (Pollinations API key field) but the class was left unimported,\n// which is what broke the release build.\nimport \'../services/export_service.dart\';\nimport \'../services/font_service.dart\'; // PATCH_S39_PERSISTENT_FONTS\nimport \'../services/karaoke.dart\'; // PATCH_S33_KARAOKE_WORD_HIGHLIGHT\nimport \'../services/media_service.dart\';\nimport \'../services/background_job.dart\'; // PATCH_S163\nimport \'../services/reciter_audio_service.dart\'; // PATCH_S104_RECITER_LIBRARY_DOWNLOAD\nimport \'../services/settings_service.dart\'; // PATCH_S37_PERSISTENT_SETTINGS\nimport \'../services/stage_effects.dart\'; // PATCH_S34_STAGE_EFFECTS\nimport \'../services/video_fx.dart\'; // PATCH_S194_CUT_FX\nimport \'../services/subtitle_service.dart\'; // PATCH_S125_SUBTITLES\nimport \'../data/text_transitions.dart\'; // PATCH_S126_TEXT_TRANSITIONS\nimport \'../services/stage_effects_library.dart\'; // PATCH_S125_EFFECTS_LIBRARY\nimport \'../services/overlay_renderer.dart\';\nimport \'../services/speech_service.dart\';\nimport \'../services/timeline_builder.dart\';\nimport \'../services/whisper_service.dart\';\nimport \'../services/app_settings.dart\'; // PATCH_S123_I18N\nimport \'../theme/ayat_fonts.dart\'; // PATCH_S106_FIX_AYAHTEXTSTYLE_IMPORT\nimport \'../theme/ayat_theme.dart\';\nimport \'../widgets/ayat_info_dialog.dart\';\nimport \'../widgets/color_picker_dialog.dart\';\nimport \'../widgets/gold_switch.dart\';\nimport \'../widgets/motion.dart\'; // PATCH_S123_MOTION\nimport \'../widgets/magic_card.dart\'; // PATCH_S170\nimport \'../services/lamp_streak.dart\'; // PATCH_S170\nimport \'../widgets/quran_entry_button.dart\'; // PATCH_S123_QURAN_ENTRY\nimport \'../widgets/stage_preview.dart\';\nimport \'../i18n/app_strings.dart\';\nimport \'../widgets/first_run_tour.dart\';\nimport \'../widgets/text_editor_pro.dart\';\nimport \'../widgets/timeline_ribbon.dart\'; // PATCH_S83_SYNC_QOL\nimport \'../widgets/pro_timeline.dart\'; // PATCH_S174_PRO_EDITOR\nimport \'../widgets/pro_panels.dart\'; // PATCH_S174_PRO_EDITOR\nimport \'../widgets/pro_capcut.dart\'; // PATCH_S175_CAPCUT\nimport \'../widgets/pro_extras.dart\'; // PATCH_S179_AAA\nimport \'../widgets/pro_transform.dart\'; // PATCH_S180_TRANSFORM\nimport \'../widgets/pro_pip.dart\'; // PATCH_S188_PIP\nimport \'../models/pip_clip.dart\'; // PATCH_S188_PIP\nimport \'../services/ruh_touch.dart\'; // PATCH_S183_TEXT_BAR\nimport \'mushaf_screen.dart\'; // PATCH_S62_MUSHAF_READER\nimport \'sequence_screen.dart\'; // PATCH_S125_SEQUENCE\nimport \'../widgets/autoseg_wizard.dart\'; // PATCH_S134_AUTOSEG_WIZARD\nimport \'settings_screen.dart\'; // PATCH_S123_SETTINGS_SCREEN\n\n// PATCH_S144_UNIFIED_TEXT_CARD: the three kinds of text a project can\n// carry -- the single Quran-matched ayah slot, the single caption\n// slot, and the (now unbounded) list of free layers from S143. One\n// enum so the add/edit sheet, the row list, and the sheet\'s own kind\n// chips all agree on what "kind" means.\nenum _TextKind { ayah, caption, layer }\n\nclass HomeScreen extends StatefulWidget {\n  const HomeScreen({super.key});\n  @override\n  State<HomeScreen> createState() => _HomeScreenState();\n}\n\nclass _HomeScreenState extends State<HomeScreen>\n    with WidgetsBindingObserver {\n  // PATCH_S128: rebuild when language changes\n  // (AppSettings notifies; home already rebuilds via setState from settings return) // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE\n  final StudioState state = StudioState();\n\n  VideoPlayerController? _video;\n  VideoPlayerController? _reciterPreview;\n  int? _previewingReciter;\n  int? _downloadingReciter; // PATCH_S104_RECITER_LIBRARY_DOWNLOAD\n  double? _downloadProgress; // PATCH_S104_RECITER_LIBRARY_DOWNLOAD: 0..1, null = indeterminate\n\n  final ValueNotifier<StageOverlayText?> _liveOverlay = ValueNotifier(null);\n  Timer? _syncTimer;\n\n  bool _busy = false;\n  String _busyStatus = \'\';\n  double? _busyProgress;\n  // PATCH_S83_SYNC_QOL: wall-clock of the running job — with the progress\n  // fraction it yields a remaining-time estimate for BOTH export and sync.\n  final Stopwatch _busyWatch = Stopwatch();\n  // PATCH_S37_CANCEL_LONG_JOBS: set by long jobs (export / auto-sync) so the\n  // status card can offer a working إلغاء button; cleared when the job ends.\n  VoidCallback? _busyCancelAction;\n  bool _listening = false;\n  Timer? _persistDebounce; // PATCH_S37_PERSISTENT_SETTINGS\n  bool _settingsRestored = false;\n\n  int _selectedTab = 0;\n  // PATCH_S173_INSHOT_LAYOUT: which bottom tool panel is open (-1 = none).\n  // 100 = video, 101 = size, 102 = magic, 0..n-1 = the tab index.\n  int _toolOpen = -1;\n  double _panelFrac = 0.36; // PATCH_S184_PRO_MAIN: height of the tool panel (drag its handle)\n  // PATCH_S174_PRO_EDITOR: selected ayah clip on the timeline (-1 = none) and\n  // the playhead markers (session only, like a scratch pad).\n  int _selSeg = -1;\n  int _selCue = -1; // PATCH_S181_CLIPTOUCH: selected text block on the timeline\n  bool _selMain = false; // PATCH_S181_CLIPTOUCH: the main clip is selected\n  bool _ayahAdvOpen = false; // PATCH_S181_CLIPTOUCH: آيات tab "advanced" fold\n  final List<double> _markers = [];\n  bool _guides = false; // PATCH_S179_AAA\n  // PATCH_S132_GAUNTLET_LOOP: classic<->grouped have different tab\n  // counts (8 vs 5) -- clamp so a stale index can\'t be out of range.\n  int get _safeSelectedTab => _selectedTab.clamp(0, _tabs.length - 1);\n  int _selectedSurah = 1;\n  // PATCH_S113_AYAH_DROPDOWN_SELECTION_STATE: the "الآية" dropdown\'s value\n  // was hardcoded to null, so it never reflected the chosen ayah and reset\n  // to the hint on every rebuild -- looked like the selection wasn\'t being\n  // applied even though it was. This is the missing tracked selection.\n  int? _selectedAyahIdx;\n  // PATCH_S101_AUTOSYNC_HINT_PARTIAL_AYAH: last ayah picked from the dropdown below,\n  // so the partial-ayah word-range section knows what to slice from.\n  Ayah? _partialSourceAyah;\n  int _partialFromWord = 0;\n  int _partialToWord = 0;\n\n  // PATCH_S83_SYNC_QOL: playback aids for reviewing a detected timeline.\n  static const _speeds = [1.0, 1.25, 1.5, 0.75];\n  double _playbackSpeed = 1.0;\n  bool _loopAyah = false;\n  TimelineSegment? _loopSeg; // the ayah the loop control snaps back to\n\n  // PATCH_S119_TIMELINE_VISIBILITY_AND_ENABLE_FIX: "مراجعة الآيات\n  // المرصودة" renders above the ayah panel, but every action that adds a\n  // segment to it lives scrolled down inside that panel -- so the card\n  // appearing was invisible in practice. This lets code scroll back to\n  // it instead of just telling the user to do it themselves in a toast.\n  final _scrollCtrl = ScrollController();\n  final _stripCtrl = ScrollController(); // PATCH_S176_SMOOTH\n  final _customArCtrl = TextEditingController();\n  final _customEnCtrl = TextEditingController();\n  // PATCH_S143_TEXT_LAYERS: separate from the ayah-matching controllers\n  // above -- this box never tries to match the Quran, it just adds a\n  // new stacked text layer verbatim.\n  final _newLayerCtrl = TextEditingController();\n  AyahTextPosition _newLayerPosition = AyahTextPosition.top;\n  // PATCH_S144_UNIFIED_TEXT_CARD: which kind the add/edit sheet is\n  // currently showing, whether that sheet is editing an existing\n  // element (locks the kind chips) or adding a fresh one, and -- only\n  // for the layer kind, which is a list rather than a single slot --\n  // which index is being edited.\n  _TextKind _sheetKind = _TextKind.layer;\n  bool _sheetIsEdit = false;\n  int? _editingLayerIndex;\n  // ---- PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION ----\n  final _captionCtrl = TextEditingController();\n  final _textStartCtrl = TextEditingController();\n  final _textEndCtrl = TextEditingController();\n  // PATCH_S125_CUSTOM_ASPECT\n  late final _customWCtrl =\n      TextEditingController(text: \'${state.customAspectW}\');\n  late final _customHCtrl =\n      TextEditingController(text: \'${state.customAspectH}\');\n  // PATCH_S123_WATERMARK\n  late final _watermarkCtrl =\n      TextEditingController(text: state.watermarkText);\n  late final _outroCtrl = TextEditingController(text: state.outroText);\n  late final _staticDurCtrl =\n      TextEditingController(text: \'${state.staticDurationSec}\');\n\n  // PATCH_S123_I18N: the tab strip is the app\'s main navigation, so it is\n  // localized even though the deeper panel copy is still Arabic-only.\n  // A getter, not a const list, because the language can change at runtime.\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: five clear groups instead of an 8-tab 4×2 grid.\n  // Content (which words) stays in الآيات; look (fonts/border/…) in النص.\n  List<(IconData, String)> get _tabs =>\n      AppSettings.instance.classicTabs ? _classicTabs : _groupedTabs;\n\n  // PATCH_S132_GAUNTLET_LOOP: was hardcoded Arabic -- the old 8-tab strip\n  // was localized via _t(), this one silently wasn\'t. Fixed.\n  List<(IconData, String)> get _groupedTabs => [\n        (Icons.menu_book_outlined, _t(\'studio.group.ayat\')),\n        (Icons.text_fields, _t(\'studio.tab.text\')),\n        (Icons.auto_awesome_outlined, _t(\'studio.group.shape\')),\n        (Icons.perm_media_outlined, _t(\'studio.group.media\')),\n        (Icons.more_horiz, _t(\'studio.group.more\')),\n      ];\n\n  // PATCH_S132_GAUNTLET_LOOP: pre-S129 8-tab grid, recovered verbatim from\n  // repo history (commit 62eca15) behind a settings toggle instead of the\n  // 5 grouped tabs -- for people who want the old layout back.\n  List<(IconData, String)> get _classicTabs => [\n        (Icons.menu_book_outlined, _t(\'studio.tab.ayah\')),\n        (Icons.dark_mode_outlined, _t(\'studio.tab.backgrounds\')),\n        (Icons.water_drop_outlined, _t(\'studio.tab.effects\')),\n        (Icons.filter_hdr_outlined, _t(\'studio.tab.chroma\')),\n        (Icons.graphic_eq, _t(\'studio.tab.reciters\')),\n        (Icons.grid_view_outlined, _t(\'studio.tab.templates\')),\n        (Icons.text_fields, _t(\'studio.tab.text\')),\n        (Icons.video_settings_outlined, _t(\'studio.tab.export\')),\n      ];\n\n  /// Shorthand for a localized string in this screen\'s chrome.\n  String _t(String key) => AppSettings.instance.strings.t(key);\n  // PATCH_S141_HOME_SEQUENCE_ABOUT_I18N: same shorthand, with `{}` placeholders filled left\n  // to right -- see AppStrings.f.\n  String _tf(String key, List<Object> args) =>\n      AppSettings.instance.strings.f(key, args);\n\n  // PATCH_S123_QURAN_ENTRY: an ayah chosen while reading the mushaf comes\n  // straight back here as the studio\'s current ayah -- same path a manual\n  // dropdown pick takes, so AI art, karaoke and the partial-ayah slicer all\n  // see it exactly as if it had been picked from the list.\n  void _useAyahFromMushaf(Ayah a) {\n    final idx = state.ayaat.indexWhere(\n        (x) => x.surahNum == a.surahNum && x.num == a.num);\n    _liveOverlay.value = null;\n    state.setAyah(a.ar, a.en, \'من المصحف: سورة ${a.surah} — آية ${a.num}\',\n        surahNum: a.surahNum, ayahNum: a.num);\n    final words =\n        a.ar.split(RegExp(r\'\\s+\')).where((w) => w.isNotEmpty).toList();\n    setState(() {\n      _selectedSurah = a.surahNum;\n      if (idx >= 0) _selectedAyahIdx = idx;\n      _partialSourceAyah = a;\n      _partialFromWord = 0;\n      _partialToWord = words.isEmpty ? 0 : words.length - 1;\n    });\n    if (!mounted) return;\n    ScaffoldMessenger.of(context).showSnackBar(\n      SnackBar(content: Text(_t(\'mushaf.ayahAdded\'))),\n    );\n  }\n\n  @override\n  void initState() {\n    super.initState();\n    _loadCorpus();\n    // PATCH_S26_FONT_LOAD_REBUILD: google_fonts paints with a system-fallback font while\n    // the real Amiri Quran / Aref Ruqaa files are still downloading, and\n    // does not rebuild this widget on its own once they\'re ready --\n    // without the setState() below the preview could be stuck showing\n    // fallback glyphs (wrong shaping/tashkeel) for the whole session.\n    OverlayRenderer.ensureFontsLoaded().then((_) {\n      if (mounted) setState(() {});\n    });\n    _syncTimer = Timer.periodic(\n        const Duration(milliseconds: 100), (_) => _tickAutoSync());\n    // PATCH_S39_PERSISTENT_FONTS: re-register previously imported fonts\n    // FIRST, so a persisted fontKey pointing at one of them validates —\n    // PATCH_S37_PERSISTENT_SETTINGS then reopens the studio the way it was\n    // left and starts auto-saving style changes (debounced).\n    FontService.loadSavedFonts().then((fonts) async {\n      if (!mounted) return;\n      if (fonts.isNotEmpty) {\n        state.customFonts.addAll(fonts\n            .where((f) => state.allFonts.every((e) => e.key != f.key)));\n      }\n      await SettingsService.restore(state);\n      WhisperService.setModelSize(state.whisperModelSize); // PATCH_S43_MODEL_SIZE_PICKER\n      if (!mounted) return;\n      _settingsRestored = true;\n      _outroCtrl.text = state.outroText;\n      _staticDurCtrl.text = \'${state.staticDurationSec}\';\n      _watermarkCtrl.text = state.watermarkText; // PATCH_S123_WATERMARK\n      _customWCtrl.text = \'${state.customAspectW}\'; // PATCH_S125_CUSTOM_ASPECT\n      _customHCtrl.text = \'${state.customAspectH}\';\n    });\n    state.addListener(_schedulePersist);\n    // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE: dispose() only fires when\n    // Flutter tears this widget down, not when Android backgrounds the app\n    // (home button, app-switch, later process kill) -- which is how this\n    // app actually "closes" on a phone almost every time. Without this\n    // observer nothing saves at that moment at all.\n    WidgetsBinding.instance.addObserver(this);\n    // PATCH_S128: one-time 3-step tour\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      // PATCH_S132_GAUNTLET_LOOP: WelcomeScreen (shown before this screen)\n      // already introduces the app\'s features -- this second, in-app tour\n      // was redundant. Left first_run_tour.dart in place (harmless if\n      // re-enabled later) but stopped calling it.\n      // if (mounted) FirstRunTour.maybeShow(context);\n    });\n  }\n\n  // PATCH_S37_PERSISTENT_SETTINGS\n  void _schedulePersist() {\n    if (!_settingsRestored) return; // don\'t overwrite saved prefs with defaults\n    _persistDebounce?.cancel();\n    _persistDebounce = Timer(const Duration(milliseconds: 800), () {\n      SettingsService.persist(state);\n    });\n  }\n\n  // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE: paused is the last\n  // reliable checkpoint before Android may kill the process outright --\n  // flush immediately instead of hoping the 800ms debounce already fired.\n  @override\n  void didChangeAppLifecycleState(AppLifecycleState appState) {\n    if (appState == AppLifecycleState.paused && _settingsRestored) {\n      _persistDebounce?.cancel();\n      SettingsService.persist(state);\n    }\n  }\n\n  @override\n  void dispose() {\n    WidgetsBinding.instance\n        .removeObserver(this); // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE\n    state.removeListener(_schedulePersist); // PATCH_S37_PERSISTENT_SETTINGS\n    // PATCH_S91_RELABEL_KARAOKE_AND_SAVE_ON_CLOSE: flush, don\'t just drop,\n    // whatever change was still waiting on the debounce.\n    _persistDebounce?.cancel();\n    // PATCH_S123_QOL: the 10Hz auto-sync ticker was started in initState and\n    // never cancelled -- it kept firing _tickAutoSync() against a disposed\n    // State (and a disposed VideoPlayerController) after leaving the studio.\n    _syncTimer?.cancel();\n    if (_settingsRestored) SettingsService.persist(state);\n    _video?.dispose();\n    _reciterPreview?.dispose();\n    _liveOverlay.dispose();\n    _scrollCtrl.dispose(); // PATCH_S119_TIMELINE_VISIBILITY_AND_ENABLE_FIX\n    _stripCtrl.dispose(); // PATCH_S176_SMOOTH\n    _customArCtrl.dispose();\n    _customEnCtrl.dispose();\n    _newLayerCtrl.dispose(); // PATCH_S143_TEXT_LAYERS\n    // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION\n    _captionCtrl.dispose();\n    _textStartCtrl.dispose();\n    _textEndCtrl.dispose();\n    _customWCtrl.dispose(); // PATCH_S125_CUSTOM_ASPECT\n    _customHCtrl.dispose();\n    _watermarkCtrl.dispose(); // PATCH_S123_WATERMARK\n    _outroCtrl.dispose();\n    _staticDurCtrl.dispose();\n    super.dispose();\n  }\n\n  Future<void> _loadCorpus() async {\n    try {\n      final ayaat = await QuranRepository.loadFullCorpus();\n      state.update(() {\n        state.ayaat = ayaat;\n        state.matcher = AyahMatcher(ayaat);\n        // PATCH_S128: prefer i18n when available\n        state.corpusStatus =\n            AppStrings(AppSettings.instance.lang).t(\'studio.loaded\') + \' ✓\'; // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n      });\n    } catch (e) {\n      state.update(() => state.corpusStatus = \'تعذّر تحميل القرآن الكامل: $e\');\n    }\n  }\n\n  void _toast(String msg) {\n    if (!mounted) return;\n    ScaffoldMessenger.of(context)\n      ..hideCurrentSnackBar()\n      ..showSnackBar(SnackBar(\n        // PATCH_S167_APP_POLISH: gold spark + text; shape/colour from the theme.\n        content: Row(\n          children: [\n            const Icon(Icons.auto_awesome,\n                size: 16, color: AyatColors.goldBright),\n            const SizedBox(width: 10),\n            Expanded(child: Text(msg)),\n          ],\n        ),\n        behavior: SnackBarBehavior.floating,\n        margin: const EdgeInsets.fromLTRB(16, 0, 16, 16),\n        duration: const Duration(milliseconds: 2200),\n      ));\n  }\n\n  // PATCH_S75_COMPACT_PICKER_FALLBACK: WhisperService.ensureReady() can silently fall back to a\n  // different (working) tier than the one selected -- e.g. دقة القرآن isn\'t\n  // published yet. Call this after any job that may have run ensureReady()\n  // so the compact selector\'s displayed tier stays truthful, and let the\n  // user know why it changed.\n  void _syncModelSizeDisplay() {\n    final actual = WhisperService.currentSize;\n    if (actual != state.whisperModelSize) {\n      final newLabel = WhisperService.labelFor(actual).split(\' — \').first;\n      state.update(() => state.whisperModelSize = actual);\n      _toast(\'تم التبديل تلقائيًا إلى "$newLabel" لأن الخيار المحدّد غير متاح حاليًا\');\n    }\n  }\n\n  Future<T?> _withBusy<T>(Future<T> Function() job) async {\n    if (_busy) return null;\n    setState(() {\n      _busy = true;\n      _busyProgress = null;\n    });\n    _busyWatch\n      ..reset()\n      ..start(); // PATCH_S83_SYNC_QOL\n    await BackgroundJob.start(); // PATCH_S163: survive minimize / screen-off\n    try {\n      return await job();\n    } catch (e) {\n      _toast(\'$e\'.replaceFirst(\'Exception: \', \'\'));\n      return null;\n    } finally {\n      await BackgroundJob.stop(); // PATCH_S163\n      _busyWatch.stop(); // PATCH_S83_SYNC_QOL\n      if (mounted) {\n        setState(() {\n          _busy = false;\n          _busyStatus = \'\';\n          _busyProgress = null;\n          _busyCancelAction = null; // PATCH_S37_CANCEL_LONG_JOBS\n        });\n      }\n    }\n  }\n\n  // PATCH_S83_SYNC_QOL: linear projection of the remaining time from how\n  // long the completed fraction took. Null while it can\'t be trusted (too\n  // early, basically done, or no measurable pace yet).\n  String? _busyEta() {\n    final f = _busyProgress;\n    if (f == null || f < 0.03 || f > 0.995) return null;\n    final elapsedSec = _busyWatch.elapsedMilliseconds / 1000;\n    if (elapsedSec < 2) return null;\n    final remaining = (elapsedSec * (1 - f) / f).round();\n    if (remaining < 1) return null;\n    if (remaining < 60) return \'يتبقى نحو $remaining ث\';\n    return \'يتبقى نحو ${remaining ~/ 60} د ${remaining % 60} ث\';\n  }\n\n  void _setBusyStatus(String s, [double? progress]) {\n    BackgroundJob.update(s, progress ?? _busyProgress); // PATCH_S163\n    if (!mounted) return;\n    setState(() {\n      _busyStatus = s;\n      if (progress != null) _busyProgress = progress;\n    });\n  }\n\n  // ---------------------------------------------------------------- media\n\n  Future<void> _pickVideo() async {\n    final res = await FilePicker.platform.pickFiles(type: FileType.any);\n    final path = res?.files.single.path;\n    if (path == null) return;\n    await _video?.dispose();\n    _liveOverlay.value = null;\n    // PATCH_S83_SYNC_QOL: playback aids belong to the previous clip\n    _playbackSpeed = 1.0;\n    _loopAyah = false;\n    _loopSeg = null;\n    final controller = VideoPlayerController.file(File(path));\n    _video = controller;\n    state.setVideo(path);\n    try {\n      await controller.initialize();\n      await controller.setLooping(true);\n      await controller.play();\n      // PATCH_S34_PLAYER_CONTROLS_TRIM: known duration drives the seek bar\n      // and the manual-cut range slider.\n      state.update(() => state.videoDurationSec =\n          controller.value.duration.inMilliseconds / 1000.0);\n    } catch (_) {\n      // audio-only files still work for detection/auto-sync even if the\n      // preview player refuses them\n    }\n    if (mounted) setState(() {});\n    _toast(\'تم رفع الملف ✓\');\n  }\n\n  // PATCH_S125_SEQUENCE: builds a multi-clip sequence in its own screen and\n  // adopts the rendered file as the studio\'s working clip. Everything\n  // downstream keeps seeing a single source, so nothing else had to change.\n  Future<void> _openSequence() async {\n    final (fw, fh) = state.frameSize;\n    final merged = await openSequenceBuilder(\n      context,\n      initialClipPath: state.videoPath,\n      frameWidth: fw,\n      frameHeight: fh,\n    );\n    if (merged == null || !mounted) return;\n    // A new source invalidates any timeline detected against the old one --\n    // setVideo already clears it, which is exactly what\'s wanted here.\n    await _video?.dispose();\n    _liveOverlay.value = null;\n    _playbackSpeed = 1.0;\n    _loopAyah = false;\n    _loopSeg = null;\n    final controller = VideoPlayerController.file(File(merged));\n    _video = controller;\n    state.setVideo(merged);\n    try {\n      await controller.initialize();\n      await controller.setLooping(true);\n      await controller.play();\n      state.update(() => state.videoDurationSec =\n          controller.value.duration.inMilliseconds / 1000.0);\n    } catch (_) {\n      // The rendered sequence should always be a valid mp4, but a preview\n      // player refusing it must not lose the render.\n    }\n    if (!mounted) return;\n    setState(() {});\n    ScaffoldMessenger.of(context).showSnackBar(\n      const SnackBar(\n          content: Text(\'تم تركيب المقاطع — شغّلي المزامنة التلقائية من جديد\')),\n    );\n  }\n\n  // PATCH_S79_CUSTOM_BG_NUMBER_AND_VIDEO_MERGE: appends a second picked video/clip onto the end of\n  // the one already loaded, then swaps the player over to the\n  // merged file. Requires a first video to already be loaded.\n  Future<void> _pickAndMergeVideo() async {\n    if (!state.hasVideo) {\n      _toast(\'ارفع فيديو أولًا قبل الدمج\');\n      return;\n    }\n    final res = await FilePicker.platform.pickFiles(type: FileType.any);\n    final secondPath = res?.files.single.path;\n    if (secondPath == null) return;\n    final firstPath = state.videoPath!;\n    final merged = await _withBusy(() async {\n      _setBusyStatus(\'جارٍ دمج الفيديوهين…\');\n      return MediaService.mergeVideos(firstPath, secondPath);\n    });\n    if (merged == null || !mounted) return;\n    await _video?.dispose();\n    _liveOverlay.value = null;\n    final controller = VideoPlayerController.file(File(merged));\n    _video = controller;\n    state.setVideo(merged);\n    try {\n      await controller.initialize();\n      await controller.setLooping(true);\n      await controller.play();\n      state.update(() => state.videoDurationSec =\n          controller.value.duration.inMilliseconds / 1000.0);\n    } catch (_) {\n      // merged output should always be a valid mp4, but don\'t crash\n      // the flow if the preview player still refuses it.\n    }\n    if (mounted) setState(() {});\n    _toast(\'تم دمج الفيديوهين ✓\');\n  }\n\n  // PATCH_S35_SMARTER_DETECTION: apply one confirmed/auto-detected match.\n  void _applyDetectedAyah(AyahMatch m, {String? heardText}) {\n    _liveOverlay.value = null;\n    state.setAyah(\n      m.ayah.ar,\n      m.ayah.en,\n      \'تم التعرف: سورة ${m.ayah.surah} — آية ${m.ayah.num}\',\n      confidenceText: \'نسبة التطابق: ${(m.confidence * 100).round()}٪\'\n          \'${heardText != null ? \' — النص المسموع: "$heardText"\' : \'\'}\',\n      surahNum: m.ayah.surahNum, // PATCH_S32_AI_ART_NANO_BANANA\n      ayahNum: m.ayah.num,\n    );\n  }\n\n  // PATCH_S35_SMARTER_DETECTION: "did you mean…?" — instead of silently\n  // committing to a borderline winner, let the user pick among the top\n  // candidates. Returns (match, false), (null, true) for "use the text as\n  // typed" (only when [allowRaw]), or null when dismissed.\n  Future<(AyahMatch?, bool)?> _pickAyahCandidate(\n    List<AyahMatch> candidates, {\n    bool allowRaw = false,\n  }) {\n    String snippet(String s) =>\n        s.length <= 90 ? s : \'${s.substring(0, 90)}…\';\n    return showDialog<(AyahMatch?, bool)>(\n      context: context,\n      builder: (context) => AlertDialog(\n        backgroundColor: AyatColors.surface,\n        shape: RoundedRectangleBorder(\n          borderRadius: BorderRadius.circular(22),\n          side: const BorderSide(color: AyatColors.hairline),\n        ),\n        title: const Text(\'هل تقصد إحدى هذه الآيات؟\'),\n        content: SingleChildScrollView(\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n              for (final m in candidates)\n                Container(\n                  margin: const EdgeInsets.only(bottom: 8),\n                  decoration: BoxDecoration(\n                    color: AyatColors.surface2,\n                    borderRadius: BorderRadius.circular(14),\n                    border: Border.all(color: AyatColors.hairline),\n                  ),\n                  child: InkWell(\n                    borderRadius: BorderRadius.circular(14),\n                    onTap: () => Navigator.pop(context, (m, false)),\n                    child: Padding(\n                      padding: const EdgeInsets.all(10),\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: [\n                          Text(\n                            \'سورة ${m.ayah.surah} — آية ${m.ayah.num} · ${(m.confidence * 100).round()}٪\',\n                            style: const TextStyle(\n                                fontSize: 12, color: AyatColors.goldBright),\n                          ),\n                          const SizedBox(height: 4),\n                          Text(\n                            snippet(m.ayah.ar),\n                            textDirection: TextDirection.rtl,\n                            style: Theme.of(context).textTheme.bodyLarge,\n                          ),\n                        ],\n                      ),\n                    ),\n                  ),\n                ),\n              if (allowRaw)\n                TextButton(\n                  onPressed: () => Navigator.pop(context, (null, true)),\n                  child: const Text(\'ولا واحدة — استخدم النص كما كتبته\'),\n                ),\n            ],\n          ),\n        ),\n        actions: [\n          TextButton(\n              onPressed: () => Navigator.pop(context),\n              child: const Text(\'إلغاء\')),\n        ],\n      ),\n    );\n  }\n\n  Future<void> _detectFromVideo() async {\n    WhisperService.setModelSize(state.whisperModelSize); // PATCH_S43_MODEL_SIZE_PICKER\n    final matcher = state.matcher;\n    if (!state.hasVideo || matcher == null) { // PATCH_S185_POLISH\n      _toast(!state.hasVideo\n          ? \'ارفع فيديو أولًا\'\n          : \'نص القرآن ما زال يُحمَّل — انتظر لحظات ثم أعد المحاولة\');\n      return;\n    }\n    final text = await _withBusy(() async {\n      _setBusyStatus(\'جارٍ استخراج الصوت…\');\n      final wav = await MediaService.extractWav16kMono(state.videoPath!);\n      final t = await WhisperService.transcribeWav(wav,\n          onStatus: (s) => _setBusyStatus(s));\n      File(wav).delete().ignore();\n      return t;\n    });\n    if (text == null || !mounted) return;\n    if (text.isEmpty) {\n      _toast(\'لم يتم استخراج أي كلام واضح من الفيديو\');\n      return;\n    }\n    // PATCH_S35_SMARTER_DETECTION: strong winner applies directly; a\n    // borderline one offers the top candidates to choose from.\n    final candidates = matcher.matchTop(text, k: 3, minConfidence: 0.30);\n    if (candidates.isEmpty) {\n      _toast(\'تم تفريغ الصوت لكن لم تُطابق أي آية بثقة كافية\');\n      return;\n    }\n    if (candidates.first.confidence >= 0.55 || candidates.length == 1) {\n      _applyDetectedAyah(candidates.first, heardText: text);\n      return;\n    }\n    final picked = await _pickAyahCandidate(candidates);\n    if (picked?.$1 != null) _applyDetectedAyah(picked!.$1!, heardText: text);\n  }\n\n  Future<void> _autoSync() async {\n    WhisperService.setModelSize(state.whisperModelSize); // PATCH_S43_MODEL_SIZE_PICKER\n    final matcher = state.matcher;\n    if (!state.hasVideo || matcher == null) { // PATCH_S185_POLISH\n      _toast(!state.hasVideo\n          ? \'ارفع فيديو أولًا\'\n          : \'نص القرآن ما زال يُحمَّل — انتظر لحظات ثم أعد المحاولة\');\n      return;\n    }\n    // pause the preview so the decoder isn\'t fighting the analysis pass\n    await _video?.pause();\n    // PATCH_S37_CANCEL_LONG_JOBS: a full scan can take minutes on long clips\n    setState(() => _busyCancelAction = TimelineBuilder.requestCancel);\n    await _withBusy(() async {\n      // PATCH_S86_SCAN_RANGE: with a manual cut set, only the span that\n      // will actually be exported gets scanned — proportionally faster.\n      // PATCH_S90_HONEST_COVERAGE: build() now also returns the real\n      // decoded duration -- stash it before anything below reads coverage.\n      final result = await TimelineBuilder.build(\n        mediaPath: state.videoPath!,\n        matcher: matcher,\n        scanStart: state.manualTrimSet ? state.trimManualStart : null,\n        scanEnd: state.manualTrimSet ? state.trimManualEnd : null,\n        onStatus: (s) => _setBusyStatus(s),\n        onProgress: (f) {\n          BackgroundJob.update(null, f); // PATCH_S163\n          setState(() => _busyProgress = f);\n        },\n      );\n      final timeline = result.timeline;\n      state.detectedAudioDurationSec = result.totalSec;\n      final decodeWarning = result.decodeWarning; // PATCH_S97_DECODE_MISMATCH_WARNING\n      if (timeline.isEmpty) {\n        state.setTimeline([]);\n        _toast(\'لم يتم رصد أي آية معروفة بثقة كافية في هذا الفيديو\');\n        return;\n      }\n      state.setTimeline(timeline);\n      _loopSeg = null; // PATCH_S83_SYNC_QOL: old loop target no longer exists\n      // PATCH_S83_SYNC_QOL: a real summary — which ayat, how much of the\n      // clip they cover, and whether any were inferred and deserve review.\n      final first = timeline.first.ayah;\n      final last = timeline.last.ayah;\n      final range = first.surahNum == last.surahNum\n          ? \'سورة ${first.surah}: ${first.num}–${last.num}\'\n          : \'من ${first.surah} ${first.num} إلى ${last.surah} ${last.num}\';\n      final coverage = (state.timelineCoverageFraction() * 100).round();\n      final inferredCount = timeline.where((s) => s.inferred).length;\n      // PATCH_S88_AUTOSYNC_HONEST_FIX: a low-confidence scan used to render\n      // as the exact same success summary as a solid one -- say so plainly\n      // instead, and point at what actually helps.\n      final avgConfidence = state.timelineAverageConfidence();\n      const lowConfidenceWarnBar = 0.5;\n      final qualityWarning = avgConfidence < lowConfidenceWarnBar\n          ? \'\\n⚠️ متوسط الثقة منخفض (${(avgConfidence * 100).round()}٪) — \'\n              \'التوقيت قد يكون غير دقيق. \'\n              \'${state.whisperModelSize == WhisperModelSize.quranTuned ? \'جرّب مقطعًا أوضح صوتًا وأقل ضجيجًا.\' : \'ارفع دقة التعرف (حجم النموذج) من الإعدادات إلى النموذج المخصص للقرآن للحصول على نتيجة أدق.\'}\'\n          : \'\';\n      state.update(() {\n        state.matchConfidenceText =\n            \'تم رصد ${timeline.length} آية ($range) تغطي $coverage٪ من المقطع\'\n            \'${inferredCount > 0 ? \' — منها $inferredCount مستنتجة من تسلسل المصحف، راجعها في «مراجعة الآيات المرصودة»\' : \'\'}\'\n            \'$qualityWarning\'\n            // PATCH_S97_DECODE_MISMATCH_WARNING\n            \'${decodeWarning != null ? \'\\n$decodeWarning\' : \'\'}\';\n        state.detectedLabel = \'مزامنة تلقائية مفعّلة — التصدير سيستخدم نفس التوقيت\';\n      });\n      HapticFeedback.mediumImpact(); // PATCH_S83_SYNC_QOL\n      // PATCH_S97_DECODE_MISMATCH_WARNING: a different, more specific kind of\n      // problem than "detected N ayat" -- worth its own toast, not just a\n      // line buried inside the longer summary text.\n      if (decodeWarning != null) _toast(decodeWarning);\n      _toast(\'تم رصد ${timeline.length} آية ✓ — التصدير سيستخدم نفس التوقيت تلقائيًا\');\n      await _video?.play();\n    });\n    _syncModelSizeDisplay(); // PATCH_S75_COMPACT_PICKER_FALLBACK\n  }\n\n  /// 10x/sec: while an auto-sync timeline is active, light the current\n  /// ayah\'s words up in the preview in step with the playing recitation.\n  /// PATCH_S33_KARAOKE_WORD_HIGHLIGHT: karaoke-style — the whole part is\n  /// visible dimmed and each word brightens as الشيخ reaches it; ayahs\n  /// longer than 12 words are shown as 2-3+ sequential parts.\n  void _tickAutoSync() {\n    final controller = _video;\n    if (!state.timelineActive ||\n        controller == null ||\n        !controller.value.isInitialized) {\n      _gateTypedText(controller); // PATCH_S183_TEXT_BAR\n      return;\n    }\n    final t = controller.value.position.inMilliseconds / 1000.0;\n    // PATCH_S83_SYNC_QOL: loop-one-ayah — once the playhead crosses the end\n    // of the ayah it was inside, snap back to that ayah\'s start. The narrow\n    // trigger window means a deliberate manual seek far past the end simply\n    // leaves the loop and adopts the new ayah.\n    final loopSeg = _loopSeg;\n    if (_loopAyah &&\n        loopSeg != null &&\n        controller.value.isPlaying &&\n        t >= loopSeg.end - 0.05 &&\n        t <= loopSeg.end + 1.0) {\n      controller\n          .seekTo(Duration(milliseconds: (loopSeg.start * 1000).round() + 30));\n      return;\n    }\n    final seg = state.segmentAt(t);\n    if (seg != null) _loopSeg = seg;\n    if (seg == null) return; // keep the last ayah on screen between segments\n    // PATCH_S84_AI_ART_FOLLOWS_PLAYBACK: per-ayah art now tracks the\n    // recitation live (internal guards make this call ~free per tick).\n    // Only when the background is actually visible: audio-only uploads\n    // (no video surface) or chroma, where the art replaces the backdrop —\n    // generating behind an opaque video would just burn bandwidth.\n    if (controller.value.size.width <= 0 || state.chromaEnabled) {\n      state.ensureArtForPlayback(seg.ayah);\n    }\n    // PATCH_S156_LONG_AYAH_SPLIT_CONTROL: an effectively-infinite\n    // threshold when splitting is off keeps the whole ayah as one chunk\n    // no matter its word count, instead of always cutting long ayat into\n    // parts.\n    final cue = karaokeCueAt(\n        buildKaraokeChunks(seg,\n            maxWordsPerChunk:\n                state.splitLongAyahsEnabled ? state.maxWordsPerChunk : 1 << 30),\n        t);\n    // PATCH_S27_FADE_TEXT_ANIMATIONS: stable per-part key so StagePreview only fades when\n    // the ayah part actually changes, not on every newly lit word.\n    final segmentKey =\n        \'${seg.ayah.surahNum}:${seg.ayah.num}:${cue.chunk.index}\';\n    // PATCH_S51_KARAOKE_TOGGLE: with the toggle off, drop the per-word\n    // list entirely -- StagePreview already falls back to plain static\n    // text whenever karaokeWords is null, so this reuses that path\n    // instead of adding a second rendering branch.\n    final words = state.karaokeEnabled ? cue.chunk.words : null;\n    final litWords = state.karaokeEnabled ? cue.litWords : 0;\n    final current = _liveOverlay.value;\n    if (current == null ||\n        current.segmentKey != segmentKey ||\n        current.litWords != litWords) {\n      _liveOverlay.value = StageOverlayText(\n          cue.chunk.text,\n          cue.chunk.translation,\n          segmentKey,\n          words,\n          litWords,\n          // PATCH_S83_SYNC_QOL: which ayah is playing, right on the stage\n          \'سورة ${seg.ayah.surah} — ${seg.ayah.num}\'\n          \'${seg.inferred ? \' · مستنتجة\' : \'\'}\');\n    }\n  }\n\n  Future<void> _micDetect() async {\n    final matcher = state.matcher;\n    if (matcher == null) return;\n    if (_listening) {\n      await SpeechService.stop();\n      return;\n    }\n    setState(() => _listening = true);\n    try {\n      final best = await SpeechService.listenForAyah(matcher);\n      if (best != null) {\n        _liveOverlay.value = null;\n        state.setAyah(\n          best.ayah.ar,\n          best.ayah.en,\n          \'تم التعرف: سورة ${best.ayah.surah} — آية ${best.ayah.num}\',\n          confidenceText: \'نسبة التطابق: ${(best.confidence * 100).round()}٪\',\n          surahNum: best.ayah.surahNum, // PATCH_S32_AI_ART_NANO_BANANA\n          ayahNum: best.ayah.num,\n        );\n      } else {\n        _toast(\'لم يتم العثور على آية مطابقة بثقة كافية — حاول التلاوة بوضوح أكبر\');\n      }\n    } catch (e) {\n      _toast(\'$e\'.replaceFirst(\'Exception: \', \'\'));\n    } finally {\n      _syncModelSizeDisplay(); // PATCH_S75_COMPACT_PICKER_FALLBACK\n      if (mounted) setState(() => _listening = false);\n    }\n  }\n\n  // ---------------------------------------------------------------- export\n\n  Future<void> _export() async {\n    if (!state.hasAyah && !state.timelineActive && !state.hasVideo) {\n      _toast(\'اختر آية أو ارفع فيديو أولًا\');\n      return;\n    }\n    state.staticDurationSec =\n        (int.tryParse(_staticDurCtrl.text) ?? 6).clamp(2, 60);\n    await _video?.pause();\n    // PATCH_S37_CANCEL_LONG_JOBS\n    setState(() => _busyCancelAction = () => ExportService.cancel());\n    final path = await _withBusy(() async {\n      _setBusyStatus(\'جارٍ تجهيز التصدير…\', 0);\n      return ExportService.export(\n        state: state,\n        onStatus: (s) => _setBusyStatus(s),\n        onProgress: (f) {\n          BackgroundJob.update(null, f); // PATCH_S163\n          setState(() => _busyProgress = f);\n        },\n      );\n    });\n    if (path == null || !mounted) return;\n    HapticFeedback.mediumImpact(); // PATCH_S83_SYNC_QOL\n    showGoldBurst(context); // PATCH_S169_MOTION_FEEL\n    LampStreak.lightUp().then((info) {\n      // PATCH_S170: light the studio lamp, mark milestones\n      final msg = LampStreak.milestoneMessage(info.streak);\n      if (msg != null && mounted) _toast(msg);\n    });\n    // PATCH_S83_SYNC_QOL: the file size answers "will this upload/share OK?"\n    // right in the done dialog.\n    String sizeNote = \'\';\n    try {\n      final mb = File(path).lengthSync() / (1024 * 1024);\n      sizeNote = \'\\nحجم الملف: ${mb.toStringAsFixed(1)} م.ب\';\n    } catch (_) {}\n    showDialog<void>(\n      context: context,\n      builder: (context) => AlertDialog(\n        backgroundColor: AyatColors.surface,\n        shape: RoundedRectangleBorder(\n          borderRadius: BorderRadius.circular(22),\n          side: const BorderSide(color: AyatColors.hairline),\n        ),\n        title: const Text(\'التصدير جاهز ✓\'),\n        content: Text(\'تم حفظ المقطع بصيغة MP4:\\n$path$sizeNote\',\n            style: Theme.of(context).textTheme.bodyMedium),\n        actions: [\n          TextButton(\n              onPressed: () => Navigator.pop(context),\n              child: const Text(\'إغلاق\')),\n          FilledButton.icon(\n            onPressed: () => SharePlus.instance\n                .share(ShareParams(files: [XFile(path)])),\n            icon: const Icon(Icons.share, size: 16),\n            label: const Text(\'مشاركة الفيديو\'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  // ---------------------------------------------------------------- pickers\n\n  // PATCH_S107_CURATED_NATURE_BACKGROUNDS: bundled photos are Flutter\n  // assets, not files, so the first tap on each copies it once into the\n  // app\'s documents dir and reuses the existing useCustomBg/customBgPath\n  // rendering path from then on -- preview, export, and chroma key all\n  // already just read customBgPath as a normal file.\n  final Map<String, String> _curatedBgResolvedPaths = {};\n\n  Future<void> _useCuratedBg(CuratedBg c) async {\n    var path = _curatedBgResolvedPaths[c.asset];\n    if (path == null) {\n      final docsDir = await getApplicationDocumentsDirectory();\n      final bgDir = Directory(\'${docsDir.path}/curated_bg\');\n      if (!bgDir.existsSync()) bgDir.createSync(recursive: true);\n      final destFile = File(\'${bgDir.path}/${c.asset.split(\'/\').last}\');\n      if (!destFile.existsSync()) {\n        final data = await rootBundle.load(c.asset);\n        await destFile.writeAsBytes(\n            data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes));\n      }\n      path = destFile.path;\n      _curatedBgResolvedPaths[c.asset] = path;\n    }\n    state.update(() {\n      state.useCustomBg = true;\n      state.customBgPath = path;\n    });\n  }\n\n  Future<void> _pickCustomBg() async {\n    final res = await FilePicker.platform.pickFiles(type: FileType.image);\n    final pickedPath = res?.files.single.path;\n    if (pickedPath == null) return;\n    // PATCH_S64_BG_UPLOAD_PERSIST: the picker\'s path is often a transient\n    // cache/content-resolver path the OS can clear at any time (that\'s why\n    // the background used to vanish). Copy it into the app\'s own permanent\n    // documents dir first -- same pattern ai_art_service.dart already uses\n    // for AI-art backgrounds -- and store THAT path instead.\n    final permanentPath = await _copyToPermanentBgStorage(pickedPath);\n    state.update(() {\n      // PATCH_S82_CUSTOM_BG_LIBRARY: kept, not overwritten -- every upload\n      // stays available to reuse later instead of replacing the last one.\n      state.customBgLibrary.add(permanentPath);\n      state.useCustomBg = true;\n      state.customBgPath = permanentPath;\n    });\n    _toast(\'تم رفع الخلفية وحفظها في مكتبتك ✓\');\n  }\n\n  // PATCH_S64_BG_UPLOAD_PERSIST\n  Future<String> _copyToPermanentBgStorage(String pickedPath) async {\n    try {\n      final docs = await getApplicationDocumentsDirectory();\n      final dir = Directory(\'${docs.path}/custom_backgrounds\');\n      if (!await dir.exists()) await dir.create(recursive: true);\n      final ext = pickedPath.contains(\'.\') ? pickedPath.split(\'.\').last : \'img\';\n      final dest = File(\n          \'${dir.path}/${DateTime.now().millisecondsSinceEpoch}.$ext\');\n      await File(pickedPath).copy(dest.path);\n      return dest.path;\n    } catch (_) {\n      // Copy failed (e.g. source already gone) -- fall back to the\n      // original path; better than crashing, even if it may not survive.\n      return pickedPath;\n    }\n  }\n\n  Future<void> _pickCustomFont() async {\n    final res = await FilePicker.platform.pickFiles(\n        type: FileType.custom, allowedExtensions: [\'ttf\', \'otf\']);\n    final file = res?.files.single;\n    if (file?.path == null) return;\n    try {\n      // PATCH_S39_PERSISTENT_FONTS: the font is copied into app storage and\n      // re-registered on every launch — pick Elgharib-NoonHafs.ttf (or any\n      // Quran font) once and it stays the selected font permanently.\n      final choice = await FontService.importFont(file!.path!, file.name);\n      state.update(() {\n        state.customFonts.removeWhere((f) => f.key == choice.key);\n        state.customFonts.add(choice);\n        state.fontKey = choice.key;\n      });\n      _toast(\'تم حفظ الخط وتطبيقه — سيبقى متاحًا بعد إغلاق التطبيق ✓\');\n    } catch (_) {\n      _toast(\'تعذّر تحميل هذا الملف كخط — تأكد أنه TTF أو OTF صالح\');\n    }\n  }\n\n  Future<void> _pickReciterAudio(int i) async {\n    final res = await FilePicker.platform.pickFiles(type: FileType.audio);\n    final path = res?.files.single.path;\n    if (path == null) return;\n    state.update(() => state.reciterAudioPaths[i] = path);\n    _toast(\'تم إرفاق تلاوة لـ ${kReciters[i]} ✓\');\n  }\n\n  Future<void> _toggleReciterPreview(int i) async {\n    final path = state.reciterAudioPaths[i];\n    if (path == null) {\n      _toast(\'أرفق ملف تلاوة صوتية أولًا\');\n      return;\n    }\n    if (_previewingReciter == i && _reciterPreview != null) {\n      await _reciterPreview!.dispose();\n      setState(() {\n        _reciterPreview = null;\n        _previewingReciter = null;\n      });\n      return;\n    }\n    await _reciterPreview?.dispose();\n    final c = VideoPlayerController.file(File(path));\n    setState(() {\n      _reciterPreview = c;\n      _previewingReciter = i;\n    });\n    try {\n      await c.initialize();\n      await c.play();\n      c.addListener(() {\n        if (c.value.position >= c.value.duration &&\n            !c.value.isPlaying &&\n            mounted &&\n            _previewingReciter == i) {\n          setState(() => _previewingReciter = null);\n        }\n      });\n    } catch (_) {\n      _toast(\'تعذّر تشغيل هذا الملف الصوتي\');\n      setState(() {\n        _reciterPreview = null;\n        _previewingReciter = null;\n      });\n    }\n  }\n\n  // PATCH_S104_RECITER_LIBRARY_DOWNLOAD: second way to fill a reciter\n  // slot -- download the real recitation instead of attaching a file.\n  // Reuses state.reciterAudioPaths[i], so playback/export are unchanged.\n  Future<void> _downloadReciterAudio(int i) async {\n    final name = kReciters[i];\n    final surahNum = await _pickSurahForDownload();\n    if (surahNum == null || !mounted) return;\n    setState(() {\n      _downloadingReciter = i;\n      _downloadProgress = null;\n    });\n    try {\n      final path = await ReciterAudioService.downloadSurah(\n        displayName: name,\n        surahNum: surahNum,\n        onProgress: (p) {\n          if (mounted) setState(() => _downloadProgress = p);\n        },\n      );\n      if (!mounted) return;\n      state.update(() => state.reciterAudioPaths[i] = path);\n      _toast(\'تم تنزيل تلاوة $name ✓\');\n    } on ReciterAudioException catch (e) {\n      _toast(e.message);\n    } catch (_) {\n      _toast(\'تعذّر تنزيل الملف الصوتي\');\n    } finally {\n      if (mounted) {\n        setState(() {\n          _downloadingReciter = null;\n          _downloadProgress = null;\n        });\n      }\n    }\n  }\n\n  // Surah picker built from the already-loaded Quran corpus (state.matcher)\n  // rather than a separately maintained list of 114 surah names.\n  Future<int?> _pickSurahForDownload() async {\n    final matcher = state.matcher;\n    final surahs = <int, String>{};\n    if (matcher != null) {\n      for (final a in matcher.ayaat) {\n        surahs[a.surahNum] = a.surah;\n      }\n    }\n    final entries = surahs.entries.toList()\n      ..sort((a, b) => a.key.compareTo(b.key));\n    return showDialog<int>(\n      context: context,\n      builder: (ctx) => AlertDialog(\n        backgroundColor: AyatColors.surface2,\n        title: const Text(\'اختر السورة للتنزيل\'),\n        content: SizedBox(\n          width: double.maxFinite,\n          height: 420,\n          child: entries.isEmpty\n              ? const Center(\n                  child: Text(\'انتظر تحميل بيانات القرآن ثم أعد المحاولة\'))\n              : ListView.builder(\n                  itemCount: entries.length,\n                  itemBuilder: (c, idx) {\n                    final e = entries[idx];\n                    return ListTile(\n                      title: Text(\'${e.key}. ${e.value}\'),\n                      onTap: () => Navigator.pop(ctx, e.key),\n                    );\n                  },\n                ),\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(ctx, null),\n            child: const Text(\'إلغاء\'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Future<void> _applyCustomText() async {\n    final matcher = state.matcher;\n    final ar = _customArCtrl.text.trim();\n    final en = _customEnCtrl.text.trim();\n    if (ar.isEmpty) {\n      _toast(\'اكتب نص الآية أولًا\');\n      return;\n    }\n    _liveOverlay.value = null;\n    void applyMatch(AyahMatch m) {\n      state.setAyah(m.ayah.ar, en.isNotEmpty ? en : m.ayah.en,\n          \'تم التعرّف: سورة ${m.ayah.surah} — آية ${m.ayah.num}\',\n          surahNum: m.ayah.surahNum, ayahNum: m.ayah.num); // PATCH_S32_AI_ART_NANO_BANANA\n      _toast(\'تم العثور على الآية ✓ (سورة ${m.ayah.surah}:${m.ayah.num})\');\n    }\n\n    void applyRaw() {\n      state.setAyah(ar, en, \'نص مخصص (لم يتم العثور على تطابق في القرآن)\');\n      _toast(\'تم استخدام النص كما كتبته\');\n    }\n\n    // PATCH_S35_SMARTER_DETECTION: confident match applies directly; weaker\n    // ones offer the top candidates (plus "use as typed") to choose from.\n    final candidates = matcher?.matchTop(ar, k: 3, minConfidence: 0.2) ??\n        const <AyahMatch>[];\n    if (candidates.isEmpty) {\n      applyRaw();\n      return;\n    }\n    if (candidates.first.confidence >= 0.5) {\n      applyMatch(candidates.first);\n      return;\n    }\n    final picked = await _pickAyahCandidate(candidates, allowRaw: true);\n    if (picked == null) return; // dismissed — change nothing\n    if (picked.$2) {\n      applyRaw();\n    } else if (picked.$1 != null) {\n      applyMatch(picked.$1!);\n    }\n  }\n\n  // ---- PATCH_S191_FEEL: back does the gentle thing first ----------------\n  DateTime _lastBack = DateTime.fromMillisecondsSinceEpoch(0);\n\n  void _onBack(bool didPop, Object? result) {\n    if (didPop) return;\n    if (_toolOpen != -1) {\n      setState(() => _toolOpen = -1);\n      return;\n    }\n    if (_hasSelSeg ||\n        _hasSelCue ||\n        _hasSelMain ||\n        state.stageTextSelected ||\n        state.hasPipSel) {\n      state.clearStageSelection();\n      state.selectPip(-1);\n      setState(() {\n        _selSeg = -1;\n        _selCue = -1;\n        _selMain = false;\n      });\n      return;\n    }\n    final now = DateTime.now();\n    if (state.hasVideo &&\n        now.difference(_lastBack) > const Duration(seconds: 2)) {\n      _lastBack = now;\n      _toast(\'اضغط رجوع مرة أخرى للخروج\');\n      return;\n    }\n    SystemNavigator.pop();\n  }\n\n  void _showInfo() => showAyatInfoDialog(context);\n\n  // ------------------------------------------------------------------ build\n\n  @override\n  Widget build(BuildContext context) => PopScope(\n        canPop: false,\n        onPopInvokedWithResult: _onBack, // PATCH_S191_FEEL\n        child: _studioScaffold(context),\n      );\n\n  Widget _studioScaffold(BuildContext context) {\n    return Scaffold(\n      backgroundColor: AyatColors.ink,\n      // PATCH_S165_UI_REFRESH: transparent bar, shimmering wordmark, gold\n      // hairline - the prototype\'s header.\n      appBar: AppBar(\n        backgroundColor: Colors.transparent,\n        surfaceTintColor: Colors.transparent,\n        scrolledUnderElevation: 0,\n        title: GoldShimmer(child: Text(_t(\'app.name\'))),\n        bottom: PreferredSize(\n          preferredSize: const Size.fromHeight(1),\n          child: Container(\n            height: 1,\n            margin: const EdgeInsets.symmetric(horizontal: 20),\n            decoration: const BoxDecoration(\n              gradient: LinearGradient(\n                colors: [\n                  Colors.transparent,\n                  AyatColors.hairline,\n                  AyatColors.hairline,\n                  Colors.transparent,\n                ],\n                stops: [0, 0.2, 0.8, 1],\n              ),\n            ),\n          ),\n        ),\n        actions: [\n          // PATCH_S56_UNDO_REDO: tester-requested step back / step forward\n          ListenableBuilder(\n            listenable: state,\n            builder: (context, _) => Row(\n              mainAxisSize: MainAxisSize.min,\n              children: [\n                IconButton(\n                  onPressed: state.canUndo ? () { HapticFeedback.selectionClick(); state.undoStep(); } : null, // PATCH_S191_FEEL\n                  icon: const Icon(Icons.undo),\n                  tooltip: _t(\'studio.undo\'),\n                ),\n                IconButton(\n                  onPressed: state.canRedo ? () { HapticFeedback.selectionClick(); state.redoStep(); } : null, // PATCH_S191_FEEL\n                  icon: const Icon(Icons.redo),\n                  tooltip: _t(\'studio.redo\'),\n                ),\n              ],\n            ),\n          ),\n          // PATCH_S123_SETTINGS_SCREEN: language, animations and the reader\'s\n          // light mode live one tap from anywhere in the studio.\n          // PATCH_S165_UI_REFRESH: settings + info share one overflow menu so\n          // the bar only carries the two actions used while editing.\n          PopupMenuButton<int>(\n            icon: const Icon(Icons.more_vert),\n            color: AyatColors.surface2,\n            shape: RoundedRectangleBorder(\n              borderRadius: BorderRadius.circular(14),\n              side: const BorderSide(color: AyatColors.hairline),\n            ),\n            onSelected: (v) {\n              if (v == 0) {\n                Navigator.of(context)\n                    .push(AppMotion.route(const SettingsScreen()));\n              } else {\n                _showInfo();\n              }\n            },\n            itemBuilder: (_) => [\n              PopupMenuItem<int>(\n                value: 0,\n                child: Row(\n                  children: [\n                    const Icon(Icons.settings_outlined,\n                        size: 18, color: AyatColors.goldBright),\n                    const SizedBox(width: 10),\n                    Text(_t(\'settings.title\')),\n                  ],\n                ),\n              ),\n              PopupMenuItem<int>(\n                value: 1,\n                child: Row(\n                  children: [\n                    const Icon(Icons.info_outline,\n                        size: 18, color: AyatColors.goldBright),\n                    const SizedBox(width: 10),\n                    Text(_t(\'studio.info\')),\n                  ],\n                ),\n              ),\n            ],\n          ),\n          Padding(\n            padding: const EdgeInsetsDirectional.only(end: 6),\n            child: Center(child: _exportPill()), // PATCH_S173_INSHOT_LAYOUT\n          ),\n        ],\n      ),\n      body: Stack(\n        children: [\n          const Positioned.fill(child: _AmbientGlow()),\n          SafeArea(\n            child: ListenableBuilder(\n              listenable: state,\n              builder: (context, _) => _studioBody(),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  // ---------------------------------------------------------------------\n  // PATCH_S173_INSHOT_LAYOUT: preview on top, tool strip at the bottom.\n  // ---------------------------------------------------------------------\n\n  // (id, icon, label). 100/101/102 are extra tools, 0..n-1 the existing tabs.\n  // PATCH_S184_PRO_MAIN: one flat strip, every old tab section is its own tool.\n  List<(int, IconData, String)> _toolList() => [\n        (100, Icons.movie_outlined, \'الفيديو\'),\n        (101, Icons.aspect_ratio, \'المقاس\'),\n        (112, Icons.open_with, \'التحويل\'),\n        (107, Icons.speed, \'السرعة\'),\n        (120, Icons.menu_book_outlined, \'الآيات\'),\n        (121, Icons.text_fields, \'النص\'),\n        (122, Icons.border_style, \'الإطار\'),\n        (123, Icons.filter_frames, \'الظل\'),\n        (124, Icons.wb_sunny_outlined, \'التوهج\'),\n        (125, Icons.label_outline, \'اللافتة\'),\n        (126, Icons.opacity, \'الشفافية\'),\n        (108, Icons.animation, \'الحركة\'),\n        (109, Icons.closed_caption_outlined, \'الترجمة\'),\n        (110, Icons.emoji_emotions_outlined, \'ملصقات\'),\n        (113, Icons.picture_in_picture_alt_outlined, \'PIP\'), // PATCH_S188_PIP\n        (127, Icons.wallpaper, \'الخلفية\'),\n        (128, Icons.layers_outlined, \'كروما\'),\n        (130, Icons.auto_awesome_outlined, \'تأثيرات\'),\n        (131, Icons.dashboard_customize_outlined, \'قوالب\'),\n        (103, Icons.palette_outlined, \'اللون\'),\n        (111, Icons.high_quality_outlined, \'تحسين\'),\n        (104, Icons.equalizer, \'الصوت\'),\n        (129, Icons.record_voice_over_outlined, \'القارئ\'),\n        (105, Icons.subtitles_outlined, \'النص المفرَّغ\'),\n        (102, Icons.auto_fix_high, \'لمسات\'),\n        (132, Icons.branding_watermark_outlined, \'علامة\'),\n        (106, Icons.ios_share, \'تصدير سريع\'),\n        (133, Icons.tune, \'الإخراج\'),\n      ];\n\n  Widget _teOnly(TextEditorTab t) => TextEditorPro(\n        key: ValueKey(\'te-${t.name}\'),\n        state: state,\n        segmentTexts: state.unifiedTexts,\n        canvasWidth: 1080,\n        onPickCustomFont: _pickCustomFont,\n        only: t,\n      );\n\n  void _openTool(int id) {\n    HapticFeedback.selectionClick();\n    final switching = _toolOpen != -1 && _toolOpen != id; // PATCH_S176_SMOOTH\n    setState(() {\n      _toolOpen = _toolOpen == id ? -1 : id;\n      if (id < 100) _selectedTab = id;\n    });\n    if (switching && _scrollCtrl.hasClients) _scrollCtrl.jumpTo(0);\n    _centerTool(id);\n  }\n\n  // PATCH_S176_SMOOTH: glide the tapped tool to the middle of the strip.\n  void _centerTool(int id) {\n    final idx = _toolList().indexWhere((t) => t.$1 == id);\n    if (idx < 0 || !_stripCtrl.hasClients) return;\n    final pos = _stripCtrl.position;\n    final target =\n        (8 + idx * 76.0 + 38 - pos.viewportDimension / 2)\n            .clamp(0.0, pos.maxScrollExtent);\n    _stripCtrl.animateTo(target,\n        duration: AppMotion.d(const Duration(milliseconds: 420)),\n        curve: Curves.easeOutCubic);\n  }\n\n  Widget _studioBody() {\n    return LayoutBuilder(builder: (context, c) {\n      // PATCH_S184_PRO_MAIN: resizable, never so tall that the stage disappears\n      final panelH = max(0.0, min(c.maxHeight * _panelFrac, c.maxHeight - 330.0))\n          .clamp(0.0, 560.0)\n          .toDouble();\n      final hasStatus = _busy || state.corpusStatus.isNotEmpty;\n      final dockCompact = _toolOpen != -1 || c.maxHeight < 560; // PATCH_S174_PRO_EDITOR\n      return Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          if (hasStatus)\n            Padding(\n              padding: const EdgeInsets.fromLTRB(16, 6, 16, 0),\n              child: _statusCard(),\n            ),\n          Expanded(\n            child: Padding(\n              padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),\n              child: Stack(\n                children: [\n                  Center(\n                    child: StagePreview(\n                      state: state,\n                      videoController: _video,\n                      liveOverride: _liveOverlay,\n                    ),\n                  ),\n                  if (_video != null && _video!.value.isInitialized) // PATCH_S179_AAA\n                    PositionedDirectional(\n                      start: 6,\n                      top: 6,\n                      child:\n                          ProNowPlayingChip(state: state, controller: _video!),\n                    ),\n                  if (_toolOpen == 112 && _video != null && _video!.value.isInitialized) // PATCH_S180_TRANSFORM\n                    Positioned.fill(child: _xformGestureLayer()),\n                  if (_guides)\n                    Positioned.fill(\n                      child: IgnorePointer(\n                        child: ProGuidesOverlay(aspect: _frameAspect()),\n                      ),\n                    ),\n                  PositionedDirectional(\n                    end: 6,\n                    bottom: 6,\n                    child: Row(\n                      mainAxisSize: MainAxisSize.min,\n                      children: [\n                        _guidesButton(),\n                        const SizedBox(width: 6),\n                        _fullscreenButton(), // PATCH_S175_CAPCUT\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n          if (_video != null && _video!.value.isInitialized)\n            _proDock(dockCompact), // PATCH_S174_PRO_EDITOR\n          if (!state.hasVideo && _toolOpen == -1)\n            Padding(\n              padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),\n              child: FadeSlideIn(child: _uploadHero()), // PATCH_S176_SMOOTH\n            ),\n          // PATCH_S176_SMOOTH: the panel glides open/closed\n          SmoothReveal(\n            show: _toolOpen != -1,\n            child: _toolOpen != -1 ? _toolPanel(panelH) : null,\n          ),\n          SmoothSwap( // PATCH_S176_SMOOTH\n            slide: const Offset(0, 0.3),\n            child: KeyedSubtree(\n              key: ValueKey(_hasAnySel), // PATCH_S181_CLIPTOUCH\n              child: _hasAnySel ? _clipToolStrip() : _toolStrip(),\n            ),\n          ),\n        ],\n      );\n    });\n  }\n\n  // ---------------------------------------------------------------------\n  // PATCH_S174_PRO_EDITOR: CapCut / Premiere / Resolve style timeline dock\n  // (transport with timecode + multi-track timeline) and the contextual\n  // clip toolbar that replaces the tool strip while an ayah clip is selected.\n  // ---------------------------------------------------------------------\n\n  final GlobalKey<ProTimelineState> _tlKey = GlobalKey<ProTimelineState>();\n\n  bool get _hasSelSeg => _selSeg >= 0 && _selSeg < state.timeline.length;\n  // PATCH_S181_CLIPTOUCH\n  bool get _hasSelCue => _selCue >= 0 && _selCue < state.textTimeCues.length;\n  bool get _hasSelMain => _selMain && _video != null && _video!.value.isInitialized;\n  bool get _hasAnySel =>\n      _hasSelSeg || _hasSelCue || _hasSelMain || state.stageTextSelected || state.hasPipSel; // PATCH_S183_TEXT_BAR + PATCH_S188_PIP\n\n  Widget _proDock(bool compact) {\n    final c = _video!;\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      children: [\n        _proTransport(),\n        ProTimeline(\n          key: _tlKey,\n          state: state,\n          controller: c,\n          selectedSeg: _selSeg,\n          // PATCH_S181_CLIPTOUCH: any selection change on the ayah lane first\n          // clears the other kinds; text / main selections set theirs after it.\n          onSelectSeg: (i) {\n            state.clearStageSelection(); // PATCH_S183_TEXT_BAR\n            if (i >= 0) state.selectPip(-1); // PATCH_S188_PIP\n            setState(() {\n              _selSeg = i;\n              _selCue = -1;\n              _selMain = false;\n            });\n          },\n          selectedCue: _hasSelCue ? _selCue : -1,\n          onSelectCue: (i) {\n            if (i >= 0) state.selectPip(-1); // PATCH_S188_PIP\n            setState(() {\n              _selCue = i;\n              _selSeg = -1;\n              _selMain = false;\n            });\n          },\n          selectedMain: _hasSelMain,\n          onSelectMain: (v) {\n            if (v) state.selectPip(-1); // PATCH_S188_PIP\n            setState(() {\n              _selMain = v;\n              if (v) {\n                _selSeg = -1;\n                _selCue = -1;\n              }\n            });\n          },\n          onAddMedia: _addMediaSheet,\n          onAutoSync: _busy ? null : _autoSync, // PATCH_S182_WHISPER_MAIN\n          markers: _markers,\n          compact: compact,\n        ),\n      ],\n    );\n  }\n\n  Widget _tIcon(IconData ic, VoidCallback onTap, String tip,\n      {bool on = false}) {\n    return IconButton(\n      onPressed: onTap,\n      tooltip: tip,\n      padding: EdgeInsets.zero,\n      constraints: const BoxConstraints(minWidth: 32, minHeight: 40),\n      icon: Icon(ic,\n          size: 20,\n          color: on ? AyatColors.goldBright : AyatColors.parchmentDim),\n    );\n  }\n\n  // ---- PATCH_S190_COMFORT ----------------------------------------------\n  // Newest-wins seeking for jogging, and the fine-nudge sheet.\n  bool _seekBusyH = false;\n  int? _seekPendH;\n\n  void _seekCoalesced(int ms) {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    if (_seekBusyH) {\n      _seekPendH = ms;\n      return;\n    }\n    _seekBusyH = true;\n    c.seekTo(Duration(milliseconds: ms)).catchError((_) {}).whenComplete(() {\n      _seekBusyH = false;\n      final p = _seekPendH;\n      _seekPendH = null;\n      if (p != null && mounted) _seekCoalesced(p);\n    });\n  }\n\n  double _jogAcc = 0;\n  int _jogBaseMs = 0;\n  int _jogLastSec = -1;\n\n  void _jogStart() {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    if (c.value.isPlaying) c.pause();\n    _jogAcc = 0;\n    _jogBaseMs = c.value.position.inMilliseconds;\n    _jogLastSec = _jogBaseMs ~/ 1000;\n    HapticFeedback.selectionClick();\n  }\n\n  // Drag the time readout: one frame per ~5 px, a tick every second crossed.\n  void _jogUpdate(double dx) {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    _jogAcc += dx;\n    final fps = state.exportFps.clamp(24, 60);\n    final frames = (_jogAcc / 5.0).round();\n    final total = c.value.duration.inMilliseconds;\n    final ms = (_jogBaseMs + (frames * 1000 / fps).round()).clamp(0, total);\n    if (ms ~/ 1000 != _jogLastSec) {\n      _jogLastSec = ms ~/ 1000;\n      HapticFeedback.selectionClick();\n    }\n    _seekCoalesced(ms);\n  }\n\n  Future<void> _openNudgeSheet() async {\n    final isSeg = _hasSelSeg;\n    final isCue = !isSeg && _hasSelCue;\n    final isPip = !isSeg && !isCue && state.hasPipSel;\n    if (!isSeg && !isCue && !isPip) return;\n    final si = _selSeg, ci = _selCue, pi = state.pipSel;\n    final total = (_video?.value.duration.inMilliseconds ?? 0) / 1000.0;\n    final fps = state.exportFps.clamp(24, 60);\n\n    (double, double) range() {\n      if (isSeg && si < state.timeline.length) {\n        return (state.timeline[si].start, state.timeline[si].end);\n      }\n      if (isCue && ci < state.textTimeCues.length) {\n        return (state.textTimeCues[ci].start, state.textTimeCues[ci].end);\n      }\n      if (isPip && pi < state.pipClips.length) {\n        return (state.pipClips[pi].start, state.pipClips[pi].end);\n      }\n      return (0.0, 0.0);\n    }\n\n    void nudge(int mode, double d) {\n      final (s0, e0) = range();\n      if (e0 <= s0) return;\n      // keep the whole block inside the clip when moving it\n      var dd = d;\n      if (mode == 2) {\n        if (s0 + dd < 0) dd = -s0;\n        if (total > 0 && e0 + dd > total) dd = total - e0;\n      }\n      if (mode == 1 && total > 0 && e0 + dd > total) dd = total - e0;\n      if (dd == 0) return;\n      if (isSeg) {\n        state.nudgeTimelineSegment(si,\n            startDelta: mode == 0 ? dd : 0, endDelta: mode == 1 ? dd : 0);\n      } else if (isCue) {\n        state.pushHistory();\n        state.setTextCueWindow(ci,\n            start: mode == 1 ? null : s0 + dd, end: mode == 0 ? null : e0 + dd);\n      } else {\n        state.pushHistory();\n        if (mode == 2) {\n          state.movePipTo(pi, s0 + dd);\n        } else {\n          state.setPipWindow(pi,\n              start: mode == 0 ? s0 + dd : null,\n              end: mode == 1 ? e0 + dd : null);\n        }\n      }\n      final (s1, e1) = range();\n      final at = mode == 1 ? max(s1, e1 - 0.05) : s1;\n      _seekCoalesced((at * 1000).round());\n    }\n\n    await showNudgeSheet(\n      context,\n      title: isSeg ? \'إزاحة دقيقة — آية\' : (isCue ? \'إزاحة دقيقة — نص\' : \'إزاحة دقيقة — PIP\'),\n      canMove: !isSeg,\n      frame: 1.0 / fps,\n      range: range,\n      onNudge: nudge,\n    );\n  }\n\n  Widget _proTransport() {\n    final c = _video!;\n    return Container(\n      height: 54,\n      padding: const EdgeInsets.symmetric(horizontal: 8),\n      decoration: const BoxDecoration(\n        color: AyatColors.surface,\n        border: Border(top: BorderSide(color: AyatColors.hairline)),\n      ),\n      child: Directionality(\n        textDirection: TextDirection.ltr,\n        child: ValueListenableBuilder<VideoPlayerValue>(\n          valueListenable: c,\n          builder: (context, v, _) {\n            final durS = max(0.1, v.duration.inMilliseconds / 1000.0);\n            final posS = (v.position.inMilliseconds / 1000.0)\n                .clamp(0.0, durS)\n                .toDouble();\n            return Row(\n              children: [\n                SizedBox(\n                  width: 84,\n                  child: GestureDetector(\n                    behavior: HitTestBehavior.opaque,\n                    onTap: _goToTime, // PATCH_S179_AAA\n                    onHorizontalDragStart: (_) => _jogStart(), // PATCH_S190_COMFORT\n                    onHorizontalDragUpdate: (d) => _jogUpdate(d.delta.dx),\n                    child: Column(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(_fmtSecFine(posS),\n                          style: const TextStyle(\n                              fontSize: 13,\n                              fontWeight: FontWeight.w800,\n                              color: AyatColors.goldBright,\n                              fontFeatures: [FontFeature.tabularFigures()])),\n                      Text(\'/ ${_fmtSecFine(durS)}\',\n                          style: const TextStyle(\n                              fontSize: 10,\n                              color: AyatColors.parchmentDim,\n                              fontFeatures: [FontFeature.tabularFigures()])),\n                    ],\n                  ),\n                  ),\n                ),\n                GestureDetector(\n                  onLongPress: () => _jumpMarker(-1), // PATCH_S179_AAA\n                  child: IconButton(\n                    onPressed: () => _seekToAdjacentAyah(-1),\n                    padding: EdgeInsets.zero,\n                    constraints:\n                        const BoxConstraints(minWidth: 32, minHeight: 40),\n                    icon: const Icon(Icons.skip_previous_rounded,\n                        size: 20, color: AyatColors.parchmentDim),\n                  ),\n                ),\n                GestureDetector(\n                  onTap: () {\n                    HapticFeedback.selectionClick();\n                    if (v.isPlaying) {\n                      c.pause();\n                    } else {\n                      c.play();\n                    }\n                  },\n                  child: Container(\n                    width: 40,\n                    height: 40,\n                    margin: const EdgeInsets.symmetric(horizontal: 3),\n                    decoration: BoxDecoration(\n                      shape: BoxShape.circle,\n                      gradient: const LinearGradient(\n                        begin: Alignment.topCenter,\n                        end: Alignment.bottomCenter,\n                        colors: [AyatColors.goldBright, AyatColors.gold],\n                      ),\n                      boxShadow: [\n                        BoxShadow(\n                          color: AyatColors.gold\n                              .withValues(alpha: v.isPlaying ? 0.55 : 0.3),\n                          blurRadius: v.isPlaying ? 18 : 10,\n                        ),\n                      ],\n                    ),\n                    child: Icon(\n                      v.isPlaying\n                          ? Icons.pause_rounded\n                          : Icons.play_arrow_rounded,\n                      size: 26,\n                      color: AyatColors.ink,\n                    ),\n                  ),\n                ),\n                GestureDetector(\n                  onLongPress: () => _jumpMarker(1), // PATCH_S179_AAA\n                  child: IconButton(\n                    onPressed: () => _seekToAdjacentAyah(1),\n                    padding: EdgeInsets.zero,\n                    constraints:\n                        const BoxConstraints(minWidth: 32, minHeight: 40),\n                    icon: const Icon(Icons.skip_next_rounded,\n                        size: 20, color: AyatColors.parchmentDim),\n                  ),\n                ),\n                const Spacer(),\n                _tIcon(Icons.content_cut, _splitAtPlayhead, \'تقسيم عند المؤشر\'),\n                _tIcon(Icons.bookmark_border, _toggleMarker, \'علامة\'),\n                _tIcon(Icons.repeat_one, () {\n                  HapticFeedback.selectionClick();\n                  setState(() => _loopAyah = !_loopAyah);\n                  _toast(_loopAyah\n                      ? \'تكرار الآية الحالية مفعّل\'\n                      : \'تم إيقاف تكرار الآية\');\n                }, \'تكرار الآية\', on: _loopAyah),\n                TextButton(\n                  onPressed: _cycleSpeed,\n                  style: TextButton.styleFrom(\n                    minimumSize: const Size(34, 40),\n                    padding: EdgeInsets.zero,\n                  ),\n                  child: Text(\n                    _speedLabel(_playbackSpeed),\n                    style: TextStyle(\n                        fontSize: 11,\n                        fontWeight: FontWeight.w700,\n                        color: _playbackSpeed == 1.0\n                            ? AyatColors.parchmentDim\n                            : AyatColors.goldBright),\n                  ),\n                ),\n              ],\n            );\n          },\n        ),\n      ),\n    );\n  }\n\n  /// Split the ayah clip under the playhead in two (CapCut\'s scissors).\n  void _splitAtPlayhead() {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    final t = c.value.position.inMilliseconds / 1000.0;\n    final seg = state.segmentAt(t);\n    // PATCH_S181_CLIPTOUCH: a selected text block is split in preference to\n    // whatever ayah happens to sit under the playhead.\n    if (_hasSelCue) {\n      final sc = state.textTimeCues[_selCue];\n      if (t > sc.start + 0.3 && t < sc.end - 0.3) {\n        _cueSplit(_selCue);\n        return;\n      }\n    }\n    // PATCH_S194_CUT_FX: a PIP clip (selected first, else under the playhead)\n    final pi = state.hasPipSel &&\n            t > state.pipClips[state.pipSel].start + 0.3 &&\n            t < state.pipClips[state.pipSel].end - 0.3\n        ? state.pipSel\n        : state.pipClips.indexWhere(\n            (p) => t > p.start + 0.3 && t < p.end - 0.3);\n    if (pi >= 0) {\n      if (state.splitPipAt(pi, t)) {\n        HapticFeedback.mediumImpact();\n      } else {\n        _toast(\'ضع المؤشر داخل المقطع الصغير ثم قسّم\');\n      }\n      return;\n    }\n    if (seg == null) {\n      final ci = state.textTimeCues\n          .indexWhere((c) => t > c.start + 0.3 && t < c.end - 0.3);\n      if (ci >= 0) {\n        _cueSplit(ci);\n        return;\n      }\n      _toast(\'ضع المؤشر داخل آية أو نص لتقسيمه\');\n      return;\n    }\n    final i = state.timeline.indexOf(seg);\n    state.pushHistory();\n    if (state.splitTimelineSegment(i, t)) {\n      HapticFeedback.mediumImpact();\n      setState(() => _selSeg = i + 1);\n    } else {\n      _toast(\'المؤشر قريب جدًا من حافة الآية\');\n    }\n  }\n\n  /// Drop / remove a marker at the playhead (Premiere + Resolve markers).\n  void _toggleMarker() {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    final t = c.value.position.inMilliseconds / 1000.0;\n    final near = _markers.indexWhere((m) => (m - t).abs() < 0.3);\n    setState(() {\n      if (near >= 0) {\n        _markers.removeAt(near);\n      } else {\n        _markers.add(t);\n        _markers.sort();\n      }\n    });\n    HapticFeedback.selectionClick();\n  }\n\n  void _deleteSegWithUndo(int i) {\n    final removed = state.removeTimelineSegment(i);\n    if (removed == null) return;\n    setState(() => _selSeg = -1);\n    ScaffoldMessenger.of(context)\n      ..hideCurrentSnackBar()\n      ..showSnackBar(SnackBar(\n        content: const Text(\'تم حذف الآية من الخط الزمني\',\n            textAlign: TextAlign.center),\n        behavior: SnackBarBehavior.floating,\n        duration: const Duration(seconds: 5),\n        action: SnackBarAction(\n          label: \'تراجع\',\n          textColor: AyatColors.goldBright,\n          onPressed: () => state.insertTimelineSegment(i, removed),\n        ),\n      ));\n  }\n\n  /// CapCut-style contextual toolbar: while an ayah clip is selected the\n  /// bottom strip turns into that clip\'s actions.\n  Widget _clipToolStrip() {\n    // PATCH_S181_CLIPTOUCH: text blocks and the main clip have their own bars\n    // PATCH_S183_TEXT_BAR: the text on the stage / its block on the timeline has a text bar\n    if (state.stageTextSelected && !_hasSelSeg) return _clipBar(_textItems());\n    if (state.hasPipSel && !_hasSelSeg) return _clipBar(_pipItems()); // PATCH_S188_PIP\n    if (!_hasSelSeg) return _clipBar(_hasSelCue ? _cueItems() : _mainItems());\n    final i = _selSeg;\n    final items = <(IconData, String, VoidCallback, bool)>[\n      (Icons.check_circle_outline, \'تم\', () => setState(() { _selSeg = -1; _toolOpen = -1; }), // PATCH_S185_POLISH\n          false),\n      (Icons.content_cut, \'تقسيم\', _splitAtPlayhead, false),\n      ..._segExtraItems(i), // PATCH_S181_CLIPTOUCH\n      (Icons.tune, \'التوقيت\', () => _editSegmentTiming(i), false),\n      (Icons.straighten, \'إزاحة دقيقة\', _openNudgeSheet, false), // PATCH_S190_COMFORT\n      (Icons.swap_horiz, \'تغيير الآية\', () => _changeSegmentAyahDialog(i),\n          false),\n      if (i + 1 < state.timeline.length)\n        (\n          Icons.call_merge,\n          \'دمج\',\n          () {\n            state.pushHistory();\n            state.mergeTimelineSegments(i);\n            _toast(\'تم دمج المقطعين\');\n          },\n          false\n        ),\n      (\n        Icons.repeat_one,\n        \'تكرار\',\n        () {\n          HapticFeedback.selectionClick();\n          setState(() => _loopAyah = !_loopAyah);\n        },\n        _loopAyah\n      ),\n      (Icons.delete_outline, \'حذف\', () => _deleteSegWithUndo(i), false),\n    ];\n    return Container(\n      height: 68,\n      decoration: const BoxDecoration(\n        color: AyatColors.ink,\n        border: Border(top: BorderSide(color: AyatColors.hairline)),\n      ),\n      child: Material(\n        color: Colors.transparent,\n        child: ListView.builder(\n          scrollDirection: Axis.horizontal,\n          padding: const EdgeInsets.symmetric(horizontal: 8),\n          itemCount: items.length,\n          itemBuilder: (context, k) {\n            final it = items[k];\n            final col = it.$4 ? AyatColors.goldBright : AyatColors.parchmentDim;\n            return PressableScale( // PATCH_S186_SMOOTH_CONTROL\n              borderRadius: BorderRadius.circular(14),\n              pressedScale: 0.9,\n              onTap: () {\n                HapticFeedback.selectionClick();\n                it.$3();\n              },\n              child: SizedBox(\n                width: min(76.0, MediaQuery.of(context).size.width / 6.4), // PATCH_S182_WHISPER_MAIN\n                child: Column(\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  children: [\n                    Icon(it.$1, size: 23, color: col),\n                    const SizedBox(height: 4),\n                    Text(it.$2,\n                        maxLines: 1,\n                        overflow: TextOverflow.ellipsis,\n                        style: TextStyle(\n                            fontSize: 11,\n                            fontWeight: FontWeight.w700,\n                            color: col)),\n                  ],\n                ),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n\n  // ---------------------------------------------------------------------\n  // PATCH_S181_CLIPTOUCH: touchable clips (ayah blocks, text blocks, the main\n  // clip), trim-to-playhead, transitions, zoom, add video / picture, and the\n  // folded "advanced" card of the آيات tab.\n  // ---------------------------------------------------------------------\n\n  double get _playheadSec {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return 0;\n    return c.value.position.inMilliseconds / 1000.0;\n  }\n\n  Widget _clipBar(List<(IconData, String, VoidCallback, bool)> items) {\n    return Container(\n      height: 68,\n      decoration: const BoxDecoration(\n        color: AyatColors.ink,\n        border: Border(top: BorderSide(color: AyatColors.hairline)),\n      ),\n      child: Material(\n        color: Colors.transparent,\n        child: ListView.builder(\n          scrollDirection: Axis.horizontal,\n          padding: const EdgeInsets.symmetric(horizontal: 8),\n          itemCount: items.length,\n          itemBuilder: (context, k) {\n            final it = items[k];\n            final col = it.$4 ? AyatColors.goldBright : AyatColors.parchmentDim;\n            return PressableScale( // PATCH_S186_SMOOTH_CONTROL\n              borderRadius: BorderRadius.circular(14),\n              pressedScale: 0.9,\n              onTap: () {\n                HapticFeedback.selectionClick();\n                it.$3();\n              },\n              child: SizedBox(\n                width: min(76.0, MediaQuery.of(context).size.width / 6.4), // PATCH_S182_WHISPER_MAIN\n                child: Column(\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  children: [\n                    Icon(it.$1, size: 23, color: col),\n                    const SizedBox(height: 4),\n                    Text(it.$2,\n                        maxLines: 1,\n                        overflow: TextOverflow.ellipsis,\n                        style: TextStyle(\n                            fontSize: 11,\n                            fontWeight: FontWeight.w700,\n                            color: col)),\n                  ],\n                ),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n\n  /// Extra actions for a selected ayah block (placed after «تقسيم»).\n  List<(IconData, String, VoidCallback, bool)> _segExtraItems(int i) => [\n        (Icons.first_page, \'قص البداية\', () => _trimSeg(i, head: true), false),\n        (Icons.last_page, \'قص النهاية\', () => _trimSeg(i, head: false), false),\n        (Icons.animation, \'انتقال\', _openTransitionSheet, false),\n        (Icons.zoom_in, \'تكبير\', _zoomToSelection, false),\n        // PATCH_S184_PRO_MAIN\n        (Icons.text_fields, \'النمط\', () => _openToolFromClip(121), _toolOpen == 121),\n        (Icons.animation, \'الحركة\', () => _openToolFromClip(108), _toolOpen == 108),\n        (Icons.closed_caption_outlined, \'الترجمة\', () => _openToolFromClip(109), _toolOpen == 109),\n        (Icons.record_voice_over_outlined, \'القارئ\', () => _openToolFromClip(129), _toolOpen == 129),\n        (Icons.tune, \'ضبط\', _openTextTuneSheet, false), // PATCH_S186_SMOOTH_CONTROL\n      ];\n\n  void _trimSeg(int i, {required bool head}) {\n    if (i < 0 || i >= state.timeline.length) return;\n    final seg = state.timeline[i];\n    final t = _playheadSec;\n    if (t <= seg.start + 0.3 || t >= seg.end - 0.3) {\n      _toast(\'ضع المؤشر داخل الآية المحددة ثم اقصّ\');\n      return;\n    }\n    HapticFeedback.mediumImpact();\n    if (head) {\n      state.nudgeTimelineSegment(i, startDelta: t - seg.start);\n    } else {\n      state.nudgeTimelineSegment(i, endDelta: t - seg.end);\n    }\n  }\n\n  // ---- text blocks --------------------------------------------------------\n\n  List<(IconData, String, VoidCallback, bool)> _cueItems() {\n    final i = _selCue;\n    return [\n      (Icons.check_circle_outline, \'تم\', () => setState(() { _selCue = -1; _toolOpen = -1; }), false), // PATCH_S185_POLISH\n      (Icons.content_cut, \'تقسيم\', () => _cueSplit(i), false),\n      (Icons.first_page, \'قص البداية\', () => _cueTrim(i, head: true), false),\n      (Icons.last_page, \'قص النهاية\', () => _cueTrim(i, head: false), false),\n      (Icons.animation, \'انتقال\', _openTransitionSheet, false),\n      (Icons.edit_outlined, \'تعديل النص\', () => _cueEditText(i), false),\n      (Icons.straighten, \'إزاحة دقيقة\', _openNudgeSheet, false), // PATCH_S190_COMFORT\n      (Icons.text_fields, \'النمط\', () => _openToolFromClip(121), _toolOpen == 121),\n      (Icons.border_style, \'الإطار\', () => _openToolFromClip(122), _toolOpen == 122),\n      (Icons.filter_frames, \'الظل\', () => _openToolFromClip(123), _toolOpen == 123),\n      (Icons.zoom_in, \'تكبير\', _zoomToSelection, false),\n      (Icons.content_copy, \'نسخ\', () => _cueDuplicate(i), false),\n      (Icons.delete_outline, \'حذف\', () => _cueDelete(i), false),\n    ];\n  }\n\n  void _cueSplit(int i) {\n    if (i < 0 || i >= state.textTimeCues.length) return;\n    final t = _playheadSec;\n    state.pushHistory();\n    if (state.splitTextCueAt(i, t)) {\n      HapticFeedback.mediumImpact();\n      setState(() {\n        _selCue = i + 1;\n        _selSeg = -1;\n        _selMain = false;\n      });\n    } else {\n      _toast(\'ضع المؤشر داخل النص المحدد ثم قسّم\');\n    }\n  }\n\n  void _cueTrim(int i, {required bool head}) {\n    if (i < 0 || i >= state.textTimeCues.length) return;\n    final c = state.textTimeCues[i];\n    final t = _playheadSec;\n    if (t <= c.start + 0.3 || t >= c.end - 0.3) {\n      _toast(\'ضع المؤشر داخل النص المحدد ثم اقصّ\');\n      return;\n    }\n    HapticFeedback.mediumImpact();\n    state.pushHistory();\n    state.setTextCueWindow(i, start: head ? t : null, end: head ? null : t);\n  }\n\n  void _cueDuplicate(int i) {\n    if (i < 0 || i >= state.textTimeCues.length) return;\n    state.pushHistory();\n    state.duplicateTextCue(i);\n    HapticFeedback.selectionClick();\n    setState(() => _selCue = i + 1);\n  }\n\n  void _cueDelete(int i) {\n    if (i < 0 || i >= state.textTimeCues.length) return;\n    state.pushHistory();\n    state.removeTextTimeCueAt(i);\n    setState(() => _selCue = -1);\n    ScaffoldMessenger.of(context)\n      ..hideCurrentSnackBar()\n      ..showSnackBar(SnackBar(\n        content: const Text(\'تم حذف النص من الخط الزمني\',\n            textAlign: TextAlign.center),\n        behavior: SnackBarBehavior.floating,\n        duration: const Duration(seconds: 5),\n        action: SnackBarAction(\n          label: \'تراجع\',\n          textColor: AyatColors.goldBright,\n          onPressed: state.undoStep,\n        ),\n      ));\n  }\n\n  // PATCH_S189_QURAN_TYPE: typing a text, the Quran finishes it.\n  Future<void> _addQuranText() async {\n    final main = _video;\n    if (!state.hasVideo || main == null || !main.value.isInitialized) {\n      _toast(\'ارفع فيديو أولًا\');\n      return;\n    }\n    final r = await showQuranTextSheet(context,\n        ayaat: state.ayaat, title: \'نص جديد\');\n    if (r == null || !mounted) return;\n    final total = main.value.duration.inMilliseconds / 1000.0;\n    var s = _playheadSec;\n    var e = s + 4.0;\n    if (e > total) {\n      e = total;\n      s = max(0.0, total - 4.0);\n    }\n    if (e - s < 0.3) {\n      _toast(\'المقطع الأساسي قصير جدًّا\');\n      return;\n    }\n    state.update(() {\n      state.textTimeCues = [\n        ...state.textTimeCues,\n        TextTimeCue(\n            text: r.text, translation: r.translation, start: s, end: e),\n      ];\n    });\n    HapticFeedback.mediumImpact();\n    setState(() {\n      _selCue = state.textTimeCues.length - 1;\n      _selSeg = -1;\n      _selMain = false;\n    });\n    _toast(\'أُضيف النص\');\n  }\n\n  Future<void> _cueEditText(int i) async {\n    if (i < 0 || i >= state.textTimeCues.length) return;\n    final cue = state.textTimeCues[i];\n    final r = await showQuranTextSheet(context,\n        ayaat: state.ayaat,\n        title: \'تعديل النص\',\n        initial: cue.text,\n        initialTranslation: cue.translation);\n    if (r == null || !mounted) return;\n    if (i >= state.textTimeCues.length) return;\n    state.update(() {\n      cue.text = r.text;\n      cue.translation = r.translation;\n    });\n  }\n\n  // ---- the main clip ------------------------------------------------------\n\n  List<(IconData, String, VoidCallback, bool)> _mainItems() => [\n        (Icons.check_circle_outline, \'تم\', () => setState(() { _selMain = false; _toolOpen = -1; }), false), // PATCH_S185_POLISH\n        // PATCH_S182_WHISPER_MAIN: Whisper on the main screen\n        (Icons.auto_awesome, \'مزامنة تلقائية\', () { if (!_busy) _autoSync(); }, state.timelineActive),\n        (Icons.manage_search, \'تعرّف من الصوت\', () { if (!_busy) _detectFromVideo(); }, false),\n        (Icons.spellcheck, \'كتابة بالقرآن\', _addQuranText, false), // PATCH_S189_QURAN_TYPE\n        (Icons.hearing, \'دقة التعرّف\', () { if (!_busy) _showModelSizePicker(); }, false),\n        (Icons.first_page, \'قص البداية\', () => _trimMain(head: true), false),\n        (Icons.last_page, \'قص النهاية\', () => _trimMain(head: false), false),\n        (\n          Icons.restart_alt,\n          \'إعادة القص\',\n          _trimMainReset,\n          state.manualTrimSet || state.trimFromIndex >= 0\n        ),\n        (Icons.add_photo_alternate_outlined, \'إضافة\', _addMediaSheet, false),\n        (Icons.animation, \'انتقال\', _openTransitionSheet, false),\n        (Icons.open_with, \'التحويل\', () => _openToolFromClip(112), false),\n        (Icons.auto_awesome_outlined, \'تأثيرات\', () => _openToolFromClip(130), _toolOpen == 130), // PATCH_S194_CUT_FX\n        (Icons.picture_in_picture_alt_outlined, \'PIP\', () => _openToolFromClip(113), _toolOpen == 113), // PATCH_S188_PIP\n        (Icons.speed, \'السرعة\', () => _openToolFromClip(107), _toolOpen == 107),\n        // PATCH_S184_PRO_MAIN: every tool of the main clip, one tap away\n        (Icons.palette_outlined, \'اللون\', () => _openToolFromClip(103), _toolOpen == 103),\n        (Icons.equalizer, \'الصوت\', () => _openToolFromClip(104), _toolOpen == 104),\n        (Icons.high_quality_outlined, \'تحسين\', () => _openToolFromClip(111), _toolOpen == 111),\n        (Icons.aspect_ratio, \'المقاس\', () => _openToolFromClip(101), _toolOpen == 101),\n        (Icons.wallpaper, \'الخلفية\', () => _openToolFromClip(127), _toolOpen == 127),\n        (Icons.layers_outlined, \'كروما\', () => _openToolFromClip(128), _toolOpen == 128),\n        (Icons.fit_screen_outlined, \'ملاءمة\', () => _tlKey.currentState?.fit(), false),\n      ];\n\n  void _openToolFromClip(int id) {\n    _openTool(id); // PATCH_S184_PRO_MAIN: keep the selection, tap again to close the tool\n  }\n\n  void _trimMain({required bool head}) {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    final dur = c.value.duration.inMilliseconds / 1000.0;\n    final t = _playheadSec;\n    final end = state.trimManualEnd < 0 ? dur : min(state.trimManualEnd, dur);\n    final start = min(state.trimManualStart, end);\n    if (head ? t >= end - 0.5 : t <= start + 0.5) {\n      _toast(\'ضع المؤشر داخل المقطع المحدد ثم اقصّ\');\n      return;\n    }\n    HapticFeedback.mediumImpact();\n    state.update(() {\n      state.trimFromIndex = -1;\n      state.trimToIndex = -1;\n      if (head) {\n        state.trimManualStart = max(0.0, t);\n        state.trimManualEnd = end;\n      } else {\n        state.trimManualStart = start;\n        state.trimManualEnd = min(t, dur);\n      }\n    });\n  }\n\n  void _trimMainReset() {\n    HapticFeedback.selectionClick();\n    state.update(() {\n      state.trimFromIndex = -1;\n      state.trimToIndex = -1;\n      state.trimManualStart = 0;\n      state.trimManualEnd = -1;\n    });\n  }\n\n  void _zoomToSelection() {\n    double? a;\n    double? b;\n    if (_hasSelSeg) {\n      a = state.timeline[_selSeg].start;\n      b = state.timeline[_selSeg].end;\n    } else if (_hasSelCue) {\n      a = state.textTimeCues[_selCue].start;\n      b = state.textTimeCues[_selCue].end;\n    } else if (_hasSelMain) {\n      a = 0;\n      b = max(0.5, state.videoDurationSec);\n    }\n    if (a == null || b == null) return;\n    _tlKey.currentState?.zoomToRange(a, b);\n  }\n\n  // ---- transitions --------------------------------------------------------\n\n  /// Quick access to the entrance / exit style from any selected clip. The\n  /// style is one setting for all text (that is how the exporter works), and\n  /// the sheet says so.\n  void _openTransitionSheet() {\n    HapticFeedback.selectionClick();\n    showModalBottomSheet<void>(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      isScrollControlled: true,\n      shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),\n      builder: (ctx) => SafeArea(\n        child: ListenableBuilder(\n          listenable: state,\n          builder: (context, _) => ConstrainedBox(\n            constraints: BoxConstraints(\n                maxHeight: MediaQuery.of(ctx).size.height * 0.72),\n            child: SingleChildScrollView(\n              padding: const EdgeInsets.fromLTRB(16, 14, 16, 20),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Text(\'الانتقال يُطبَّق على ظهور كل نص واختفائه\',\n                      style: Theme.of(ctx).textTheme.bodyMedium?.copyWith(\n                          color: AyatColors.goldBright,\n                          fontWeight: FontWeight.w700)),\n                  const SizedBox(height: 10),\n                  _textTransitionSection(),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  // ---- add a video / a picture --------------------------------------------\n\n  // ---------------------------------------------------------------------\n  // PATCH_S188_PIP: a little video / picture floating over the main clip.\n  // ---------------------------------------------------------------------\n\n  Future<void> _addPip({required bool image}) async {\n    final main = _video;\n    if (!state.hasVideo || main == null || !main.value.isInitialized) {\n      _toast(\'ارفع فيديو أولًا\');\n      return;\n    }\n    final res = await FilePicker.platform\n        .pickFiles(type: image ? FileType.image : FileType.video);\n    final path = res?.files.single.path;\n    if (path == null || !mounted) return;\n    var aspect = 9 / 16;\n    var mediaDur = 0.0;\n    try {\n      if (image) {\n        final bytes = await File(path).readAsBytes();\n        final img = await decodeImageFromList(bytes);\n        aspect = img.width / img.height;\n        img.dispose();\n      } else {\n        final probe = VideoPlayerController.file(File(path));\n        try {\n          await probe.initialize();\n          aspect = probe.value.size.width / probe.value.size.height;\n          mediaDur = probe.value.duration.inMilliseconds / 1000.0;\n        } finally {\n          await probe.dispose();\n        }\n      }\n    } catch (_) {\n      _toast(\'تعذّر فتح الملف\');\n      return;\n    }\n    if (!aspect.isFinite || aspect <= 0.05) {\n      _toast(\'هذا الملف لا يحتوي على صورة\');\n      return;\n    }\n    if (!mounted) return;\n    final total = main.value.duration.inMilliseconds / 1000.0;\n    final want = image ? 4.0 : (mediaDur > 0.5 ? mediaDur : 4.0);\n    var start = _playheadSec;\n    var end = start + want;\n    if (end > total) {\n      end = total;\n      start = (total - want) < 0 ? 0.0 : (total - want);\n    }\n    if (end - start < 0.5) {\n      _toast(\'المقطع الأساسي قصير جدًّا\');\n      return;\n    }\n    state.addPip(PipClip(\n      path: path,\n      isImage: image,\n      aspect: aspect,\n      mediaDur: mediaDur,\n      start: start,\n      end: end,\n      width: aspect < 0.8 ? 0.36 : 0.5,\n    ));\n    HapticFeedback.mediumImpact();\n    if (_toolOpen != 113) _openTool(113);\n    _toast(image ? \'أُضيفت الصورة\' : \'أُضيف الفيديو\');\n  }\n\n  List<(IconData, String, VoidCallback, bool)> _pipItems() {\n    final i = state.pipSel;\n    return [\n      (\n        Icons.check_circle_outline,\n        \'تم\',\n        () {\n          state.selectPip(-1);\n          setState(() => _toolOpen = -1);\n        },\n        false\n      ),\n      (Icons.tune, \'الخصائص\', () => _openToolFromClip(113), _toolOpen == 113),\n      (Icons.auto_awesome_outlined, \'تأثيرات\', () => _openToolFromClip(130), _toolOpen == 130), // PATCH_S194_CUT_FX\n      (Icons.content_cut, \'تقسيم\', () => _pipSplit(i), false),\n      (Icons.first_page, \'قص البداية\', () => _pipTrim(i, head: true), false),\n      (Icons.last_page, \'قص النهاية\', () => _pipTrim(i, head: false), false),\n      (Icons.flip_to_front, \'للأمام\', () => state.movePipLayer(i, 1), false),\n      (Icons.flip_to_back, \'للخلف\', () => state.movePipLayer(i, -1), false),\n      (Icons.straighten, \'إزاحة دقيقة\', _openNudgeSheet, false), // PATCH_S190_COMFORT\n      (Icons.content_copy, \'نسخ\', () => state.duplicatePipAt(i), false),\n      (Icons.delete_outline, \'حذف\', () => _pipDelete(i), false),\n    ];\n  }\n\n  void _pipSplit(int i) {\n    if (state.splitPipAt(i, _playheadSec)) {\n      HapticFeedback.mediumImpact();\n    } else {\n      _toast(\'ضع المؤشر داخل المقطع الصغير ثم قسّم\');\n    }\n  }\n\n  void _pipTrim(int i, {required bool head}) {\n    if (i < 0 || i >= state.pipClips.length) return;\n    final c = state.pipClips[i];\n    final t = _playheadSec;\n    if (t <= c.start + 0.3 || t >= c.end - 0.3) {\n      _toast(\'ضع المؤشر داخل المقطع الصغير ثم اقصّ\');\n      return;\n    }\n    HapticFeedback.mediumImpact();\n    state.pushHistory();\n    state.setPipWindow(i, start: head ? t : null, end: head ? null : t);\n  }\n\n  void _pipDelete(int i) {\n    if (i < 0 || i >= state.pipClips.length) return;\n    HapticFeedback.mediumImpact();\n    state.removePipAt(i);\n    ScaffoldMessenger.of(context)\n      ..hideCurrentSnackBar()\n      ..showSnackBar(SnackBar(\n        content: const Text(\'تم حذف المقطع الصغير\', textAlign: TextAlign.center),\n        behavior: SnackBarBehavior.floating,\n        duration: const Duration(seconds: 5),\n        action: SnackBarAction(\n          label: \'تراجع\',\n          textColor: AyatColors.goldBright,\n          onPressed: state.undoStep,\n        ),\n      ));\n  }\n\n  Future<void> _addMediaSheet() async {\n    if (!state.hasVideo) {\n      _toast(\'ارفع ملفًا أولًا\');\n      return;\n    }\n    final choice = await showModalBottomSheet<String>(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),\n      builder: (ctx) => SafeArea(\n        child: Padding(\n          padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n              Text(\'إضافة بعد نهاية المقطع\',\n                  style: Theme.of(ctx).textTheme.headlineMedium),\n              const SizedBox(height: 8),\n              ListTile(\n                leading: const Icon(Icons.movie_outlined,\n                    color: AyatColors.goldBright),\n                title: const Text(\'فيديو\'),\n                onTap: () => Navigator.pop(ctx, \'video\'),\n              ),\n              ListTile(\n                leading: const Icon(Icons.image_outlined,\n                    color: AyatColors.goldBright),\n                title: const Text(\'صورة\'),\n                onTap: () => Navigator.pop(ctx, \'image\'),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n    if (choice == null || !mounted) return;\n    final res = await FilePicker.platform\n        .pickFiles(type: choice == \'image\' ? FileType.image : FileType.video);\n    final path = res?.files.single.path;\n    if (path == null || !mounted) return;\n    var sec = 5.0;\n    if (choice == \'image\') {\n      final s = await _askImageSeconds();\n      if (s == null || !mounted) return;\n      sec = s;\n    }\n    await _appendMedia(path, isImage: choice == \'image\', imageSec: sec);\n  }\n\n  Future<double?> _askImageSeconds() {\n    var sel = 5;\n    return showDialog<double>(\n      context: context,\n      builder: (ctx) => StatefulBuilder(\n        builder: (ctx, setD) => AlertDialog(\n          backgroundColor: AyatColors.surface,\n          title: const Text(\'مدة ظهور الصورة\'),\n          content: Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final s in const [3, 5, 8, 10, 15])\n                ChoiceChip(\n                  label: Text(\'$s ث\'),\n                  selected: sel == s,\n                  onSelected: (_) => setD(() => sel = s),\n                ),\n            ],\n          ),\n          actions: [\n            TextButton(\n                onPressed: () => Navigator.pop(ctx),\n                child: const Text(\'إلغاء\')),\n            TextButton(\n                onPressed: () => Navigator.pop(ctx, sel.toDouble()),\n                child: const Text(\'إضافة\')),\n          ],\n        ),\n      ),\n    );\n  }\n\n  /// Renders "current clip + the new video / picture" into one file (the same\n  /// pre-pass idea as S79 / S125), so auto-sync, text and export still see a\n  /// single source. The new part goes AFTER the current clip, so everything\n  /// already detected stays exactly where it was.\n  Future<void> _appendMedia(String addPath,\n      {required bool isImage, required double imageSec}) async {\n    final basePath = state.videoPath;\n    if (basePath == null) return;\n    final keepTimeline = List<TimelineSegment>.of(state.timeline);\n    final keepActive = state.timelineActive;\n    final keepFrom = state.trimFromIndex;\n    final keepTo = state.trimToIndex;\n    final keepStart = state.trimManualStart;\n    final keepEnd = state.trimManualEnd;\n    final keepDetected = state.detectedAudioDurationSec;\n    final cur = _video;\n    final baseDur = (cur != null && cur.value.isInitialized)\n        ? cur.value.duration.inMilliseconds / 1000.0\n        : state.videoDurationSec;\n    final baseHasVideo =\n        cur != null && cur.value.isInitialized && cur.value.size.width > 0;\n    final (fw, fh) = state.frameSize;\n    final merged = await _withBusy(() async {\n      _setBusyStatus(isImage ? \'جارٍ إضافة الصورة…\' : \'جارٍ إضافة الفيديو…\');\n      return MediaService.appendClip(\n        basePath,\n        addPath,\n        baseDurationSec: baseDur,\n        baseHasVideo: baseHasVideo,\n        addIsImage: isImage,\n        imageSec: imageSec,\n        width: fw,\n        height: fh,\n      );\n    });\n    if (merged == null || !mounted) return;\n    await _video?.dispose();\n    _liveOverlay.value = null;\n    final controller = VideoPlayerController.file(File(merged));\n    _video = controller;\n    state.setVideo(merged);\n    try {\n      await controller.initialize();\n      await controller.setLooping(true);\n      await controller.play();\n      state.update(() {\n        state.videoDurationSec =\n            controller.value.duration.inMilliseconds / 1000.0;\n        if (keepTimeline.isNotEmpty) {\n          state.timeline = keepTimeline;\n          state.timelineActive = keepActive;\n        }\n        state.trimFromIndex = keepFrom;\n        state.trimToIndex = keepTo;\n        state.trimManualStart = keepStart;\n        // A tail that was cut off would hide what was just added.\n        state.trimManualEnd = -1;\n        state.detectedAudioDurationSec = keepDetected;\n      });\n    } catch (_) {\n      // the player refusing the file must not lose the render\n    }\n    if (mounted) setState(() {});\n    _toast(isImage ? \'أُضيفت الصورة ✓\' : \'أُضيف الفيديو ✓\');\n  }\n\n  // ---------------------------------------------------------------------\n  // PATCH_S183_TEXT_BAR: the text bar of the main screen\n  // ---------------------------------------------------------------------\n\n  /// With a begin / stop window on the typed text, the stage shows the text\n  /// only inside it - through the same fade the export uses. (A single\n  /// invisible "hidden" overlay key lets the stage\'s own transition run.)\n  void _gateTypedText(VideoPlayerController? c) {\n    final s = state.textTimeStartOverride;\n    final e = state.textTimeEndOverride;\n    final cur = _liveOverlay.value;\n    final hiddenNow = cur != null && cur.segmentKey == \'hidden-window\';\n    // PATCH_S193_PIP_POWER: text blocks of the timeline now show on the stage\n    // at their time (they were only ever drawn by the exporter).\n    if (c != null &&\n        c.value.isInitialized &&\n        !state.timelineActive &&\n        state.textTimeCues.isNotEmpty) {\n      final tt = c.value.position.inMilliseconds / 1000.0;\n      final k = state.textTimeCues.indexWhere((q) => tt >= q.start && tt < q.end);\n      if (k < 0) {\n        if (!hiddenNow) {\n          _liveOverlay.value =\n              StageOverlayText(\' \', \'\', \'hidden-window\', null, 0, \'\');\n        }\n      } else {\n        final q = state.textTimeCues[k];\n        final key = \'cue:$k:${q.text.hashCode}\';\n        if (cur == null || cur.segmentKey != key) {\n          _liveOverlay.value = StageOverlayText(q.text, q.translation, key);\n        }\n      }\n      return;\n    }\n    if (c == null ||\n        !c.value.isInitialized ||\n        s == null ||\n        e == null ||\n        state.timelineActive ||\n        !state.hasAyah) {\n      if (hiddenNow) _liveOverlay.value = null;\n      return;\n    }\n    final t = c.value.position.inMilliseconds / 1000.0;\n    final inside = t >= s && t < e;\n    if (!inside && !hiddenNow) {\n      _liveOverlay.value = StageOverlayText(\' \', \'\', \'hidden-window\', null, 0, \'\');\n    } else if (inside && hiddenNow) {\n      _liveOverlay.value = null;\n    }\n  }\n\n  double get _clipLenSec {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return state.videoDurationSec;\n    return c.value.duration.inMilliseconds / 1000.0;\n  }\n\n  List<(IconData, String, VoidCallback, bool)> _textItems() {\n    final synced = state.timelineActive && state.timeline.isNotEmpty;\n    final hasWin = state.textTimeStartOverride != null &&\n        state.textTimeEndOverride != null;\n    return [\n      (\n        Icons.check_circle_outline,\n        \'تم\',\n        () {\n          state.clearStageSelection();\n          setState(() {\n            _selMain = false;\n            _selCue = -1;\n            _toolOpen = -1; // PATCH_S185_POLISH\n          });\n        },\n        false\n      ),\n      (Icons.text_decrease, \'أصغر\', () => _nudgeTextSize(-0.1), false),\n      (Icons.text_increase, \'أكبر\', () => _nudgeTextSize(0.1), false),\n      (Icons.tune, \'ضبط\', _openTextTuneSheet, false), // PATCH_S186_SMOOTH_CONTROL\n      (Icons.font_download_outlined, \'الخط\', _openFontSheet, false),\n      (Icons.vertical_align_center, \'الموضع\', _cycleTextPos, false),\n      // PATCH_S184_PRO_MAIN: the whole look of the text, from the bar\n      (Icons.text_fields, \'النمط\', () => _openToolFromClip(121), _toolOpen == 121),\n      (Icons.border_style, \'الإطار\', () => _openToolFromClip(122), _toolOpen == 122),\n      (Icons.filter_frames, \'الظل\', () => _openToolFromClip(123), _toolOpen == 123),\n      (Icons.wb_sunny_outlined, \'التوهج\', () => _openToolFromClip(124), _toolOpen == 124),\n      (Icons.label_outline, \'اللافتة\', () => _openToolFromClip(125), _toolOpen == 125),\n      (Icons.opacity, \'الشفافية\', () => _openToolFromClip(126), _toolOpen == 126),\n      (Icons.animation, \'الحركة\', () => _openToolFromClip(108), _toolOpen == 108),\n      (Icons.animation, \'انتقال\', _openTransitionSheet, false),\n      if (!synced) ...[\n        (Icons.first_page, \'يبدأ هنا\', () => _setTextWindowHere(start: true), hasWin),\n        (Icons.last_page, \'ينتهي هنا\', () => _setTextWindowHere(start: false), hasWin),\n        if (hasWin) ...[\n          (Icons.restart_alt, \'كامل المدة\', _resetTextWindow, false),\n        ],\n      ],\n      (Icons.auto_awesome, \'الروح\', _applyRuhNow, false),\n    ];\n  }\n\n  // PATCH_S186_SMOOTH_CONTROL: live fine-tune of the text, every value on a slider.\n  Widget _tuneSlider(String label, String shown, double value, double min,\n      double max, void Function(double) onChanged) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Row(\n          children: [\n            Expanded(\n              child: Text(label,\n                  style: const TextStyle(\n                      fontSize: 13,\n                      fontWeight: FontWeight.w700,\n                      color: AyatColors.parchment)),\n            ),\n            Text(shown,\n                style: const TextStyle(\n                    fontSize: 12.5,\n                    fontWeight: FontWeight.w800,\n                    color: AyatColors.goldBright)),\n          ],\n        ),\n        Slider(\n          value: value.clamp(min, max).toDouble(),\n          min: min,\n          max: max,\n          onChanged: onChanged,\n        ),\n      ],\n    );\n  }\n\n  void _openTextTuneSheet() {\n    HapticFeedback.selectionClick();\n    showModalBottomSheet<void>(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      isScrollControlled: true,\n      shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),\n      builder: (ctx) => SafeArea(\n        child: ListenableBuilder(\n          listenable: state,\n          builder: (context, _) => ConstrainedBox(\n            constraints: BoxConstraints(\n                maxHeight: MediaQuery.of(ctx).size.height * 0.62),\n            child: SingleChildScrollView(\n              padding: const EdgeInsets.fromLTRB(18, 14, 18, 20),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Text(\'ضبط النص\',\n                      style: Theme.of(ctx).textTheme.headlineMedium),\n                  const SizedBox(height: 6),\n                  _tuneSlider(\n                      \'الحجم\',\n                      \'${(state.textUserScale * 100).round()}٪\',\n                      state.textUserScale,\n                      0.4,\n                      3.0,\n                      (v) => state.update(() => state.textUserScale = v)),\n                  _tuneSlider(\n                      \'تباعد الأحرف\',\n                      state.letterSpacing.toStringAsFixed(1),\n                      state.letterSpacing,\n                      0,\n                      12,\n                      (v) => state.update(() => state.letterSpacing = v)),\n                  _tuneSlider(\n                      \'ارتفاع السطر\',\n                      state.lineHeightMultiplier.toStringAsFixed(2),\n                      state.lineHeightMultiplier,\n                      1.0,\n                      2.4,\n                      (v) => state.update(() => state.lineHeightMultiplier = v)),\n                  _tuneSlider(\n                      \'الشفافية\',\n                      \'${(state.overallOpacity * 100).round()}٪\',\n                      state.overallOpacity,\n                      0.1,\n                      1.0,\n                      (v) => state.update(() => state.overallOpacity = v)),\n                  _tuneSlider(\n                      \'مدة الانتقال\',\n                      \'${state.textTransitionMs} م.ث\',\n                      state.textTransitionMs.toDouble(),\n                      100,\n                      2000,\n                      (v) => state\n                          .update(() => state.textTransitionMs = v.round())),\n                  const SizedBox(height: 8),\n                  Row(\n                    children: [\n                      Expanded(\n                        child: OutlinedButton.icon(\n                          onPressed: () {\n                            HapticFeedback.selectionClick();\n                            state.update(() => state.textOffset = Offset.zero);\n                          },\n                          icon: const Icon(Icons.center_focus_strong, size: 18),\n                          label: const Text(\'إعادة الموضع\'),\n                        ),\n                      ),\n                      const SizedBox(width: 10),\n                      Expanded(\n                        child: OutlinedButton.icon(\n                          onPressed: () {\n                            HapticFeedback.selectionClick();\n                            state.update(() => state.textUserScale = 1.0);\n                          },\n                          icon: const Icon(Icons.restart_alt, size: 18),\n                          label: const Text(\'إعادة الحجم\'),\n                        ),\n                      ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  void _nudgeTextSize(double d) {\n    final v = (state.textUserScale + d).clamp(0.4, 3.0).toDouble();\n    HapticFeedback.selectionClick();\n    state.update(() => state.textUserScale = v);\n  }\n\n  void _cycleTextPos() {\n    const vs = AyahTextPosition.values;\n    final n = vs[(state.textPosition.index + 1) % vs.length];\n    HapticFeedback.selectionClick();\n    state.update(() => state.textPosition = n);\n    _toast(switch (n) {\n      AyahTextPosition.top => \'النص في الأعلى\',\n      AyahTextPosition.center => \'النص في الوسط\',\n      AyahTextPosition.bottom => \'النص في الأسفل\',\n    });\n  }\n\n  void _setTextWindowHere({required bool start}) {\n    final dur = _clipLenSec;\n    if (dur <= 0.3) return;\n    final t = _playheadSec;\n    HapticFeedback.mediumImpact();\n    state.pushHistory();\n    state.setTextWindow(dur, start: start ? t : null, end: start ? null : t);\n  }\n\n  void _resetTextWindow() {\n    HapticFeedback.selectionClick();\n    state.pushHistory();\n    state.clearTextWindow();\n    if (_liveOverlay.value?.segmentKey == \'hidden-window\') {\n      _liveOverlay.value = null;\n    }\n  }\n\n  void _applyRuhNow() {\n    final text = _liveOverlay.value?.segmentKey == \'hidden-window\'\n        ? state.ayahText\n        : (_liveOverlay.value?.text ?? state.ayahText);\n    RuhTouch.apply(context, state, text);\n  }\n\n  void _openFontSheet() {\n    HapticFeedback.selectionClick();\n    showModalBottomSheet<void>(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      isScrollControlled: true,\n      shape: const RoundedRectangleBorder(\n          borderRadius: BorderRadius.vertical(top: Radius.circular(22))),\n      builder: (ctx) => SafeArea(\n        child: ListenableBuilder(\n          listenable: state,\n          builder: (context, _) => ConstrainedBox(\n            constraints: BoxConstraints(\n                maxHeight: MediaQuery.of(ctx).size.height * 0.6),\n            child: SingleChildScrollView(\n              padding: const EdgeInsets.fromLTRB(16, 14, 16, 20),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Text(\'اختر الخط\',\n                      style: Theme.of(ctx).textTheme.headlineMedium),\n                  const SizedBox(height: 10),\n                  Wrap(\n                    spacing: 8,\n                    runSpacing: 8,\n                    children: [\n                      for (final f in state.allFonts)\n                        ChoiceChip(\n                          label: Text(_t(f.label),\n                              style: ayahTextStyle(f.key, fontSize: 17)),\n                          selected: state.fontKey == f.key,\n                          onSelected: (_) =>\n                              state.update(() => state.fontKey = f.key),\n                        ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  // ---- آيات tab: the folded "advanced" card -----------------------------------\n\n  Widget _advancedFold(Widget child) {\n    return Container(\n      margin: const EdgeInsets.only(top: 14),\n      decoration: BoxDecoration(\n        color: AyatColors.surface2.withValues(alpha: 0.55),\n        borderRadius: BorderRadius.circular(16),\n        border: Border.all(color: AyatColors.hairline),\n      ),\n      child: Theme(\n        data: Theme.of(context).copyWith(dividerColor: Colors.transparent),\n        child: ExpansionTile(\n          key: const PageStorageKey<String>(\'ayah_advanced_fold\'),\n          initiallyExpanded: _ayahAdvOpen,\n          onExpansionChanged: (v) => _ayahAdvOpen = v,\n          leading: const Icon(Icons.tune, color: AyatColors.goldBright),\n          title: const Text(\'خيارات متقدمة\',\n              style: TextStyle(\n                  fontWeight: FontWeight.w800, color: AyatColors.parchment)),\n          subtitle: const Text(\n              \'جزء من آية · توقيت النص · المعالج · بطاقات البسملة والخاتمة\',\n              style: TextStyle(fontSize: 11.5, color: AyatColors.parchmentDim)),\n          childrenPadding: const EdgeInsets.fromLTRB(12, 0, 12, 12),\n          children: [child],\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S175_CAPCUT: fullscreen preview (the player\'s corner button).\n  Widget _fullscreenButton() {\n    return Material(\n      color: const Color(0x99050F0D),\n      shape: const CircleBorder(),\n      child: InkWell(\n        customBorder: const CircleBorder(),\n        onTap: _openFullscreen,\n        child: const Padding(\n          padding: EdgeInsets.all(7),\n          child: Icon(Icons.fullscreen, size: 20, color: AyatColors.parchment),\n        ),\n      ),\n    );\n  }\n\n  Future<void> _openFullscreen() async {\n    HapticFeedback.selectionClick(); // PATCH_S176_SMOOTH\n    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);\n    await Navigator.of(context).push(AppMotion.route<void>(Builder(\n      builder: (ctx) => Scaffold(\n        backgroundColor: Colors.black,\n        body: SafeArea(\n          child: Stack(\n            children: [\n              Center(\n                child: StagePreview(\n                  state: state,\n                  videoController: _video,\n                  liveOverride: _liveOverlay,\n                ),\n              ),\n              PositionedDirectional(\n                top: 8,\n                end: 8,\n                child: IconButton(\n                  icon: const Icon(Icons.fullscreen_exit,\n                      color: AyatColors.parchment),\n                  onPressed: () => Navigator.pop(ctx),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    )));\n    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);\n  }\n\n  // PATCH_S179_AAA: type a time and jump (Premiere\'s timecode box).\n  Future<void> _goToTime() async {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    final dur = c.value.duration.inMilliseconds / 1000.0;\n    final t = await showGoToTimeDialog(context,\n        current: c.value.position.inMilliseconds / 1000.0, max: dur);\n    if (t == null || !mounted) return;\n    await c.seekTo(Duration(milliseconds: (t * 1000).round()));\n  }\n\n  /// Long-press on previous / next in the transport.\n  void _jumpMarker(int dir) {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    if (_markers.isEmpty) {\n      _toast(\'لا توجد علامات بعد\');\n      return;\n    }\n    final t = c.value.position.inMilliseconds / 1000.0;\n    double? target;\n    if (dir > 0) {\n      for (final m in _markers) {\n        if (m > t + 0.05) {\n          target = m;\n          break;\n        }\n      }\n    } else {\n      for (final m in _markers.reversed) {\n        if (m < t - 0.05) {\n          target = m;\n          break;\n        }\n      }\n    }\n    if (target == null) {\n      _toast(dir > 0 ? \'لا علامة بعد المؤشر\' : \'لا علامة قبل المؤشر\');\n      return;\n    }\n    HapticFeedback.selectionClick();\n    c.seekTo(Duration(milliseconds: (target * 1000).round()));\n  }\n\n  double _frameAspect() {\n    final fs = state.frameSize;\n    return fs.$1 / fs.$2;\n  }\n\n  Widget _guidesButton() {\n    return Material(\n      color: const Color(0x99050F0D),\n      shape: const CircleBorder(),\n      child: InkWell(\n        customBorder: const CircleBorder(),\n        onTap: () => setState(() => _guides = !_guides),\n        child: Padding(\n          padding: const EdgeInsets.all(7),\n          child: Icon(Icons.grid_3x3,\n              size: 20,\n              color: _guides ? AyatColors.goldBright : AyatColors.parchment),\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S180_TRANSFORM: touch transform on the preview (page «التحويل»):\n  // drag = move, pinch = scale, twist = rotate. With keyframes present each\n  // gesture writes a keyframe at the playhead.\n  double _gBaseScale = 1, _gBaseRot = 0, _gBaseX = 0, _gBaseY = 0;\n  Offset _gStart = Offset.zero;\n\n  Widget _xformGestureLayer() {\n    return LayoutBuilder(builder: (context, c) {\n      final aspect = _frameAspect();\n      var pw = c.maxWidth;\n      var ph = pw / aspect;\n      if (ph > c.maxHeight) {\n        ph = c.maxHeight;\n        pw = ph * aspect;\n      }\n      return GestureDetector(\n        behavior: HitTestBehavior.opaque,\n        onScaleStart: (d) {\n          final vc = _video;\n          if (vc == null) return;\n          vc.pause();\n          final t = vc.value.position.inMilliseconds / 1000.0;\n          final cur = state.videoTransformAt(t);\n          _gBaseScale = cur.scale;\n          _gBaseRot = cur.rot;\n          _gBaseX = cur.x;\n          _gBaseY = cur.y;\n          _gStart = d.focalPoint;\n        },\n        onScaleUpdate: (d) {\n          final vc = _video;\n          if (vc == null) return;\n          final t = vc.value.position.inMilliseconds / 1000.0;\n          final ns = (_gBaseScale * d.scale).clamp(0.3, 2.0).toDouble();\n          final nx = (_gBaseX + (d.focalPoint.dx - _gStart.dx) / pw)\n              .clamp(-0.9, 0.9)\n              .toDouble();\n          final ny = (_gBaseY + (d.focalPoint.dy - _gStart.dy) / ph)\n              .clamp(-0.9, 0.9)\n              .toDouble();\n          var nr = _gBaseRot + d.rotation * 180 / pi;\n          nr = ((nr + 180) % 360) - 180;\n          if (nr.abs() < 2.5) nr = 0; // snap upright\n          if (state.videoKeys.isNotEmpty) {\n            state.setKeyAt(t, scale: ns, x: nx, y: ny, rot: nr);\n          } else {\n            state.update(() {\n              state.videoScale = ns;\n              state.videoPosX = nx;\n              state.videoPosY = ny;\n              state.videoRot = nr;\n            });\n          }\n        },\n        child: Align(\n          alignment: Alignment.topCenter,\n          child: IgnorePointer(\n            child: Container(\n              margin: const EdgeInsets.only(top: 8),\n              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),\n              decoration: BoxDecoration(\n                color: const Color(0xB3050F0D),\n                borderRadius: BorderRadius.circular(20),\n                border: Border.all(color: const Color(0x55ECC875)),\n              ),\n              child: const Text(\'اسحب · قرّب · لُفّ\',\n                  style: TextStyle(\n                      fontSize: 11,\n                      fontWeight: FontWeight.w700,\n                      color: AyatColors.parchment)),\n            ),\n          ),\n        ),\n      );\n    });\n  }\n\n  Widget _toolPanel(double h) {\n    final tools = _toolList();\n    final cur =\n        tools.firstWhere((t) => t.$1 == _toolOpen, orElse: () => tools.first);\n    return Container(\n      height: h,\n      decoration: BoxDecoration(\n        color: AyatColors.surface,\n        borderRadius: const BorderRadius.vertical(top: Radius.circular(22)),\n        border: Border.all(color: AyatColors.hairline),\n      ),\n      child: Column(\n        children: [\n          // PATCH_S184_PRO_MAIN: drag to resize the panel, double tap to toggle\n          GestureDetector(\n            behavior: HitTestBehavior.opaque,\n            onVerticalDragUpdate: (d) {\n              final hh = MediaQuery.of(context).size.height * 0.8;\n              setState(() => _panelFrac =\n                  (_panelFrac - d.delta.dy / hh).clamp(0.2, 0.6).toDouble());\n            },\n            onDoubleTap: () => setState(\n                () => _panelFrac = _panelFrac > 0.45 ? 0.36 : 0.58),\n            child: SizedBox(\n              height: 20,\n              child: Center(\n                child: Container(\n                  width: 42,\n                  height: 4,\n                  decoration: BoxDecoration(\n                    color: AyatColors.parchmentDim,\n                    borderRadius: BorderRadius.circular(2),\n                  ),\n                ),\n              ),\n            ),\n          ),\n          SizedBox(\n            height: 46,\n            child: Row(\n              children: [\n                const SizedBox(width: 16),\n                Container(\n                  width: 3,\n                  height: 16,\n                  decoration: BoxDecoration(\n                    color: AyatColors.goldBright,\n                    borderRadius: BorderRadius.circular(3),\n                  ),\n                ),\n                const SizedBox(width: 8),\n                Expanded(\n                  child: SmoothSwap( // PATCH_S176_SMOOTH\n                    slide: const Offset(0.08, 0),\n                    child: Text(cur.$3,\n                        key: ValueKey(cur.$1),\n                        style: Theme.of(context).textTheme.headlineMedium),\n                  ),\n                ),\n                IconButton(\n                  icon: const Icon(Icons.keyboard_arrow_down,\n                      color: AyatColors.goldBright),\n                  onPressed: () => setState(() => _toolOpen = -1),\n                ),\n              ],\n            ),\n          ),\n          Expanded(\n            child: SingleChildScrollView(\n              controller: _scrollCtrl,\n              padding: EdgeInsets.fromLTRB(16, 4, 16, 24),\n              child: SmoothSwap( // PATCH_S176_SMOOTH\n                child: KeyedSubtree(\n                  key: ValueKey(_toolOpen),\n                  child: _toolBody(),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _toolBody() {\n    switch (_toolOpen) {\n      case 100:\n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _mediaButtons(),\n            if (state.detectedLabel.isNotEmpty) ...[\n              const SizedBox(height: 8),\n              Text(state.detectedLabel,\n                  textAlign: TextAlign.center,\n                  style: const TextStyle(\n                      fontSize: 12, color: AyatColors.goldBright)),\n            ],\n            if (state.matchConfidenceText.isNotEmpty) ...[\n              const SizedBox(height: 4),\n              Text(state.matchConfidenceText,\n                  textAlign: TextAlign.center,\n                  style: const TextStyle(\n                      fontSize: 11, color: AyatColors.parchmentDim)),\n            ],\n            if (state.hasVideo && state.videoDurationSec > 1) ...[\n              const SizedBox(height: 12),\n              _manualCutCard(),\n            ],\n            if (state.timelineActive) ...[\n              const SizedBox(height: 12),\n              _trimCard(),\n              const SizedBox(height: 12),\n              _timelineEditorCard(),\n            ],\n            if (!state.hasVideo) ...[\n              const SizedBox(height: 12),\n              _staticDurationRow(),\n            ],\n          ],\n        );\n      case 101:\n        return _ratioToggle();\n      case 103: // PATCH_S174_PRO_EDITOR\n        return ProColorPage(state: state);\n      case 104:\n        return ProAudioMixer(state: state, onPickAmbience: _pickAmbienceBed);\n      case 105:\n        return ProTranscript(\n          state: state,\n          controller: _video,\n          onToast: _toast,\n          onSelectSeg: (i) => setState(() => _selSeg = i),\n        );\n      case 106:\n        return ProExportPresets(\n            state: state, busy: _busy, onExport: _export);\n      case 107: // PATCH_S175_CAPCUT\n        return _speedSection();\n      case 108:\n        return _textTransitionSection();\n      case 109:\n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _captionSection(),\n            const Divider(height: 32, color: AyatColors.hairline),\n            _subtitleSection(),\n          ],\n        );\n      case 110:\n        return ProStickers(state: state, onToast: _toast);\n      case 111:\n        return ProEnhance(state: state);\n      case 112: // PATCH_S180_TRANSFORM\n        return ProTransformPage(state: state, controller: _video);\n      case 113: // PATCH_S188_PIP\n        return ProPipPage(\n          state: state,\n          controller: _video,\n          onAddVideo: () => _addPip(image: false),\n          onAddImage: () => _addPip(image: true),\n          onToast: _toast,\n        );\n      case 102:\n        return MagicCard(state: state, onToast: _toast);\n      // PATCH_S184_PRO_MAIN: the old tab sections, one tool each\n      case 120:\n        return _ayahPanel();\n      case 121:\n        return _teOnly(TextEditorTab.text);\n      case 122:\n        return _teOnly(TextEditorTab.border);\n      case 123:\n        return _teOnly(TextEditorTab.shadow);\n      case 124:\n        return _teOnly(TextEditorTab.glow);\n      case 125:\n        return _teOnly(TextEditorTab.label);\n      case 126:\n        return _teOnly(TextEditorTab.opacity);\n      case 127:\n        return _bgPanel();\n      case 128:\n        return _chromaPanel();\n      case 129:\n        return _recitersPanel();\n      case 130:\n        return _effectsPanel();\n      case 131:\n        return _templatesPanel();\n      case 132:\n        return _watermarkSection();\n      case 133:\n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _exportPanel(),\n            const SizedBox(height: 16),\n            _exportButton(),\n          ],\n        );\n      default:\n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _panelBody(),\n            if (_toolOpen == _tabs.length - 1) ...[\n              const SizedBox(height: 16),\n              _exportButton(),\n            ],\n          ],\n        );\n    }\n  }\n\n  Widget _toolStrip() {\n    final tools = _toolList();\n    return Container(\n      height: 68,\n      decoration: const BoxDecoration(\n        color: AyatColors.ink,\n        border: Border(top: BorderSide(color: AyatColors.hairline)),\n      ),\n      child: Material(\n        color: Colors.transparent,\n        child: ListView.builder(\n          scrollDirection: Axis.horizontal,\n          padding: const EdgeInsets.symmetric(horizontal: 8),\n          controller: _stripCtrl, // PATCH_S176_SMOOTH\n          itemCount: tools.length,\n          itemBuilder: (context, i) {\n            final t = tools[i];\n            final sel = _toolOpen == t.$1;\n            final col = sel ? AyatColors.goldBright : AyatColors.parchmentDim;\n            return PressableScale(\n              borderRadius: BorderRadius.circular(14),\n              pressedScale: 0.9, // PATCH_S176_SMOOTH\n              onTap: () => _openTool(t.$1),\n              child: SizedBox(\n                width: 76,\n                child: Column(\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  children: [\n                    AnimatedContainer(\n                      duration: AppMotion.d(AppMotion.medium),\n                      curve: Curves.easeOutCubic,\n                      width: sel ? 22 : 0,\n                      height: 3,\n                      margin: const EdgeInsets.only(bottom: 5),\n                      decoration: BoxDecoration(\n                        color: AyatColors.goldBright,\n                        borderRadius: BorderRadius.circular(3),\n                      ),\n                    ),\n                    AnimatedScale(\n                      scale: sel ? 1.18 : 1.0,\n                      duration: AppMotion.d(AppMotion.medium),\n                      curve: AppMotion.spring,\n                      child: TweenAnimationBuilder<Color?>(\n                        tween: ColorTween(end: col),\n                        duration: AppMotion.d(AppMotion.medium),\n                        builder: (_, c, __) => Icon(t.$2, size: 23, color: c),\n                      ),\n                    ),\n                    const SizedBox(height: 3),\n                    AnimatedDefaultTextStyle(\n                      duration: AppMotion.d(AppMotion.medium),\n                      curve: Curves.easeOutCubic,\n                      style: TextStyle(\n                          fontSize: 11,\n                          fontWeight: FontWeight.w700,\n                          color: col),\n                      child: Text(t.$3,\n                          maxLines: 1, overflow: TextOverflow.ellipsis),\n                    ),\n                  ],\n                ),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n\n  // The InShot-style "SAVE": compact gold pill in the app bar.\n  Widget _exportPill() {\n    final disabled = _busy;\n    return Opacity(\n      opacity: disabled ? 0.5 : 1,\n      child: Material(\n        color: Colors.transparent,\n        child: InkWell(\n          borderRadius: BorderRadius.circular(12),\n          onTap: disabled\n              ? null\n              : () {\n                  HapticFeedback.mediumImpact();\n                  _export();\n                },\n          child: Ink(\n            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),\n            decoration: BoxDecoration(\n              gradient: const LinearGradient(\n                begin: Alignment.topCenter,\n                end: Alignment.bottomCenter,\n                colors: [AyatColors.goldBright, AyatColors.gold],\n              ),\n              borderRadius: BorderRadius.circular(12),\n            ),\n            child: Row(\n              mainAxisSize: MainAxisSize.min,\n              children: const [\n                Icon(Icons.movie_creation_outlined,\n                    size: 16, color: AyatColors.ink),\n                SizedBox(width: 6),\n                Text(\'تصدير\',\n                    style: TextStyle(\n                        fontSize: 13,\n                        fontWeight: FontWeight.w800,\n                        color: AyatColors.ink)),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S165_UI_REFRESH: a touch of depth - top-lit gradient + soft shadow.\n  Widget _card({required Widget child, EdgeInsets? padding}) => Container(\n        padding: padding ?? const EdgeInsets.all(16),\n        decoration: BoxDecoration(\n          gradient: const LinearGradient(\n            begin: Alignment.topCenter,\n            end: Alignment.bottomCenter,\n            colors: [Color(0xFF0F201B), AyatColors.surface],\n          ),\n          borderRadius: BorderRadius.circular(24),\n          border: Border.all(color: AyatColors.hairline),\n          boxShadow: [\n            BoxShadow(\n              color: Colors.black.withValues(alpha: 0.35),\n              blurRadius: 22,\n              offset: const Offset(0, 10),\n            ),\n          ],\n        ),\n        child: child,\n      );\n\n  // PATCH_S165_UI_REFRESH: idle = one quiet line, busy = the full progress\n  // card. AnimatedSize makes the swap glide instead of jump.\n  Widget _statusCard() {\n    return AnimatedSize(\n      duration: AppMotion.d(AppMotion.medium),\n      curve: Curves.easeOutCubic,\n      alignment: Alignment.topCenter,\n      child: _busy ? _statusBusyCard() : _statusPill(),\n    );\n  }\n\n  Widget _statusPill() {\n    final text = state.corpusStatus;\n    if (text.isEmpty) return const SizedBox(width: double.infinity);\n    return Center(\n      child: Container(\n        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 7),\n        decoration: BoxDecoration(\n          color: AyatColors.gold.withValues(alpha: 0.06),\n          borderRadius: BorderRadius.circular(999),\n          border: Border.all(color: AyatColors.hairline),\n        ),\n        child: Row(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            Container(\n              width: 7,\n              height: 7,\n              decoration: BoxDecoration(\n                shape: BoxShape.circle,\n                color: AyatColors.goldBright,\n                boxShadow: [\n                  BoxShadow(\n                    color: AyatColors.gold.withValues(alpha: 0.7),\n                    blurRadius: 6,\n                  ),\n                ],\n              ),\n            ),\n            const SizedBox(width: 8),\n            Flexible(\n              child: AnimatedSwitcher( // PATCH_S169_MOTION_FEEL\n                duration: AppMotion.d(AppMotion.medium),\n                child: Text(\n                  text,\n                  key: ValueKey(text),\n                  maxLines: 1,\n                  overflow: TextOverflow.ellipsis,\n                  style: const TextStyle(\n                      fontSize: 12, color: AyatColors.parchmentDim),\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S165_UI_REFRESH: the export call-to-action. Gold gradient, glow,\n  // press-in scale and a slow sheen; dims while a job is running.\n  // PATCH_S168_EXPORT_BUTTON_FIX: sheen is a plain overlay (GoldSheen), not a\n  // ShaderMask, and the whole button paints in its own RepaintBoundary.\n  Widget _exportButton() {\n    final disabled = _busy;\n    return KeyedSubtree( // PATCH_S172_NO_LAYER_WRAP: no own layer\n      child: AnimatedOpacity(\n        duration: AppMotion.d(AppMotion.fast),\n        opacity: disabled ? 0.5 : 1,\n        child: PressableScale(\n          borderRadius: BorderRadius.circular(20),\n          pressedScale: 0.97,\n          onTap: disabled\n              ? null\n              : () {\n                  HapticFeedback.mediumImpact(); // PATCH_S167_APP_POLISH\n                  _export();\n                },\n          child: Container(\n            decoration: BoxDecoration(\n              gradient: const LinearGradient(\n                begin: Alignment.topCenter,\n                end: Alignment.bottomCenter,\n                colors: [AyatColors.goldBright, AyatColors.gold],\n              ),\n              borderRadius: BorderRadius.circular(20),\n              boxShadow: [\n                BoxShadow(\n                  color: AyatColors.gold.withValues(alpha: 0.35),\n                  blurRadius: 20,\n                  offset: const Offset(0, 8),\n                ),\n              ],\n            ),\n            child: GoldSheen(\n              borderRadius: BorderRadius.circular(20),\n              child: Padding(\n                padding:\n                    const EdgeInsets.symmetric(vertical: 16, horizontal: 18),\n                child: Row(\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  children: [\n                    const Icon(Icons.movie_creation_outlined,\n                        size: 22, color: AyatColors.ink),\n                    const SizedBox(width: 12),\n                    Flexible(\n                      child: Column(\n                        mainAxisSize: MainAxisSize.min,\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        children: const [\n                          Text(\'تصدير المقطع\',\n                              maxLines: 1,\n                              overflow: TextOverflow.ellipsis,\n                              style: TextStyle(\n                                  fontSize: 16,\n                                  fontWeight: FontWeight.w800,\n                                  color: AyatColors.ink)),\n                          Text(\'MP4 — بدون حد للمدة أو الدقة\',\n                              maxLines: 1,\n                              overflow: TextOverflow.ellipsis,\n                              style: TextStyle(\n                                  fontSize: 11,\n                                  fontWeight: FontWeight.w500,\n                                  color: Color(0xCC050F0D))),\n                        ],\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S169_MOTION_FEEL: the busy card breathes a gold glow.\n  Widget _statusBusyCard() => PulseGlow(\n      active: _busy,\n      borderRadius: BorderRadius.circular(24),\n      child: _statusBusyCardBody());\n\n  Widget _statusBusyCardBody() {\n    return _card(\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          Text(\n            _busy && _busyStatus.isNotEmpty ? _busyStatus : state.corpusStatus,\n            textAlign: TextAlign.center,\n            style: const TextStyle(fontSize: 13, color: AyatColors.goldBright),\n          ),\n          if (_busy) ...[\n            const SizedBox(height: 12),\n            // PATCH_S83_SYNC_QOL: a numeric ٪ readout beside the bar\n            Row(\n              children: [\n                Expanded(\n                  // PATCH_S167_APP_POLISH: thicker bar with the gold sweep.\n                  child: GoldSheen(\n                    borderRadius: BorderRadius.circular(999), // PATCH_S168\n                    child: ClipRRect(\n                      borderRadius: BorderRadius.circular(999),\n                      child: SmoothProgressBar( // PATCH_S169_MOTION_FEEL\n                        value: _busyProgress,\n                        minHeight: 9,\n                        backgroundColor: AyatColors.surface3,\n                        color: AyatColors.gold,\n                      ),\n                    ),\n                  ),\n                ),\n                if (_busyProgress != null) ...[\n                  const SizedBox(width: 8),\n                  Text(\'${(_busyProgress! * 100).round()}٪\',\n                      style: const TextStyle(\n                          fontSize: 11, color: AyatColors.goldBright)),\n                ],\n              ],\n            ),\n            // PATCH_S83_SYNC_QOL: remaining-time projection for any job that\n            // reports a fraction (export and all the auto-sync passes).\n            if (_busyEta() != null) ...[\n              const SizedBox(height: 6),\n              Text(_busyEta()!,\n                  textAlign: TextAlign.center,\n                  style: const TextStyle(\n                      fontSize: 11, color: AyatColors.parchmentDim)),\n            ],\n            // PATCH_S37_CANCEL_LONG_JOBS: abort export / auto-sync scan.\n            // PATCH_S57_RESUMABLE_MODEL_DOWNLOAD: now shown for EVERY busy\n            // job — tester feedback: a hung model download used to keep the\n            // whole app (including the export button) locked forever. With\n            // no job-specific cancel, this releases the UI; a partially\n            // downloaded model resumes from where it stopped next time.\n            const SizedBox(height: 6),\n            TextButton.icon(\n              onPressed: () {\n                final action = _busyCancelAction;\n                if (action != null) {\n                  action();\n                  setState(() => _busyCancelAction = null);\n                  _setBusyStatus(\'جارٍ الإلغاء…\');\n                } else {\n                  setState(() {\n                    _busy = false;\n                    _busyStatus = \'\';\n                    _busyProgress = null;\n                  });\n                  _toast(\'تم تحرير الواجهة — لو كان تنزيل النموذج جاريًا فسيُستأنف من حيث توقف عند المحاولة القادمة\');\n                }\n              },\n              icon: const Icon(Icons.cancel_outlined,\n                  size: 16, color: AyatColors.parchmentDim),\n              label: const Text(\'إلغاء العملية\',\n                  style: TextStyle(\n                      fontSize: 12, color: AyatColors.parchmentDim)),\n            ),\n          ],\n        ],\n      ),\n    );\n  }\n\n  Widget _ratioToggle() {\n    // PATCH_S53_LANDSCAPE_EXPORT: renders all shapes from kAspectRatios instead of\n    // two hardcoded chips.\n    // PATCH_S125_CUSTOM_ASPECT: plus a custom size, for the platforms and\n    // print sizes no preset covers.\n    final (fw, fh) = state.frameSize;\n    return Column(\n      children: [\n        // PATCH_S166_UI_POLISH: every shape drawn as a miniature of itself.\n        Row(\n          children: [\n            for (var i = 0; i < kAspectRatios.length; i++) ...[\n              if (i > 0) const SizedBox(width: 6),\n              Expanded(child: _ratioTile(kAspectRatios[i])),\n            ],\n          ],\n        ),\n        if (state.aspectRatio == AyatAspectRatio.custom) ...[\n          const SizedBox(height: 10),\n          Row(\n            children: [\n              Expanded(\n                child: TextField(\n                  controller: _customWCtrl,\n                  keyboardType: TextInputType.number,\n                  decoration: const InputDecoration(\n                      labelText: \'العرض\', isDense: true),\n                  onChanged: (v) => state.update(() =>\n                      state.customAspectW = int.tryParse(v) ?? state.customAspectW),\n                ),\n              ),\n              const Padding(\n                padding: EdgeInsets.symmetric(horizontal: 10),\n                child: Text(\'×\'),\n              ),\n              Expanded(\n                child: TextField(\n                  controller: _customHCtrl,\n                  keyboardType: TextInputType.number,\n                  decoration: const InputDecoration(\n                      labelText: \'الارتفاع\', isDense: true),\n                  onChanged: (v) => state.update(() =>\n                      state.customAspectH = int.tryParse(v) ?? state.customAspectH),\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 6),\n          Text(\n            // Both are forced even and clamped, so say what will actually be\n            // encoded rather than what was typed -- H.264 cannot encode an\n            // odd dimension and libx264 fails outright on one.\n            \'سيتم التصدير بمقاس $fw × $fh بكسل (يُقرَّب لأقرب رقم زوجي، بين 240 و3840).\',\n            textAlign: TextAlign.center,\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n        ],\n      ],\n    );\n  }\n\n  // PATCH_S75_COMPACT_PICKER_FALLBACK: compact selector button shown inline; opens the full tier\n  // list in a bottom sheet instead of always showing all 5 cards.\n  Widget _modelSizeSelector() {\n    final parts = WhisperService.labelFor(state.whisperModelSize).split(\' — \');\n    final sizeLabel = parts.first;\n    final qualityLabel = parts.length > 1 ? parts[1] : \'\';\n    return Material(\n      color: AyatColors.ink.withValues(alpha: 0.4),\n      borderRadius: BorderRadius.circular(10),\n      child: InkWell(\n        borderRadius: BorderRadius.circular(10),\n        onTap: _busy ? null : _showModelSizePicker,\n        child: Container(\n          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),\n          decoration: BoxDecoration(\n            borderRadius: BorderRadius.circular(10),\n            border: Border.all(color: AyatColors.hairline, width: 1),\n          ),\n          child: Row(\n            children: [\n              Expanded(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Text(sizeLabel,\n                        style: const TextStyle(\n                            fontWeight: FontWeight.bold,\n                            color: AyatColors.goldBright)),\n                    if (qualityLabel.isNotEmpty) ...[\n                      const SizedBox(height: 2),\n                      Text(qualityLabel,\n                          style: TextStyle(\n                              fontSize: 12,\n                              color: Colors.white.withValues(alpha: 0.6))),\n                    ],\n                  ],\n                ),\n              ),\n              Icon(Icons.unfold_more,\n                  color: Colors.white.withValues(alpha: 0.5), size: 20),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S75_COMPACT_PICKER_FALLBACK: bottom-sheet with all 5 tiers -- same card styling S50 used\n  // inline, just shown on demand. Tapping a tier updates selection and\n  // closes the sheet; the actual model file is still only fetched lazily\n  // the next time a detect/auto-sync job runs ensureReady().\n  void _showModelSizePicker() {\n    showModalBottomSheet(\n      context: context,\n      backgroundColor: AyatColors.surface,\n      shape: const RoundedRectangleBorder(\n        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),\n      ),\n      builder: (sheetContext) {\n        return SafeArea(\n          child: Padding(\n            padding: const EdgeInsets.fromLTRB(14, 18, 14, 14),\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                _fieldLabel(\'دقة التعرّف على الكلام\'),\n                const SizedBox(height: 8),\n                for (final size in WhisperModelSize.values)\n                  Builder(builder: (context) {\n                    final selected = state.whisperModelSize == size;\n                    final parts = WhisperService.labelFor(size).split(\' — \');\n                    final sizeLabel = parts.first;\n                    final qualityLabel = parts.length > 1 ? parts[1] : \'\';\n                    return Padding(\n                      padding: const EdgeInsets.only(bottom: 8),\n                      child: Material(\n                        color: selected\n                            ? AyatColors.gold.withValues(alpha: 0.12)\n                            : AyatColors.ink.withValues(alpha: 0.4),\n                        borderRadius: BorderRadius.circular(10),\n                        child: InkWell(\n                          borderRadius: BorderRadius.circular(10),\n                          onTap: () {\n                            state.update(() => state.whisperModelSize = size);\n                            WhisperService.setModelSize(size);\n                            Navigator.of(sheetContext).pop();\n                          },\n                          child: Container(\n                            padding: const EdgeInsets.symmetric(\n                                horizontal: 14, vertical: 12),\n                            decoration: BoxDecoration(\n                              borderRadius: BorderRadius.circular(10),\n                              border: Border.all(\n                                color: selected\n                                    ? AyatColors.gold\n                                    : AyatColors.hairline,\n                                width: selected ? 1.4 : 1,\n                              ),\n                            ),\n                            child: Row(\n                              children: [\n                                Expanded(\n                                  child: Column(\n                                    crossAxisAlignment:\n                                        CrossAxisAlignment.start,\n                                    children: [\n                                      Text(\n                                        sizeLabel,\n                                        style: TextStyle(\n                                          fontWeight: selected\n                                              ? FontWeight.bold\n                                              : FontWeight.w500,\n                                          color: selected\n                                              ? AyatColors.goldBright\n                                              : Colors.white,\n                                        ),\n                                      ),\n                                      if (qualityLabel.isNotEmpty) ...[\n                                        const SizedBox(height: 2),\n                                        Text(\n                                          qualityLabel,\n                                          style: TextStyle(\n                                            fontSize: 12,\n                                            color: Colors.white\n                                                .withValues(alpha: 0.6),\n                                          ),\n                                        ),\n                                      ],\n                                    ],\n                                  ),\n                                ),\n                                if (selected)\n                                  const Icon(Icons.check_circle,\n                                      color: AyatColors.goldBright, size: 20)\n                                else\n                                  Icon(Icons.circle_outlined,\n                                      color:\n                                          Colors.white.withValues(alpha: 0.3),\n                                      size: 20),\n                              ],\n                            ),\n                          ),\n                        ),\n                      ),\n                    );\n                  }),\n              ],\n            ),\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _mediaButtons() {\n    // PATCH_S166_UI_POLISH: one hero upload card, three action tiles, the\n    // model picker, and the rarely-used clip tools tucked in a drawer.\n    // Handlers and enabled-state are identical to the old button stack.\n    final lang = AppStrings(AppSettings.instance.lang);\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _uploadHero(),\n        const SizedBox(height: 10),\n        Row(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            Expanded(\n              child: _actionTile(\n                icon: _listening ? Icons.stop_circle_outlined : Icons.mic,\n                label: _listening ? \'إيقاف الاستماع\' : \'تعرّف من الميكروفون\',\n                onTap: _busy ? null : _micDetect,\n                active: _listening,\n              ),\n            ),\n            const SizedBox(width: 8),\n            Expanded(\n              child: _actionTile(\n                icon: Icons.manage_search,\n                label: \'تعرّف من صوت الفيديو\',\n                onTap: _busy ? null : _detectFromVideo,\n              ),\n            ),\n            const SizedBox(width: 8),\n            Expanded(\n              child: _actionTile(\n                icon: Icons.auto_awesome,\n                label: state.timelineActive\n                    ? lang.t(\'autosync.btnRescan\')\n                    : lang.t(\'autosync.btn\'),\n                onTap: _busy ? null : _autoSync,\n                primary: true,\n              ),\n            ),\n          ],\n        ),\n        // PATCH_S101_AUTOSYNC_HINT_PARTIAL_AYAH: set expectations before they tap it --\n        // it does the job well on roughly half the video; the rest may\n        // need a manual touch-up from the review card above.\n        const SizedBox(height: 8),\n        Text(\n          lang.t(\'autosync.hint\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n          textAlign: TextAlign.center,\n          style: Theme.of(context)\n              .textTheme\n              .bodyMedium\n              ?.copyWith(color: AyatColors.goldDim, fontSize: 12),\n        ),\n        // PATCH_S75_COMPACT_PICKER_FALLBACK: model-size picker -- controls every detect/auto-sync\n        // button above via WhisperService.setModelSize(). One compact row\n        // that opens a bottom-sheet list on tap.\n        _fieldLabel(\'دقة التعرّف على الكلام\'),\n        _modelSizeSelector(),\n        const SizedBox(height: 8),\n        Theme(\n          data: Theme.of(context).copyWith(dividerColor: Colors.transparent),\n          child: ExpansionTile(\n            tilePadding: const EdgeInsets.symmetric(horizontal: 4),\n            childrenPadding: const EdgeInsets.only(bottom: 4),\n            iconColor: AyatColors.goldBright,\n            collapsedIconColor: AyatColors.parchmentDim,\n            leading: const Icon(Icons.video_collection_outlined,\n                size: 19, color: AyatColors.goldDim),\n            title: const Text(\'أدوات المقاطع\',\n                style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700)),\n            children: [\n              // PATCH_S79_CUSTOM_BG_NUMBER_AND_VIDEO_MERGE\n              OutlinedButton.icon(\n                onPressed:\n                    (_busy || !state.hasVideo) ? null : _pickAndMergeVideo,\n                icon: const Icon(Icons.video_collection_outlined, size: 18),\n                label: const Text(\'دمج مع فيديو آخر\'),\n              ),\n              const SizedBox(height: 8),\n              // PATCH_S125_SEQUENCE: S79\'s merge is two clips, whole, butted\n              // together. This is the general case -- any number of clips,\n              // each trimmed, reordered, joined with a real transition.\n              OutlinedButton.icon(\n                onPressed: _busy ? null : _openSequence,\n                icon: const Icon(Icons.playlist_add, size: 18),\n                label: const Text(\'تركيب عدة مقاطع (قصّ وترتيب وانتقالات)\'),\n              ),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n\n  // PATCH_S166_UI_POLISH: the primary entry point. While nothing is loaded\n  // its halo breathes, drawing the eye to the one thing to do first.\n  Widget _uploadHero() {\n    final empty = !state.hasVideo;\n    final disabled = _busy;\n    final card = Container(\n      padding: const EdgeInsets.symmetric(vertical: 18, horizontal: 16),\n      decoration: BoxDecoration(\n        gradient: LinearGradient(\n          begin: Alignment.topCenter,\n          end: Alignment.bottomCenter,\n          colors: [\n            AyatColors.gold.withValues(alpha: empty ? 0.16 : 0.08),\n            AyatColors.gold.withValues(alpha: 0.03),\n          ],\n        ),\n        borderRadius: BorderRadius.circular(22),\n        border: Border.all(\n          color: AyatColors.gold.withValues(alpha: empty ? 0.55 : 0.28),\n        ),\n      ),\n      child: Row(\n        children: [\n          Container(\n            width: 46,\n            height: 46,\n            decoration: BoxDecoration(\n              shape: BoxShape.circle,\n              color: AyatColors.gold.withValues(alpha: 0.14),\n              border:\n                  Border.all(color: AyatColors.gold.withValues(alpha: 0.5)),\n            ),\n            child: const Icon(Icons.upload_file,\n                size: 22, color: AyatColors.goldBright),\n          ),\n          const SizedBox(width: 14),\n          Expanded(\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                const Text(\'رفع فيديو أو تلاوة صوتية\',\n                    style: TextStyle(\n                        fontSize: 15,\n                        fontWeight: FontWeight.w800,\n                        color: AyatColors.parchment)),\n                const SizedBox(height: 2),\n                Text(\n                  empty ? \'ابدأ من هنا\' : \'استبدال الملف الحالي\',\n                  style: const TextStyle(\n                      fontSize: 12, color: AyatColors.parchmentDim),\n                ),\n              ],\n            ),\n          ),\n          const Icon(Icons.chevron_left, color: AyatColors.goldDim),\n        ],\n      ),\n    );\n    return AnimatedOpacity(\n      duration: AppMotion.d(AppMotion.fast),\n      opacity: disabled ? 0.5 : 1,\n      child: _Breathing(\n        enabled: empty && !disabled,\n        borderRadius: 22,\n        child: PressableScale(\n          borderRadius: BorderRadius.circular(22),\n          onTap: disabled\n              ? null\n              : () {\n                  HapticFeedback.selectionClick(); // PATCH_S167_APP_POLISH\n                  _pickVideo();\n                },\n          child: card,\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S166_UI_POLISH: square-ish action tile. primary = gold (auto-sync).\n  Widget _actionTile({\n    required IconData icon,\n    required String label,\n    required VoidCallback? onTap,\n    bool primary = false,\n    bool active = false,\n  }) {\n    final on = onTap != null;\n    final fg = primary ? AyatColors.ink : AyatColors.parchment;\n    return AnimatedOpacity(\n      duration: AppMotion.d(AppMotion.fast),\n      opacity: on ? 1 : 0.45,\n      child: PressableScale(\n        borderRadius: BorderRadius.circular(18),\n        onTap: onTap == null\n            ? null\n            : () {\n                HapticFeedback.selectionClick(); // PATCH_S167_APP_POLISH\n                onTap();\n              },\n        child: Container(\n          constraints: const BoxConstraints(minHeight: 84),\n          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 12),\n          decoration: BoxDecoration(\n            gradient: primary\n                ? const LinearGradient(\n                    begin: Alignment.topCenter,\n                    end: Alignment.bottomCenter,\n                    colors: [AyatColors.goldBright, AyatColors.gold],\n                  )\n                : null,\n            color: primary\n                ? null\n                : (active\n                    ? AyatColors.gold.withValues(alpha: 0.18)\n                    : AyatColors.surface2),\n            borderRadius: BorderRadius.circular(18),\n            border: Border.all(\n              color: primary\n                  ? AyatColors.goldBright\n                  : (active ? AyatColors.gold : AyatColors.hairline),\n            ),\n            boxShadow: primary && on\n                ? [\n                    BoxShadow(\n                      color: AyatColors.gold.withValues(alpha: 0.3),\n                      blurRadius: 14,\n                      offset: const Offset(0, 5),\n                    ),\n                  ]\n                : const [],\n          ),\n          child: Column(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [\n              Icon(icon,\n                  size: 24,\n                  color: primary ? AyatColors.ink : AyatColors.goldBright),\n              const SizedBox(height: 8),\n              Text(\n                label,\n                textAlign: TextAlign.center,\n                maxLines: 2,\n                overflow: TextOverflow.ellipsis,\n                style: TextStyle(\n                  fontSize: 11.5,\n                  height: 1.25,\n                  fontWeight: FontWeight.w700,\n                  color: fg,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S166_UI_POLISH: one aspect-ratio tile - a miniature frame drawn in\n  // the real proportion of the shape it selects.\n  Widget _ratioTile((AyatAspectRatio, String, int, int) entry) {\n    final selected = state.aspectRatio == entry.$1;\n    final isCustom = entry.$1 == AyatAspectRatio.custom;\n    final ar = (entry.$4 > 0) ? entry.$3 / entry.$4 : 1.0;\n    const box = 26.0;\n    final gw = ar >= 1 ? box : box * ar;\n    final gh = ar >= 1 ? box / ar : box;\n    final dur = AppMotion.d(AppMotion.fast);\n    final fg = selected ? AyatColors.ink : AyatColors.parchment;\n    return PressableScale(\n      borderRadius: BorderRadius.circular(16),\n      pressedScale: 0.95,\n      onTap: () {\n        HapticFeedback.selectionClick();\n        state.update(() => state.aspectRatio = entry.$1);\n      },\n      child: AnimatedContainer(\n        duration: dur,\n        curve: Curves.easeOutCubic,\n        padding: const EdgeInsets.symmetric(vertical: 9, horizontal: 2),\n        decoration: BoxDecoration(\n          gradient: selected\n              ? const LinearGradient(\n                  begin: Alignment.topCenter,\n                  end: Alignment.bottomCenter,\n                  colors: [AyatColors.goldBright, AyatColors.gold],\n                )\n              : null,\n          color: selected ? null : AyatColors.surface2,\n          borderRadius: BorderRadius.circular(16),\n          border: Border.all(\n            color: selected ? AyatColors.goldBright : AyatColors.hairline,\n          ),\n          boxShadow: selected\n              ? [\n                  BoxShadow(\n                    color: AyatColors.gold.withValues(alpha: 0.3),\n                    blurRadius: 12,\n                    offset: const Offset(0, 4),\n                  ),\n                ]\n              : const [],\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            SizedBox(\n              width: box,\n              height: box,\n              child: Center(\n                child: isCustom\n                    ? Icon(Icons.tune, size: 20, color: fg)\n                    : AnimatedContainer(\n                        duration: dur,\n                        width: gw,\n                        height: gh,\n                        decoration: BoxDecoration(\n                          borderRadius: BorderRadius.circular(4),\n                          color: selected\n                              ? AyatColors.ink.withValues(alpha: 0.12)\n                              : Colors.transparent,\n                          border: Border.all(\n                            color: selected\n                                ? AyatColors.ink\n                                : AyatColors.parchmentDim,\n                            width: 1.6,\n                          ),\n                        ),\n                      ),\n              ),\n            ),\n            const SizedBox(height: 6),\n            FittedBox(\n              fit: BoxFit.scaleDown,\n              child: Text(\n                AppStrings(AppSettings.instance.lang)\n                    .t(\'aspect.${entry.$1.name}\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n                maxLines: 1,\n                style: TextStyle(\n                  fontSize: 10.5,\n                  fontWeight: FontWeight.w700,\n                  color: fg,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S166_UI_POLISH: line - diamond - line, replaces plain Divider\n  // between panel sections.\n  Widget _ornament() {\n    const line = Expanded(\n      child: SizedBox(\n        height: 1,\n        child: DecoratedBox(\n          decoration: BoxDecoration(\n            gradient: LinearGradient(\n              colors: [Colors.transparent, AyatColors.hairline],\n            ),\n          ),\n        ),\n      ),\n    );\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 18),\n      child: Row(\n        children: [\n          line,\n          const SizedBox(width: 10),\n          Transform.rotate(\n            angle: 0.785398,\n            child: Container(\n              width: 7,\n              height: 7,\n              decoration: BoxDecoration(\n                color: AyatColors.gold,\n                boxShadow: [\n                  BoxShadow(\n                    color: AyatColors.gold.withValues(alpha: 0.6),\n                    blurRadius: 6,\n                  ),\n                ],\n              ),\n            ),\n          ),\n          const SizedBox(width: 10),\n          Expanded(\n            child: Transform.flip(\n              flipX: true,\n              child: const SizedBox(\n                height: 1,\n                child: DecoratedBox(\n                  decoration: BoxDecoration(\n                    gradient: LinearGradient(\n                      colors: [Colors.transparent, AyatColors.hairline],\n                    ),\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  // PATCH_S134_AUTOSEG_WIZARD: guided multi-step entry point (the\n  // reference "Auto-Segmentation Wizard"). The wizard lives in its\n  // own file; everything it changes flows through existing\n  // StudioState APIs (addManualSegment / whisperModelSize), same as\n  // every other dialog in this file.\n  Widget _autoSegWizardCard() {\n    return _sectionCard(Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Row(children: [\n          const Icon(Icons.auto_awesome_outlined,\n              color: AyatColors.gold, size: 20),\n          const SizedBox(width: 8),\n          Expanded(\n              child: Text(_t(\'wizard.title\'),\n                  style: Theme.of(context).textTheme.titleSmall)),\n        ]),\n        const SizedBox(height: 4),\n        Text(_t(\'wizard.subtitle\'),\n            style: Theme.of(context)\n                .textTheme\n                .bodySmall\n                ?.copyWith(color: AyatColors.goldDim)),\n        const SizedBox(height: 10),\n        OutlinedButton.icon(\n          onPressed: _openAutoSegWizard,\n          icon: const Icon(Icons.auto_fix_high, size: 18),\n          label: Text(_t(\'wizard.launch\')),\n        ),\n      ],\n    ));\n  }\n\n  // PATCH_S134_AUTOSEG_WIZARD: opens the wizard and surfaces its result\n  // through the existing toast/timeline-card plumbing.\n  Future<void> _openAutoSegWizard() async {\n    final res = await showAutoSegWizard(\n      context: context,\n      state: state,\n      audioPath: _video?.dataSource,\n    );\n    if (res == null) return;\n    if (res.importedSegments > 0) {\n      _revealTimelineCard();\n      _toast(\'${_t(\'wizard.imported\')}: ${res.importedSegments} \\u2713\');\n    } else if (res.tierApplied) {\n      // PATCH_S156_WIZARD_LOCAL_RUNS: the wizard used to just save the\n      // model tier and tell the user, in a toast, to go find the\n      // separate auto-sync button themselves -- so tapping the wizard\'s\n      // own "Start segmentation" button visibly did nothing. Local has\n      // no reason to stop short of actually running the scan it just\n      // configured, so it does now -- the same real TimelineBuilder\n      // pass the standalone button triggers.\n      if (state.hasVideo) {\n        await _autoSync();\n      } else {\n        _toast(_t(\'wizard.localNote\'));\n      }\n    } else if (res.cloudChosen) {\n      _toast(_t(\'wizard.cloudNote\'));\n    }\n  }\n\n  Widget _trimCard() {\n    final items = <DropdownMenuItem<int>>[\n      const DropdownMenuItem(value: -1, child: Text(\'(المقطع كاملاً)\')),\n      for (var i = 0; i < state.timeline.length; i++)\n        DropdownMenuItem(\n          value: i,\n          child: Text(\n              \'سورة ${state.timeline[i].ayah.surah} — آية ${state.timeline[i].ayah.num}\',\n              overflow: TextOverflow.ellipsis),\n        ),\n    ];\n    void apply(int from, int to) {\n      if (from != -1 && to != -1 && to < from) {\n        _toast(\'اختر آية نهاية بعد آية البداية\');\n        state.update(() {\n          state.trimFromIndex = -1;\n          state.trimToIndex = -1;\n        });\n        return;\n      }\n      state.update(() {\n        state.trimFromIndex = from;\n        state.trimToIndex = to;\n      });\n      if (from != -1 && to != -1) {\n        _toast(\n            \'سيُصدَّر من بداية آية ${state.timeline[from].ayah.num} حتى نهاية آية ${state.timeline[to].ayah.num}\');\n      }\n    }\n\n    return _card(\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\'تصدير نطاق آيات محدد (اختياري)\',\n              style: Theme.of(context).textTheme.labelLarge),\n          const SizedBox(height: 8),\n          Row(\n            children: [\n              Expanded(\n                child: DropdownButton<int>(\n                  isExpanded: true,\n                  value: state.trimFromIndex,\n                  items: items,\n                  onChanged: (v) => apply(v ?? -1, state.trimToIndex),\n                ),\n              ),\n              const SizedBox(width: 8),\n              Expanded(\n                child: DropdownButton<int>(\n                  isExpanded: true,\n                  value: state.trimToIndex,\n                  items: items,\n                  onChanged: (v) => apply(state.trimFromIndex, v ?? -1),\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 6),\n          Text(\n            \'القص يلتزم دائمًا ببداية ونهاية الآية كما رصدها التعرّف الصوتي — لا يمكن القص في منتصف آية أو كلمة.\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n        ],\n      ),\n    );\n  }\n\n  // PATCH_S34_PLAYER_CONTROLS_TRIM ------------------------------------------\n\n  static String _fmtSec(double s) {\n    final total = s.round();\n    final m = total ~/ 60;\n    final sec = total % 60;\n    return \'$m:${sec.toString().padLeft(2, \'0\')}\';\n  }\n\n  // PATCH_S83_SYNC_QOL: tenth-of-a-second precision for the timing editor —\n  // whole seconds are useless when nudging by ±0.1s.\n  static String _fmtSecFine(double s) {\n    final m = s ~/ 60;\n    final sec = s - m * 60;\n    return \'$m:${sec.toStringAsFixed(1).padLeft(4, \'0\')}\';\n  }\n\n  // PATCH_S83_SYNC_QOL: cycle 1× → 1.25× → 1.5× → 0.75× — reviewing a long\n  // detected timeline is much faster above 1× and fixing timings easier\n  // below it.\n  Future<void> _cycleSpeed() async {\n    final c = _video;\n    if (c == null || !c.value.isInitialized) return;\n    final i = _speeds.indexOf(_playbackSpeed);\n    final next = _speeds[(i + 1) % _speeds.length];\n    await c.setPlaybackSpeed(next);\n    if (mounted) setState(() => _playbackSpeed = next);\n  }\n\n  static String _speedLabel(double s) =>\n      s == s.roundToDouble() ? \'${s.round()}×\' : \'$s×\';\n\n  /// Play/pause + seek bar for the uploaded clip. Tapping the stage itself\n  /// also pauses/resumes (see StagePreview).\n  /// PATCH_S83_SYNC_QOL: plus the ayah ribbon (tap-to-seek map of the\n  /// detected timeline), loop-one-ayah and playback speed.\n  Widget _transportBar() {\n    final c = _video!;\n    return _card(\n      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),\n      child: ValueListenableBuilder<VideoPlayerValue>(\n        valueListenable: c,\n        builder: (context, v, _) {\n          final durMs = max(1, v.duration.inMilliseconds);\n          final posMs = v.position.inMilliseconds.clamp(0, durMs);\n          return Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              if (state.timelineActive)\n                Padding(\n                  padding: const EdgeInsets.only(top: 8, left: 4, right: 4),\n                  child: TimelineRibbon(state: state, controller: c),\n                  // PATCH_S128: AyahBlocksEditor can replace the ribbon:\n                  // AyahBlocksEditor(segs: _segVMs(), durationSec: _clipDur(),\n                  //     onChanged: () => state.pushHistory()),\n                ),\n              Row(\n                children: [\n                  // PATCH_S36_TIMELINE_EDITOR: jump between detected ayat\n                  if (state.timelineActive)\n                    IconButton(\n                      onPressed: () => _seekToAdjacentAyah(-1),\n                      padding: EdgeInsets.zero,\n                      constraints:\n                          const BoxConstraints(minWidth: 34, minHeight: 40),\n                      icon: const Icon(Icons.skip_previous_outlined,\n                          color: AyatColors.parchmentDim, size: 20),\n                      tooltip: \'الآية السابقة\',\n                    ),\n                  // PATCH_S167_APP_POLISH: round gold play/pause with an animated\n                  // icon swap and a soft glow.\n                  Padding(\n                    padding: const EdgeInsets.symmetric(horizontal: 4),\n                    child: Tooltip(\n                      message: \'تشغيل/إيقاف\',\n                      child: PressableScale(\n                        borderRadius: BorderRadius.circular(22),\n                        pressedScale: 0.9,\n                        onTap: () => v.isPlaying ? c.pause() : c.play(),\n                        child: AnimatedContainer( // PATCH_S169_MOTION_FEEL\n                          duration: AppMotion.d(AppMotion.medium),\n                          width: 44,\n                          height: 44,\n                          decoration: BoxDecoration(\n                            shape: BoxShape.circle,\n                            gradient: const LinearGradient(\n                              begin: Alignment.topCenter,\n                              end: Alignment.bottomCenter,\n                              colors: [AyatColors.goldBright, AyatColors.gold],\n                            ),\n                            boxShadow: [\n                              BoxShadow(\n                                color: AyatColors.gold.withValues(\n                                    alpha: v.isPlaying ? 0.6 : 0.35),\n                                blurRadius: v.isPlaying ? 22 : 12,\n                                offset: const Offset(0, 3),\n                              ),\n                            ],\n                          ),\n                          child: AnimatedSwitcher(\n                            duration: AppMotion.d(AppMotion.fast),\n                            transitionBuilder: (child, anim) => ScaleTransition(\n                              scale: anim,\n                              child: FadeTransition(opacity: anim, child: child),\n                            ),\n                            child: Icon(\n                              v.isPlaying\n                                  ? Icons.pause_rounded\n                                  : Icons.play_arrow_rounded,\n                              key: ValueKey(v.isPlaying),\n                              size: 26,\n                              color: AyatColors.ink,\n                            ),\n                          ),\n                        ),\n                      ),\n                    ),\n                  ),\n                  if (state.timelineActive)\n                    IconButton(\n                      onPressed: () => _seekToAdjacentAyah(1),\n                      padding: EdgeInsets.zero,\n                      constraints:\n                          const BoxConstraints(minWidth: 34, minHeight: 40),\n                      icon: const Icon(Icons.skip_next_outlined,\n                          color: AyatColors.parchmentDim, size: 20),\n                      tooltip: \'الآية التالية\',\n                    ),\n                  if (state.timelineActive)\n                    IconButton(\n                      onPressed: () {\n                        HapticFeedback.selectionClick();\n                        setState(() => _loopAyah = !_loopAyah);\n                        _toast(_loopAyah\n                            ? \'تكرار الآية الحالية مفعّل\'\n                            : \'تم إيقاف تكرار الآية\');\n                      },\n                      padding: EdgeInsets.zero,\n                      constraints:\n                          const BoxConstraints(minWidth: 34, minHeight: 40),\n                      icon: Icon(Icons.repeat_one,\n                          color: _loopAyah\n                              ? AyatColors.goldBright\n                              : AyatColors.parchmentDim,\n                          size: 20),\n                      tooltip: \'تكرار الآية الحالية\',\n                    ),\n                  Text(_fmtSec(posMs / 1000),\n                      style: const TextStyle(\n                          fontSize: 11, color: AyatColors.parchmentDim)),\n                  Expanded(\n                    child: Slider(\n                      value: posMs.toDouble(),\n                      max: durMs.toDouble(),\n                      onChanged: (x) =>\n                          c.seekTo(Duration(milliseconds: x.round())),\n                    ),\n                  ),\n                  Text(_fmtSec(durMs / 1000),\n                      style: const TextStyle(\n                          fontSize: 11, color: AyatColors.parchmentDim)),\n                  TextButton(\n                    onPressed: _cycleSpeed,\n                    style: TextButton.styleFrom(\n                      minimumSize: const Size(38, 40),\n                      padding: const EdgeInsets.symmetric(horizontal: 4),\n                    ),\n                    child: Text(\n                      _speedLabel(_playbackSpeed),\n                      style: TextStyle(\n                          fontSize: 11,\n                          color: _playbackSpeed == 1.0\n                              ? AyatColors.parchmentDim\n                              : AyatColors.goldBright),\n                    ),\n                  ),\n                ],\n              ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  // PATCH_S36_TIMELINE_EDITOR ------------------------------------------------\n  // Review and fix the detected timeline by hand: tap an ayah to jump the\n  // preview there, fine-tune its start/end (the karaoke lighting and the\n  // export follow immediately), or delete a wrong detection.\n\n  Widget _timelineEditorCard() {\n    return _card(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),\n      child: Theme(\n        // ExpansionTile draws its own dividers — keep the card clean\n        data: Theme.of(context).copyWith(dividerColor: Colors.transparent),\n        child: ExpansionTile(\n          tilePadding: EdgeInsets.zero,\n          childrenPadding: const EdgeInsets.only(bottom: 10),\n          iconColor: AyatColors.goldBright,\n          collapsedIconColor: AyatColors.parchmentDim,\n          title: Text(\'مراجعة الآيات المرصودة (${state.timeline.length})\',\n              style: Theme.of(context).textTheme.labelLarge),\n          subtitle: Text(\n            \'اضغط آية للانتقال إليها، أو عدّل توقيتها أو احذفها إن كان الرصد خاطئًا.\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n          children: [\n            for (var i = 0; i < state.timeline.length; i++)\n              _timelineSegmentRow(i),\n            _timelineManualAddRow(), // PATCH_S49_MANUAL_SEGMENTS_MERGE\n          ],\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S49_MANUAL_SEGMENTS_MERGE: manual-add dialog trigger + adjacent-ayah quick-add chips,\n  // shown below the detected-segment list regardless of whether\n  // auto-sync has run yet (a manual-only timeline is valid too).\n  Widget _timelineManualAddRow() {\n    final last = state.timeline.isNotEmpty ? state.timeline.last : null;\n    final prevAyah = last == null ? null : _neighborAyah(last.ayah, -1);\n    final nextAyah = last == null ? null : _neighborAyah(last.ayah, 1);\n    return Padding(\n      padding: const EdgeInsets.only(top: 4),\n      child: Wrap(\n        spacing: 8,\n        runSpacing: 8,\n        children: [\n          if (prevAyah != null)\n            OutlinedButton.icon(\n              onPressed: () => _quickAddNeighborAyah(prevAyah, last!),\n              icon: const Icon(Icons.arrow_back, size: 14),\n              label: Text(\'إضافة آية ${prevAyah.num} — ${prevAyah.surah}\'),\n            ),\n          if (nextAyah != null)\n            OutlinedButton.icon(\n              onPressed: () => _quickAddNeighborAyah(nextAyah, last!),\n              icon: const Icon(Icons.arrow_forward, size: 14),\n              label: Text(\'إضافة آية ${nextAyah.num} — ${nextAyah.surah}\'),\n            ),\n          OutlinedButton.icon(\n            onPressed: _addManualSegmentDialog,\n            icon: const Icon(Icons.add, size: 16),\n            label: const Text(\'إضافة آية يدويًا\'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  /// PATCH_S49_MANUAL_SEGMENTS_MERGE: ayah [delta] positions away from [of] in the Quran\'s own\n  /// order (delta -1 = previous ayah overall, +1 = next), or null past\n  /// either end of the corpus.\n  Ayah? _neighborAyah(Ayah of, int delta) {\n    final idx = state.ayaat\n        .indexWhere((a) => a.surahNum == of.surahNum && a.num == of.num);\n    if (idx == -1) return null;\n    final j = idx + delta;\n    if (j < 0 || j >= state.ayaat.length) return null;\n    return state.ayaat[j];\n  }\n\n  void _quickAddNeighborAyah(Ayah ayah, TimelineSegment after) {\n    final start = after.end;\n    final end = state.videoDurationSec > 0\n        ? (start + 4).clamp(start + 0.3, state.videoDurationSec)\n        : start + 4;\n    state.addManualSegment(ayah, start, end.toDouble());\n    _toast(\'أُضيفت آية ${ayah.num} — ${ayah.surah} — عدّل توقيتها من زر الضبط\');\n  }\n\n  // PATCH_S119_TIMELINE_VISIBILITY_AND_ENABLE_FIX: "مراجعة الآيات\n  // المرصودة" sits above the panel/tabs -- animate back up to it after a\n  // segment is added so it\'s actually seen instead of scrolled past.\n  void _revealTimelineCard() {\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (!_scrollCtrl.hasClients) return;\n      _scrollCtrl.animateTo(\n        0,\n        duration: const Duration(milliseconds: 420),\n        curve: Curves.easeOutCubic,\n      );\n    });\n  }\n\n  Future<void> _addManualSegmentDialog() {\n    int dialogSurah = _selectedSurah;\n    int? dialogAyahIdx;\n    double start = state.timeline.isNotEmpty ? state.timeline.last.end : 0;\n    double end = start + 4;\n    return showDialog<void>(\n      context: context,\n      builder: (context) => StatefulBuilder(\n        builder: (context, setDialogState) {\n          final surahs = <(int, String)>[];\n          var last = 0;\n          for (final a in state.ayaat) {\n            if (a.surahNum != last) {\n              surahs.add((a.surahNum, a.surah));\n              last = a.surahNum;\n            }\n          }\n          final ayatOfSurah = <(int, Ayah)>[\n            for (var i = 0; i < state.ayaat.length; i++)\n              if (state.ayaat[i].surahNum == dialogSurah) (i, state.ayaat[i]),\n          ];\n          Widget timeField(\n              String label, double value, void Function(double) onSet) {\n            return Padding(\n              padding: const EdgeInsets.symmetric(vertical: 4),\n              child: Row(\n                children: [\n                  Expanded(child: Text(\'$label: ${_fmtSec(value)}\')),\n                  OutlinedButton(\n                    onPressed: () =>\n                        setDialogState(() => onSet(value - 0.5)),\n                    child: const Text(\'-٠٫٥ث\'),\n                  ),\n                  const SizedBox(width: 6),\n                  OutlinedButton(\n                    onPressed: () =>\n                        setDialogState(() => onSet(value + 0.5)),\n                    child: const Text(\'+٠٫٥ث\'),\n                  ),\n                ],\n              ),\n            );\n          }\n\n          return AlertDialog(\n            backgroundColor: AyatColors.surface,\n            shape: RoundedRectangleBorder(\n              borderRadius: BorderRadius.circular(22),\n              side: const BorderSide(color: AyatColors.hairline),\n            ),\n            title: const Text(\'إضافة آية يدويًا\'),\n            content: SingleChildScrollView(\n              child: Column(\n                mainAxisSize: MainAxisSize.min,\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  DropdownButton<int>(\n                    isExpanded: true,\n                    value: surahs.any((s) => s.$1 == dialogSurah)\n                        ? dialogSurah\n                        : (surahs.isEmpty ? null : surahs.first.$1),\n                    items: [\n                      for (final s in surahs)\n                        DropdownMenuItem(\n                            value: s.$1, child: Text(\'سورة ${s.$2}\')),\n                    ],\n                    onChanged: (v) => setDialogState(() {\n                      dialogSurah = v ?? dialogSurah;\n                      dialogAyahIdx = null;\n                    }),\n                  ),\n                  DropdownButton<int>(\n                    isExpanded: true,\n                    value: dialogAyahIdx,\n                    hint: const Text(\'اختر الآية\'),\n                    items: [\n                      for (final e in ayatOfSurah)\n                        DropdownMenuItem(\n                            value: e.$1, child: Text(\'آية ${e.$2.num}\')),\n                    ],\n                    onChanged: (v) =>\n                        setDialogState(() => dialogAyahIdx = v),\n                  ),\n                  const SizedBox(height: 8),\n                  timeField(\'البداية\', start,\n                      (v) => start = v.clamp(0, end - 0.3)),\n                  timeField(\n                      \'النهاية\',\n                      end,\n                      (v) => end = v.clamp(\n                          start + 0.3,\n                          state.videoDurationSec > 0\n                              ? state.videoDurationSec\n                              : v)),\n                ],\n              ),\n            ),\n            actions: [\n              TextButton(\n                  onPressed: () => Navigator.pop(context),\n                  child: const Text(\'إلغاء\')),\n              FilledButton(\n                onPressed: dialogAyahIdx == null\n                    ? null\n                    : () {\n                        // PATCH_S57_MANUAL_MULTI_AYAH_ENTRY: the very first manual add is the\n                        // moment the editor card appears -- tell the user\n                        // where to find it instead of leaving them to\n                        // notice a new card above the fold on their own.\n                        final wasEmpty = state.timeline.isEmpty;\n                        state.addManualSegment(\n                            state.ayaat[dialogAyahIdx!], start, end);\n                        Navigator.pop(context);\n                        _revealTimelineCard(); // PATCH_S119_TIMELINE_VISIBILITY_AND_ENABLE_FIX\n                        _toast(wasEmpty\n                            ? \'أُضيفت الآية الأولى ✓ — إلى \\\'مراجعة الآيات المرصودة\\\' أعلى الشاشة\'\n                            : \'أُضيفت الآية إلى الخط الزمني ✓\');\n                      },\n                child: const Text(\'إضافة\'),\n              ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _timelineSegmentRow(int i) {\n    final seg = state.timeline[i];\n    return Container(\n      margin: const EdgeInsets.only(bottom: 6),\n      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),\n      decoration: BoxDecoration(\n        color: AyatColors.surface2,\n        borderRadius: BorderRadius.circular(12),\n        border: Border.all(color: AyatColors.hairline),\n      ),\n      child: Row(\n        children: [\n          Expanded(\n            child: InkWell(\n              onTap: () {\n                final c = _video;\n                if (c != null && c.value.isInitialized) {\n                  c.seekTo(Duration(\n                      milliseconds: (seg.start * 1000).round() + 30));\n                  c.play();\n                }\n              },\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Row(\n                    children: [\n                      Flexible(\n                        child: Text(\n                            // PATCH_S118_PARTIAL_AYAH_TIMELINE_MERGE: mark\n                            // segments that only carry part of the ayah so\n                            // they\'re not mistaken for the full ayah at a\n                            // glance in the review list.\n                            \'سورة ${seg.ayah.surah} — آية ${seg.ayah.num}\'\n                            \'${seg.textOverride != null ? \' (جزء)\' : \'\'}\',\n                            overflow: TextOverflow.ellipsis,\n                            style: Theme.of(context).textTheme.bodyLarge),\n                      ),\n                      // PATCH_S82_AUTOSYNC_MAX: this ayah was inferred from\n                      // mushaf order, not heard — flag it for review.\n                      if (seg.inferred) ...[\n                        const SizedBox(width: 6),\n                        Container(\n                          padding: const EdgeInsets.symmetric(\n                              horizontal: 6, vertical: 1.5),\n                          decoration: BoxDecoration(\n                            borderRadius: BorderRadius.circular(999),\n                            border: Border.all(color: AyatColors.goldDim),\n                          ),\n                          child: const Text(\'مستنتجة\',\n                              style: TextStyle(\n                                  fontSize: 9.5,\n                                  color: AyatColors.goldBright)),\n                        ),\n                      ],\n                    ],\n                  ),\n                  Text(\n                    \'${_fmtSec(seg.start)} — ${_fmtSec(seg.end)} · ثقة ${(seg.confidence * 100).round()}٪\',\n                    style: TextStyle(\n                        fontSize: 10.5,\n                        // PATCH_S83_SYNC_QOL: low-confidence detections stand\n                        // out at a glance instead of hiding in the list.\n                        color: seg.confidence < 0.4\n                            ? AyatColors.goldBright\n                            : AyatColors.parchmentDim),\n                  ),\n                ],\n              ),\n            ),\n          ),\n          IconButton(\n            onPressed: () => _editSegmentTiming(i),\n            icon: const Icon(Icons.tune,\n                size: 18, color: AyatColors.goldBright),\n            tooltip: \'ضبط التوقيت\',\n          ),\n          if (i + 1 < state.timeline.length) // PATCH_S49_MANUAL_SEGMENTS_MERGE\n            IconButton(\n              onPressed: () {\n                state.mergeTimelineSegments(i);\n                _toast(\'تم دمج المقطعين\');\n              },\n              icon: const Icon(Icons.call_merge,\n                  size: 18, color: AyatColors.goldBright),\n              tooltip: \'دمج مع التالي\',\n            ),\n          IconButton(\n            onPressed: () {\n              // PATCH_S83_SYNC_QOL: deletion is undoable from the snackbar —\n              // no more re-running a whole scan over one slip of the finger.\n              final removed = state.removeTimelineSegment(i);\n              if (removed == null) return;\n              ScaffoldMessenger.of(context)\n                ..hideCurrentSnackBar()\n                ..showSnackBar(SnackBar(\n                  content: const Text(\'تم حذف الآية من الخط الزمني\',\n                      textAlign: TextAlign.center),\n                  behavior: SnackBarBehavior.floating,\n                  duration: const Duration(seconds: 5),\n                  action: SnackBarAction(\n                    label: \'تراجع\',\n                    textColor: AyatColors.goldBright,\n                    onPressed: () => state.insertTimelineSegment(i, removed),\n                  ),\n                ));\n            },\n            icon: const Icon(Icons.delete_outline,\n                size: 18, color: AyatColors.parchmentDim),\n            tooltip: \'حذف\',\n          ),\n        ],\n      ),\n    );\n  }\n\n  Future<void> _editSegmentTiming(int i) {\n    return showDialog<void>(\n      context: context,\n      builder: (context) => StatefulBuilder(\n        builder: (context, setDialogState) {\n          if (i >= state.timeline.length) {\n            return const SizedBox.shrink();\n          }\n          final seg = state.timeline[i];\n          // PATCH_S83_SYNC_QOL: fine ±0.1s nudges next to the coarse ±0.5s\n          // ones, and "from the playhead": pause where the ayah really\n          // starts/ends and stamp that exact moment as the boundary.\n          Widget nudgeRow(String label, double value,\n              void Function(double delta) onNudge) {\n            Widget btn(String text, double d) => OutlinedButton(\n                  onPressed: () {\n                    onNudge(d);\n                    setDialogState(() {});\n                  },\n                  style: OutlinedButton.styleFrom(\n                    minimumSize: const Size(48, 34),\n                    padding: EdgeInsets.zero,\n                    side: const BorderSide(color: AyatColors.hairline),\n                  ),\n                  child: Text(text, style: const TextStyle(fontSize: 12)),\n                );\n            final video = _video;\n            return Padding(\n              padding: const EdgeInsets.symmetric(vertical: 6),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Row(\n                    children: [\n                      Expanded(\n                          child: Text(\'$label: ${_fmtSecFine(value)}\',\n                              style: Theme.of(context).textTheme.bodyLarge)),\n                      TextButton.icon(\n                        onPressed: video == null || !video.value.isInitialized\n                            ? null\n                            : () {\n                                final pos =\n                                    video.value.position.inMilliseconds /\n                                        1000.0;\n                                onNudge(pos - value);\n                                setDialogState(() {});\n                              },\n                        icon: const Icon(Icons.my_location,\n                            size: 14, color: AyatColors.goldDim),\n                        label: const Text(\'من موضع التشغيل\',\n                            style: TextStyle(\n                                fontSize: 11, color: AyatColors.goldDim)),\n                      ),\n                    ],\n                  ),\n                  Row(\n                    children: [\n                      btn(\'-٠٫٥\', -0.5),\n                      const SizedBox(width: 5),\n                      btn(\'-٠٫١\', -0.1),\n                      const SizedBox(width: 5),\n                      btn(\'+٠٫١\', 0.1),\n                      const SizedBox(width: 5),\n                      btn(\'+٠٫٥\', 0.5),\n                    ],\n                  ),\n                ],\n              ),\n            );\n          }\n\n          return AlertDialog(\n            backgroundColor: AyatColors.surface,\n            shape: RoundedRectangleBorder(\n              borderRadius: BorderRadius.circular(22),\n              side: const BorderSide(color: AyatColors.hairline),\n            ),\n            title: Text(\'توقيت آية ${seg.ayah.num} — ${seg.ayah.surah}\'),\n            content: Column(\n              mainAxisSize: MainAxisSize.min,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                nudgeRow(\'البداية\', seg.start,\n                    (d) => state.nudgeTimelineSegment(i, startDelta: d)),\n                nudgeRow(\'النهاية\', seg.end,\n                    (d) => state.nudgeTimelineSegment(i, endDelta: d)),\n                const SizedBox(height: 4),\n                // PATCH_S83_SYNC_QOL: hear the result without leaving the dialog\n                OutlinedButton.icon(\n                  onPressed: () {\n                    final c = _video;\n                    if (c != null && c.value.isInitialized) {\n                      c.seekTo(Duration(\n                          milliseconds:\n                              (state.timeline[i].start * 1000).round() + 30));\n                      c.play();\n                    }\n                  },\n                  style: OutlinedButton.styleFrom(\n                    side: const BorderSide(color: AyatColors.hairline),\n                  ),\n                  icon: const Icon(Icons.play_arrow,\n                      size: 16, color: AyatColors.goldBright),\n                  label: const Text(\'استمع من بداية الآية\',\n                      style: TextStyle(fontSize: 12)),\n                ),\n                const SizedBox(height: 6),\n                // PATCH_S86_TIMELINE_EDITING: split one detected span that\n                // actually covers two ayat, right where the playhead is.\n                OutlinedButton.icon(\n                  onPressed: () {\n                    final c = _video;\n                    if (c == null || !c.value.isInitialized) return;\n                    final pos = c.value.position.inMilliseconds / 1000.0;\n                    if (state.splitTimelineSegment(i, pos)) {\n                      Navigator.pop(context);\n                      _toast(\n                          \'تم التقسيم عند موضع التشغيل ✓ — غيّر آية النصف الخاطئ من زر الضبط\');\n                    } else {\n                      _toast(\n                          \'حرّك موضع التشغيل إلى داخل هذه الآية أولًا ثم اضغط تقسيم\');\n                    }\n                  },\n                  style: OutlinedButton.styleFrom(\n                    side: const BorderSide(color: AyatColors.hairline),\n                  ),\n                  icon: const Icon(Icons.content_cut,\n                      size: 15, color: AyatColors.goldBright),\n                  label: const Text(\'تقسيم عند موضع التشغيل\',\n                      style: TextStyle(fontSize: 12)),\n                ),\n                const SizedBox(height: 6),\n                // PATCH_S86_TIMELINE_EDITING: relabel with the right ayah,\n                // keeping the reviewed timing.\n                OutlinedButton.icon(\n                  onPressed: () {\n                    Navigator.pop(context);\n                    _changeSegmentAyahDialog(i);\n                  },\n                  style: OutlinedButton.styleFrom(\n                    side: const BorderSide(color: AyatColors.hairline),\n                  ),\n                  icon: const Icon(Icons.swap_horiz,\n                      size: 16, color: AyatColors.goldBright),\n                  label: const Text(\'تغيير الآية (الرصد خاطئ)\',\n                      style: TextStyle(fontSize: 12)),\n                ),\n                const SizedBox(height: 8),\n                Text(\n                  \'التعديل يظهر فورًا في المعاينة وفي إضاءة الكلمات، ويلتزم به التصدير.\',\n                  style: Theme.of(context).textTheme.bodyMedium,\n                ),\n              ],\n            ),\n            actions: [\n              TextButton(\n                  onPressed: () => Navigator.pop(context),\n                  child: const Text(\'تم\')),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  // PATCH_S86_TIMELINE_EDITING: pick the correct ayah for segment [i] —\n  // keeps its timing, only the label (and confidence) changes.\n  Future<void> _changeSegmentAyahDialog(int i) {\n    if (i < 0 || i >= state.timeline.length) return Future.value();\n    int dialogSurah = state.timeline[i].ayah.surahNum;\n    int? dialogAyahIdx;\n    return showDialog<void>(\n      context: context,\n      builder: (context) => StatefulBuilder(\n        builder: (context, setDialogState) {\n          final surahs = <(int, String)>[];\n          var last = 0;\n          for (final a in state.ayaat) {\n            if (a.surahNum != last) {\n              surahs.add((a.surahNum, a.surah));\n              last = a.surahNum;\n            }\n          }\n          final ayatOfSurah = <(int, Ayah)>[\n            for (var j = 0; j < state.ayaat.length; j++)\n              if (state.ayaat[j].surahNum == dialogSurah) (j, state.ayaat[j]),\n          ];\n          return AlertDialog(\n            backgroundColor: AyatColors.surface,\n            shape: RoundedRectangleBorder(\n              borderRadius: BorderRadius.circular(22),\n              side: const BorderSide(color: AyatColors.hairline),\n            ),\n            title: const Text(\'اختر الآية الصحيحة لهذا المقطع\'),\n            content: Column(\n              mainAxisSize: MainAxisSize.min,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                DropdownButton<int>(\n                  isExpanded: true,\n                  value: surahs.any((s) => s.$1 == dialogSurah)\n                      ? dialogSurah\n                      : (surahs.isEmpty ? null : surahs.first.$1),\n                  items: [\n                    for (final s in surahs)\n                      DropdownMenuItem(\n                          value: s.$1, child: Text(\'سورة ${s.$2}\')),\n                  ],\n                  onChanged: (v) => setDialogState(() {\n                    dialogSurah = v ?? dialogSurah;\n                    dialogAyahIdx = null;\n                  }),\n                ),\n                DropdownButton<int>(\n                  isExpanded: true,\n                  value: dialogAyahIdx,\n                  hint: const Text(\'اختر الآية\'),\n                  items: [\n                    for (final e in ayatOfSurah)\n                      DropdownMenuItem(\n                          value: e.$1, child: Text(\'آية ${e.$2.num}\')),\n                  ],\n                  onChanged: (v) => setDialogState(() => dialogAyahIdx = v),\n                ),\n                const SizedBox(height: 6),\n                Text(\n                  \'التوقيت الذي ضبطته يبقى كما هو — يتغير نص الآية فقط في المعاينة والتصدير.\',\n                  style: Theme.of(context).textTheme.bodyMedium,\n                ),\n              ],\n            ),\n            actions: [\n              TextButton(\n                  onPressed: () => Navigator.pop(context),\n                  child: const Text(\'إلغاء\')),\n              FilledButton(\n                onPressed: dialogAyahIdx == null\n                    ? null\n                    : () {\n                        final ayah = state.ayaat[dialogAyahIdx!];\n                        state.changeSegmentAyah(i, ayah);\n                        Navigator.pop(context);\n                        _toast(\n                            \'تم التغيير إلى سورة ${ayah.surah} — آية ${ayah.num} ✓\');\n                      },\n                child: const Text(\'تطبيق\'),\n              ),\n            ],\n          );\n        },\n      ),\n    );\n  }\n\n  // PATCH_S36_TIMELINE_EDITOR: seek to the previous/next detected ayah.\n  void _seekToAdjacentAyah(int dir) {\n    final c = _video;\n    if (c == null || !c.value.isInitialized || state.timeline.isEmpty) return;\n    final t = c.value.position.inMilliseconds / 1000.0;\n    double? target;\n    if (dir > 0) {\n      for (final s in state.timeline) {\n        if (s.start > t + 0.25) {\n          target = s.start;\n          break;\n        }\n      }\n    } else {\n      for (final s in state.timeline.reversed) {\n        if (s.start < t - 1.0) {\n          target = s.start;\n          break;\n        }\n      }\n      target ??= state.timeline.first.start;\n    }\n    if (target != null) {\n      c.seekTo(Duration(milliseconds: (target * 1000).round() + 30));\n    }\n  }\n\n  /// Free manual cut anywhere in the clip — complements the ayah-boundary\n  /// trim card that appears once an auto-sync timeline exists.\n  Widget _manualCutCard() {\n    final dur = state.videoDurationSec;\n    final end =\n        min(state.trimManualEnd < 0 ? dur : state.trimManualEnd, dur);\n    final start = min(max(0.0, state.trimManualStart), end);\n    return _card(\n      padding: const EdgeInsets.all(12),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Row(\n            children: [\n              Expanded(\n                child: Text(AppStrings(AppSettings.instance.lang).t(\'trim.label\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n                    style: Theme.of(context).textTheme.labelLarge),\n              ),\n              Text(\'${_fmtSec(start)} — ${_fmtSec(end)}\',\n                  style: const TextStyle(\n                      fontSize: 11, color: AyatColors.goldBright)),\n              if (state.manualTrimSet)\n                IconButton(\n                  onPressed: () => state.update(() {\n                    state.trimManualStart = 0;\n                    state.trimManualEnd = -1;\n                  }),\n                  icon: const Icon(Icons.restart_alt,\n                      size: 18, color: AyatColors.parchmentDim),\n                  tooltip: \'إلغاء القص\',\n                ),\n            ],\n          ),\n          RangeSlider(\n            values: RangeValues(start, end),\n            max: dur,\n            onChanged: (r) => state.update(() {\n              state.trimManualStart = r.start;\n              state.trimManualEnd = r.end;\n            }),\n          ),\n          Text(\n            state.trimFromIndex >= 0 && state.trimToIndex >= 0\n                ? \'ملاحظة: نطاق الآيات المحدد أدناه له الأولوية على هذا القص عند التصدير.\'\n                // PATCH_S86_SCAN_RANGE\n                : \'سيُصدَّر هذا النطاق فقط من المقطع — والمزامنة التلقائية ستفحص هذا النطاق وحده (أسرع بكثير في المقاطع الطويلة).\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n        ],\n      ),\n    );\n  }\n\n  // ------------------------------------------------------- tab: تأثيرات\n  // PATCH_S34_STAGE_EFFECTS\n\n  Widget _effectsPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'تأثيرات مرئية\',\n            \'${StageEffect.values.length - 1} تأثيرًا فوق الفيديو أو الخلفية — يظهر التأثير في المعاينة مباشرة ويُدمج في الفيديو المُصدَّر بنفس الشكل.\'),\n        // PATCH_S125_EFFECTS_LIBRARY: 74 effects in one flat Wrap is a wall of\n        // chips nobody reads to the end of. Grouped by category, with the\n        // group holding the current selection expanded, it stays a menu.\n        // PATCH_S194_CUT_FX: everyday editor looks, applied live and exported\n        _fieldLabel(\'لمسات الفيديو\'),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final f in VideoFx.values)\n              ChoiceChip(\n                avatar: const Icon(Icons.movie_filter_outlined, size: 15),\n                label: Text(f.label),\n                selected: state.videoFx == f,\n                onSelected: (_) => state.update(() => state.videoFx =\n                    state.videoFx == f ? VideoFx.none : f),\n              ),\n          ],\n        ),\n        const SizedBox(height: 14),\n        _EffectPicker(\n          selected: state.effect,\n          onSelected: (e) => state.update(\n              () => state.effect = state.effect == e ? StageEffect.none : e),\n        ),\n        if (state.effect != StageEffect.none) ...[\n          _fieldLabel(\'كثافة التأثير\'),\n          Slider(\n            value: state.effectIntensity,\n            min: 0.2,\n            max: 1.0,\n            onChanged: (v) => state.update(() => state.effectIntensity = v),\n          ),\n          const SizedBox(height: 4),\n          Text(\n            \'لإلغاء التأثير بسرعة اضغط زر ✕ أعلى المعاينة — لمس المعاينة في أي مكان آخر يوقف/يشغّل الفيديو فقط.\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n        ],\n        // PATCH_S38_VIDEO_EFFECTS\n        const Divider(height: 32, color: AyatColors.hairline),\n        // PATCH_S58_LIVE_EFFECTS_PREVIEW\n        _panelTitle(\'تأثيرات التصدير\',\n            \'معاينة تقريبية مباشرة على المسرح أعلاه — الملف المُصدَّر هو المرجع النهائي للشكل الدقيق. بصري بحت، لا يغيّر صوت التلاوة إطلاقًا.\'),\n        _fieldLabel(\'تدرّج لوني\'),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final entry in kColorGrades)\n              ChoiceChip(\n                label: Text(_t(entry.$2)),\n                selected: state.colorGrade == entry.$1,\n                onSelected: (_) =>\n                    state.update(() => state.colorGrade = entry.$1),\n              ),\n          ],\n        ),\n        const SizedBox(height: 10),\n        // PATCH_S100_FONTS_SPINSTAR_TINT: quick blue/gold presets plus a full\n        // color picker (showAyatColorPicker), so any color works, not just\n        // the two swatches.\n        _fieldLabel(\'تدرّج بلون مخصص (أزرق / ذهبي / أي لون)\'),\n        Wrap(\n          spacing: 10,\n          runSpacing: 10,\n          crossAxisAlignment: WrapCrossAlignment.center,\n          children: [\n            GestureDetector(\n              onTap: () => state.update(() => state.tintColor = null),\n              child: Container(\n                width: 34,\n                height: 34,\n                decoration: BoxDecoration(\n                  shape: BoxShape.circle,\n                  border: Border.all(\n                      color: state.tintColor == null\n                          ? AyatColors.goldBright\n                          : AyatColors.hairline,\n                      width: state.tintColor == null ? 2.5 : 1),\n                ),\n                child: const Icon(Icons.block, size: 16, color: AyatColors.parchmentDim),\n              ),\n            ),\n            for (final preset in const [\n              (Color(0xFF2A6FDB), \'أزرق\'),\n              (Color(0xFFD4A017), \'ذهبي\'),\n            ])\n              GestureDetector(\n                onTap: () => state.update(() => state.tintColor = preset.$1),\n                child: Container(\n                  width: 34,\n                  height: 34,\n                  decoration: BoxDecoration(\n                    color: preset.$1,\n                    shape: BoxShape.circle,\n                    border: Border.all(\n                        color: state.tintColor?.toARGB32() ==\n                                preset.$1.toARGB32()\n                            ? AyatColors.goldBright\n                            : AyatColors.hairline,\n                        width: state.tintColor?.toARGB32() ==\n                                preset.$1.toARGB32()\n                            ? 2.5\n                            : 1),\n                  ),\n                ),\n              ),\n            GestureDetector(\n              onTap: () async {\n                final c = await showAyatColorPicker(\n                    context, state.tintColor ?? AyatColors.gold);\n                if (c != null) state.update(() => state.tintColor = c);\n              },\n              child: Container(\n                width: 34,\n                height: 34,\n                decoration: BoxDecoration(\n                  color: state.tintColor,\n                  borderRadius: BorderRadius.circular(8),\n                  border: Border.all(color: AyatColors.goldBright),\n                ),\n                child: const Icon(Icons.colorize, size: 15, color: Colors.black54),\n              ),\n            ),\n          ],\n        ),\n        if (state.tintColor != null)\n          Slider(\n            value: state.tintIntensity.toDouble(),\n            min: 0,\n            max: 100,\n            onChanged: (v) => state.update(() => state.tintIntensity = v.round()),\n          ),\n        const SizedBox(height: 10),\n        ToggleRow(\n          label: \'تظليل الحواف (فينيت)\',\n          value: state.vignetteEnabled,\n          onChanged: (v) => state.update(() => state.vignetteEnabled = v),\n        ),\n        if (state.vignetteEnabled)\n          Slider(\n            value: state.vignetteIntensity.toDouble(),\n            min: 0,\n            max: 100,\n            onChanged: (v) =>\n                state.update(() => state.vignetteIntensity = v.round()),\n          ),\n        ToggleRow(\n          label: \'حبيبات سينمائية\',\n          value: state.grainEnabled,\n          onChanged: (v) => state.update(() => state.grainEnabled = v),\n        ),\n        if (state.grainEnabled)\n          Slider(\n            value: state.grainIntensity.toDouble(),\n            min: 0,\n            max: 100,\n            onChanged: (v) =>\n                state.update(() => state.grainIntensity = v.round()),\n          ),\n        // PATCH_S85_VIDEO_ADJUST: manual picture controls, live in the\n        // preview and burned in at export on top of the chosen grade.\n        const Divider(height: 32, color: AyatColors.hairline),\n        Row(\n          children: [\n            Expanded(\n              child: Text(\'ضبط الصورة يدويًا\',\n                  style: Theme.of(context).textTheme.headlineMedium),\n            ),\n            if (state.hasManualAdjust || state.videoBlur > 0.05)\n              TextButton.icon(\n                onPressed: () => state.resetManualAdjust(),\n                icon: const Icon(Icons.restart_alt,\n                    size: 16, color: AyatColors.parchmentDim),\n                label: const Text(\'إعادة الضبط\',\n                    style: TextStyle(\n                        fontSize: 11, color: AyatColors.parchmentDim)),\n              ),\n          ],\n        ),\n        _fieldLabel(\'السطوع\'),\n        Slider(\n          value: state.adjustBrightness,\n          min: -0.25,\n          max: 0.25,\n          onChanged: (v) => state.update(() => state.adjustBrightness = v),\n        ),\n        _fieldLabel(\'التباين\'),\n        Slider(\n          value: state.adjustContrast,\n          min: 0.7,\n          max: 1.4,\n          onChanged: (v) => state.update(() => state.adjustContrast = v),\n        ),\n        _fieldLabel(\'تشبّع الألوان\'),\n        Slider(\n          value: state.adjustSaturation,\n          min: 0.0,\n          max: 2.0,\n          onChanged: (v) => state.update(() => state.adjustSaturation = v),\n        ),\n        _fieldLabel(\'تمويه الفيديو/الخلفية (النص يبقى حادًا)\'),\n        Slider(\n          value: state.videoBlur,\n          min: 0.0,\n          max: 6.0,\n          onChanged: (v) => state.update(() => state.videoBlur = v),\n        ),\n        const Divider(height: 32, color: AyatColors.hairline),\n        ToggleRow(\n          label: \'تكبير بطيء للخلفية (كين برنز)\',\n          value: state.kenBurnsEnabled,\n          onChanged: (v) => state.update(() => state.kenBurnsEnabled = v),\n        ),\n        Text(\n          \'يُطبَّق على الخلفية فقط (جاهزة، طبيعية، فن ذكاء اصطناعي، أو مخصّصة) — لا يُطبَّق أبدًا على فيديو التلاوة المرفوع نفسه.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        ToggleRow(\n          label: \'انتقالات ناعمة حول البسملة والخاتمة\',\n          value: state.softTransitions,\n          onChanged: (v) => state.update(() => state.softTransitions = v),\n        ),\n        const SizedBox(height: 6),\n        Text(\n          \'ملاحظة: قالب «زجاج مصنفر أنيق» الجديد (تبويب قوالب) يستخدم لوحة نص زجاجية — جرّبه مع هذه التأثيرات.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n      ],\n    );\n  }\n\n  // PATCH_S59_TAB_GRID: fixed 4-column grid so 8 tabs always lay out as a\n  // clean 4+4, instead of Wrap\'s width-driven 3/4/1 orphan row.\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: one horizontal row of 5 equal chips — easy to scan.\n  Widget _tabChips() {\n    // PATCH_S132_GAUNTLET_LOOP: classic mode uses the original fixed\n    // 4-column grid (8 tabs never fit a single Row); grouped mode keeps\n    // the current 5-wide Row unchanged.\n    if (AppSettings.instance.classicTabs) {\n      return GridView.count(\n        crossAxisCount: 4,\n        shrinkWrap: true,\n        physics: const NeverScrollableScrollPhysics(),\n        mainAxisSpacing: 8,\n        crossAxisSpacing: 8,\n        childAspectRatio: 1.55,\n        children: [\n          for (var i = 0; i < _tabs.length; i++) _tabButton(i),\n        ],\n      );\n    }\n    // PATCH_S166_UI_POLISH: one gold pill glides behind the tabs. Directional\n    // alignment, so it follows the tab order in both RTL and LTR.\n    final n = _tabs.length;\n    final sel = _safeSelectedTab;\n    return Container(\n      height: 62,\n      padding: const EdgeInsets.all(3),\n      decoration: BoxDecoration(\n        color: AyatColors.surface2,\n        borderRadius: BorderRadius.circular(22),\n        border: Border.all(color: AyatColors.hairline),\n      ),\n      child: Stack(\n        children: [\n          AnimatedAlign(\n            duration: AppMotion.d(AppMotion.medium),\n            curve: Curves.easeOutBack,\n            alignment: AlignmentDirectional(\n                n <= 1 ? 0.0 : -1.0 + 2.0 * sel / (n - 1), 0),\n            child: FractionallySizedBox(\n              widthFactor: 1 / n,\n              heightFactor: 1,\n              child: DecoratedBox(\n                decoration: BoxDecoration(\n                  gradient: const LinearGradient(\n                    begin: Alignment.topCenter,\n                    end: Alignment.bottomCenter,\n                    colors: [AyatColors.goldBright, AyatColors.gold],\n                  ),\n                  borderRadius: BorderRadius.circular(18),\n                  boxShadow: [\n                    BoxShadow(\n                      color: AyatColors.gold.withValues(alpha: 0.4),\n                      blurRadius: 14,\n                      offset: const Offset(0, 3),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n          Row(\n            children: [\n              for (var i = 0; i < n; i++)\n                Expanded(child: _tabButton(i, slider: true)),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: compact chip — icon + short label, works in a 5-wide row.\n  Widget _tabButton(int i, {bool slider = false}) {\n    // PATCH_S165_UI_REFRESH: animated pill. Selected = gold gradient + glow,\n    // icon pops with a spring; everything is a no-op when animations are off.\n    // PATCH_S166_UI_POLISH: slider = true means the shared sliding pill in\n    // _tabChips paints the selected background, so this tab stays transparent.\n    final selected = _safeSelectedTab == i;\n    final dur = AppMotion.d(AppMotion.fast);\n    return PressableScale(\n      borderRadius: BorderRadius.circular(18),\n      pressedScale: 0.94,\n      onTap: () {\n        HapticFeedback.selectionClick();\n        setState(() => _selectedTab = i);\n      },\n      child: AnimatedContainer(\n        duration: dur,\n        curve: Curves.easeOutCubic,\n        height: slider ? double.infinity : 56,\n        alignment: Alignment.center,\n        decoration: BoxDecoration(\n          gradient: (selected && !slider)\n              ? const LinearGradient(\n                  begin: Alignment.topCenter,\n                  end: Alignment.bottomCenter,\n                  colors: [AyatColors.goldBright, AyatColors.gold],\n                )\n              : null,\n          color: (selected || slider) ? null : AyatColors.surface2,\n          borderRadius: BorderRadius.circular(16),\n          border: slider\n              ? null\n              : Border.all(\n                  color:\n                      selected ? AyatColors.goldBright : AyatColors.hairline,\n                ),\n          boxShadow: (selected && !slider)\n              ? [\n                  BoxShadow(\n                    color: AyatColors.gold.withValues(alpha: 0.38),\n                    blurRadius: 14,\n                    offset: const Offset(0, 4),\n                  ),\n                ]\n              : const [],\n        ),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            AnimatedScale(\n              scale: selected ? 1.14 : 1.0,\n              duration: dur,\n              curve: AppMotion.spring,\n              child: Icon(_tabs[i].$1,\n                  size: 19,\n                  color: selected ? AyatColors.ink : AyatColors.parchmentDim),\n            ),\n            const SizedBox(height: 3),\n            AnimatedDefaultTextStyle(\n              duration: dur,\n              maxLines: 1,\n              overflow: TextOverflow.ellipsis,\n              textAlign: TextAlign.center,\n              style: TextStyle(\n                fontSize: 11,\n                fontWeight: FontWeight.w700,\n                color: selected ? AyatColors.ink : AyatColors.parchment,\n              ),\n              child: Text(_tabs[i].$2),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: case map matches the 5-group bar.\n  // النص (1) finally mounts TextEditorPro instead of the old plain panel.\n  // ignore: unused_element\n  Widget _panelCard() {\n    // PATCH_S165_UI_REFRESH: cross-fade + a small upward slide between tabs.\n    // Keyed on tab + mode so switching classic/grouped also animates.\n    return _card(\n      child: AnimatedSize( // PATCH_S169_MOTION_FEEL: glide the height\n        duration: AppMotion.d(AppMotion.medium),\n        curve: Curves.easeOutCubic,\n        alignment: Alignment.topCenter,\n        child: AnimatedSwitcher(\n        duration: AppMotion.d(AppMotion.medium),\n        switchInCurve: Curves.easeOutCubic,\n        switchOutCurve: Curves.easeIn,\n        transitionBuilder: (child, anim) => FadeTransition(\n          opacity: anim,\n          child: SlideTransition(\n            position: Tween<Offset>(\n              begin: const Offset(0, 0.03),\n              end: Offset.zero,\n            ).animate(anim),\n            child: child,\n          ),\n        ),\n        layoutBuilder: (current, previous) => Stack(\n          alignment: Alignment.topCenter,\n          fit: StackFit.passthrough,\n          children: [...previous, if (current != null) current],\n        ),\n        child: KeyedSubtree(\n          key: ValueKey(\'${AppSettings.instance.classicTabs}-$_selectedTab\'),\n          child: _panelBody(),\n        ),\n      ),\n      ),\n    );\n  }\n\n  Widget _panelBody() {\n    return AppSettings.instance.classicTabs\n        ? switch (_selectedTab) {\n            0 => _ayahPanel(),\n            1 => _bgPanel(),\n            2 => _effectsPanel(),\n            3 => _chromaPanel(),\n            4 => _recitersPanel(),\n            5 => _templatesPanel(),\n            6 => _textEditorProPanel(),\n            _ => _exportPanel(),\n          }\n        : switch (_selectedTab) {\n            0 => _ayahPanel(),\n            1 => _textEditorProPanel(),\n            2 => _shapePanel(), // effects + templates\n            3 => _mediaPanel(), // backgrounds + chroma + reciters\n            _ => _exportPanel(),\n          };\n  }\n\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: "الشكل" — visual look (particles + ready templates).\n  Widget _shapePanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _effectsPanel(),\n        _ornament(), // PATCH_S166_UI_POLISH\n        _templatesPanel(),\n      ],\n    );\n  }\n\n  // PATCH_S129_WIRE_AND_SIMPLIFY_UI: "الوسائط" — backgrounds, chroma, reciter audio.\n  Widget _mediaPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _bgPanel(),\n        _ornament(), // PATCH_S166_UI_POLISH\n        _chromaPanel(),\n        _ornament(),\n        _recitersPanel(),\n      ],\n    );\n  }\n\n  // ------------------------------------------------------------ tab: تصدير\n  // PATCH_S54_PRO_EXPORT_CONTROLS\n\n  Widget _exportPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'إعدادات التصدير\',\n            \'تحكّم احترافي في الإخراج النهائي — بلا أي شعار للتطبيق، ولا علامة مائية إلا التي تضيفينها بنفسك.\'),\n        if (state.hasVideo) ...[\n          // PATCH_S154_STUDIO_PRESETS_I18N: was reading kAspectRatios\' dead\n          // Arabic-only 2nd field directly -- always showed Arabic regardless\n          // of interface language, even though the chip row right below this\n          // already uses the aspect.* i18n key. Now consistent with it.\n          _fieldLabel(_tf(\'preset.fitModeFrameHint\',\n              [_t(\'aspect.${state.aspectRatio.name}\')])),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final entry in kVideoFitModes)\n                ChoiceChip(\n                  label: Text(_t(entry.$2)),\n                  selected: state.videoFit == entry.$1,\n                  onSelected: (_) =>\n                      state.update(() => state.videoFit = entry.$1),\n                ),\n            ],\n          ),\n          const SizedBox(height: 6),\n          Text(\n            \'«احتواء + خلفية ضبابية» يعرض الفيديو كاملًا فوق نسخة ضبابية منه تملأ الإطار (مظهر الريلز الشهير). المعاينة تعرض الاحتواء، والضبابية تُرسم في الفيديو المُصدَّر.\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n          _fieldLabel(\'تدوير وقلب الفيديو\'),\n          Row(\n            children: [\n              OutlinedButton.icon(\n                onPressed: () => state.update(() =>\n                    state.videoRotationQuarterTurns =\n                        (state.videoRotationQuarterTurns + 1) % 4),\n                icon:\n                    const Icon(Icons.rotate_90_degrees_cw_outlined, size: 18),\n                label: Text(state.videoRotationQuarterTurns == 0\n                    ? \'تدوير 90°\'\n                    : \'تدوير: ${state.videoRotationQuarterTurns * 90}°\'),\n              ),\n              const SizedBox(width: 8),\n              OutlinedButton.icon(\n                onPressed: () =>\n                    state.update(() => state.videoMirror = !state.videoMirror),\n                icon: const Icon(Icons.flip, size: 18),\n                label: Text(state.videoMirror ? \'مقلوب ✓\' : \'قلب أفقي\'),\n              ),\n            ],\n          ),\n          const Divider(height: 32, color: AyatColors.hairline),\n        ],\n        _fieldLabel(\'جودة الترميز\'),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final entry in kExportQualities)\n              ChoiceChip(\n                label: Text(_t(entry.$2)),\n                selected: state.exportQuality == entry.$1,\n                onSelected: (_) =>\n                    state.update(() => state.exportQuality = entry.$1),\n              ),\n          ],\n        ),\n        _fieldLabel(\'دقة الإخراج\'),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final entry in kExportResolutions)\n              ChoiceChip(\n                // PATCH_S154_STUDIO_PRESETS_I18N: \'1080p\'/\'720p\' aren\'t\n                // i18n keys and t() returns an unknown key unchanged, so\n                // this is safe for all three entries.\n                label: Text(_t(entry.$2)),\n                selected: state.exportResolution == entry.$1,\n                onSelected: (_) =>\n                    state.update(() => state.exportResolution = entry.$1),\n              ),\n          ],\n        ),\n        const Divider(height: 32, color: AyatColors.hairline),\n        Text(\'صوت التلاوة في المقطع المُصدَّر\',\n            style: Theme.of(context).textTheme.headlineMedium),\n        _fieldLabel(\'مستوى الصوت: ${(state.audioVolume * 100).round()}٪\'),\n        Slider(\n          value: state.audioVolume,\n          min: 0.0,\n          max: 2.0,\n          divisions: 40,\n          onChanged: (v) => state.update(() => state.audioVolume = v),\n        ),\n        ToggleRow(\n          label: \'دخول تدريجي للصوت (ثانية واحدة)\',\n          value: state.audioFadeIn,\n          onChanged: (v) => state.update(() => state.audioFadeIn = v),\n        ),\n        ToggleRow(\n          label: \'خفوت تدريجي في نهاية المقطع\',\n          value: state.audioFadeOut,\n          onChanged: (v) => state.update(() => state.audioFadeOut = v),\n        ),\n        // PATCH_S123_AUDIO_MIX: attaching a reciter used to silence the clip\n        // outright. This keeps the original underneath at a chosen level.\n        if (state.selectedReciterAudio != null && state.hasVideo) ...[\n          _fieldLabel(\n              \'${_t(\'audio.originalUnder\')}: ${(state.originalAudioMix * 100).round()}٪\'),\n          Slider(\n            value: state.originalAudioMix,\n            min: 0.0,\n            max: 1.0,\n            divisions: 20,\n            onChanged: (v) => state.update(() => state.originalAudioMix = v),\n          ),\n          Text(_t(\'audio.originalUnderHint\'),\n              style: Theme.of(context).textTheme.bodyMedium),\n          const SizedBox(height: 6),\n        ],\n        ToggleRow(\n          label: _t(\'audio.muteAll\'),\n          value: state.muteAudio,\n          onChanged: (v) => state.update(() => state.muteAudio = v),\n        ),\n        const SizedBox(height: 6),\n        Text(\n          \'تُطبَّق هذه الإعدادات على المسار الصوتي المُصدَّر أيًّا كان مصدره (تلاوة مرفقة أو صوت الفيديو نفسه) — التلاوة نفسها لا تُسرَّع ولا تُبطَّأ أبدًا.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const Divider(height: 32, color: AyatColors.hairline),\n        _ambienceBedSection(),\n        const Divider(height: 32, color: AyatColors.hairline),\n        _speedSection(),\n        const Divider(height: 32, color: AyatColors.hairline),\n        _subtitleSection(),\n        const Divider(height: 32, color: AyatColors.hairline),\n        _watermarkSection(),\n      ],\n    );\n  }\n\n  // PATCH_S126_TEXT_TRANSITIONS: how the ayah text arrives and leaves.\n  // Split in/out, because "rise in, fade out" is the pairing most people\n  // actually want and forcing one setting for both makes it unreachable.\n  Widget _textTransitionSection() {\n    Widget picker({\n      required String label,\n      required TextTransition current,\n      required ValueChanged<TextTransition> onPick,\n    }) {\n      final plain = TextTransition.values.where((t) => !t.isReveal).toList();\n      final reveals = TextTransition.values.where((t) => t.isReveal).toList();\n      return Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          _fieldLabel(label),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final t in plain)\n                ChoiceChip(\n                  label: Text(t.label),\n                  selected: current == t,\n                  onSelected: (_) => onPick(t),\n                ),\n            ],\n          ),\n          const SizedBox(height: 8),\n          Text(\'كشف تدريجي\',\n              style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n                  color: AyatColors.gold, fontWeight: FontWeight.w700)),\n          const SizedBox(height: 6),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final t in reveals)\n                ChoiceChip(\n                  label: Text(t.label),\n                  selected: current == t,\n                  onSelected: (_) => onPick(t),\n                ),\n            ],\n          ),\n        ],\n      );\n    }\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(\'ظهور النص واختفاؤه\',\n            style: Theme.of(context).textTheme.headlineMedium),\n        const SizedBox(height: 4),\n        Text(\n          \'${TextTransition.values.length} أسلوبًا لدخول النص وخروجه. المعاينة \'\n          \'أعلاه تعرض الأسلوب نفسه الذي سيُدمج في الفيديو تمامًا.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const SizedBox(height: 10),\n        picker(\n          label: \'أسلوب الدخول\',\n          current: state.textInTransition,\n          onPick: (t) => state.update(() => state.textInTransition = t),\n        ),\n        const SizedBox(height: 14),\n        picker(\n          label: \'أسلوب الخروج\',\n          current: state.textOutTransition,\n          onPick: (t) => state.update(() => state.textOutTransition = t),\n        ),\n        const SizedBox(height: 14),\n        _fieldLabel(\'مدة الحركة: ${state.textTransitionMs} مللي ثانية\'),\n        Slider(\n          value: state.textTransitionMs\n              .toDouble()\n              .clamp(kMinTextTransitionMs.toDouble(),\n                  kMaxTextTransitionMs.toDouble()),\n          min: kMinTextTransitionMs.toDouble(),\n          max: kMaxTextTransitionMs.toDouble(),\n          divisions: (kMaxTextTransitionMs - kMinTextTransitionMs) ~/ 50,\n          onChanged: (v) =>\n              state.update(() => state.textTransitionMs = v.round()),\n        ),\n        Text(\n          \'الأطول أهدأ وأنعم. تُرسم الحركة بـ ${ExportService.overlayFps} إطارًا \'\n          \'في الثانية عند التصدير، فلا يظهر أي تقطيع.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n      ],\n    );\n  }\n\n  // PATCH_S127_MUSIC_BED: an ambience/nasheed track UNDER everything else.\n  // Distinct from the reciter mix above, which only rebalances the two tracks\n  // that were already in the clip.\n  Widget _ambienceBedSection() {\n    final path = state.ambienceBedPath;\n    final name = path == null ? null : path.split(Platform.pathSeparator).last;\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(\'خلفية صوتية / أجواء\',\n            style: Theme.of(context).textTheme.headlineMedium),\n        const SizedBox(height: 4),\n        Text(\n          \'مسار صوتي هادئ يُمزج تحت التلاوة وصوت المقطع. يُكرَّر تلقائيًا إذا \'\n          \'كان أقصر من الفيديو ويُقصّ إذا كان أطول، فلا حاجة لمطابقة المدة.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const SizedBox(height: 10),\n        Row(\n          children: [\n            Expanded(\n              child: OutlinedButton.icon(\n                onPressed: _pickAmbienceBed,\n                icon: const Icon(Icons.graphic_eq),\n                label: Text(path == null ? \'اختيار ملف صوتي\' : \'تغيير الملف\'),\n              ),\n            ),\n            if (path != null) ...[\n              const SizedBox(width: 8),\n              IconButton(\n                tooltip: \'إزالة الخلفية الصوتية\',\n                onPressed: () => state.update(() => state.ambienceBedPath = null),\n                icon: const Icon(Icons.close),\n              ),\n            ],\n          ],\n        ),\n        if (name != null) ...[\n          const SizedBox(height: 6),\n          Text(name,\n              maxLines: 1,\n              overflow: TextOverflow.ellipsis,\n              style: Theme.of(context)\n                  .textTheme\n                  .bodyMedium\n                  ?.copyWith(color: AyatColors.gold)),\n          const SizedBox(height: 10),\n          _fieldLabel(\n              \'مستوى الخلفية: ${(state.ambienceBedVolume * 100).round()}٪\'),\n          Slider(\n            value: state.ambienceBedVolume,\n            min: 0.0,\n            max: 1.0,\n            divisions: 20,\n            onChanged: (v) => state.update(() => state.ambienceBedVolume = v),\n          ),\n          ToggleRow(\n            label: \'دخول وخروج تدريجي للخلفية\',\n            value: state.ambienceBedFade,\n            onChanged: (v) => state.update(() => state.ambienceBedFade = v),\n          ),\n          if (state.muteAudio)\n            Text(\'الصوت مكتوم بالكامل حاليًا — أوقف الكتم لتسمع الخلفية.\',\n                style: Theme.of(context).textTheme.bodyMedium),\n        ],\n      ],\n    );\n  }\n\n  Future<void> _pickAmbienceBed() async {\n    final res = await FilePicker.platform.pickFiles(type: FileType.audio);\n    final path = res?.files.single.path;\n    if (path == null) return;\n    state.update(() => state.ambienceBedPath = path);\n    _toast(\'تمت إضافة خلفية صوتية ✓\');\n  }\n\n  // PATCH_S125_SPEED: constant-rate speed change, applied to the finished\n  // composite so picture, synced text and particles all move together.\n  Widget _speedSection() {\n    const presets = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0];\n    final hasReciter = state.selectedReciterAudio != null;\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(\'سرعة المقطع\', style: Theme.of(context).textTheme.headlineMedium),\n        const SizedBox(height: 4),\n        Text(\n          \'أقل من ١× حركة بطيئة، وأكثر تسريع. تُطبَّق على الصورة وعلى نص الآية \'\n          \'المتزامن معًا، فلا ينفصل أحدهما عن الآخر.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const SizedBox(height: 8),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final sp in presets)\n              ChoiceChip(\n                label: Text(sp == 1.0 ? \'عادي ١×\' : \'${sp}×\'),\n                selected: (state.playbackSpeed - sp).abs() < 0.005,\n                onSelected: (_) =>\n                    state.update(() => state.playbackSpeed = sp),\n              ),\n          ],\n        ),\n        if (state.hasSpeedChange) ...[\n          const SizedBox(height: 8),\n          Text(\n            hasReciter\n                ? \'تلاوة القارئ المرفقة لا تُسرَّع ولا تُبطَّأ إطلاقًا — تبقى بطبقة \'\n                    \'صوتها الأصلية. السرعة تُطبَّق على الصورة وصوت المقطع فقط.\'\n                : \'صوت المقطع الأصلي يتغيّر مع الصورة للحفاظ على التزامن.\',\n            style: Theme.of(context)\n                .textTheme\n                .bodyMedium\n                ?.copyWith(color: AyatColors.goldBright),\n          ),\n        ],\n      ],\n    );\n  }\n\n  // PATCH_S125_SUBTITLES: the auto-sync timeline already knows which ayah was\n  // recited between which two seconds -- that IS a subtitle track, it just\n  // had nowhere to go. Burned-in text can\'t be switched off, translated or\n  // read by a screen reader; a sidecar file can.\n  Widget _subtitleSection() {\n    final cues = SubtitleService.cueCount(state.timeline);\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(\'ملف الترجمة (SRT / VTT)\',\n            style: Theme.of(context).textTheme.headlineMedium),\n        const SizedBox(height: 4),\n        Text(\n          \'يُحفظ ملف ترجمة بجانب الفيديو في مجلد التنزيلات، مبنيًّا على توقيت \'\n          \'الآيات المرصودة. مفيد ليوتيوب وللمشاهدين الذين يحتاجون نصًا يمكن \'\n          \'إيقافه أو ترجمته — بخلاف النص المحروق في الصورة.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const SizedBox(height: 8),\n        ToggleRow(\n          label: \'تصدير ملف ترجمة مع الفيديو\',\n          value: state.exportSubtitles,\n          onChanged: (v) => state.update(() => state.exportSubtitles = v),\n        ),\n        if (state.exportSubtitles) ...[\n          const SizedBox(height: 8),\n          if (state.timeline.isEmpty)\n            Text(\n              \'لا توجد آيات مرصودة بعد — شغّلي «المزامنة التلقائية» أو أضيفي \'\n              \'آيات للخط الزمني يدويًا، وإلا فلن يحتوي الملف على شيء.\',\n              style: Theme.of(context)\n                  .textTheme\n                  .bodyMedium\n                  ?.copyWith(color: AyatColors.goldBright),\n            )\n          else\n            Text(\'سيحتوي الملف على $cues مقطعًا نصيًا.\',\n                style: Theme.of(context).textTheme.bodyMedium),\n          const SizedBox(height: 8),\n          _fieldLabel(\'الصيغة\'),\n          Wrap(\n            spacing: 8,\n            children: [\n              for (final f in SubtitleFormat.values)\n                ChoiceChip(\n                  label: Text(f.labelAr),\n                  selected: state.subtitleFormat == f,\n                  onSelected: (_) =>\n                      state.update(() => state.subtitleFormat = f),\n                ),\n            ],\n          ),\n          _fieldLabel(\'المحتوى\'),\n          Wrap(\n            spacing: 8,\n            children: [\n              for (final c in SubtitleContent.values)\n                ChoiceChip(\n                  label: Text(switch (c) {\n                    SubtitleContent.arabic => \'الآية بالعربية\',\n                    SubtitleContent.translation => \'ترجمة المعاني\',\n                    SubtitleContent.both => \'الاثنان معًا\',\n                  }),\n                  selected: state.subtitleContent == c,\n                  onSelected: (_) =>\n                      state.update(() => state.subtitleContent = c),\n                ),\n            ],\n          ),\n        ],\n      ],\n    );\n  }\n\n  // PATCH_S123_WATERMARK: opt-in, and visibly so. The app adds nothing to an\n  // export by default and never asks for money to remove a mark it put there\n  // itself -- this exists so a channel can sign its OWN work.\n  Widget _watermarkSection() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(_t(\'wm.section\'),\n            style: Theme.of(context).textTheme.headlineMedium),\n        const SizedBox(height: 4),\n        Text(_t(\'wm.hint\'), style: Theme.of(context).textTheme.bodyMedium),\n        const SizedBox(height: 8),\n        ToggleRow(\n          label: _t(\'wm.enable\'),\n          value: state.watermarkEnabled,\n          onChanged: (v) => state.update(() => state.watermarkEnabled = v),\n        ),\n        if (state.watermarkEnabled) ...[\n          const SizedBox(height: 8),\n          TextField(\n            controller: _watermarkCtrl,\n            decoration: InputDecoration(\n              labelText: _t(\'wm.text\'),\n              hintText: \'مثال: قناة نور\',\n            ),\n            onChanged: (v) => state.update(() => state.watermarkText = v),\n          ),\n          const SizedBox(height: 10),\n          Row(\n            children: [\n              Expanded(\n                child: OutlinedButton.icon(\n                  onPressed: _pickWatermarkImage,\n                  icon: const Icon(Icons.image_outlined, size: 18),\n                  label: Text(state.watermarkImagePath == null\n                      ? _t(\'wm.pickImage\')\n                      : _t(\'wm.image\')),\n                ),\n              ),\n              if (state.watermarkImagePath != null) ...[\n                const SizedBox(width: 8),\n                IconButton(\n                  tooltip: _t(\'wm.clearImage\'),\n                  onPressed: () =>\n                      state.update(() => state.watermarkImagePath = null),\n                  icon: const Icon(Icons.close, color: AyatColors.gold),\n                ),\n              ],\n            ],\n          ),\n          const SizedBox(height: 4),\n          Text(\n            state.watermarkImagePath == null\n                ? \'بدون صورة ستُستخدم الكتابة أعلاه.\'\n                : \'الصورة تحلّ محل النص. أزيليها للعودة إلى الكتابة.\',\n            style: Theme.of(context).textTheme.bodyMedium,\n          ),\n          const SizedBox(height: 10),\n          _fieldLabel(_t(\'wm.position\')),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final entry in kWatermarkCorners)\n                ChoiceChip(\n                  label: Text(_t(entry.$2)),\n                  selected: state.watermarkCorner == entry.$1,\n                  onSelected: (_) =>\n                      state.update(() => state.watermarkCorner = entry.$1),\n                ),\n            ],\n          ),\n          _fieldLabel(\n              \'${_t(\'wm.size\')}: ${(state.watermarkScale * 100).round()}٪\'),\n          Slider(\n            value: state.watermarkScale,\n            min: 0.08,\n            max: 0.45,\n            divisions: 37,\n            onChanged: (v) => state.update(() => state.watermarkScale = v),\n          ),\n          _fieldLabel(\n              \'${_t(\'wm.opacity\')}: ${(state.watermarkOpacity * 100).round()}٪\'),\n          Slider(\n            value: state.watermarkOpacity,\n            min: 0.15,\n            max: 1.0,\n            divisions: 17,\n            onChanged: (v) => state.update(() => state.watermarkOpacity = v),\n          ),\n        ],\n      ],\n    );\n  }\n\n  // PATCH_S123_WATERMARK: copied into app storage like the background\n  // uploads (S64) -- a picked file\'s original path can be a temporary\n  // content:// cache entry that no longer resolves on the next launch.\n  Future<void> _pickWatermarkImage() async {\n    final res = await FilePicker.platform.pickFiles(type: FileType.image);\n    final src = res?.files.single.path;\n    if (src == null) return;\n    try {\n      final docs = await getApplicationDocumentsDirectory();\n      final dir = Directory(\'${docs.path}/watermark\');\n      if (!dir.existsSync()) dir.createSync(recursive: true);\n      final ext = src.contains(\'.\') ? src.split(\'.\').last : \'png\';\n      final dst =\n          \'${dir.path}/wm_${DateTime.now().millisecondsSinceEpoch}.$ext\';\n      await File(src).copy(dst);\n      state.update(() {\n        state.watermarkImagePath = dst;\n        state.watermarkEnabled = true;\n      });\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context)\n          .showSnackBar(SnackBar(content: Text(\'تعذّر استخدام هذه الصورة: $e\')));\n    }\n  }\n\n  Widget _panelTitle(String title, [String? hint]) {\n    // PATCH_S165_UI_REFRESH: small gold accent bar before the title.\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Row(\n          children: [\n            Container(\n              width: 3,\n              height: 18,\n              decoration: BoxDecoration(\n                borderRadius: BorderRadius.circular(3),\n                gradient: const LinearGradient(\n                  begin: Alignment.topCenter,\n                  end: Alignment.bottomCenter,\n                  colors: [AyatColors.goldBright, AyatColors.goldDim],\n                ),\n              ),\n            ),\n            const SizedBox(width: 10),\n            Expanded(\n              child: Text(title,\n                  style: Theme.of(context).textTheme.headlineMedium),\n            ),\n          ],\n        ),\n        if (hint != null) ...[\n          const SizedBox(height: 4),\n          Padding(\n            padding: const EdgeInsetsDirectional.only(start: 13),\n            child: Text(hint, style: Theme.of(context).textTheme.bodyMedium),\n          ),\n        ],\n        const SizedBox(height: 12),\n      ],\n    );\n  }\n\n  Widget _fieldLabel(String s) => Padding(\n        padding: const EdgeInsets.only(top: 10, bottom: 6),\n        child: Text(s,\n            style: Theme.of(context)\n                .textTheme\n                .labelLarge\n                ?.copyWith(color: AyatColors.goldDim)),\n      );\n\n  // PATCH_S128: tabbed pro text editor\n  // PATCH_S132_GAUNTLET_LOOP: the 30-style transitions section\n  // (_textTransitionSection, PATCH_S126) never got ported into\n  // TextEditorPro when S128 replaced the old _textPanel() -- it still\n  // works exactly as before, it was just orphaned. Mounted alongside\n  // the tabbed editor instead of duplicating 30 already-correct entries.\n  Widget _textEditorProPanel() => Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          TextEditorPro(\n            state: state,\n            segmentTexts: state.unifiedTexts,\n            canvasWidth: 1080,\n            onPickCustomFont: _pickCustomFont,\n          ),\n          const Divider(height: 32, color: AyatColors.hairline),\n          _textTransitionSection(),\n        ],\n      );\n\n  // PATCH_S128_FIX1_BUILD_ERRORS: bridge only -- PATCH_S128 called this but never\n  // defined it. This just restores the old tab strip so the app\n  // builds. TODO: replace with the real 5 grouped tabs\n  // (آيات/نص/شكل/وسائط/مزيد) described in the PATCH_S128 comment.\n  // ignore: unused_element\n  Widget _simpleTopTabs() => _tabChips();\n\n  // PATCH_S120_ADVANCED_OPTIONS_CLEANUP: shared header for every optional\n  // section below the ayah picker (partial-ayah, red words, manual\n  // timing, caption, multi-ayah range, intro/outro cards). badgeNum\n  // reuses the same gold ayahNumberBadge size/style as the السورة/الآية\n  // dropdown above (size: 22, fontSize: 10) instead of each section\n  // picking its own -- that mismatch was the "floating circle" mess.\n  // The long explanation moves into a tap-to-open popup instead of\n  // sitting permanently inline under the title.\n  Widget _sectionHeader(String title, String infoText, {int? badgeNum}) {\n    return Row(\n      crossAxisAlignment: CrossAxisAlignment.center,\n      children: [\n        if (badgeNum != null) ...[\n          ayahNumberBadge(badgeNum, size: 22, fontSize: 10),\n          const SizedBox(width: 8),\n        ],\n        Expanded(\n          child: Text(title, style: Theme.of(context).textTheme.headlineMedium),\n        ),\n        IconButton(\n          padding: EdgeInsets.zero,\n          constraints: const BoxConstraints(minWidth: 32, minHeight: 32),\n          visualDensity: VisualDensity.compact,\n          icon: const Icon(Icons.info_outline,\n              size: 19, color: AyatColors.goldDim),\n          tooltip: \'توضيح\',\n          onPressed: () => _showSectionInfo(title, infoText),\n        ),\n      ],\n    );\n  }\n\n  Future<void> _showSectionInfo(String title, String text) {\n    return showDialog(\n      context: context,\n      builder: (_) => AlertDialog(\n        backgroundColor: AyatColors.surface2,\n        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n        title: Text(title, style: Theme.of(context).textTheme.headlineMedium),\n        content: Text(text, style: Theme.of(context).textTheme.bodyMedium),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text(\'حسنًا\'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  // One consistent bordered surface for every optional section instead\n  // of the previous mix of bare SizedBox/Divider spacers between them.\n  Widget _sectionCard(Widget child) {\n    return Container(\n      margin: const EdgeInsets.only(top: 14),\n      padding: const EdgeInsets.all(14),\n      decoration: BoxDecoration(\n        color: AyatColors.surface2,\n        borderRadius: BorderRadius.circular(16), // PATCH_S165_UI_REFRESH\n        border: Border.all(color: AyatColors.hairline),\n      ),\n      child: child,\n    );\n  }\n\n  // ------------------------------------------------------------ tab: الآية\n\n  // PATCH_S101_AUTOSYNC_HINT_PARTIAL_AYAH: lets you use only part of the\n  // currently-picked ayah (e.g. the first half) as the on-screen text,\n  // instead of always the whole ayah. Purely a text-slicing UI -- the\n  // result still goes through the normal state.setAyah() path, so\n  // AI-art/karaoke/export don\'t need to know the difference.\n  Widget _partialAyahSection() {\n    final a = _partialSourceAyah;\n    if (a == null) return const SizedBox.shrink();\n    final words = a.ar.split(RegExp(r\'\\s+\')).where((w) => w.isNotEmpty).toList();\n    if (words.length < 2) return const SizedBox.shrink();\n    final from = _partialFromWord.clamp(0, words.length - 1);\n    final to = _partialToWord.clamp(from, words.length - 1);\n    final partialText = words.sublist(from, to + 1).join(\' \');\n    final isFull = from == 0 && to == words.length - 1;\n    return _sectionCard(Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _sectionHeader(\n          _t(\'partial.use\'), // PATCH_S134_AUTOSEG_WIZARD\n          \'اختاري من أي كلمة إلى أي كلمة من الآية المحددة أعلاه -- مفيد لعرض \'\n          \'نصفها فقط مثلاً بدل الآية كاملة، أو لإضافتها كمقطع مستقل في الخط \'\n          \'الزمني أدناه. مثال: لو اخترتِ من الكلمة الأولى إلى الثالثة فقط \'\n          \'يظهر هذا الجزء بمفرده -- إمّا كنص الآية نفسه، أو كمقطع منفصل عبر \'\n          \'"إضافة هذا الجزء إلى الخط الزمني" أسفل الصفحة.\',\n          badgeNum: a.num,\n        ),\n        const SizedBox(height: 10),\n        Row(\n          children: [\n            Expanded(\n              child: DropdownButtonFormField<int>(\n                decoration: InputDecoration(labelText: _t(\'partial.fromWord\')), // PATCH_S134_AUTOSEG_WIZARD\n                initialValue: from,\n                items: [\n                  for (var i = 0; i < words.length; i++)\n                    DropdownMenuItem(\n                      value: i,\n                      // PATCH_S107_WORD_DROPDOWN_FONT: match the ayah font\n                      // picked under \'خط الآية\', same fix S105 already did\n                      // for the preview box below.\n                      child: Text(\'${i + 1}. ${words[i]}\',\n                          style: ayahTextStyle(state.fontKey, fontSize: 15)),\n                    ),\n                ],\n                onChanged: (v) => setState(() {\n                  _partialFromWord = v ?? 0;\n                  if (_partialToWord < _partialFromWord) {\n                    _partialToWord = _partialFromWord;\n                  }\n                }),\n              ),\n            ),\n            const SizedBox(width: 10),\n            Expanded(\n              child: DropdownButtonFormField<int>(\n                decoration: InputDecoration(labelText: _t(\'partial.toWord\')), // PATCH_S134_AUTOSEG_WIZARD\n                initialValue: to,\n                items: [\n                  for (var i = 0; i < words.length; i++)\n                    DropdownMenuItem(\n                      value: i,\n                      // PATCH_S107_WORD_DROPDOWN_FONT: match the ayah font\n                      // picked under \'خط الآية\', same fix S105 already did\n                      // for the preview box below.\n                      child: Text(\'${i + 1}. ${words[i]}\',\n                          style: ayahTextStyle(state.fontKey, fontSize: 15)),\n                    ),\n                ],\n                onChanged: (v) => setState(() {\n                  _partialToWord = v ?? (words.length - 1);\n                  if (_partialFromWord > _partialToWord) {\n                    _partialFromWord = _partialToWord;\n                  }\n                }),\n              ),\n            ),\n          ],\n        ),\n        const SizedBox(height: 10),\n        // PATCH_S118_PARTIAL_AYAH_TIMELINE_MERGE: more breathing room around\n        // the preview text itself (was a tight EdgeInsets.all(10)).\n        Container(\n          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 20),\n          decoration: BoxDecoration(\n            border: Border.all(color: AyatColors.hairline),\n            borderRadius: BorderRadius.circular(8),\n          ),\n          child: Text(partialText,\n              textAlign: TextAlign.center,\n              // PATCH_S105_DEFAULT_FONT_PREVIEW: use the ayah font the user\n              // actually picked under \'خط الآية\' (state.fontKey) instead of\n              // the generic UI text style, so this preview matches what\n              // will actually be exported.\n              style: ayahTextStyle(state.fontKey,\n                  fontSize: 20, color: AyatColors.parchment)),\n        ),\n        const SizedBox(height: 10),\n        ElevatedButton(\n          onPressed: isFull\n              ? null\n              : () {\n                  _liveOverlay.value = null;\n                  state.setAyah(\n                    partialText,\n                    a.en,\n                    \'جزء من: سورة ${a.surah} — آية ${a.num}\',\n                    surahNum: a.surahNum,\n                    ayahNum: a.num,\n                  );\n                  _toast(_t(\'partial.usedToast\')); // PATCH_S134_AUTOSEG_WIZARD\n                },\n          child: Text(_t(isFull ? \'partial.full\' : \'partial.useThis\')), // PATCH_S134_AUTOSEG_WIZARD\n        ),\n        const SizedBox(height: 8),\n        // PATCH_S118_PARTIAL_AYAH_TIMELINE_MERGE: the missing link between\n        // this picker and "نطاق آيات متعدد" -- adds the sliced words as a\n        // real timeline segment (chained after the last one, like the\n        // full-ayah manual-add dialog), which makes timelineActive true\n        // and brings up "مراجعة الآيات المرصودة" immediately. No video or\n        // audio required, same as adding a full ayah manually.\n        // PATCH_S119_TIMELINE_VISIBILITY_AND_ENABLE_FIX: this was disabled\n        // whenever the picked range equalled the full ayah (isFull), but\n        // that\'s the default selection AND the only possible selection\n        // for any 2-word ayah -- adding a *whole* ayah to the timeline is\n        // completely valid (it\'s what the full-ayah dialog already does\n        // with no such restriction), so this button no longer checks\n        // isFull at all.\n        OutlinedButton.icon(\n          onPressed: () {\n            final start =\n                state.timeline.isNotEmpty ? state.timeline.last.end : 0.0;\n            final end = start + 4;\n            state.addManualSegment(a, start, end, textOverride: partialText);\n            _revealTimelineCard();\n            _toast(_t(\'partial.addedToast\')); // PATCH_S134_AUTOSEG_WIZARD\n          },\n          icon: const Icon(Icons.playlist_add, size: 18),\n          label: Text(_t(\'partial.addToTimeline\')), // PATCH_S134_AUTOSEG_WIZARD\n        ),\n      ],\n    )); // PATCH_S120_ADVANCED_OPTIONS_CLEANUP\n  }\n\n  // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION: tap a word of the currently\n  // displayed ayah to color just that word red in the exported video.\n  // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION / PATCH_S146_FINISH_WORDCOLORS:\n  // "تلوين كلمات بالأحمر" and "توقيت ظهور النص يدويًا" used to be two\n  // separate boxes stacked back-to-back, even though both are the same\n  // job -- extra control over how the on-screen ayah text stands out --\n  // and coloring a word used to only ever mean red, applied instantly\n  // with no other option. Now one card: pick a color (red by default,\n  // same as before, or any color via the picker), tap words to\n  // paint/unpaint them with it, and set when the whole ayah text\n  // (colored words included) appears/disappears -- one place instead\n  // of two.\n  Widget _manualTimingSection() {\n    final words = state.ayahText\n        .split(RegExp(r\'\\s+\'))\n        .where((w) => w.isNotEmpty)\n        .toList();\n    return _sectionCard(Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _sectionHeader(\n          \'تلوين الكلمات وتوقيت ظهورها (اختياري)\',\n          \'اختاري لونًا ثم اضغطي على أي كلمة لتلوينها به في الفيديو \'\n          \'المُصدَّر -- مفيدة لتمييز اسم الجلالة أو كلمة محورية. اضغطي \'\n          \'الكلمة مجددًا لإزالة لونها. حدّدي أيضًا بالثواني متى يظهر نص \'\n          \'الآية ومتى يختفي؛ اتركي الحقلين فارغين ليظهر طوال المقطع \'\n          \'كالمعتاد.\',\n        ),\n        if (words.isNotEmpty) ...[\n          const SizedBox(height: 10),\n          // PATCH_S145/S146: the color the next tap applies -- defaults to\n          // red so tapping a word behaves exactly like before unless a\n          // different color is chosen first.\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            crossAxisAlignment: WrapCrossAlignment.center,\n            children: [\n              for (final c in const [\n                Color(0xFFE53935), // red -- the old, only option\n                Color(0xFFECC875), // gold\n                Color(0xFFFFFFFF), // white\n                Color(0xFF4CAF50), // green\n                Color(0xFF2A6FDB), // blue\n              ])\n                GestureDetector(\n                  onTap: () => state.update(() => state.activeWordColor = c),\n                  child: Container(\n                    width: 28,\n                    height: 28,\n                    decoration: BoxDecoration(\n                      color: c,\n                      shape: BoxShape.circle,\n                      border: Border.all(\n                          color: state.activeWordColor.toARGB32() ==\n                                  c.toARGB32()\n                              ? AyatColors.goldBright\n                              : Colors.black26,\n                          width: state.activeWordColor.toARGB32() ==\n                                  c.toARGB32()\n                              ? 2.5\n                              : 1),\n                    ),\n                  ),\n                ),\n              GestureDetector(\n                onTap: () async {\n                  final c = await showAyatColorPicker(\n                      context, state.activeWordColor);\n                  if (c != null) {\n                    state.update(() => state.activeWordColor = c);\n                  }\n                },\n                child: Container(\n                  width: 28,\n                  height: 28,\n                  decoration: BoxDecoration(\n                    color: state.activeWordColor,\n                    borderRadius: BorderRadius.circular(8),\n                    border: Border.all(color: AyatColors.goldBright),\n                  ),\n                  child: const Icon(Icons.colorize,\n                      size: 14, color: Colors.black54),\n                ),\n              ),\n            ],\n          ),\n          const SizedBox(height: 8),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (var i = 0; i < words.length; i++)\n                FilterChip(\n                  label: Text(words[i],\n                      style: ayahTextStyle(state.fontKey, fontSize: 14)),\n                  selected: state.wordColors.containsKey(i),\n                  selectedColor:\n                      (state.wordColors[i] ?? state.activeWordColor)\n                          .withValues(alpha: 0.35),\n                  onSelected: (sel) => state.update(() {\n                    if (sel) {\n                      state.wordColors[i] = state.activeWordColor;\n                    } else {\n                      state.wordColors.remove(i);\n                    }\n                  }),\n                ),\n            ],\n          ),\n        ],\n        const Divider(height: 28, color: AyatColors.hairline),\n        Row(\n          children: [\n            Expanded(\n              child: TextField(\n                controller: _textStartCtrl,\n                keyboardType:\n                    const TextInputType.numberWithOptions(decimal: true),\n                decoration: const InputDecoration(labelText: \'يبدأ عند (ثانية)\'),\n                onChanged: (v) => state.update(\n                    () => state.textTimeStartOverride = double.tryParse(v)),\n              ),\n            ),\n            const SizedBox(width: 10),\n            Expanded(\n              child: TextField(\n                controller: _textEndCtrl,\n                keyboardType:\n                    const TextInputType.numberWithOptions(decimal: true),\n                decoration: const InputDecoration(labelText: \'ينتهي عند (ثانية)\'),\n                onChanged: (v) => state.update(\n                    () => state.textTimeEndOverride = double.tryParse(v)),\n              ),\n            ),\n            const SizedBox(width: 6),\n            IconButton(\n              tooltip: \'مسح التوقيت اليدوي\',\n              icon: const Icon(Icons.close),\n              onPressed: () => setState(() {\n                _textStartCtrl.clear();\n                _textEndCtrl.clear();\n                state.update(() {\n                  state.textTimeStartOverride = null;\n                  state.textTimeEndOverride = null;\n                });\n              }),\n            ),\n            const SizedBox(width: 6),\n            // PATCH_S160_MULTI_TEXT_TIME_CUES: commits the text+window above as its OWN cue\n            // instead of it getting silently overwritten by the next text\n            // you type -- this is what actually lets two different texts\n            // each appear in their own time window.\n            IconButton(\n              tooltip: \'إضافة كنص مستقل بتوقيته الخاص\',\n              icon: const Icon(Icons.playlist_add),\n              onPressed: (state.textTimeStartOverride == null ||\n                      state.textTimeEndOverride == null ||\n                      state.ayahText.trim().isEmpty)\n                  ? null\n                  : () => setState(() {\n                        state.update(() => state.commitTextTimeCue());\n                        _textStartCtrl.clear();\n                        _textEndCtrl.clear();\n                        _toast(\'أُضيف النص إلى القائمة ✓\');\n                      }),\n            ),\n          ],\n        ),\n        if (state.textTimeCues.isNotEmpty) ...[\n          const SizedBox(height: 10),\n          for (var _cueIdx = 0; _cueIdx < state.textTimeCues.length; _cueIdx++)\n            Padding(\n              padding: const EdgeInsets.only(bottom: 6),\n              child: Row(\n                children: [\n                  Expanded(\n                    child: Text(\n                      \'${state.textTimeCues[_cueIdx].text}  ·  \'\n                      \'${_fmtSec(state.textTimeCues[_cueIdx].start)}\'\n                      \'–${_fmtSec(state.textTimeCues[_cueIdx].end)}\',\n                      maxLines: 1,\n                      overflow: TextOverflow.ellipsis,\n                      style: ayahTextStyle(state.fontKey, fontSize: 13),\n                    ),\n                  ),\n                  IconButton(\n                    tooltip: \'حذف\',\n                    icon: const Icon(Icons.delete_outline, size: 18),\n                    onPressed: () =>\n                        state.update(() => state.removeTextTimeCueAt(_cueIdx)),\n                  ),\n                ],\n              ),\n            ),\n        ],\n      ],\n    )); // PATCH_S120_ADVANCED_OPTIONS_CLEANUP\n  }\n\n  // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION: free-text caption (reciter\n  // name, ayah-range label, ...) shown near the top or bottom of the frame.\n  Widget _captionSection() {\n    return _sectionCard(Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _sectionHeader(\n          \'نص إضافي (اسم الشيخ، نطاق الآيات...)\',\n          \'مثال: "من آية ١٦ إلى ١٨" أو اسم القارئ -- يظهر كسطر صغير أعلى أو \'\n          \'أسفل الفيديو، بمعزل تمامًا عن نص الآية نفسه، ويمكن اختيار مكانه \'\n          \'(أعلى أو أسفل) من الخيارين تحت الحقل.\',\n        ),\n        const SizedBox(height: 8),\n        TextField(\n          controller: _captionCtrl,\n          decoration: const InputDecoration(\n              hintText: \'مثال: الشيخ عبد الباسط عبد الصمد\'),\n          onChanged: (v) => state.update(() => state.captionText = v),\n        ),\n        const SizedBox(height: 4),\n        // PATCH_S123_QOL: RadioListTile\'s own groupValue/onChanged are\n        // deprecated -- the group is declared once by the RadioGroup\n        // ancestor now, and each tile only carries its own value.\n        RadioGroup<CaptionPosition>(\n          groupValue: state.captionPosition,\n          onChanged: (v) => state.update(\n              () => state.captionPosition = v ?? CaptionPosition.bottom),\n          child: Row(\n            children: [\n              for (final pos in CaptionPosition.values)\n                Expanded(\n                  child: RadioListTile<CaptionPosition>(\n                    dense: true,\n                    contentPadding: EdgeInsets.zero,\n                    title: Text(pos == CaptionPosition.top ? \'أعلى\' : \'أسفل\'),\n                    value: pos,\n                  ),\n                ),\n            ],\n          ),\n        ),\n      ],\n    )); // PATCH_S120_ADVANCED_OPTIONS_CLEANUP\n  }\n\n  // -------------------------------------------------------------------\n  // PATCH_S144_UNIFIED_TEXT_CARD\n  //\n  // Before this patch, "text on the video" was three separate cards in\n  // the الآية tab: "اكتب نص الآية" (Quran-matched ayah text), "طبقات نص\n  // ثابتة" (S143\'s stacked free layers), and a third card further down\n  // the same tab for a small caption (reciter name / ayah range). Three\n  // boxes for one job, each with its own explanation and its own\n  // Add/Apply button, and no single place showing everything that\'s\n  // actually on the video right now.\n  //\n  // This replaces all three with ONE card: a list of every text\n  // element currently on the video (ayah, then caption, then every\n  // layer, in that order) with one edit (pencil) and one delete (X)\n  // action per row -- the same two-icon pattern InShot and every other\n  // mainstream video editor uses for an on-canvas text element -- plus\n  // a single "+ إضافة نص" button that opens one add/edit sheet shared\n  // by all three kinds.\n  //\n  // Nothing about WHAT each kind does changes underneath: ayah text\n  // still runs through the same Quran matcher (_applyCustomText),\n  // captions still write state.captionText/captionPosition, layers\n  // still go through state.addTextLayer/updateTextLayerAt/\n  // removeTextLayerAt exactly as PATCH_S143 left them. This patch only\n  // changes how you reach those three actions -- one door instead of\n  // three.\n  // -------------------------------------------------------------------\n\n  Widget _unifiedTextCard() {\n    return _sectionCard(Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _sectionHeader(\n          \'النص على الفيديو\',\n          \'مكان واحد لكل نص يظهر على الفيديو — نص الآية، تسمية توضيحية \'\n          \'(مثل اسم القارئ)، وأي عدد تريدينه من طبقات النص الحرة. لكل \'\n          \'عنصر أدناه زر تعديل (✎) وزر حذف (✕)، وتظهر كل العناصر معًا \'\n          \'فوق الفيديو دون أن يستبدل أحدها الآخر.\',\n        ),\n        const SizedBox(height: 10),\n        _textElementsList(),\n        const SizedBox(height: 10),\n        ElevatedButton.icon(\n          onPressed: () => _openTextSheet(),\n          icon: const Icon(Icons.add, size: 20),\n          label: const Text(\'إضافة نص\'),\n        ),\n      ],\n    ));\n  }\n\n  // One row per element currently on the video, in a fixed order\n  // (ayah, then caption, then layers) so the list doesn\'t reshuffle\n  // as you edit things. Empty state explains what the button below\n  // does instead of just showing a blank card.\n  Widget _textElementsList() {\n    final rows = <Widget>[];\n    if (state.hasAyah) {\n      rows.add(_textElementRow(\n        icon: Icons.menu_book_outlined,\n        kindLabel: \'آية\',\n        preview: state.ayahText,\n        onEdit: () => _openTextSheet(kind: _TextKind.ayah),\n        onDelete: () => state.setAyah(\'\', \'\', \'\'),\n      ));\n    }\n    if (state.captionText.isNotEmpty) {\n      rows.add(_textElementRow(\n        icon: Icons.label_outline,\n        kindLabel: \'تسمية\',\n        preview: state.captionText,\n        onEdit: () => _openTextSheet(kind: _TextKind.caption),\n        onDelete: () {\n          state.update(() => state.captionText = \'\');\n          _captionCtrl.clear();\n        },\n      ));\n    }\n    for (var i = 0; i < state.textLayers.length; i++) {\n      final layer = state.textLayers[i];\n      rows.add(_textElementRow(\n        icon: Icons.layers_outlined,\n        kindLabel: \'طبقة\',\n        preview: layer.text,\n        onEdit: () => _openTextSheet(kind: _TextKind.layer, layerIndex: i),\n        onDelete: () => state.removeTextLayerAt(i),\n      ));\n    }\n    if (rows.isEmpty) {\n      return Container(\n        width: double.infinity,\n        padding: const EdgeInsets.symmetric(vertical: 20),\n        decoration: BoxDecoration(\n          border: Border.all(color: AyatColors.hairline),\n          borderRadius: BorderRadius.circular(10),\n        ),\n        child: Column(children: [\n          const Icon(Icons.text_fields,\n              size: 24, color: AyatColors.parchmentDim),\n          const SizedBox(height: 6),\n          Text(\'لا يوجد أي نص على الفيديو بعد\',\n              style: Theme.of(context).textTheme.bodyMedium),\n        ]),\n      );\n    }\n    return Column(children: [\n      for (final r in rows)\n        Padding(padding: const EdgeInsets.only(bottom: 6), child: r),\n    ]);\n  }\n\n  // Same bordered-row look S143 introduced for layers, now shared by\n  // all three kinds, with a small gold kind badge (آية/تسمية/طبقة) so\n  // the mixed list still reads clearly at a glance -- plus the\n  // edit-pencil that S143\'s layer rows never had.\n  Widget _textElementRow({\n    required IconData icon,\n    required String kindLabel,\n    required String preview,\n    required VoidCallback onEdit,\n    required VoidCallback onDelete,\n  }) {\n    return Container(\n      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),\n      decoration: BoxDecoration(\n        border: Border.all(color: AyatColors.hairline),\n        borderRadius: BorderRadius.circular(10),\n      ),\n      child: Row(children: [\n        Icon(icon, size: 17, color: AyatColors.goldDim),\n        const SizedBox(width: 6),\n        Container(\n          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),\n          decoration: BoxDecoration(\n            color: AyatColors.surface,\n            borderRadius: BorderRadius.circular(6),\n          ),\n          child: Text(kindLabel,\n              style:\n                  const TextStyle(fontSize: 10, color: AyatColors.goldDim)),\n        ),\n        const SizedBox(width: 8),\n        Expanded(\n          child: Text(\n            preview,\n            maxLines: 1,\n            overflow: TextOverflow.ellipsis,\n            textDirection: TextDirection.rtl,\n          ),\n        ),\n        IconButton(\n          tooltip: \'تعديل\',\n          padding: EdgeInsets.zero,\n          constraints: const BoxConstraints(minWidth: 34, minHeight: 34),\n          icon: const Icon(Icons.edit_outlined, size: 18),\n          onPressed: onEdit,\n        ),\n        IconButton(\n          tooltip: \'حذف\',\n          padding: EdgeInsets.zero,\n          constraints: const BoxConstraints(minWidth: 34, minHeight: 34),\n          icon: const Icon(Icons.cancel, size: 18, color: Colors.redAccent),\n          onPressed: onDelete,\n        ),\n      ]),\n    );\n  }\n\n  String _textKindTitle(_TextKind k, bool isEdit) => switch (k) {\n        _TextKind.ayah => isEdit ? \'تعديل نص الآية\' : \'كتابة نص الآية\',\n        _TextKind.caption =>\n          isEdit ? \'تعديل التسمية التوضيحية\' : \'تسمية توضيحية جديدة\',\n        _TextKind.layer => isEdit ? \'تعديل طبقة النص\' : \'طبقة نص جديدة\',\n      };\n\n  // The single entry point for every "add" or "edit" of text on the\n  // video. Called with no args from the "+ إضافة نص" button (fresh add,\n  // starts on the "نص حر" kind); called with a kind (+ layerIndex for\n  // layers) from a row\'s own edit pencil, which also locks the kind\n  // chips so an in-progress edit can\'t accidentally turn into adding a\n  // different kind of element.\n  void _openTextSheet({_TextKind? kind, int? layerIndex}) {\n    _sheetIsEdit = kind != null;\n    _editingLayerIndex = layerIndex;\n    if (kind == _TextKind.ayah) {\n      _customArCtrl.text = state.ayahText;\n      _customEnCtrl.text = state.translationText;\n      _sheetKind = _TextKind.ayah;\n    } else if (kind == _TextKind.caption) {\n      _captionCtrl.text = state.captionText;\n      _sheetKind = _TextKind.caption;\n    } else if (kind == _TextKind.layer && layerIndex != null) {\n      final l = state.textLayers[layerIndex];\n      _newLayerCtrl.text = l.text;\n      _newLayerPosition = l.position;\n      _sheetKind = _TextKind.layer;\n    } else {\n      _newLayerCtrl.clear();\n      _newLayerPosition = AyahTextPosition.top;\n      _sheetKind = _TextKind.layer;\n    }\n    showModalBottomSheet(\n      context: context,\n      isScrollControlled: true,\n      backgroundColor: AyatColors.surface2,\n      shape: const RoundedRectangleBorder(\n        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),\n      ),\n      builder: (context) => StatefulBuilder(\n        builder: (context, setSheetState) => Padding(\n          padding: EdgeInsets.only(\n            left: 18,\n            right: 18,\n            top: 14,\n            // PATCH_S150_TEXT_SHEET_SAFE_AREA_FIX: viewInsets.bottom only\n            // covers the keyboard -- it ignored the bottom system nav /\n            // gesture bar, so the last button in the sheet rendered\n            // straight underneath it. padding.bottom is the system-UI\n            // inset; add it on top of the keyboard inset so content\n            // always clears both.\n            bottom: MediaQuery.of(context).viewInsets.bottom +\n                MediaQuery.of(context).padding.bottom +\n                18,\n          ),\n          // PATCH_S147_TEXT_SHEET_SCROLL_FIX: the sheet\'s content\n          // (title + kind chips + fields + buttons) doesn\'t fit above\n          // the keyboard once it opens -- scroll instead of clipping\n          // the bottom (which used to cut off the Apply/Save buttons).\n          child: SingleChildScrollView(\n            child: _textSheetBody(context, setSheetState),\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _textSheetBody(BuildContext context, StateSetter setSheetState) {\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Row(children: [\n          Expanded(\n            child: Text(_textKindTitle(_sheetKind, _sheetIsEdit),\n                style: Theme.of(context).textTheme.headlineMedium),\n          ),\n          IconButton(\n            icon: const Icon(Icons.close, size: 20),\n            onPressed: () => Navigator.pop(context),\n          ),\n        ]),\n        // Kind chips only show when adding fresh -- editing an existing\n        // element keeps its kind fixed, same as you can\'t turn a\n        // caption into a layer by fiddling with it after the fact.\n        if (!_sheetIsEdit) ...[\n          const SizedBox(height: 4),\n          Wrap(spacing: 8, children: [\n            for (final k in _TextKind.values)\n              ChoiceChip(\n                label: Text(switch (k) {\n                  _TextKind.ayah => \'آية قرآنية\',\n                  _TextKind.caption => \'تسمية توضيحية\',\n                  _TextKind.layer => \'نص حر\',\n                }),\n                selected: _sheetKind == k,\n                onSelected: (_) => setSheetState(() {\n                  _sheetKind = k;\n                  // ayah/caption are single slots -- switching to them\n                  // from the fresh-add flow should show what\'s already\n                  // there (if anything) instead of a misleadingly\n                  // blank field.\n                  if (k == _TextKind.ayah) {\n                    _customArCtrl.text = state.ayahText;\n                    _customEnCtrl.text = state.translationText;\n                  } else if (k == _TextKind.caption) {\n                    _captionCtrl.text = state.captionText;\n                  } else {\n                    _newLayerCtrl.clear();\n                    _newLayerPosition = AyahTextPosition.top;\n                  }\n                }),\n              ),\n          ]),\n        ],\n        const SizedBox(height: 12),\n        switch (_sheetKind) {\n          _TextKind.ayah => _ayahSheetFields(context),\n          _TextKind.caption => _captionSheetFields(context, setSheetState),\n          _TextKind.layer => _layerSheetFields(context, setSheetState),\n        },\n        const SizedBox(height: 8),\n      ],\n    );\n  }\n\n  // Same matcher flow _applyCustomText() always ran -- only the field\n  // now lives in the sheet instead of its own card. Both actions close\n  // the sheet first, then run the (possibly async, possibly\n  // dialog-showing) existing method on the main screen underneath.\n  Widget _ayahSheetFields(BuildContext context) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Text(\n          \'اكتبي الآية أو أي نص عربي — سيُطابَق تلقائيًا مع القرآن إن \'\n          \'أمكن، وإلا يُستخدم كما كتبتِه.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        const SizedBox(height: 8),\n        TextField(\n          controller: _customArCtrl,\n          maxLines: 3,\n          textAlign: TextAlign.right,\n          decoration: const InputDecoration(\n            hintText: \'اكتب الآية أو أي نص عربي…\',\n            border: OutlineInputBorder(),\n          ),\n        ),\n        const SizedBox(height: 8),\n        TextField(\n          controller: _customEnCtrl,\n          decoration:\n              const InputDecoration(hintText: \'ترجمة المعاني (اختياري)\'),\n        ),\n        const SizedBox(height: 10),\n        Row(children: [\n          Expanded(child: ElevatedButton(\n              onPressed: () {\n                Navigator.pop(context);\n                _applyCustomText();\n              },\n              child: const Text(\'تطبيق على الفيديو\'))),\n          const SizedBox(width: 8),\n          Expanded(child: OutlinedButton.icon(\n              onPressed: () {\n                Navigator.pop(context);\n                _saveTypedTextToTimeline();\n              },\n              icon: const Icon(Icons.timeline, size: 18),\n              label: const Text(\'حفظ في الخط الزمني\'))),\n        ]),\n      ],\n    );\n  }\n\n  Widget _captionSheetFields(\n      BuildContext context, StateSetter setSheetState) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        TextField(\n          controller: _captionCtrl,\n          decoration: const InputDecoration(\n              hintText: \'مثال: الشيخ عبد الباسط عبد الصمد\'),\n          onChanged: (v) => state.update(() => state.captionText = v),\n        ),\n        const SizedBox(height: 4),\n        RadioGroup<CaptionPosition>(\n          groupValue: state.captionPosition,\n          onChanged: (v) => setSheetState(() => state.update(\n              () => state.captionPosition = v ?? CaptionPosition.bottom)),\n          child: Row(\n            children: [\n              for (final pos in CaptionPosition.values)\n                Expanded(\n                  child: RadioListTile<CaptionPosition>(\n                    dense: true,\n                    contentPadding: EdgeInsets.zero,\n                    title:\n                        Text(pos == CaptionPosition.top ? \'أعلى\' : \'أسفل\'),\n                    value: pos,\n                  ),\n                ),\n            ],\n          ),\n        ),\n        const SizedBox(height: 6),\n        ElevatedButton(\n          onPressed: () => Navigator.pop(context),\n          child: const Text(\'تم\'),\n        ),\n      ],\n    );\n  }\n\n  Widget _layerSheetFields(BuildContext context, StateSetter setSheetState) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        TextField(\n          controller: _newLayerCtrl,\n          maxLines: 2,\n          textAlign: TextAlign.right,\n          decoration: const InputDecoration(\n            hintText: \'اكتب أي نص… (اسم القناة، تعليق، عنوان، ...)\',\n            border: OutlineInputBorder(),\n          ),\n        ),\n        const SizedBox(height: 8),\n        Row(children: [\n          const Text(\'الموضع:\'),\n          const SizedBox(width: 10),\n          DropdownButton<AyahTextPosition>(\n            value: _newLayerPosition,\n            items: const [\n              DropdownMenuItem(\n                  value: AyahTextPosition.top, child: Text(\'أعلى الشاشة\')),\n              DropdownMenuItem(\n                  value: AyahTextPosition.center,\n                  child: Text(\'منتصف الشاشة\')),\n              DropdownMenuItem(\n                  value: AyahTextPosition.bottom,\n                  child: Text(\'أسفل الشاشة\')),\n            ],\n            onChanged: (v) => setSheetState(\n                () => _newLayerPosition = v ?? AyahTextPosition.top),\n          ),\n        ]),\n        const SizedBox(height: 10),\n        ElevatedButton.icon(\n          onPressed: () {\n            final txt = _newLayerCtrl.text.trim();\n            if (txt.isEmpty) {\n              _toast(\'اكتبي نصًا أولًا\');\n              return;\n            }\n            if (_editingLayerIndex != null) {\n              // Preserve whatever fontSize/color the layer already had\n              // -- there\'s no per-layer style control yet (S144 doesn\'t\n              // add one), so this only ever carries S143\'s own\n              // defaults today, but won\'t silently reset a real custom\n              // value if a future patch adds that control.\n              final orig = state.textLayers[_editingLayerIndex!];\n              state.updateTextLayerAt(\n                  _editingLayerIndex!,\n                  TextLayer(\n                      text: txt,\n                      position: _newLayerPosition,\n                      fontSize: orig.fontSize,\n                      color: orig.color));\n            } else {\n              state.addTextLayer(\n                  TextLayer(text: txt, position: _newLayerPosition));\n            }\n            _newLayerCtrl.clear();\n            Navigator.pop(context);\n          },\n          icon: Icon(\n              _editingLayerIndex != null\n                  ? Icons.check\n                  : Icons.add_box_outlined,\n              size: 18),\n          label: Text(\n              _editingLayerIndex != null ? \'حفظ التعديل\' : \'إضافة الطبقة\'),\n        ),\n      ],\n    );\n  }\n\n  Future<void> _saveTypedTextToTimeline() async {\n    final ar = _customArCtrl.text.trim();\n    if (ar.isEmpty) {\n      _toast(\'اكتب النص أولًا\');\n      return;\n    }\n    final en = _customEnCtrl.text.trim();\n    final m = state.matcher?.match(ar);\n    final ayah = m?.ayah ??\n        Ayah(surahNum: 0, surah: \'نص مخصص\', num: 0, ar: ar, en: en);\n    final range = await _pickTextTimeRange();\n    if (range == null) return;\n    state.addManualSegment(ayah, range.$1, range.$2, textOverride: ar);\n    _revealTimelineCard();\n    _toast(\'حُفظ النص في الخط الزمني ✓ — سيظهر من ${_fmtSec(range.$1)} \'\n        \'إلى ${_fmtSec(range.$2)}\');\n  }\n\n  Future<(double, double)?> _pickTextTimeRange() {\n    final sCtrl = TextEditingController(text: \'0\');\n    final eCtrl = TextEditingController(text: \'5\');\n    return showDialog<(double, double)>(\n      context: context,\n      builder: (context) => StatefulBuilder(builder: (context, setS) {\n        void chip(double a, double b) => setS(() {\n          sCtrl.text = a.toStringAsFixed(0);\n          eCtrl.text = b.toStringAsFixed(0);\n        });\n        final dur = state.videoDurationSec;\n        return AlertDialog(\n          backgroundColor: AyatColors.surface,\n          shape: RoundedRectangleBorder(\n            borderRadius: BorderRadius.circular(22),\n            side: const BorderSide(color: AyatColors.hairline)),\n          title: const Text(\'متى يظهر هذا النص؟\'),\n          content: Column(\n            mainAxisSize: MainAxisSize.min,\n            crossAxisAlignment: CrossAxisAlignment.stretch,\n            children: [\n              Wrap(spacing: 6, runSpacing: 6, children: [\n                for (final r in const [\n                  (0.0, 5.0), (5.0, 10.0), (10.0, 15.0), (15.0, 20.0)\n                ])\n                  ActionChip(\n                    label: Text(\'${r.$1.toInt()}–${r.$2.toInt()} ث\'),\n                    onPressed: () => chip(r.$1, r.$2)),\n              ]),\n              const SizedBox(height: 10),\n              Row(children: [\n                Expanded(child: TextField(\n                  controller: sCtrl,\n                  keyboardType:\n                      const TextInputType.numberWithOptions(decimal: true),\n                  decoration: const InputDecoration(labelText: \'من (ث)\'))),\n                const SizedBox(width: 8),\n                Expanded(child: TextField(\n                  controller: eCtrl,\n                  keyboardType:\n                      const TextInputType.numberWithOptions(decimal: true),\n                  decoration: const InputDecoration(labelText: \'إلى (ث)\'))),\n              ]),\n              if (dur > 0) ...[\n                const SizedBox(height: 6),\n                Text(\'مدة الفيديو: ${_fmtSec(dur)}\',\n                  style: const TextStyle(\n                      fontSize: 11, color: AyatColors.parchmentDim)),\n              ],\n            ],\n          ),\n          actions: [\n            TextButton(\n              onPressed: () => Navigator.pop(context),\n              child: const Text(\'إلغاء\')),\n            FilledButton(onPressed: () {\n              final s = double.tryParse(sCtrl.text) ?? 0;\n              var e = double.tryParse(eCtrl.text) ?? (s + 5);\n              if (dur > 0) e = e.clamp(0, dur);\n              if (e <= s) {\n                _toast(\'النهاية يجب أن تكون بعد البداية\');\n                return;\n              }\n              Navigator.pop(context, (s.clamp(0, 9999), e));\n            }, child: const Text(\'حفظ\')),\n          ],\n        );\n      }),\n    );\n  }\n\n  Widget _ayahPanel() {\n    final surahs = <(int, String)>[];\n    var last = 0;\n    for (final a in state.ayaat) {\n      if (a.surahNum != last) {\n        surahs.add((a.surahNum, a.surah));\n        last = a.surahNum;\n      }\n    }\n    final ayatOfSurah = <(int, Ayah)>[\n      for (var i = 0; i < state.ayaat.length; i++)\n        if (state.ayaat[i].surahNum == _selectedSurah) (i, state.ayaat[i]),\n    ];\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'اختيار الآية\',\n            \'اختر السورة ثم الآية، أو استخدم أزرار التعرّف بالذكاء الاصطناعي، أو اكتب نصًا مخصصًا.\'),\n        // PATCH_S144_UNIFIED_TEXT_CARD: the ayah-matching card, S143\'s\n        // "طبقات نص ثابتة" layers card, and the caption card further\n        // down this tab used to be three separate boxes for one job\n        // (text on the video). They\'re now one list + one add/edit\n        // sheet -- see _unifiedTextCard() and its supporting methods\n        // below. _captionSection() is left defined but uncalled --\n        // nothing else references it, kept only so a future patch\n        // can resurrect the standalone caption box without redoing it\n        // from scratch.\n        _unifiedTextCard(),\n        // PATCH_S62_MUSHAF_READER: standalone full-mushaf browser, separate from\n        // the single-ayah picker below it -- reuses state.ayaat, no extra load.\n        // PATCH_S123_QURAN_ENTRY: was a bare OutlinedButton -- the plainest\n        // control on the screen for the app\'s most meaningful destination.\n        // Now the ornamented card, and it hands the chosen ayah straight back\n        // into the editor instead of being a read-only detour.\n        QuranEntryButton(\n          title: _t(\'mushaf.open\'),\n          subtitle: _t(\'mushaf.openHint\'),\n          onTap: () => Navigator.push(\n            context,\n            AppMotion.route( // PATCH_S63_MUSHAF_FONT_FIX: pass the user\'s selected ayah font\n              MushafScreen(\n                ayaat: state.ayaat,\n                fontKey: state.fontKey,\n                initialSurah: _selectedSurah,\n                onUseAyah: _useAyahFromMushaf,\n              ),\n            ),\n          ),\n        ),\n        const Divider(height: 28, color: AyatColors.hairline),\n        _fieldLabel(\'السورة\'),\n        DropdownButton<int>(\n          isExpanded: true,\n          value: surahs.any((s) => s.$1 == _selectedSurah)\n              ? _selectedSurah\n              : (surahs.isEmpty ? null : surahs.first.$1),\n          items: [\n            for (final s in surahs)\n              DropdownMenuItem(value: s.$1, child: Text(\'سورة ${s.$2}\')),\n          ],\n          onChanged: (v) => setState(() {\n            _selectedSurah = v ?? 1;\n            // PATCH_S113_AYAH_DROPDOWN_SELECTION_STATE: old index belonged\n            // to the previous surah\'s ayah list -- drop it instead of\n            // pointing at the wrong ayah (or a now out-of-range index).\n            _selectedAyahIdx = null;\n          }),\n        ),\n        _fieldLabel(\'الآية\'),\n        DropdownButton<int>(\n          isExpanded: true,\n          value: _selectedAyahIdx,\n          hint: const Text(\'اختر الآية\'),\n          items: [\n            for (final e in ayatOfSurah)\n              // PATCH_S105_GOLD_AYAH_BADGE: gold-circle number badge instead\n              // of plain "آية N" text, matching the mushaf reader\'s style.\n              DropdownMenuItem(\n                value: e.$1,\n                child: Row(\n                  mainAxisSize: MainAxisSize.min,\n                  children: [\n                    ayahNumberBadge(e.$2.num, size: 22, fontSize: 10),\n                    const SizedBox(width: 8),\n                    Text(\'آية ${e.$2.num}\'),\n                  ],\n                ),\n              ),\n          ],\n          onChanged: (v) {\n            if (v == null) return;\n            final a = state.ayaat[v];\n            _liveOverlay.value = null;\n            state.setAyah(a.ar, a.en,\n                \'تم الاختيار يدويًا: سورة ${a.surah} — آية ${a.num}\',\n                surahNum: a.surahNum, ayahNum: a.num); // PATCH_S32_AI_ART_NANO_BANANA\n            // PATCH_S101_AUTOSYNC_HINT_PARTIAL_AYAH\n            final words = a.ar.split(RegExp(r\'\\s+\')).where((w) => w.isNotEmpty).toList();\n            setState(() {\n              // PATCH_S113_AYAH_DROPDOWN_SELECTION_STATE: actually remember\n              // the picked index so the dropdown shows it instead of\n              // snapping back to the \'اختر الآية\' hint.\n              _selectedAyahIdx = v;\n              _partialSourceAyah = a;\n              _partialFromWord = 0;\n              _partialToWord = words.isEmpty ? 0 : words.length - 1;\n            });\n          },\n        ),\n        // PATCH_S181_CLIPTOUCH: everything below is folded away; nothing was removed\n        _advancedFold(Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n        if (_partialSourceAyah != null) _partialAyahSection(),\n        // PATCH_S109_TEXT_TIMING_RED_WORDS_CAPTION / PATCH_S146_FINISH_WORDCOLORS\n        _manualTimingSection(),\n        // PATCH_S144_UNIFIED_TEXT_CARD: caption is now one of the rows\n        // in _unifiedTextCard() above, not its own card down here.\n        _autoSegWizardCard(), // PATCH_S134_AUTOSEG_WIZARD\n        // PATCH_S57_MANUAL_MULTI_AYAH_ENTRY: the dropdown above sets ONE static ayah. For a\n        // recitation that moves through several ayat, build a manual\n        // timeline instead -- this opens the same add-a-segment dialog\n        // used by the auto-sync review card, so the first ayah added\n        // here becomes the start of a full multi-ayah timeline you can\n        // keep extending from the card that appears above once it\'s\n        // no longer empty.\n        // PATCH_S120_ADVANCED_OPTIONS_CLEANUP: card replaces the old bare\n        // Divider(height: 32) that used to separate this from the field\n        // above -- the card\'s own border/margin does that job now.\n        _sectionCard(Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _sectionHeader(\n              AppStrings(AppSettings.instance.lang).t(\'multi.range\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n              \'لتلاوة تمر بعدة آيات، أضيفي كل آية بتوقيتها الخاص. ستظهر \'\n              \'بطاقة \\\'مراجعة الآيات المرصودة\\\' أعلى الشاشة بعد أول آية \'\n              \'لإكمال الباقي أو تعديل التوقيت -- يمكنك إضافة آية كاملة من \'\n              \'هنا، أو جزء من آية فقط عبر قسم "استخدام جزء من الآية فقط" \'\n              \'أعلاه.\',\n            ),\n            const SizedBox(height: 8),\n            OutlinedButton.icon(\n              onPressed: _addManualSegmentDialog,\n              icon: const Icon(Icons.playlist_add, size: 18),\n              label: const Text(\'إضافة آية إلى خط زمني متعدد\'),\n            ),\n          ],\n        )),\n        _sectionCard(Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            _sectionHeader(\n              \'بطاقات افتتاحية وختامية\',\n              \'تظهر البسملة والخاتمة كشاشتين مستقلتين قبل/بعد المقطع فقط — \'\n              \'لا تُدمجان أبدًا فوق الفيديو أو أي خلفية صوتية. عطّلي أيًا منهما \'\n              \'إن لم ترغبي بها، ويمكنك تخصيص نص الخاتمة بعد تفعيلها.\',\n            ),\n            ToggleRow(\n              label: \'بسملة في مقدمة المقطع\',\n              value: state.showIntro,\n              onChanged: (v) => state.update(() => state.showIntro = v),\n            ),\n            ToggleRow(\n              label: \'خاتمة بعد التلاوة\',\n              value: state.showOutro,\n              onChanged: (v) => state.update(() => state.showOutro = v),\n            ),\n            if (state.showOutro)\n              TextField(\n                controller: _outroCtrl,\n                decoration: const InputDecoration(hintText: \'نص الخاتمة\'),\n                onChanged: (v) => state.outroText =\n                    v.trim().isEmpty ? kDefaultOutro : v.trim(),\n              ),\n          ],\n        )),\n          ],\n        )), // PATCH_S181_CLIPTOUCH: closes the advanced fold\n      ],\n    );\n  }\n\n  // ---------------------------------------------------------- tab: خلفيات\n\n  Widget _bgPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'خلفيات جاهزة\',\n            \'تُستخدم خلف النص إن لم تُحمّل فيديو، أو كخلفية بديلة عند تفعيل الكروم.\'),\n        GridView.count(\n          crossAxisCount: 2,\n          shrinkWrap: true,\n          physics: const NeverScrollableScrollPhysics(),\n          mainAxisSpacing: 11,\n          crossAxisSpacing: 11,\n          childAspectRatio: 9 / 13,\n          children: [\n            for (var i = 0; i < kBackgrounds.length; i++)\n              GestureDetector(\n                onTap: () => state.update(() {\n                  state.bgIndex = i;\n                  state.useCustomBg = false;\n                }),\n                child: Container(\n                  decoration: BoxDecoration(\n                    gradient: kBackgrounds[i].gradient,\n                    borderRadius: BorderRadius.circular(11),\n                    border: Border.all(\n                      color: (!state.useCustomBg && state.bgIndex == i)\n                          ? AyatColors.goldBright\n                          : Colors.white.withValues(alpha: 0.05),\n                      width:\n                          (!state.useCustomBg && state.bgIndex == i) ? 2 : 1,\n                    ),\n                  ),\n                  alignment: Alignment.bottomRight,\n                  padding: const EdgeInsets.all(8),\n                  child: Text(\'خلفية ${i + 1}\',\n                      style: const TextStyle(\n                          fontSize: 11, color: AyatColors.parchmentDim)),\n                ),\n              ),\n          ],\n        ),\n        // PATCH_S29_BG_ANIMATION_TOGGLE: on/off switch for the S28 animated sheen -- only\n        // meaningful for the preset gradients above, so it\'s placed\n        // right under them.\n        const SizedBox(height: 10),\n        ToggleRow(\n          label: \'خلفية متحركة\',\n          value: state.bgAnimated,\n          onChanged: (v) => state.update(() => state.bgAnimated = v),\n        ),\n        // PATCH_S40_MULTI_BG_CYCLE\n        const Divider(height: 32, color: AyatColors.hairline),\n        ToggleRow(\n          label: \'خلفيات متعددة (تبديل تلقائي أثناء التصدير)\',\n          value: state.multiBgEnabled,\n          onChanged: (v) => state.update(() => state.multiBgEnabled = v),\n        ),\n        if (state.multiBgEnabled) ...[\n          const SizedBox(height: 6),\n          Text(\n            \'اضغط على خلفيتين أو أكثر بالترتيب الذي تريد التبديل بينه؛ الرقم على كل خلفية مختارة هو ترتيبها في الدورة. يظهر التبديل في الفيديو المُصدَّر فقط — المعاينة المباشرة تعرض الخلفية المحددة أعلاه. الخلفيات المخصصة/فن الذكاء الاصطناعي تبقى خلفية واحدة.\',\n            style: Theme.of(context)\n                .textTheme\n                .bodyMedium\n                ?.copyWith(color: AyatColors.goldBright),\n          ),\n          const SizedBox(height: 10),\n          GridView.count(\n            crossAxisCount: 2,\n            shrinkWrap: true,\n            physics: const NeverScrollableScrollPhysics(),\n            mainAxisSpacing: 11,\n            crossAxisSpacing: 11,\n            childAspectRatio: 9 / 13,\n            children: [\n              for (var i = 0; i < kBackgrounds.length; i++)\n                GestureDetector(\n                  onTap: () => state.update(() {\n                    if (state.multiBgIndexes.contains(i)) {\n                      state.multiBgIndexes.remove(i);\n                    } else {\n                      state.multiBgIndexes.add(i);\n                    }\n                  }),\n                  child: Container(\n                    decoration: BoxDecoration(\n                      gradient: kBackgrounds[i].gradient,\n                      borderRadius: BorderRadius.circular(11),\n                      border: Border.all(\n                        color: state.multiBgIndexes.contains(i)\n                            ? AyatColors.goldBright\n                            : Colors.white.withValues(alpha: 0.05),\n                        width: state.multiBgIndexes.contains(i) ? 2 : 1,\n                      ),\n                    ),\n                    alignment: Alignment.topLeft,\n                    padding: const EdgeInsets.all(8),\n                    child: state.multiBgIndexes.contains(i)\n                        ? CircleAvatar(\n                            radius: 11,\n                            backgroundColor: AyatColors.goldBright,\n                            child: Text(\n                              \'${state.multiBgIndexes.indexOf(i) + 1}\',\n                              style: const TextStyle(\n                                  fontSize: 12,\n                                  fontWeight: FontWeight.bold,\n                                  color: Colors.black),\n                            ),\n                          )\n                        : const SizedBox.shrink(),\n                  ),\n                ),\n            ],\n          ),\n          if (state.multiBgIndexes.length < 2) ...[\n            const SizedBox(height: 6),\n            Text(\'اختر خلفيتين على الأقل ليعمل التبديل.\',\n                style: Theme.of(context)\n                    .textTheme\n                    .bodyMedium\n                    ?.copyWith(color: AyatColors.parchmentDim)),\n          ],\n          const SizedBox(height: 12),\n          _fieldLabel(\'التبديل\'),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final entry in kBgSwitchTriggers)\n                ChoiceChip(\n                  label: Text(_t(entry.$2)),\n                  selected: state.bgSwitchTrigger == entry.$1,\n                  onSelected: (_) =>\n                      state.update(() => state.bgSwitchTrigger = entry.$1),\n                ),\n            ],\n          ),\n          if (state.bgSwitchTrigger == BgSwitchTrigger.ayahs) ...[\n            const SizedBox(height: 8),\n            _fieldLabel(\n                \'كل ${state.bgSwitchAyahs} آية/آيات (يتطلب مزامنة تلقائية، وإلا يُستخدم التبديل بالثواني)\'),\n            Slider(\n              value: state.bgSwitchAyahs.toDouble(),\n              min: 1,\n              max: 10,\n              divisions: 9,\n              onChanged: (v) =>\n                  state.update(() => state.bgSwitchAyahs = v.round()),\n            ),\n          ] else ...[\n            const SizedBox(height: 8),\n            _fieldLabel(\'كل ${state.bgSwitchSeconds} ثانية\'),\n            Slider(\n              value: state.bgSwitchSeconds.toDouble(),\n              min: 3,\n              max: 30,\n              divisions: 27,\n              onChanged: (v) =>\n                  state.update(() => state.bgSwitchSeconds = v.round()),\n            ),\n          ],\n          const SizedBox(height: 8),\n          _fieldLabel(\'طريقة الانتقال\'),\n          Wrap(\n            spacing: 8,\n            runSpacing: 8,\n            children: [\n              for (final entry in kBgTransitionStyles)\n                ChoiceChip(\n                  label: Text(_t(entry.$2)),\n                  selected: state.bgTransitionStyle == entry.$1,\n                  onSelected: (_) =>\n                      state.update(() => state.bgTransitionStyle = entry.$1),\n                ),\n            ],\n          ),\n          // PATCH_S70_MORE_TRANSITIONS: every non-hardCut style now uses the same\n          // duration/overlap slider via xfade, not just crossfade specifically.\n          if (state.bgTransitionStyle != BgTransitionStyle.hardCut) ...[\n            const SizedBox(height: 8),\n            _fieldLabel(\n                \'مدة الانتقال: ${state.bgCrossfadeDuration.toStringAsFixed(1)} ثانية\'),\n            Slider(\n              value: state.bgCrossfadeDuration,\n              min: 0.2,\n              max: 3.0,\n              divisions: 28,\n              onChanged: (v) =>\n                  state.update(() => state.bgCrossfadeDuration = v),\n            ),\n          ],\n        ],\n        // PATCH_S32_AI_ART_NANO_BANANA\n        const Divider(height: 32, color: AyatColors.hairline),\n        ToggleRow(\n          label: \'فن الذكاء الاصطناعي لكل آية\',\n          value: state.aiArtEnabled,\n          onChanged: (v) => state.update(() => state.aiArtEnabled = v),\n        ),\n        if (state.aiArtEnabled) ...[\n          const SizedBox(height: 6),\n          Text(\n            // PATCH_S84_AI_ART_MODEL_CHAIN + PATCH_S84_AI_ART_FOLLOWS_PLAYBACK\n            \'تُنشأ خلفية بأسلوب خطوط متوهجة أحادية اللون لكل آية تُكتشف تلقائيًا، بلا وجوه بشرية أبدًا؛ إن ذُكر نبي في الآية يظهر عمود نور واسمه بخط عربي بدل أي شخصية. \'\n            \'يختار التطبيق تلقائيًا أفضل نموذج مجاني متاح، ومع المزامنة التلقائية يتبدّل الفن مع كل آية أثناء التلاوة (في التلاوات الصوتية أو مع الكروم).\',\n            style: Theme.of(context)\n                .textTheme\n                .bodyMedium\n                ?.copyWith(color: AyatColors.goldBright),\n          ),\n          // PATCH_S87_AI_ART_ONE_TAP_FLOW: the API-key field used to sit in\n          // plain view and read like a requirement to use the feature at\n          // all -- it\'s optional (S80 made generation fully keyless), so\n          // it now lives behind a collapsed "خيارات متقدمة" expander.\n          const SizedBox(height: 8),\n          Theme(\n            data: Theme.of(context).copyWith(dividerColor: Colors.transparent),\n            child: ExpansionTile(\n              tilePadding: EdgeInsets.zero,\n              childrenPadding: EdgeInsets.zero,\n              title: const Text(\'خيارات متقدمة\',\n                  style: TextStyle(fontSize: 13, color: AyatColors.parchmentDim)),\n              children: [\n                TextField(\n                  controller: TextEditingController(text: state.pollinationsApiKey)\n                    ..selection = TextSelection.collapsed(\n                        offset: state.pollinationsApiKey.length),\n                  style: const TextStyle(fontSize: 13),\n                  decoration: const InputDecoration(\n                    labelText: \'مفتاح Pollinations (اختياري)\',\n                    helperText: \'التوليد يعمل بدون مفتاح -- اتركه فارغًا. أدخل مفتاحك الشخصي فقط لرفع الحد لاحقًا\',\n                    helperMaxLines: 2,\n                    isDense: true,\n                  ),\n                  onChanged: (v) => state.update(() {\n                    state.pollinationsApiKey = v.trim();\n                    AiArtService.apiKey = state.pollinationsApiKey;\n                  }),\n                ),\n              ],\n            ),\n          ),\n          const SizedBox(height: 8),\n          if (state.aiArtError != null)\n            Padding(\n              padding: const EdgeInsets.symmetric(vertical: 4),\n              child: Text(\n                state.aiArtError!,\n                style: Theme.of(context)\n                    .textTheme\n                    .bodySmall\n                    ?.copyWith(color: Colors.redAccent),\n              ),\n            ),\n          // PATCH_S87_AI_ART_ONE_TAP_FLOW: one obvious flow instead of three\n          // half-explained states. With an auto-sync timeline active this\n          // batch-generates + caches art for the segment\'s ayat (up to 6)\n          // in one tap with live progress; without one it falls back to\n          // the single current-ayah path (previous behavior, unchanged).\n          if (state.aiArtBatchBusy)\n            Padding(\n              padding: const EdgeInsets.symmetric(vertical: 4),\n              child: Row(children: [\n                const SizedBox(\n                    width: 16,\n                    height: 16,\n                    child: CircularProgressIndicator(strokeWidth: 2)),\n                const SizedBox(width: 8),\n                Expanded(\n                    child:\n                        Text(state.aiArtBatchProgress ?? \'جارٍ توليد الفن...\')),\n              ]),\n            )\n          else if (state.aiArtBusy)\n            const Padding(\n              padding: EdgeInsets.symmetric(vertical: 4),\n              child: Row(children: [\n                SizedBox(\n                    width: 16,\n                    height: 16,\n                    child: CircularProgressIndicator(strokeWidth: 2)),\n                SizedBox(width: 8),\n                Text(\'جارٍ توليد الفن...\'),\n              ]),\n            )\n          else ...[\n            if (state.aiArtBatchProgress != null)\n              Padding(\n                padding: const EdgeInsets.symmetric(vertical: 4),\n                child: Text(state.aiArtBatchProgress!,\n                    style: Theme.of(context)\n                        .textTheme\n                        .bodySmall\n                        ?.copyWith(color: AyatColors.goldBright)),\n              ),\n            ElevatedButton.icon(\n              onPressed: () => state.timelineActive\n                  ? state.generateArtForTimelineBatch()\n                  : state.generateAiArtNow(),\n              icon: const Icon(Icons.auto_awesome, size: 18),\n              label: Text(state.timelineActive\n                  ? \'توليد الفن لآيات المقطع (حتى 6 آيات)\'\n                  : \'توليد فن للآية الحالية\'),\n            ),\n            if (state.hasAiArt) ...[\n              const SizedBox(height: 6),\n              OutlinedButton.icon(\n                onPressed: () => state.regenerateAiArt(),\n                icon: const Icon(Icons.refresh, size: 18),\n                label: const Text(\'إعادة توليد فن هذه الآية\'),\n              ),\n              const SizedBox(height: 6),\n              // PATCH_S51_AI_ART_DELETE: distinct from regenerate -- wipes\n              // the cached image from disk and drops back to the preset\n              // background instead of making a new one.\n              OutlinedButton.icon(\n                onPressed: () => state.deleteAiArt(),\n                icon: const Icon(Icons.delete_outline, size: 18),\n                label: const Text(\'حذف الفن المولّد لهذه الآية\'),\n              ),\n            ],\n          ],\n        ],\n        const SizedBox(height: 10),\n        // PATCH_S82_CUSTOM_BG_LIBRARY: the old single numbered slot\n        // (kBackgrounds.length + 1) only made sense for exactly one custom\n        // background. Now that every upload is kept, they\'re shown as their\n        // own scrollable gallery instead -- tap to use, long-press to\n        // remove from the library (storage itself is uncapped).\n        if (state.customBgLibrary.isNotEmpty) ...[\n          Text(\'خلفياتك المرفوعة (${state.customBgLibrary.length})\',\n              style: const TextStyle(fontSize: 11, color: AyatColors.parchmentDim)),\n          const SizedBox(height: 8),\n          SizedBox(\n            height: 92,\n            child: ListView.builder(\n              scrollDirection: Axis.horizontal,\n              itemCount: state.customBgLibrary.length,\n              itemBuilder: (context, i) {\n                final path = state.customBgLibrary[i];\n                final isActive =\n                    state.useCustomBg && state.customBgPath == path;\n                return Padding(\n                  padding: const EdgeInsets.only(left: 8),\n                  child: GestureDetector(\n                    onTap: () => state.update(() {\n                      state.useCustomBg = true;\n                      state.customBgPath = path;\n                    }),\n                    onLongPress: () => state.update(() {\n                      state.customBgLibrary.removeAt(i);\n                      if (state.customBgPath == path) {\n                        state.useCustomBg = false;\n                        state.customBgPath = null;\n                      }\n                    }),\n                    child: Container(\n                      width: 64,\n                      decoration: BoxDecoration(\n                        borderRadius: BorderRadius.circular(10),\n                        border: Border.all(\n                          color: isActive\n                              ? AyatColors.goldBright\n                              : Colors.white.withValues(alpha: 0.08),\n                          width: isActive ? 2 : 1,\n                        ),\n                      ),\n                      clipBehavior: Clip.antiAlias,\n                      child: File(path).existsSync()\n                          ? Image.file(File(path),\n                              fit: BoxFit.cover, cacheWidth: 160)\n                          : Container(\n                              color: Colors.white.withValues(alpha: 0.05)),\n                    ),\n                  ),\n                );\n              },\n            ),\n          ),\n          const SizedBox(height: 4),\n          Text(\'اضغط مطولًا على أي صورة لحذفها من المكتبة\',\n              style: TextStyle(\n                  fontSize: 10,\n                  color: AyatColors.parchmentDim.withValues(alpha: 0.7))),\n          const SizedBox(height: 10),\n        ],\n        // PATCH_S107_CURATED_NATURE_BACKGROUNDS\n        Text(\'خلفيات طبيعية جاهزة\',\n            style: const TextStyle(fontSize: 11, color: AyatColors.parchmentDim)),\n        const SizedBox(height: 8),\n        SizedBox(\n          height: 92,\n          child: ListView.builder(\n            scrollDirection: Axis.horizontal,\n            itemCount: kCuratedBackgrounds.length,\n            itemBuilder: (context, i) {\n              final c = kCuratedBackgrounds[i];\n              final isActive = state.useCustomBg &&\n                  state.customBgPath == _curatedBgResolvedPaths[c.asset];\n              return Padding(\n                padding: const EdgeInsets.only(left: 8),\n                child: GestureDetector(\n                  onTap: () => _useCuratedBg(c),\n                  child: Container(\n                    width: 64,\n                    decoration: BoxDecoration(\n                      borderRadius: BorderRadius.circular(10),\n                      border: Border.all(\n                        color: isActive\n                            ? AyatColors.goldBright\n                            : Colors.white.withValues(alpha: 0.08),\n                        width: isActive ? 2 : 1,\n                      ),\n                    ),\n                    clipBehavior: Clip.antiAlias,\n                    child: Image.asset(c.asset, fit: BoxFit.cover, cacheWidth: 160),\n                  ),\n                ),\n              );\n            },\n          ),\n        ),\n        const SizedBox(height: 4),\n        Text(\'اضغط على أي صورة لاستخدامها كخلفية مباشرة\',\n            style: TextStyle(\n                fontSize: 10,\n                color: AyatColors.parchmentDim.withValues(alpha: 0.7))),\n        const SizedBox(height: 10),\n        ElevatedButton.icon(\n          onPressed: _pickCustomBg,\n          icon: const Icon(Icons.add_photo_alternate_outlined, size: 18),\n          label: const Text(\'ارفع خلفية جديدة\'),\n        ),\n        if (state.useCustomBg) ...[\n          const SizedBox(height: 10),\n          Text(\n            AppStrings(AppSettings.instance.lang).t(\'bg.customNote\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n            style: Theme.of(context)\n                .textTheme\n                .bodyMedium\n                ?.copyWith(color: AyatColors.goldBright),\n          ),\n          const SizedBox(height: 8),\n          ElevatedButton(\n            onPressed: () => state.update(() {\n              state.useCustomBg = false;\n              state.customBgPath = null;\n            }),\n            child: const Text(\'إلغاء التفعيل والعودة للخلفيات الجاهزة\'),\n          ),\n        ],\n      ],\n    );\n  }\n\n  // ------------------------------------------------------------ tab: كروم\n\n  Widget _chromaPanel() {\n    Widget colorDot(Color c, {String? label}) {\n      final selected = state.chromaColor.toARGB32() == c.toARGB32();\n      return GestureDetector(\n        onTap: () => state.update(() => state.chromaColor = c),\n        child: Container(\n          width: 34,\n          height: 34,\n          decoration: BoxDecoration(\n            color: c,\n            shape: BoxShape.circle,\n            border: Border.all(\n                color: selected ? AyatColors.goldBright : AyatColors.hairline,\n                width: selected ? 2.5 : 1),\n          ),\n        ),\n      );\n    }\n\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'الكروم (خلفية خضراء)\',\n            \'فعّل هذا الخيار إذا كان الفيديو المرفوع مصوّرًا أمام خلفية بلون موحّد (أخضر أو أزرق أو غيره)، ليتم استبدالها بالخلفية المختارة عند التصدير.\'),\n        ToggleRow(\n          label: AppStrings(AppSettings.instance.lang).t(\'chroma.enable\'), // PATCH_S128_TEXT_EDITOR_PRO_SIMPLE_MODE_SELECTION_GUIDE_I18N\n          value: state.chromaEnabled,\n          onChanged: (v) => state.update(() => state.chromaEnabled = v),\n        ),\n        _fieldLabel(\'لون الشاشة الملوّنة\'),\n        Row(\n          children: [\n            GestureDetector(\n              onTap: () async {\n                final c = await showAyatColorPicker(context, state.chromaColor);\n                if (c != null) state.update(() => state.chromaColor = c);\n              },\n              child: Container(\n                width: 34,\n                height: 34,\n                decoration: BoxDecoration(\n                  color: state.chromaColor,\n                  borderRadius: BorderRadius.circular(8),\n                  border: Border.all(color: AyatColors.goldBright),\n                ),\n                child: const Icon(Icons.colorize,\n                    size: 15, color: Colors.black54),\n              ),\n            ),\n            const SizedBox(width: 10),\n            colorDot(const Color(0xFF00FF00)),\n            const SizedBox(width: 8),\n            colorDot(const Color(0xFF0000FF)),\n            const SizedBox(width: 10),\n            Expanded(\n              child: Text(\'اختر نفس لون الشاشة التي صوّرت أمامها\',\n                  style: Theme.of(context).textTheme.bodyMedium),\n            ),\n          ],\n        ),\n        _fieldLabel(\'قوة إزالة اللون\'),\n        Slider(\n          value: state.chromaThreshold.toDouble(),\n          min: 40,\n          max: 140,\n          onChanged: (v) =>\n              state.update(() => state.chromaThreshold = v.round()),\n        ),\n        _fieldLabel(\'نعومة حواف القص\'),\n        Slider(\n          value: state.chromaSoftness.toDouble(),\n          min: 10,\n          max: 90,\n          onChanged: (v) =>\n              state.update(() => state.chromaSoftness = v.round()),\n        ),\n        const SizedBox(height: 6),\n        Text(\n          \'تتم إزالة اللون فعليًا على جهازك أثناء التصدير (بمحرك ffmpeg)، ويعمل مع أي لون شاشة تختاره وليس الأخضر فقط. اضبط «القوة» إذا بقيت بقايا من لون الخلفية، و«النعومة» إذا ظهرت حواف حادة حول الشخص. الجودة النهائية تعتمد أيضًا على إضاءة التصوير الأصلية.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n      ],\n    );\n  }\n\n  // ------------------------------------------------------------ tab: قرّاء\n\n  Widget _recitersPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'مقاطع صوتية للقرّاء\',\n            // PATCH_S104_RECITER_LIBRARY_DOWNLOAD: no longer true that the app\n            // can only use manually-attached files -- it can fetch real\n            // recitations from mp3quran.net now.\n            \'اختر قارئًا ثم إمّا نزّل تلاوته لسورة معيّنة من الإنترنت، أو أرفق ملف تلاوة خاص بك.\'),\n        for (var i = 0; i < kReciters.length; i++)\n          Container(\n            margin: const EdgeInsets.only(bottom: 8),\n            padding: const EdgeInsets.all(10),\n            decoration: BoxDecoration(\n              color: state.reciterIndex == i\n                  ? AyatColors.surface3\n                  : AyatColors.surface2,\n              borderRadius: BorderRadius.circular(14),\n              border: Border.all(\n                  color: state.reciterIndex == i\n                      ? AyatColors.gold\n                      : AyatColors.hairline),\n            ),\n            child: InkWell(\n              onTap: () {\n                state.update(() => state.reciterIndex = i);\n                _toast(\'تم اختيار قارئ: ${kReciters[i]}\');\n              },\n              child: Row(\n                children: [\n                  CircleAvatar(\n                    radius: 17,\n                    backgroundColor: AyatColors.emerald,\n                    child: Text(kReciters[i].characters.first,\n                        style: const TextStyle(\n                            fontSize: 13, color: AyatColors.goldBright)),\n                  ),\n                  const SizedBox(width: 10),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(kReciters[i],\n                            style: Theme.of(context).textTheme.bodyLarge),\n                        GestureDetector(\n                          onTap: () => _pickReciterAudio(i),\n                          child: Text(\n                            state.reciterAudioPaths[i] == null\n                                ? \'إرفاق تلاوة صوتية\'\n                                : \'✓ ${state.reciterAudioPaths[i]!.split(\'/\').last}\',\n                            style: TextStyle(\n                              fontSize: 10.5,\n                              color: state.reciterAudioPaths[i] == null\n                                  ? AyatColors.parchmentDim\n                                  : AyatColors.goldDim,\n                              decoration: TextDecoration.underline,\n                              decorationColor: AyatColors.parchmentDim,\n                            ),\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                  // PATCH_S104_RECITER_LIBRARY_DOWNLOAD: download this\n                  // reciter\'s audio for a chosen سورة straight from the\n                  // internet instead of attaching a file.\n                  _downloadingReciter == i\n                      ? SizedBox(\n                          width: 40,\n                          height: 40,\n                          child: Padding(\n                            padding: const EdgeInsets.all(9),\n                            child: CircularProgressIndicator(\n                              strokeWidth: 2.4,\n                              value: _downloadProgress,\n                              color: AyatColors.goldBright,\n                            ),\n                          ),\n                        )\n                      : IconButton(\n                          onPressed: () => _downloadReciterAudio(i),\n                          icon: const Icon(\n                            Icons.cloud_download_outlined,\n                            color: AyatColors.goldBright,\n                          ),\n                          tooltip: \'تنزيل من الإنترنت\',\n                        ),\n                  IconButton(\n                    onPressed: () => _toggleReciterPreview(i),\n                    icon: Icon(\n                      _previewingReciter == i\n                          ? Icons.pause_circle_outline\n                          : Icons.play_circle_outline,\n                      color: AyatColors.goldBright,\n                    ),\n                    tooltip: \'تشغيل/إيقاف\',\n                  ),\n                ],\n              ),\n            ),\n          ),\n      ],\n    );\n  }\n\n  // ------------------------------------------------------------ tab: قوالب\n\n  Widget _templatesPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'قوالب جاهزة\', \'كل قالب يضبط الموضع والخط واللون دفعة واحدة.\'),\n        for (var i = 0; i < kTemplates.length; i++)\n          GestureDetector(\n            onTap: () {\n              HapticFeedback.selectionClick(); // PATCH_S83_SYNC_QOL\n              state.applyTemplate(i);\n              _toast(_tf(\'preset.templateAppliedToast\', [_t(kTemplates[i].name)]));\n            },\n            child: Container(\n              margin: const EdgeInsets.only(bottom: 8),\n              padding: const EdgeInsets.all(12),\n              decoration: BoxDecoration(\n                color: state.templateIndex == i\n                    ? AyatColors.surface3\n                    : AyatColors.surface2,\n                borderRadius: BorderRadius.circular(14),\n                border: Border.all(\n                    color: state.templateIndex == i\n                        ? AyatColors.gold\n                        : AyatColors.hairline),\n              ),\n              child: Row(\n                children: [\n                  Container(\n                    width: 34,\n                    height: 52,\n                    decoration: BoxDecoration(\n                      color: AyatColors.ink,\n                      borderRadius: BorderRadius.circular(6),\n                      border: Border.all(color: AyatColors.hairline),\n                    ),\n                    child: Align(\n                      alignment: switch (kTemplates[i].pos) {\n                        AyahTextPosition.top => const Alignment(0, -0.7),\n                        AyahTextPosition.center => Alignment.center,\n                        AyahTextPosition.bottom => const Alignment(0, 0.7),\n                      },\n                      child: Container(\n                          width: 22, height: 3, color: kTemplates[i].color),\n                    ),\n                  ),\n                  const SizedBox(width: 12),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(_t(kTemplates[i].name),\n                            style: Theme.of(context).textTheme.bodyLarge),\n                        Text(_t(kTemplates[i].desc),\n                            style: Theme.of(context).textTheme.bodyMedium),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n      ],\n    );\n  }\n\n  // ------------------------------------------------------------- tab: النص\n\n  Widget _textPanel() {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        _panelTitle(\'تنسيق النص\'),\n        // PATCH_S126_TEXT_TRANSITIONS\n        _textTransitionSection(),\n        const Divider(height: 32, color: AyatColors.hairline),\n        _fieldLabel(\'خط الآية\'),\n        // PATCH_S46_DEFAULT_FONT_AND_GLOW: default fallback is now the bundled elgharib font.\n        DropdownButton<String>(\n          isExpanded: true,\n          value: state.allFonts.any((f) => f.key == state.fontKey)\n              ? state.fontKey\n              : \'elgharib\',\n          items: [\n            for (final f in state.allFonts)\n              // PATCH_S154_STUDIO_PRESETS_I18N: built-in fonts\' `.label` is\n              // now an i18n key; custom/uploaded fonts keep a raw filename\n              // there, which t() returns unchanged since it\'s not a known\n              // key -- one call handles both cases correctly.\n              DropdownMenuItem(value: f.key, child: Text(_t(f.label))),\n          ],\n          onChanged: (v) => state.update(() => state.fontKey = v ?? \'elgharib\'),\n        ),\n        const SizedBox(height: 6),\n        ElevatedButton.icon(\n          onPressed: _pickCustomFont,\n          icon: const Icon(Icons.font_download_outlined, size: 18),\n          label: const Text(\'رفع خط مخصص (TTF/OTF)\'),\n        ),\n        const SizedBox(height: 6),\n        // PATCH_S39_PERSISTENT_FONTS\n        Text(\n          \'الخطوط المرفوعة تُحفظ داخل التطبيق وتبقى متاحة ومحددة بعد إغلاقه — ارفع خط المصحف المفضل لديك (مثل الغريب نون حفص) مرة واحدة فقط.\',\n          style: Theme.of(context).textTheme.bodyMedium,\n        ),\n        // PATCH_S46_DEFAULT_FONT_AND_GLOW: glow on/off + intensity (plan 2.2)\n        SwitchListTile(\n          contentPadding: EdgeInsets.zero,\n          title: const Text(\'توهّج النص\'),\n          value: state.glowEnabled,\n          onChanged: (v) => state.update(() => state.glowEnabled = v),\n        ),\n        if (state.glowEnabled) ...[\n          _fieldLabel(\'شدة التوهّج\'),\n          Slider(\n            value: state.glowIntensity,\n            min: 0,\n            max: 1.5,\n            onChanged: (v) => state.update(() => state.glowIntensity = v),\n          ),\n        ],\n        // PATCH_S51_KARAOKE_TOGGLE: on by default; off shows each ayah\n        // part as plain static text instead of lighting up word-by-word\n        // in step with الشيخ\'s recitation.\n        SwitchListTile(\n          contentPadding: EdgeInsets.zero,\n          title: const Text(\'تظليل الكلمات مع التلاوة (كاريوكي)\'),\n          subtitle: const Text(\n              \'عند الإيقاف: تُعرض الآية كاملة دون إضاءة كل كلمة على حدة\'),\n          value: state.karaokeEnabled,\n          onChanged: (v) => state.update(() => state.karaokeEnabled = v),\n        ),\n        // PATCH_S48_TEXT_SPACING_TOGGLES\n        _fieldLabel(\'تباعد الأحرف\'),\n        Slider(\n          value: state.letterSpacing,\n          min: -1,\n          max: 3,\n          onChanged: (v) => state.update(() => state.letterSpacing = v),\n        ),\n        _fieldLabel(\'تباعد الأسطر\'),\n        Slider(\n          value: state.lineHeightMultiplier,\n          min: 1.2,\n          max: 2.2,\n          onChanged: (v) => state.update(() => state.lineHeightMultiplier = v),\n        ),\n        _fieldLabel(\'حجم خط الآية\'),\n        Slider(\n          value: state.ayahFontSize,\n          min: 14,\n          max: 60, // PATCH_S185_POLISH\n          onChanged: (v) => state.update(() => state.ayahFontSize = v),\n        ),\n        _fieldLabel(\'حجم خط ترجمة المعاني\'),\n        Slider(\n          value: state.transFontSize,\n          min: 9,\n          max: 18,\n          onChanged: (v) => state.update(() => state.transFontSize = v),\n        ),\n        // PATCH_S50_DRAGGABLE_TEXT: sliders above stay as the fine-tune/reset-to-default\n        // controls; drag the ayah text directly on the preview above to\n        // reposition, pinch it to resize, or double-tap it to snap back.\n        if (state.textOffset != Offset.zero || state.textUserScale != 1.0)\n          Padding(\n            padding: const EdgeInsets.only(bottom: 8),\n            child: OutlinedButton.icon(\n              onPressed: () => state.update(() {\n                state.textOffset = Offset.zero;\n                state.textUserScale = 1.0;\n              }),\n              icon: const Icon(Icons.restart_alt, size: 16),\n              label: const Text(\'إعادة موضع/حجم النص للوضع الافتراضي\'),\n            ),\n          ),\n        _fieldLabel(\'لون النص\'),\n        Wrap(\n          spacing: 8,\n          runSpacing: 8,\n          children: [\n            for (final c in kTextColors)\n              GestureDetector(\n                onTap: () => state.update(() => state.textColor = c),\n                child: Container(\n                  width: 28,\n                  height: 28,\n                  decoration: BoxDecoration(\n                    color: c,\n                    shape: BoxShape.circle,\n                    border: Border.all(\n                        color: state.textColor.toARGB32() == c.toARGB32()\n                            ? AyatColors.goldBright\n                            : AyatColors.hairline,\n                        width:\n                            state.textColor.toARGB32() == c.toARGB32() ? 2.5 : 1),\n                  ),\n                ),\n              ),\n            GestureDetector(\n              onTap: () async {\n                final c = await showAyatColorPicker(context, state.textColor);\n                if (c != null) state.update(() => state.textColor = c);\n              },\n              child: Container(\n                width: 28,\n                height: 28,\n                decoration: BoxDecoration(\n                  color: state.textColor,\n                  shape: BoxShape.circle,\n                  border: Border.all(color: AyatColors.goldBright),\n                ),\n                child:\n                    const Icon(Icons.colorize, size: 13, color: Colors.black54),\n              ),\n            ),\n          ],\n        ),\n        _fieldLabel(\'موضع النص على الشاشة\'),\n        DropdownButton<AyahTextPosition>(\n          isExpanded: true,\n          value: state.textPosition,\n          items: const [\n            DropdownMenuItem(\n                value: AyahTextPosition.top, child: Text(\'أعلى الشاشة\')),\n            DropdownMenuItem(\n                value: AyahTextPosition.center, child: Text(\'منتصف الشاشة\')),\n            DropdownMenuItem(\n                value: AyahTextPosition.bottom, child: Text(\'أسفل الشاشة\')),\n          ],\n          onChanged: (v) => state\n              .update(() => state.textPosition = v ?? AyahTextPosition.bottom),\n        ),\n        ToggleRow(\n          label: \'إظهار ترجمة المعاني\',\n          value: state.showTranslation,\n          onChanged: (v) => state.update(() => state.showTranslation = v),\n        ),\n      ],\n    );\n  }\n\n  Widget _staticDurationRow() {\n    return Row(\n      children: [\n        Expanded(\n          child: Text(\'مدة التصدير بدون فيديو (ثانية)\',\n              style: Theme.of(context).textTheme.bodyLarge),\n        ),\n        SizedBox(\n          width: 70,\n          child: TextField(\n            controller: _staticDurCtrl,\n            keyboardType: TextInputType.number,\n            textAlign: TextAlign.center,\n            decoration: const InputDecoration(isDense: true),\n            onChanged: (v) =>\n                state.staticDurationSec = (int.tryParse(v) ?? 6).clamp(2, 60),\n          ),\n        ),\n      ],\n    );\n  }\n}\n\n// PATCH_S125_EFFECTS_LIBRARY: category-grouped effect picker. One category is\n// open at a time (the one holding the current selection, so reopening the\n// panel lands you where you left off), and "بدون تأثير" is always reachable\n// at the top rather than buried inside a group.\n// PATCH_S165_UI_REFRESH: the prototype\'s ambient background - emerald light\n// from the top corner, a whisper of burgundy from the bottom. Static, so it\n// sits in its own repaint layer and never costs a frame while scrolling.\n// PATCH_S166_UI_POLISH: a slow breathing gold halo behind [child]. The halo\n// lives in its own RepaintBoundary and the child is passed through untouched,\n// so animating it never repaints the child (which may be a live video).\n// Static when animations are off or [enabled] is false.\n// ignore: unused_element\nclass _Breathing extends StatefulWidget {\n  final Widget child;\n  final bool enabled;\n  final double borderRadius;\n  final bool subtle;\n  const _Breathing({\n    required this.child,\n    required this.enabled,\n    this.borderRadius = 18,\n    this.subtle = false,\n  });\n\n  @override\n  State<_Breathing> createState() => _BreathingState();\n}\n\nclass _BreathingState extends State<_Breathing>\n    with SingleTickerProviderStateMixin {\n  late final AnimationController _c;\n\n  @override\n  void initState() {\n    super.initState();\n    _c = AnimationController(\n        vsync: this, duration: const Duration(milliseconds: 3600));\n    _sync();\n  }\n\n  @override\n  void didUpdateWidget(covariant _Breathing old) {\n    super.didUpdateWidget(old);\n    _sync();\n  }\n\n  void _sync() {\n    if (AppMotion.on && widget.enabled) {\n      if (!_c.isAnimating) _c.repeat(reverse: true);\n    } else {\n      _c.stop();\n      _c.value = 0.5;\n    }\n  }\n\n  @override\n  void dispose() {\n    _c.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final base = widget.subtle ? 0.05 : 0.10;\n    final swing = widget.subtle ? 0.10 : 0.22;\n    return Stack(\n      clipBehavior: Clip.none,\n      children: [\n        Positioned.fill(\n          child: IgnorePointer(\n            child: RepaintBoundary(\n              child: AnimatedBuilder(\n                animation: _c,\n                builder: (context, _) {\n                  final t = Curves.easeInOut.transform(_c.value);\n                  return DecoratedBox(\n                    decoration: BoxDecoration(\n                      borderRadius:\n                          BorderRadius.circular(widget.borderRadius),\n                      boxShadow: [\n                        BoxShadow(\n                          color: AyatColors.gold\n                              .withValues(alpha: base + swing * t),\n                          blurRadius: 18 + 16 * t,\n                          spreadRadius: 0.5 + 1.5 * t,\n                        ),\n                      ],\n                    ),\n                  );\n                },\n              ),\n            ),\n          ),\n        ),\n        widget.child,\n      ],\n    );\n  }\n}\n\nclass _AmbientGlow extends StatelessWidget {\n  const _AmbientGlow();\n\n  @override\n  Widget build(BuildContext context) {\n    return IgnorePointer(\n      child: RepaintBoundary(\n        child: Stack(\n          fit: StackFit.expand,\n          children: [\n            DecoratedBox(\n              decoration: BoxDecoration(\n                gradient: RadialGradient(\n                  center: const Alignment(0.9, -0.85),\n                  radius: 1.15,\n                  colors: [\n                    AyatColors.emerald.withValues(alpha: 0.45),\n                    Colors.transparent,\n                  ],\n                ),\n              ),\n            ),\n            DecoratedBox(\n              decoration: BoxDecoration(\n                gradient: RadialGradient(\n                  center: const Alignment(-0.9, 1.0),\n                  radius: 1.0,\n                  colors: [\n                    const Color(0xFF5C2430).withValues(alpha: 0.22),\n                    Colors.transparent,\n                  ],\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nclass _EffectPicker extends StatefulWidget {\n  final StageEffect selected;\n  final ValueChanged<StageEffect> onSelected;\n  const _EffectPicker({required this.selected, required this.onSelected});\n\n  @override\n  State<_EffectPicker> createState() => _EffectPickerState();\n}\n\nclass _EffectPickerState extends State<_EffectPicker> {\n  late EffectCategory _open = widget.selected == StageEffect.none\n      ? EffectCategory.nature\n      : widget.selected.category;\n\n  @override\n  void didUpdateWidget(covariant _EffectPicker old) {\n    super.didUpdateWidget(old);\n    if (widget.selected != old.selected &&\n        widget.selected != StageEffect.none) {\n      _open = widget.selected.category;\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final byCategory = <EffectCategory, List<StageEffect>>{};\n    for (final e in StageEffect.values) {\n      if (e == StageEffect.none) continue;\n      byCategory.putIfAbsent(e.category, () => []).add(e);\n    }\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Align(\n          alignment: AlignmentDirectional.centerStart,\n          child: ChoiceChip(\n            avatar: const Icon(Icons.block, size: 15),\n            label: Text(StageEffect.none.label),\n            selected: widget.selected == StageEffect.none,\n            onSelected: (_) => widget.onSelected(StageEffect.none),\n          ),\n        ),\n        const SizedBox(height: 10),\n        for (final cat in EffectCategory.values)\n          if ((byCategory[cat] ?? const []).isNotEmpty) ...[\n            InkWell(\n              onTap: () => setState(() => _open = cat),\n              borderRadius: BorderRadius.circular(10),\n              child: Padding(\n                padding: const EdgeInsets.symmetric(vertical: 8),\n                child: Row(\n                  children: [\n                    Icon(cat.icon,\n                        size: 16,\n                        color: _open == cat\n                            ? AyatColors.goldBright\n                            : AyatColors.parchmentDim),\n                    const SizedBox(width: 8),\n                    Text(\n                      cat.labelAr,\n                      style: TextStyle(\n                        fontSize: 13,\n                        fontWeight: FontWeight.w700,\n                        color: _open == cat\n                            ? AyatColors.goldBright\n                            : AyatColors.parchmentDim,\n                      ),\n                    ),\n                    const SizedBox(width: 6),\n                    Text(\'(${byCategory[cat]!.length})\',\n                        style: const TextStyle(\n                            fontSize: 11, color: AyatColors.parchmentDim)),\n                    const Spacer(),\n                    Icon(\n                      _open == cat ? Icons.expand_less : Icons.expand_more,\n                      size: 18,\n                      color: AyatColors.gold,\n                    ),\n                  ],\n                ),\n              ),\n            ),\n            if (_open == cat)\n              Padding(\n                padding: const EdgeInsets.only(bottom: 6),\n                child: Wrap(\n                  spacing: 8,\n                  runSpacing: 8,\n                  children: [\n                    for (final e in byCategory[cat]!)\n                      ChoiceChip(\n                        avatar: Icon(e.icon,\n                            size: 15,\n                            color: widget.selected == e\n                                ? AyatColors.goldBright\n                                : AyatColors.parchmentDim),\n                        label: Text(e.label),\n                        selected: widget.selected == e,\n                        onSelected: (_) => widget.onSelected(e),\n                      ),\n                  ],\n                ),\n              ),\n            const Divider(height: 1, color: AyatColors.hairline),\n          ],\n      ],\n    );\n  }\n}\n')), 'lib/services/export_service.dart': ('edit', [("import 'karaoke.dart'; // PATCH_S33_KARAOKE_WORD_HIGHLIGHT\nimport 'overlay_renderer.dart';\nimport 'pip_export.dart'; // PATCH_S188_PIP\nimport 'stage_effects.dart'; // PATCH_S34_STAGE_EFFECTS\n\nclass ExportService {\n", "import 'karaoke.dart'; // PATCH_S33_KARAOKE_WORD_HIGHLIGHT\nimport 'overlay_renderer.dart';\nimport 'pip_export.dart'; // PATCH_S188_PIP\nimport 'video_fx.dart'; // PATCH_S194_CUT_FX\nimport 'stage_effects.dart'; // PATCH_S34_STAGE_EFFECTS\n\nclass ExportService {\n"), ("      final a = (state.enhanceSharpen / 100 * 1.5).toStringAsFixed(2);\n      parts.add('unsharp=5:5:$a:5:5:0.0');\n    }\n    if (state.vignetteEnabled) {\n      parts.add(_vignetteFilter(state.vignetteIntensity));\n    }\n", "      final a = (state.enhanceSharpen / 100 * 1.5).toStringAsFixed(2);\n      parts.add('unsharp=5:5:$a:5:5:0.0');\n    }\n    // PATCH_S194_CUT_FX: B&W / negative / dramatic / warm / cool\n    final fxColor = VideoFxFilters.color(state.videoFx);\n    if (fxColor.isNotEmpty) parts.add(fxColor);\n    if (state.vignetteEnabled) {\n      parts.add(_vignetteFilter(state.vignetteIntensity));\n    }\n"), ("    // segments concatenated before/after this one — see export()), applied\n    // to the composited [outv] before mapping. Audio is untouched by all of\n    // this.\n    final post = _postFilterChain(state);\n    var outLabel = 'outv';\n    if (post.isNotEmpty) {\n      filters.add('[outv]$post[outv2]');\n", "    // segments concatenated before/after this one — see export()), applied\n    // to the composited [outv] before mapping. Audio is untouched by all of\n    // this.\n    // PATCH_S194_CUT_FX: fades / flash / bars / shake / pulse (main clip only)\n    final fxTimed = VideoFxFilters.timed(state.videoFx, w, h, duration);\n    final post = [_postFilterChain(state), fxTimed]\n        .where((e) => e.isNotEmpty)\n        .join(',');\n    var outLabel = 'outv';\n    if (post.isNotEmpty) {\n      filters.add('[outv]$post[outv2]');\n")]), 'lib/services/video_fx.dart': ('new', '// PATCH_S194_CUT_FX\n// The everyday video-editor looks (black & white, negative, cinematic bars,\n// fade from / to black, flash, shake, pulse ...). Pure Dart: the preview\n// (VideoFxLayer) and the exporter (VideoFxFilters) read the same table.\nenum VideoFx {\n  none,\n  bw,\n  negative,\n  dramatic,\n  warm,\n  cool,\n  bars,\n  fadeIn,\n  fadeOut,\n  fadeBoth,\n  flash,\n  shake,\n  pulse,\n}\n\nextension VideoFxInfo on VideoFx {\n  String get label => switch (this) {\n        VideoFx.none => \'بدون\',\n        VideoFx.bw => \'أبيض وأسود\',\n        VideoFx.negative => \'نيجاتيف\',\n        VideoFx.dramatic => \'درامي\',\n        VideoFx.warm => \'دافئ\',\n        VideoFx.cool => \'بارد\',\n        VideoFx.bars => \'شريط سينمائي\',\n        VideoFx.fadeIn => \'ظهور من الأسود\',\n        VideoFx.fadeOut => \'اختفاء للأسود\',\n        VideoFx.fadeBoth => \'ظهور واختفاء\',\n        VideoFx.flash => \'وميض\',\n        VideoFx.shake => \'اهتزاز\',\n        VideoFx.pulse => \'نبض\',\n      };\n\n  /// Colour looks (same on every frame) vs. time-based ones.\n  bool get isColor =>\n      this == VideoFx.bw ||\n      this == VideoFx.negative ||\n      this == VideoFx.dramatic ||\n      this == VideoFx.warm ||\n      this == VideoFx.cool;\n}\n\n/// Length of the fades / flash (seconds).\nconst double kVideoFxFade = 0.8;\nconst double kVideoFxFlash = 0.35;\n\n/// Bar height as a fraction of the frame height (each bar).\nconst double kVideoFxBar = 0.12;\n\n/// 4x5 colour matrix of the colour looks, for the live preview.\nList<double>? videoFxMatrix(VideoFx f) => switch (f) {\n      VideoFx.bw => const <double>[\n          0.299, 0.587, 0.114, 0, 0, //\n          0.299, 0.587, 0.114, 0, 0,\n          0.299, 0.587, 0.114, 0, 0,\n          0, 0, 0, 1, 0,\n        ],\n      VideoFx.negative => const <double>[\n          -1, 0, 0, 0, 255, //\n          0, -1, 0, 0, 255,\n          0, 0, -1, 0, 255,\n          0, 0, 0, 1, 0,\n        ],\n      // contrast 1.35 around mid-grey, saturation ~0.6\n      VideoFx.dramatic => const <double>[\n          1.13, 0.30, 0.06, 0, -45, //\n          0.12, 1.31, 0.06, 0, -45,\n          0.12, 0.30, 1.07, 0, -45,\n          0, 0, 0, 1, 0,\n        ],\n      VideoFx.warm => const <double>[\n          1.08, 0, 0, 0, 8, //\n          0, 1.0, 0, 0, 0,\n          0, 0, 0.9, 0, -8,\n          0, 0, 0, 1, 0,\n        ],\n      VideoFx.cool => const <double>[\n          0.9, 0, 0, 0, -8, //\n          0, 1.0, 0, 0, 0,\n          0, 0, 1.1, 0, 8,\n          0, 0, 0, 1, 0,\n        ],\n      _ => null,\n    };\n\nclass VideoFxFilters {\n  /// The colour looks, as an ffmpeg filter (\'\' for the others).\n  static String color(VideoFx f) => switch (f) {\n        VideoFx.bw => \'hue=s=0\',\n        VideoFx.negative => \'negate\',\n        VideoFx.dramatic => \'eq=contrast=1.35:saturation=0.6:brightness=-0.04\',\n        VideoFx.warm => \'colorbalance=rs=0.10:gs=0.02:bs=-0.10\',\n        VideoFx.cool => \'colorbalance=rs=-0.10:gs=0.0:bs=0.12\',\n        _ => \'\',\n      };\n\n  /// The time-based looks for a clip of [w]x[h] and [duration] seconds\n  /// (\'\' for the others). Goes after the colour chain, on the main clip only.\n  static String timed(VideoFx f, int w, int h, double duration) {\n    String d(double v) => v.toStringAsFixed(3);\n    final fadeLen = (duration / 3).clamp(0.1, kVideoFxFade).toDouble();\n    final outAt = (duration - fadeLen).clamp(0.0, double.infinity).toDouble();\n    switch (f) {\n      case VideoFx.bars:\n        return \'drawbox=x=0:y=0:w=iw:h=ih*$kVideoFxBar:color=black:t=fill,\'\n            \'drawbox=x=0:y=ih-ih*$kVideoFxBar:w=iw:h=ih*$kVideoFxBar:color=black:t=fill\';\n      case VideoFx.fadeIn:\n        return \'fade=t=in:st=0:d=${d(fadeLen)}\';\n      case VideoFx.fadeOut:\n        return \'fade=t=out:st=${d(outAt)}:d=${d(fadeLen)}\';\n      case VideoFx.fadeBoth:\n        return \'fade=t=in:st=0:d=${d(fadeLen)},\'\n            \'fade=t=out:st=${d(outAt)}:d=${d(fadeLen)}\';\n      case VideoFx.flash:\n        return \'fade=t=in:st=0:d=${d(kVideoFxFlash)}:color=white\';\n      case VideoFx.shake:\n        return \'scale=$w*1.06:$h*1.06,\'\n            "crop=$w:$h:x=\'(iw-ow)/2+sin(t*40)*(iw-ow)/2\':"\n            "y=\'(ih-oh)/2+cos(t*33)*(ih-oh)/2\'";\n      case VideoFx.pulse:\n        return "scale=w=\'$w*(1+0.05*abs(sin(t*3)))\':"\n            "h=\'$h*(1+0.05*abs(sin(t*3)))\':eval=frame:flags=bilinear,"\n            \'crop=$w:$h\';\n      default:\n        return \'\';\n    }\n  }\n}\n'), 'lib/widgets/stage_preview.dart': ('edit', [("import 'selection_box_overlay.dart'; // PATCH_S133_STAGE_TEXT_SELECT_EDIT\nimport 'pro_transform.dart'; // PATCH_S180_TRANSFORM\nimport 'pro_pip.dart'; // PATCH_S188_PIP\nimport '../services/ruh_touch.dart'; // PATCH_S181_CLIPTOUCH\nimport 'color_picker_dialog.dart' show showAyatColorPicker; // PATCH_S145\n\n", "import 'selection_box_overlay.dart'; // PATCH_S133_STAGE_TEXT_SELECT_EDIT\nimport 'pro_transform.dart'; // PATCH_S180_TRANSFORM\nimport 'pro_pip.dart'; // PATCH_S188_PIP\nimport 'video_fx_layer.dart'; // PATCH_S194_CUT_FX\nimport '../services/ruh_touch.dart'; // PATCH_S181_CLIPTOUCH\nimport 'color_picker_dialog.dart' show showAyatColorPicker; // PATCH_S145\n\n"), ('          _grainTimer?.cancel();\n          _grainTimer = null;\n        }\n        return ClipRRect(\n          borderRadius: BorderRadius.circular(26),\n          child: Container(\n            decoration: BoxDecoration(\n', '          _grainTimer?.cancel();\n          _grainTimer = null;\n        }\n        return VideoFxLayer( // PATCH_S194_CUT_FX\n          state: state,\n          controller: videoController,\n          child: ClipRRect(\n          borderRadius: BorderRadius.circular(26),\n          child: Container(\n            decoration: BoxDecoration(\n'), ('            ), // PATCH_S85_VIDEO_ADJUST: closes the manual-adjust ColorFiltered\n            ), // PATCH_S58_LIVE_EFFECTS_PREVIEW: closes ColorFiltered\n          ),\n        );\n      }),\n    );\n', '            ), // PATCH_S85_VIDEO_ADJUST: closes the manual-adjust ColorFiltered\n            ), // PATCH_S58_LIVE_EFFECTS_PREVIEW: closes ColorFiltered\n          ),\n          ), // PATCH_S194_CUT_FX: closes ClipRRect\n        );\n      }),\n    );\n')]), 'lib/widgets/video_fx_layer.dart': ('new', "// PATCH_S194_CUT_FX\n// Live preview of the everyday looks (see services/video_fx.dart). Wraps the\n// whole stage: colour looks tint it, fades / flash / bars are drawn over it,\n// shake and pulse move it.\nimport 'dart:math' as math;\n\nimport 'package:flutter/material.dart';\nimport 'package:video_player/video_player.dart';\n\nimport '../models/studio_state.dart';\nimport '../services/video_fx.dart';\n\nclass VideoFxLayer extends StatefulWidget {\n  final StudioState state;\n  final VideoPlayerController? controller;\n  final Widget child;\n  const VideoFxLayer({\n    super.key,\n    required this.state,\n    required this.controller,\n    required this.child,\n  });\n\n  @override\n  State<VideoFxLayer> createState() => _VideoFxLayerState();\n}\n\nclass _VideoFxLayerState extends State<VideoFxLayer>\n    with SingleTickerProviderStateMixin {\n  late final AnimationController _tick =\n      AnimationController(vsync: this, duration: const Duration(seconds: 60));\n\n  @override\n  void dispose() {\n    _tick.dispose();\n    super.dispose();\n  }\n\n  bool _moves(VideoFx f) => f == VideoFx.shake || f == VideoFx.pulse;\n\n  @override\n  Widget build(BuildContext context) {\n    final fx = widget.state.videoFx;\n    if (fx == VideoFx.none) {\n      if (_tick.isAnimating) _tick.stop();\n      return widget.child;\n    }\n    final m = videoFxMatrix(fx);\n    if (m != null) {\n      if (_tick.isAnimating) _tick.stop();\n      return ColorFiltered(\n          colorFilter: ColorFilter.matrix(m), child: widget.child);\n    }\n    if (fx == VideoFx.bars) {\n      return Stack(fit: StackFit.passthrough, children: [\n        widget.child,\n        Positioned.fill(\n          child: IgnorePointer(\n            child: Column(children: [\n              Expanded(flex: 12, child: Container(color: Colors.black)),\n              const Spacer(flex: 76),\n              Expanded(flex: 12, child: Container(color: Colors.black)),\n            ]),\n          ),\n        ),\n      ]);\n    }\n    if (_moves(fx)) {\n      if (!_tick.isAnimating) _tick.repeat();\n      return AnimatedBuilder(\n        animation: _tick,\n        child: widget.child,\n        builder: (context, child) {\n          final t = _tick.value * 60.0;\n          if (fx == VideoFx.shake) {\n            return ClipRect(\n              child: Transform.scale(\n                scale: 1.06,\n                child: FractionalTranslation(\n                  translation:\n                      Offset(math.sin(t * 40) * 0.027, math.cos(t * 33) * 0.027),\n                  child: child,\n                ),\n              ),\n            );\n          }\n          return ClipRect(\n            child: Transform.scale(\n                scale: 1 + 0.05 * math.sin(t * 3).abs(), child: child),\n          );\n        },\n      );\n    }\n    // fades / flash follow the playhead of the main clip\n    if (_tick.isAnimating) _tick.stop();\n    final c = widget.controller;\n    if (c == null) return widget.child;\n    return ValueListenableBuilder<VideoPlayerValue>(\n      valueListenable: c,\n      child: widget.child,\n      builder: (context, v, child) {\n        final s = widget.state;\n        final dur = v.duration.inMilliseconds / 1000.0;\n        final start = s.trimManualStart;\n        final end = s.trimManualEnd < 0 ? dur : math.min(s.trimManualEnd, dur);\n        final len = math.max(0.1, end - start);\n        final t = v.position.inMilliseconds / 1000.0 - start;\n        final fadeLen = (len / 3).clamp(0.1, kVideoFxFade).toDouble();\n        var black = 0.0;\n        var white = 0.0;\n        if (fx == VideoFx.fadeIn || fx == VideoFx.fadeBoth) {\n          black = math.max(black, 1 - (t / fadeLen).clamp(0.0, 1.0));\n        }\n        if (fx == VideoFx.fadeOut || fx == VideoFx.fadeBoth) {\n          black = math.max(black, ((t - (len - fadeLen)) / fadeLen).clamp(0.0, 1.0));\n        }\n        if (fx == VideoFx.flash) {\n          white = 1 - (t / kVideoFxFlash).clamp(0.0, 1.0);\n        }\n        return Stack(fit: StackFit.passthrough, children: [\n          child!,\n          if (black > 0.01)\n            Positioned.fill(\n              child: IgnorePointer(\n                child: ColoredBox(\n                    color: Colors.black.withValues(alpha: black.toDouble())),\n              ),\n            ),\n          if (white > 0.01)\n            Positioned.fill(\n              child: IgnorePointer(\n                child: ColoredBox(\n                    color: Colors.white.withValues(alpha: white.toDouble())),\n              ),\n            ),\n        ]);\n      },\n    );\n  }\n}\n")}
def rd(p): return open(p, encoding="utf-8").read()
if all(os.path.exists(p) and MARK in rd(p) for p in SPEC):
    print("  OK      already applied"); sys.exit(0)
bad=[]; texts={}
for p,(kind,v) in SPEC.items():
    if kind=="new":
        if os.path.exists(p) and MARK not in rd(p): bad.append(p+" exists"); 
        continue
    if not os.path.exists(p): bad.append(p+" missing"); continue
    t=rd(p)
    if MARK in t: bad.append(p+" already patched"); continue
    if kind=="full":
        import hashlib
        norm=t.rstrip(chr(10))+chr(10)
        if hashlib.sha256(norm.encode()).hexdigest()!=v[0]: bad.append(p+" differs from the S192 version it was made for")
        texts[p]=v[1]; continue
    pos=[]
    for i,(o,n) in enumerate(v):
        if t.count(o)!=1: bad.append("%s hunk %d found %d"%(p,i,t.count(o)))
        else: pos.append((t.index(o),o,n))
    pos.sort()
    for a,b in zip(pos,pos[1:]):
        if a[0]+len(a[1])>b[0]: bad.append(p+" overlapping hunks")
    for st,o,n in reversed(pos): t=t[:st]+n+t[st+len(o):]
    texts[p]=t
if bad: sys.exit("Anchor check failed, nothing written:\n  "+"\n  ".join(bad))
for p,(kind,v) in SPEC.items():
    t=v if kind=="new" else texts[p]
    os.makedirs(os.path.dirname(p) or ".",exist_ok=True)
    open(p,"w",encoding="utf-8").write(t); print("  PATCHED",p)
print("S194 applied. Next: git add -A && git commit -m \"S194: cut PIP + video looks\" && git push")
